INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87094, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "课本", "is_correct": false, "explanation": "语义：课本是学习用的书，不能用来解决污染。"}, {"text": "电影", "is_correct": false, "explanation": "搭配：“解决”的对象是污染、问题等，“电影”不能作为要解决的对象。"}, {"text": "对策", "is_correct": true, "explanation": "正确。对策指应付问题的办法，与“研究解决污染的”搭配自然。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子无法解决污染，“解决污染的桌子”说不通。"}], "explanations": {"课本": "语义：课本是学习用的书，不能用来解决污染。", "电影": "搭配：“解决”的对象是污染、问题等，“电影”不能作为要解决的对象。", "对策": "正确。对策指应付问题的办法，与“研究解决污染的”搭配自然。", "桌子": "语义：桌子无法解决污染，“解决污染的桌子”说不通。"}, "sentence_index": 0, "correct_answer": "对策"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次迟到，他的对策是路上堵车。", "explanation": "这里应该用〈理由〉。对策是应付问题的办法，不能把迟到的原因说成对策。"}, {"text": "这本小说的对策很精彩。", "explanation": "这里应该用〈情节〉。对策指应付难事的办法，小说里的故事发展要用“情节”。"}, {"text": "他穿了一件新对策去上班。", "explanation": "这里应该用〈衣服〉。对策是应付问题的办法，不能穿在身上；穿的是“衣服”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01cebb8a-1503-46fc-8817-0957501ce55d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87094, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手套", "is_correct": false, "explanation": "语义：手套是保暖用品，不是减少交通事故的办法。"}, {"text": "饮料", "is_correct": false, "explanation": "搭配：“减少”后接的是事故、污染等，“饮料”不能与“减少交通事故的”搭配。"}, {"text": "对策", "is_correct": true, "explanation": "正确。对策指应付问题的办法，“减少交通事故的对策”搭配自然。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑部件，不能用来减少交通事故。"}], "explanations": {"手套": "语义：手套是保暖用品，不是减少交通事故的办法。", "饮料": "搭配：“减少”后接的是事故、污染等，“饮料”不能与“减少交通事故的”搭配。", "对策": "正确。对策指应付问题的办法，“减少交通事故的对策”搭配自然。", "窗户": "语义：窗户是建筑部件，不能用来减少交通事故。"}, "sentence_index": 6, "correct_answer": "对策"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗面的对策很好吃。", "explanation": "这里应该用〈味道〉。对策指应付难事的办法，形容食物的口感要用“味道”。"}, {"text": "这间房子的对策很大。", "explanation": "这里应该用〈面积〉。对策是应付问题的办法，房子大小要用“面积”。"}, {"text": "他找了个对策不去上班。", "explanation": "这里应该用〈借口〉。对策是应对问题的办法，不是用来推托的理由，推托要用“借口”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01cebb8a-1503-46fc-8817-0957501ce55d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87094, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次会议上，大家提出了一本对策。", "corrected_sentence": "这次会议上，大家提出了一条对策。", "error_description": "量词错误：“对策”可以用“条”，“本”用于书籍等。正确说法是“一条对策”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01cebb8a-1503-46fc-8817-0957501ce55d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87094, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们想出了很多好地对策。", "corrected_sentence": "他们想出了很多好的对策。", "error_description": "结构助词错误：修饰名词“对策”的形容词要用“的”，应说“好的对策”；“地”用于修饰动词，不能说“好地对策”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01cebb8a-1503-46fc-8817-0957501ce55d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87096, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d6d4d56-8f24-4af4-9609-d7826352ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87096, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d6d4d56-8f24-4af4-9609-d7826352ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87096, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "代表一定财产权利、可以买卖的有价凭证，如股票、债券等。", "primary_collocate": null, "pronunciation": "zhèng quàn", "ipa": "ʈʂɤŋ˥˩ tɕʰɥɛn˥˩", "syllable_count": 2, "sentences": [{"text": "股票和债券都是常见的证券。", "target_word": "证券", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把手里的证券卖掉了，换了一套房子。", "target_word": "证券", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸买了一些证券，希望以后能赚钱。", "target_word": "证券", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "证券的价格每天都在变化。", "target_word": "证券", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张证券可以在市场上自由买卖。", "target_word": "证券", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "投资者可以通过银行买到国债这种证券。", "target_word": "证券", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她打算把证券留着，等价格涨了再卖。", "target_word": "证券", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "证券上写着金额和发行日期。", "target_word": "证券", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买证券以前，要先了解发行公司的情况。", "target_word": "证券", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司向社会发行证券，筹集了不少资金。", "target_word": "证券", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "證券", "label": "繁体"}, {"form": "证券公司", "label": "复合"}, {"form": "证券市场", "label": "复合"}], "register": "书面", "sense_fingerprint": "证券|有价凭证|股票债券|名词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94425b3a-c4ef-47ea-b6af-b5c17af3720b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87096, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "证券", "is_correct": true, "explanation": "正确答案。证券指代表财产权利、可以买卖的有价凭证，如股票、债券。"}, {"text": "政权", "is_correct": false, "explanation": "quán（第二声）与 quàn（第四声）声调不同，意思是国家政权。"}, {"text": "争权", "is_correct": false, "explanation": "zhēng（第一声）与 zhèng（第四声）、quán（第二声）与 quàn（第四声）声调都不同，意思是争夺权力。"}, {"text": "整圈", "is_correct": false, "explanation": "zhěng quān（第三声、第一声）与 zhèng quàn（第四声、第四声）声调不同，韵母也略有差别，意思是完整的一圈。"}, {"text": "正拳", "is_correct": false, "explanation": "quán（第二声）与 quàn（第四声）声调不同，意思是武术中的直拳。"}], "explanations": {"证券": "正确答案。证券指代表财产权利、可以买卖的有价凭证，如股票、债券。", "政权": "quán（第二声）与 quàn（第四声）声调不同，意思是国家政权。", "争权": "zhēng（第一声）与 zhèng（第四声）、quán（第二声）与 quàn（第四声）声调都不同，意思是争夺权力。", "整圈": "zhěng quān（第三声、第一声）与 zhèng quàn（第四声、第四声）声调不同，韵母也略有差别，意思是完整的一圈。", "正拳": "quán（第二声）与 quàn（第四声）声调不同，意思是武术中的直拳。"}, "sentence_index": null, "correct_answer": "证券"}, "level_3": {"options": [{"text": "证券", "is_correct": true, "explanation": "正确。“股票和债券”都属于有价凭证，可以说“常见的证券”。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：“饮料”与“股票和债券”属于不同类别，句子说的是金融凭证，不能说“常见的饮料”。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：“蔬菜”是食物，与“股票和债券”不能并列为同类常见物品，句意不通。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：「电脑」是电子产品，与「股票和债券」不同类，「都是常见的电脑」句意不通。"}], "explanations": {"证券": "正确。“股票和债券”都属于有价凭证，可以说“常见的证券”。", "饮料": "语义：“饮料”与“股票和债券”属于不同类别，句子说的是金融凭证，不能说“常见的饮料”。", "蔬菜": "语义：“蔬菜”是食物，与“股票和债券”不能并列为同类常见物品，句意不通。", "电脑": "语义：「电脑」是电子产品，与「股票和债券」不同类，「都是常见的电脑」句意不通。"}, "sentence_index": 0, "correct_answer": "证券"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "看病前要先去挂号处拿一张证券。", "explanation": "这里应该用〈挂号单〉。挂号单是看病的凭条，证券指股票、债券等可以买卖的有价凭证。"}, {"text": "出国前要带好护照等证券。", "explanation": "这里应该用〈证件〉。证件指护照、身份证等证明身份的文件，证券指股票、债券等有价凭证。"}, {"text": "他终于拿到了毕业证券。", "explanation": "这里应该用〈证书〉。毕业证书是学校颁发的证明，证券指股票、债券，不能用来指毕业证。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d6d4d56-8f24-4af4-9609-d7826352ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87096, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "证券", "is_correct": true, "explanation": "正确。“留着，等价格涨了再卖”说的是可以买卖的有价凭证。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“作业”没有价格，不能说“等价格涨了再卖”。"}, {"text": "故事", "is_correct": false, "explanation": "语义：故事没有价格，也不能拿来买卖，与后半句矛盾。"}, {"text": "朋友", "is_correct": false, "explanation": "语义：朋友不能标价出售，与“等价格涨了再卖”的语境矛盾。"}], "explanations": {"证券": "正确。“留着，等价格涨了再卖”说的是可以买卖的有价凭证。", "作业": "搭配：“作业”没有价格，不能说“等价格涨了再卖”。", "故事": "语义：故事没有价格，也不能拿来买卖，与后半句矛盾。", "朋友": "语义：朋友不能标价出售，与“等价格涨了再卖”的语境矛盾。"}, "sentence_index": 6, "correct_answer": "证券"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "进门前要出示证券，门口的人才会放你进去。", "explanation": "这里应该用〈门票〉。门票是入场凭证，证券指股票、债券等有价凭证，不能用来入场。"}, {"text": "退货时要带上证券，商店才会给你退钱。", "explanation": "这里应该用〈收据〉。收据是付款凭证，证券指股票、债券，不能用来办理退货。"}, {"text": "买完东西要保存好证券，以后可能需要报销。", "explanation": "这里应该用〈发票〉。发票是购物凭证，证券指股票、债券，不能用来报销。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d6d4d56-8f24-4af4-9609-d7826352ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87096, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把这证券卖了。", "corrected_sentence": "她把这张证券卖了。", "error_description": "量词漏用。“证券”前面用指示代词“这”时，中间要加量词“张”，应说“这张证券”，不能说“这证券”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d6d4d56-8f24-4af4-9609-d7826352ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87096, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把证券卖。", "corrected_sentence": "他把证券卖了。", "error_description": "“把”字句的动词不能单独出现，后面要有“了”等成分。错误形式：把证券卖；正确形式：把证券卖了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d6d4d56-8f24-4af4-9609-d7826352ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
