INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87097, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "小跑是不太快地、一小步一小步地跑。", "primary_collocate": null, "pronunciation": "xiǎo pǎo", "ipa": "ɕi̯ɑʊ̯˨˩˦ pʰɑʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "他看到老师，就小跑着过去了。", "target_word": "小跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天早上在公园小跑二十分钟。", "target_word": "小跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，大家小跑回家。", "target_word": "小跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子小跑到妈妈身边。", "target_word": "小跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她穿着高跟鞋，只能小跑几步。", "target_word": "小跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服务员小跑着给客人送水。", "target_word": "小跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们慢慢走，不用小跑。", "target_word": "小跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他小跑了一会儿，就停下来喝水。", "target_word": "小跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公交车快来了，我小跑去车站。", "target_word": "小跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗在前面小跑，我在后面走。", "target_word": "小跑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "小跑了", "label": "体标"}, {"form": "小跑着", "label": "体标"}, {"form": "小跑过", "label": "体标"}], "register": "中性", "sense_fingerprint": "小跑：步子小、速度不太快地跑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e2e0b30-a3a1-4ae4-9be1-ab2c143552df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87097, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小跑", "is_correct": true, "explanation": "小跑着过去，指步子小、不太快地去，与「就」的动作相配，是正确选项。"}, {"text": "躺", "is_correct": false, "explanation": "语义：「躺」指身体平放，不能表示移动着过去。"}, {"text": "讨论", "is_correct": false, "explanation": "语义：「讨论」是说话交流，不是移动的方式，不能和「着过去」连用。"}, {"text": "睡", "is_correct": false, "explanation": "语义：「睡」表示入睡，不能表示移动着过去。"}], "explanations": {"小跑": "小跑着过去，指步子小、不太快地去，与「就」的动作相配，是正确选项。", "躺": "语义：「躺」指身体平放，不能表示移动着过去。", "讨论": "语义：「讨论」是说话交流，不是移动的方式，不能和「着过去」连用。", "睡": "语义：「睡」表示入睡，不能表示移动着过去。"}, "sentence_index": 0, "correct_answer": "小跑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "比赛最后一圈，他小跑冲向终点。", "explanation": "这里应该用〈奔跑〉。小跑步子小、速度不快，冲向终点的急速动作要用奔跑。"}, {"text": "汽车在高速公路上小跑。", "explanation": "这里应该用〈疾驰〉。小跑指人或动物步子小、速度不快地跑，不用来形容汽车行驶。"}, {"text": "消防员接到报警，小跑到火场。", "explanation": "这里应该用〈飞奔〉。小跑速度慢，出警救火这种紧急情况要用飞奔。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c04a5e88-a9db-40ab-b6be-305f6e0ac38a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87097, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小跑", "is_correct": true, "explanation": "「不用小跑」指不必跑得那么快，与「慢慢走」相配，是正确选项。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：「睡觉」与「慢慢走」的情境无关，「不用睡觉」在这里说不通。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：「游泳」需要水域，与「慢慢走」的情境不相关，句子说不通。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：「跳舞」与「慢慢走」的情境不相关，不是走路的一种方式。"}], "explanations": {"小跑": "「不用小跑」指不必跑得那么快，与「慢慢走」相配，是正确选项。", "睡觉": "语义：「睡觉」与「慢慢走」的情境无关，「不用睡觉」在这里说不通。", "游泳": "语义：「游泳」需要水域，与「慢慢走」的情境不相关，句子说不通。", "跳舞": "语义：「跳舞」与「慢慢走」的情境不相关，不是走路的一种方式。"}, "sentence_index": 6, "correct_answer": "小跑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "最后十米，他全力小跑。", "explanation": "这里应该用〈冲刺〉。小跑步子小、速度不快，与「全力」的意思相反。"}, {"text": "他参加了百米小跑，拿了冠军。", "explanation": "这里应该用〈赛跑〉。小跑不是比赛项目，参加百米比赛要用赛跑。"}, {"text": "小猫一下小跑上了树。", "explanation": "这里应该用〈蹿〉。小跑是在地面上步子小地跑，不能用来说小猫向上窜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c04a5e88-a9db-40ab-b6be-305f6e0ac38a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87097, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他小跑超市买牛奶。", "corrected_sentence": "他小跑去超市买牛奶。", "error_description": "错误在于漏掉了「去」。「小跑」后面要接表示去向的「去」，应说「小跑去超市」，不能直接说「小跑超市」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c04a5e88-a9db-40ab-b6be-305f6e0ac38a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87097, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们小跑的穿过操场。", "corrected_sentence": "孩子们小跑着穿过操场。", "error_description": "错误在于「的」误用。表示动作进行的状态要用「着」，应说「小跑着穿过」，不能用「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c04a5e88-a9db-40ab-b6be-305f6e0ac38a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
