INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87098, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "以较小的步子、不太快的速度跑。", "primary_collocate": null, "pronunciation": "xiǎo pǎo", "ipa": "ɕi̯ɑʊ̯˨˩˦ pʰɑʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "老人每天晚上小跑一圈，身体很好。", "target_word": "小跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛前，运动员先小跑热身。", "target_word": "小跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他怕累，所以不快跑，只是小跑。", "target_word": "小跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她提着包，小跑着走进教室。", "target_word": "小跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我小跑了五分钟，出了一身汗。", "target_word": "小跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小马在草地上小跑，很可爱。", "target_word": "小跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，每天小跑比快跑更适合你。", "target_word": "小跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看见红灯变绿，小男孩小跑过马路。", "target_word": "小跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们小跑着去操场上体育课。", "target_word": "小跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他迟到了，只好一路小跑。", "target_word": "小跑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "小跑了", "label": "体标"}, {"form": "小跑着", "label": "体标"}, {"form": "小跑过", "label": "体标"}], "register": "中性", "sense_fingerprint": "小跑：小步、中慢速度地跑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e2e0b30-a3a1-4ae4-9be1-ab2c143552df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87098, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小跑", "is_correct": true, "explanation": "小跑一圈指步子小、不太快地跑一圈，与「每天晚上」的锻炼相配，是正确选项。"}, {"text": "躺", "is_correct": false, "explanation": "语义：「躺」指身体平放，不能表示绕着走一圈的锻炼。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」需要食物作宾语，不能说「吃一圈」。"}, {"text": "讨论", "is_correct": false, "explanation": "配价：「讨论」需要话题作宾语，不能直接跟「一圈」。"}], "explanations": {"小跑": "小跑一圈指步子小、不太快地跑一圈，与「每天晚上」的锻炼相配，是正确选项。", "躺": "语义：「躺」指身体平放，不能表示绕着走一圈的锻炼。", "吃": "搭配：「吃」需要食物作宾语，不能说「吃一圈」。", "讨论": "配价：「讨论」需要话题作宾语，不能直接跟「一圈」。"}, "sentence_index": 0, "correct_answer": "小跑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "猎豹在草原上小跑，速度惊人。", "explanation": "这里应该用〈狂奔〉。小跑指以较小的步子、不太快地跑，与“速度惊人”相反；猎豹飞速跑动要用狂奔。"}, {"text": "救护车小跑而来，响着警笛。", "explanation": "这里应该用〈疾驰〉。小跑速度慢，不用来形容救护车等车辆快速行驶。"}, {"text": "运动员听到发令枪，小跑出发。", "explanation": "这里应该用〈飞奔〉。小跑速度慢，听到发令枪的起跑要用飞奔。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c04a5e88-a9db-40ab-b6be-305f6e0ac38a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87098, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小跑", "is_correct": true, "explanation": "每天小跑比快跑更适合你，指步子小、不太快的跑，是正确选项。"}, {"text": "狂奔", "is_correct": false, "explanation": "语义：「狂奔」指猛跑、不顾一切地跑，与医生建议的温和锻炼相反，不能说每天狂奔更适合你。"}, {"text": "吸烟", "is_correct": false, "explanation": "语义：「吸烟」有损健康，与医生建议「更适合你」的说法矛盾。"}, {"text": "买", "is_correct": false, "explanation": "配价：「买」需要所买之物作宾语，「每天买」后不能直接接「比快跑更适合你」。"}], "explanations": {"小跑": "每天小跑比快跑更适合你，指步子小、不太快的跑，是正确选项。", "狂奔": "语义：「狂奔」指猛跑、不顾一切地跑，与医生建议的温和锻炼相反，不能说每天狂奔更适合你。", "吸烟": "语义：「吸烟」有损健康，与医生建议「更适合你」的说法矛盾。", "买": "配价：「买」需要所买之物作宾语，「每天买」后不能直接接「比快跑更适合你」。"}, "sentence_index": 6, "correct_answer": "小跑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他快要输了，拼命小跑。", "explanation": "这里应该用〈冲刺〉。小跑速度不快，与「拼命」的紧张发力不符，要说冲刺。"}, {"text": "百米比赛中，他小跑出了世界纪录。", "explanation": "这里应该用〈飞奔〉。小跑步子小、速度不快，百米比赛创纪录需要全速飞奔。"}, {"text": "小猫一下小跑上了树。", "explanation": "这里应该用〈蹿〉。小跑是在地面上步子小地跑，不能用来说小猫向上窜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c04a5e88-a9db-40ab-b6be-305f6e0ac38a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87098, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈下班后小跑的去接孩子。", "corrected_sentence": "妈妈下班后小跑着去接孩子。", "error_description": "错误在于「的」误用。表示动作进行的状态要用「着」，应说「小跑着去」，不能用「的」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c04a5e88-a9db-40ab-b6be-305f6e0ac38a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87098, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他小时候常常小跑了过这条小路。", "corrected_sentence": "他小时候常常小跑过这条小路。", "error_description": "错误在于「了」与「过」叠用。这里的「过」表示经过这条小路，动词后不能再加「了」，应说「小跑过这条小路」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c04a5e88-a9db-40ab-b6be-305f6e0ac38a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
