INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87099, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "财政是国家怎么收钱、怎么花钱的事。", "primary_collocate": null, "pronunciation": "cái zhèng", "ipa": "tsʰai˧˥ ʈʂəŋ˥˩", "syllable_count": 2, "sentences": [{"text": "国家的财政要公开给大家看。", "target_word": "财政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个县的财政比去年好多了。", "target_word": "财政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "税收是政府财政的主要来源。", "target_word": "财政", "complexity_tier": "T3", "furigana": "shuìshōu shì zhèngfǔ cáizhèng de zhǔyào láiyuán.", "sentence_source": "generated"}, {"text": "财政出了问题，工资就发不了。", "target_word": "财政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥在政府做财政工作。", "target_word": "财政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校要学习国家的财政知识。", "target_word": "财政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家财政的钱不能乱花。", "target_word": "财政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "财政好了，路和学校都能多修。", "target_word": "财政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们正在讨论明年的财政。", "target_word": "财政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几年地方财政一直很稳。", "target_word": "财政", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "財政", "label": "繁体"}, {"form": "财政部", "label": "复合"}, {"form": "财政支出", "label": "复合"}], "register": "书面", "sense_fingerprint": "国家收钱和花钱的事务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72d39edd-56d4-44c7-b5fd-93bb63a43a9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87099, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "财政", "is_correct": true, "explanation": "财政：国家怎么收钱、怎么花钱的事，「国家的财政要公开给大家看」符合句意。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：“鞋子”是穿在脚上的物品，不是需要公开给大家看的国家事务，句意不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”是自然物，与国家收支无关，“国家的石头要公开给大家看”说不通。"}, {"text": "被子", "is_correct": false, "explanation": "语义：“被子”是日常用品，不是需要公开的国家事务，句意不通。"}], "explanations": {"财政": "财政：国家怎么收钱、怎么花钱的事，「国家的财政要公开给大家看」符合句意。", "鞋子": "语义：“鞋子”是穿在脚上的物品，不是需要公开给大家看的国家事务，句意不通。", "石头": "语义：“石头”是自然物，与国家收支无关，“国家的石头要公开给大家看”说不通。", "被子": "语义：“被子”是日常用品，不是需要公开的国家事务，句意不通。"}, "sentence_index": 0, "correct_answer": "财政"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每年都要交很多财政。", "explanation": "这里应该用〈税〉。财政指国家收钱和花钱的事，个人每年交的钱是“税”，不能说“交财政”。"}, {"text": "政府财政了贫困学生。", "explanation": "这里应该用〈资助〉。“财政”不作动词，表示给人经济帮助要用〈资助〉。"}, {"text": "他把钱财政进了银行。", "explanation": "这里应该用〈存〉。“财政”不能表示把钱存入银行，应说“存进银行”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7aa74082-3c8b-4a38-b801-f88e0d556f49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87099, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "财政", "is_correct": true, "explanation": "财政：国家怎么收钱、怎么花钱的事，「国家财政的钱不能乱花」符合句意。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：“海洋”是自然地理概念，与花钱无关，“国家海洋不能花得太多”说不通。"}, {"text": "课文", "is_correct": false, "explanation": "语义：“课文”是课本里的文章，不是可以花的东西，句意不通。"}, {"text": "心情", "is_correct": false, "explanation": "语义：“心情”是感受，不是国家收支的事，“国家心情的钱”说不通。"}], "explanations": {"财政": "财政：国家怎么收钱、怎么花钱的事，「国家财政的钱不能乱花」符合句意。", "海洋": "语义：“海洋”是自然地理概念，与花钱无关，“国家海洋不能花得太多”说不通。", "课文": "语义：“课文”是课本里的文章，不是可以花的东西，句意不通。", "心情": "语义：“心情”是感受，不是国家收支的事，“国家心情的钱”说不通。"}, "sentence_index": 6, "correct_answer": "财政"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "房东退还了我的财政。", "explanation": "这里应该用〈押金〉。财政指国家收钱和花钱的事，房东退还的个人保证金要用〈押金〉。"}, {"text": "他持有公司的财政。", "explanation": "这里应该用〈股份〉。财政指国家收钱和花钱的事，公司的所有权份额要用〈股份〉。"}, {"text": "他的财政发下来了。", "explanation": "这里应该用〈工资〉。财政指国家收钱和花钱的事，个人的薪水要用〈工资〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7aa74082-3c8b-4a38-b801-f88e0d556f49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87099, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府每年都要公布财政得情况。", "corrected_sentence": "政府每年都要公布财政的情况。", "error_description": "结构助词误用：修饰「情况」的成分应用「的」，「得」用于补语，不能说「财政得情况」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7aa74082-3c8b-4a38-b801-f88e0d556f49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87099, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在学习国家得财政制度。", "corrected_sentence": "他在学习国家的财政制度。", "error_description": "“财政制度”前的修饰成分要用结构助词“的”，“得”用于补语，不能说“国家得财政制度”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7aa74082-3c8b-4a38-b801-f88e0d556f49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87101, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "大量", "is_correct": true, "explanation": "与“少量”构成反义关系，指数量很多。"}, {"text": "清楚", "is_correct": false, "explanation": "形容词，但与“少量”没有反义关系，二者意思没有对立。"}, {"text": "遥远", "is_correct": false, "explanation": "形容词，说距离远，与“少量”的数量概念无关，不是反义词。"}, {"text": "热烈", "is_correct": false, "explanation": "形容词，说情绪或气氛高涨，与“少量”的数量概念无关，不是反义词。"}], "correct_answer": "大量", "explanations": {"大量": "与“少量”构成反义关系，指数量很多。", "清楚": "形容词，但与“少量”没有反义关系，二者意思没有对立。", "遥远": "形容词，说距离远，与“少量”的数量概念无关，不是反义词。", "热烈": "形容词，说情绪或气氛高涨，与“少量”的数量概念无关，不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc2cb3a-f83b-43d7-aa27-b62ea45c5931') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87101, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "大量", "is_correct": true, "explanation": "与“少量”构成反义关系，指数量很多。"}, {"text": "明亮", "is_correct": false, "explanation": "形容词，说光线或颜色亮，与“少量”的数量概念无关，不是反义词。"}, {"text": "寒冷", "is_correct": false, "explanation": "形容词，说温度低，与“少量”没有反义关系。"}, {"text": "柔软", "is_correct": false, "explanation": "形容词，说质地软，与“少量”的数量概念无关，不是反义词。"}], "correct_answer": "大量", "explanations": {"大量": "与“少量”构成反义关系，指数量很多。", "明亮": "形容词，说光线或颜色亮，与“少量”的数量概念无关，不是反义词。", "寒冷": "形容词，说温度低，与“少量”没有反义关系。", "柔软": "形容词，说质地软，与“少量”的数量概念无关，不是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc2cb3a-f83b-43d7-aa27-b62ea45c5931') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87101, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "少量是只有一点点，不多。", "primary_collocate": null, "pronunciation": "shǎo liàng", "ipa": "ʂau˨˩ ljaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "瓶子里只剩下少量牛奶了。", "target_word": "少量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请给我少量米饭，我吃不多。", "target_word": "少量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花只需要少量的水。", "target_word": "少量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面包里加少量黄油，会更香。", "target_word": "少量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他只带了少量行李去旅行。", "target_word": "少量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少量的灰尘不会有问题。", "target_word": "少量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在茶里放了少量蜂蜜。", "target_word": "少量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个班只有少量学生会说法语。", "target_word": "少量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里只有少量的光。", "target_word": "少量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们只要买少量菜，晚上两个人吃。", "target_word": "少量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "少量的", "label": "的字结构"}], "register": "中性", "sense_fingerprint": "只有一点点，不多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20e95692-f9f1-4226-adcd-b55c18dffb26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87101, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大量", "is_correct": false, "explanation": "语义：“只剩下”限定剩余很少，“大量”与之矛盾。"}, {"text": "少量", "is_correct": true, "explanation": "少量：表示只剩一点，与“只剩下”相配，是这里唯一合适的词。"}, {"text": "庞大", "is_correct": false, "explanation": "搭配：“庞大”形容体积或规模，不能修饰牛奶这样的液体量。"}, {"text": "巨量", "is_correct": false, "explanation": "语义：“只剩下”限定剩余很少，“巨量”指数量极大，二者矛盾。"}], "explanations": {"大量": "语义：“只剩下”限定剩余很少，“大量”与之矛盾。", "少量": "少量：表示只剩一点，与“只剩下”相配，是这里唯一合适的词。", "庞大": "搭配：“庞大”形容体积或规模，不能修饰牛奶这样的液体量。", "巨量": "语义：“只剩下”限定剩余很少，“巨量”指数量极大，二者矛盾。"}, "sentence_index": 0, "correct_answer": "少量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次投票中，他们是少量派。", "explanation": "这里应该用〈少数〉。〈少数派〉指人数较少的一方，少量只说东西的分量，不能用来指一派人。"}, {"text": "我们应该少量服从多数。", "explanation": "这里应该用〈少数〉。固定说法是〈少数服从多数〉，少量不能用在这个固定搭配里。"}, {"text": "会场里少量的观众挤得水泄不通。", "explanation": "这里与“挤得水泄不通”矛盾。“少量”只表示数量少，不能描述人多到挤满的场面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc2cb3a-f83b-43d7-aa27-b62ea45c5931') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87101, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "稀薄", "is_correct": false, "explanation": "搭配：“稀薄”多形容气体或浓度低的东西，不能修饰蜂蜜这样浓稠的液体。"}, {"text": "干燥", "is_correct": false, "explanation": "搭配：蜂蜜是液体，不能用“干燥”来形容。"}, {"text": "滚烫", "is_correct": false, "explanation": "语义：“滚烫”说的是温度，不能描述蜂蜜的分量，句中也没有温度的语境。"}, {"text": "少量", "is_correct": true, "explanation": "少量：表示加入的蜂蜜只有一点，是这里唯一合适的词。"}], "explanations": {"稀薄": "搭配：“稀薄”多形容气体或浓度低的东西，不能修饰蜂蜜这样浓稠的液体。", "干燥": "搭配：蜂蜜是液体，不能用“干燥”来形容。", "滚烫": "语义：“滚烫”说的是温度，不能描述蜂蜜的分量，句中也没有温度的语境。", "少量": "少量：表示加入的蜂蜜只有一点，是这里唯一合适的词。"}, "sentence_index": 6, "correct_answer": "少量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个指标少量地增加了一倍。", "explanation": "这里与“增加了一倍”矛盾。“少量”只说分量少，不能描述成倍的增长。"}, {"text": "这个地区住着很多少量民族。", "explanation": "这里应该用〈少数〉。固定说法是〈少数民族〉，少量不用来修饰民族。"}, {"text": "他少量的一次迟到被大家记住了。", "explanation": "这里应该用〈偶尔〉。少量说的是东西的数量，不用来修饰表示次数的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc2cb3a-f83b-43d7-aa27-b62ea45c5931') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87101, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我只买了少量个水果。", "corrected_sentence": "我只买了少量水果。", "error_description": "错误：“少量”后面多加了量词“个”。“少量”是形容词，直接修饰名词，不能再接量词。正确：去掉“个”，写作“少量水果”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc2cb3a-f83b-43d7-aa27-b62ea45c5931') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87101, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她往茶里加了少量个蜂蜜。", "corrected_sentence": "她往茶里加了少量蜂蜜。", "error_description": "错误：“少量”后面多加了量词“个”。“少量”是形容词，直接修饰名词，不能再接量词。正确：去掉“个”，写作“加了少量蜂蜜”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc2cb3a-f83b-43d7-aa27-b62ea45c5931') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87102, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "大量", "is_correct": true, "explanation": "与“少量”构成反义关系，指数量很多。"}, {"text": "清楚", "is_correct": false, "explanation": "形容词，但与“少量”没有反义关系，二者意思没有对立。"}, {"text": "遥远", "is_correct": false, "explanation": "形容词，说距离远，与“少量”的数量概念无关，不是反义词。"}, {"text": "热烈", "is_correct": false, "explanation": "形容词，说情绪或气氛高涨，与“少量”的数量概念无关，不是反义词。"}], "correct_answer": "大量", "explanations": {"大量": "与“少量”构成反义关系，指数量很多。", "清楚": "形容词，但与“少量”没有反义关系，二者意思没有对立。", "遥远": "形容词，说距离远，与“少量”的数量概念无关，不是反义词。", "热烈": "形容词，说情绪或气氛高涨，与“少量”的数量概念无关，不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc2cb3a-f83b-43d7-aa27-b62ea45c5931') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
