INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87102, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "数量很少的。", "primary_collocate": null, "pronunciation": "shǎo liàng", "ipa": "ʂau˨˩ ljaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "做菜时只要放少量盐就可以了。", "target_word": "少量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药只能吃少量，多了不好。", "target_word": "少量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上只有少量的水。", "target_word": "少量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汤里加入少量糖，味道更好。", "target_word": "少量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的银行卡里只存了少量的钱。", "target_word": "少量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天只有少量学生来上课。", "target_word": "少量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天只喝少量的咖啡。", "target_word": "少量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上还留着少量的雪。", "target_word": "少量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们只买了少量水果，很快就吃完了。", "target_word": "少量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里下了少量的雨，地还是干的。", "target_word": "少量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "少量的", "label": "的字结构"}], "register": "中性", "sense_fingerprint": "数量很少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20e95692-f9f1-4226-adcd-b55c18dffb26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87102, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大量", "is_correct": false, "explanation": "语义：“只要”限定用量很少，“大量”与之矛盾，做菜时不会只放大量盐。"}, {"text": "少量", "is_correct": true, "explanation": "少量：只放一点，与“只要”相配，是这里唯一合适的词。"}, {"text": "过量", "is_correct": false, "explanation": "语义：“过量”指超出适度，与“只要”强调用量少的意思冲突。"}, {"text": "巨量", "is_correct": false, "explanation": "语义：“只要”限定用量很少，“巨量”指数量极大，二者矛盾。"}], "explanations": {"大量": "语义：“只要”限定用量很少，“大量”与之矛盾，做菜时不会只放大量盐。", "少量": "少量：只放一点，与“只要”相配，是这里唯一合适的词。", "过量": "语义：“过量”指超出适度，与“只要”强调用量少的意思冲突。", "巨量": "语义：“只要”限定用量很少，“巨量”指数量极大，二者矛盾。"}, "sentence_index": 0, "correct_answer": "少量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次表决中，他们只是少量派。", "explanation": "这里应该用〈少数〉。〈少数派〉指人数较少的一方，少量只说东西的分量，不能用来指人组成的一派。"}, {"text": "会议上我们应该少量服从多数。", "explanation": "这里应该用〈少数〉。固定说法是〈少数服从多数〉，少量不能用在这个固定搭配里。"}, {"text": "少量的观众挤满了整个体育馆。", "explanation": "这里与“挤满了整个体育馆”矛盾。“少量”只表示数量少，不能描述人数众多的场面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc2cb3a-f83b-43d7-aa27-b62ea45c5931') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87102, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "充分", "is_correct": false, "explanation": "搭配：“充分”多修饰理由、条件、时间，不能修饰咖啡。"}, {"text": "多量", "is_correct": false, "explanation": "语域：“多量”偏书面，且与句中的“只”冲突，日常不说“只喝多量的咖啡”。"}, {"text": "无数", "is_correct": false, "explanation": "语义：“只”限定数量少，“无数”表示数量极多，与之矛盾。"}, {"text": "少量", "is_correct": true, "explanation": "少量：与“只”相配，表示只喝一点，是这里唯一合适的词。"}], "explanations": {"充分": "搭配：“充分”多修饰理由、条件、时间，不能修饰咖啡。", "多量": "语域：“多量”偏书面，且与句中的“只”冲突，日常不说“只喝多量的咖啡”。", "无数": "语义：“只”限定数量少，“无数”表示数量极多，与之矛盾。", "少量": "少量：与“只”相配，表示只喝一点，是这里唯一合适的词。"}, "sentence_index": 6, "correct_answer": "少量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个地区住着很多少量民族。", "explanation": "这里应该用〈少数〉。固定说法是〈少数民族〉，少量不用来修饰民族。"}, {"text": "这个数字少量地翻了一番。", "explanation": "这里与“翻了一番”矛盾。“少量”表示分量少，不能描述成倍的增长。"}, {"text": "他少量的一次迟到，大家都记住了。", "explanation": "这里应该用〈偶尔〉。少量说的是东西的数量，不用来修饰表示次数的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc2cb3a-f83b-43d7-aa27-b62ea45c5931') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
