INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87104, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "处理事务并使其完成；经手办事。", "primary_collocate": null, "pronunciation": "bàn lǐ", "ipa": "pan˥˩ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "请到三号窗口办理业务。", "target_word": "办理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在银行办理了新的银行卡。", "target_word": "办理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事由王经理负责办理。", "target_word": "办理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天要办理出国的手续。", "target_word": "办理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请带好身份证，我们帮您办理。", "target_word": "办理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办理这个业务大概需要半小时。", "target_word": "办理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她下午去办理住院手续了。", "target_word": "办理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机号码可以在网上办理。", "target_word": "办理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的事情他都办理得很好。", "target_word": "办理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些手续可以让朋友帮你办理。", "target_word": "办理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "办理了", "label": "体标"}, {"form": "办理过", "label": "体标"}, {"form": "辦理", "label": "繁体"}], "register": "正式", "sense_fingerprint": "办理：经手处理事务并使其完成", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a98bb113-2be5-474e-b481-0147080f3c58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87104, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "欣赏", "is_correct": false, "explanation": "语义：欣赏指品味美好的事物，不能用于“业务”。"}, {"text": "办理", "is_correct": true, "explanation": "正确。“办理业务”指经手处理业务并使其完成，符合窗口服务的语境。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”用于机器、物品，不说“修理业务”。"}, {"text": "游览", "is_correct": false, "explanation": "语义：游览指参观景点，不能用于办事的“业务”。"}], "explanations": {"欣赏": "语义：欣赏指品味美好的事物，不能用于“业务”。", "办理": "正确。“办理业务”指经手处理业务并使其完成，符合窗口服务的语境。", "修理": "搭配：“修理”用于机器、物品，不说“修理业务”。", "游览": "语义：游览指参观景点，不能用于办事的“业务”。"}, "sentence_index": 0, "correct_answer": "办理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器坏了，需要办理。", "explanation": "这里应该用〈修理〉。修理用于机器、物品，办理用于手续和业务，不能用于坏了的机器。"}, {"text": "这些垃圾需要尽快办理。", "explanation": "这里应该用〈处理〉。处理用于垃圾、问题，办理用于手续和业务。"}, {"text": "我们热情地办理了客人。", "explanation": "这里应该用〈招待〉。招待指接待宾客，办理用于手续和业务，不能用于人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c31f9a31-de21-4b9e-b3f4-0442fdf8b505') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87104, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”用于房间、场所，不说“打扫手续”。"}, {"text": "办理", "is_correct": true, "explanation": "正确。“办理住院手续”指经手办好住院的各项手续，符合语境。"}, {"text": "品尝", "is_correct": false, "explanation": "语义：品尝指尝味道，手续不能被品尝。"}, {"text": "背诵", "is_correct": false, "explanation": "语义：背诵指记住并说出文字内容，不能用于“手续”。"}], "explanations": {"打扫": "搭配：“打扫”用于房间、场所，不说“打扫手续”。", "办理": "正确。“办理住院手续”指经手办好住院的各项手续，符合语境。", "品尝": "语义：品尝指尝味道，手续不能被品尝。", "背诵": "语义：背诵指记住并说出文字内容，不能用于“手续”。"}, "sentence_index": 6, "correct_answer": "办理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生正在办理病人的身体。", "explanation": "这里应该用〈检查〉。检查用于病人的身体、物品，办理用于手续和业务。"}, {"text": "农民在田里办理庄稼。", "explanation": "这里应该用〈种植〉。种植用于庄稼、树木，办理用于手续和业务。"}, {"text": "妈妈正在厨房办理晚饭。", "explanation": "这里应该用〈做〉。做晚饭指烹制饭菜，办理用于手续和业务，不能用于饭菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c31f9a31-de21-4b9e-b3f4-0442fdf8b505') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87104, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把这些手续办理完着。", "corrected_sentence": "他把这些手续办理完了。", "error_description": "体标错误：“办理完”是已经完成的动作，应用“了”，不能用“着”（“着”表示动作持续或状态）。错误形式：办理完着；正确形式：办理完了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c31f9a31-de21-4b9e-b3f4-0442fdf8b505') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87104, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事他办理的很顺利。", "corrected_sentence": "这件事他办理得很顺利。", "error_description": "补语标记错误：动词后引出补语“很顺利”应用“得”，不能用“的”。错误形式：办理的很顺利；正确形式：办理得很顺利。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c31f9a31-de21-4b9e-b3f4-0442fdf8b505') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
