INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87105, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "集团军是很多兵合在一起的一大队伍。里面有好多小队伍。", "primary_collocate": null, "pronunciation": "jí tuán jūn", "ipa": "tɕi˧˥ tʰwan˧˥ tɕyn˥", "syllable_count": 3, "sentences": [{"text": "一个集团军里有很多兵。", "target_word": "集团军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个集团军有好多小队伍。", "target_word": "集团军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里出现了一支很大的集团军。", "target_word": "集团军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "集团军在山下休息着。", "target_word": "集团军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爷爷以前在集团军当兵。", "target_word": "集团军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "集团军里有很多师，每个师有很多人。", "target_word": "集团军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个集团军走了一整天的路。", "target_word": "集团军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上说，这个集团军有十万人。", "target_word": "集团军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看，一个集团军正走过桥。", "target_word": "集团军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "集团军比一个师大得多。", "target_word": "集团军", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "支", "label": "量词"}, {"form": "集团军司令", "label": "复合"}, {"form": "集團軍", "label": "繁体"}], "register": "中性", "sense_fingerprint": "许多士兵和小队伍合成的一支大队伍", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa2e5afa-4320-49bb-ab63-b0ef2a0774da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87105, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "集团军", "is_correct": true, "explanation": "集团军：许多兵合成的一大队伍，与“里有很多兵”相符。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是家电，里面不会有很多兵。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：“花瓶”是插花的器物，与“很多兵”不相合。"}, {"text": "饭碗", "is_correct": false, "explanation": "搭配：“饭碗”是盛饭的器具，不能用“一个……里有很多兵”来描述。"}], "explanations": {"集团军": "集团军：许多兵合成的一大队伍，与“里有很多兵”相符。", "冰箱": "语义：“冰箱”是家电，里面不会有很多兵。", "花瓶": "语义：“花瓶”是插花的器物，与“很多兵”不相合。", "饭碗": "搭配：“饭碗”是盛饭的器具，不能用“一个……里有很多兵”来描述。"}, "sentence_index": 0, "correct_answer": "集团军"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一个集团军。", "explanation": "这里应该用〈士兵〉。集团军指许多兵合成的大队伍，不能指一个人。"}, {"text": "这个集团军有四十个学生。", "explanation": "这里应该用〈班〉。集团军是军队中的大队伍，不能与“学生”搭配。"}, {"text": "集团军里有很多小鸟。", "explanation": "这里应该用〈鸟窝〉。集团军是由人组成的队伍，不能与“小鸟”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97a53332-e7ed-4493-b479-854c6d71a992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87105, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "集团军", "is_correct": true, "explanation": "集团军：由许多兵合成的大队伍，能够行军，与“走了一整天的路”相符。"}, {"text": "西瓜", "is_correct": false, "explanation": "语义：西瓜不会自己行走，不能作“走了一整天的路”的主语。"}, {"text": "电话", "is_correct": false, "explanation": "配价：“走路”要求能自行移动的主语，“电话”不能作施事。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有行走的能力，与“走了一整天的路”不相合。"}], "explanations": {"集团军": "集团军：由许多兵合成的大队伍，能够行军，与“走了一整天的路”相符。", "西瓜": "语义：西瓜不会自己行走，不能作“走了一整天的路”的主语。", "电话": "配价：“走路”要求能自行移动的主语，“电话”不能作施事。", "石头": "语义：石头没有行走的能力，与“走了一整天的路”不相合。"}, "sentence_index": 6, "correct_answer": "集团军"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "集团军在画室里画画。", "explanation": "这里应该用〈画家〉。集团军是军队，不能作“画画”的主语。"}, {"text": "这个集团军有很多叶子。", "explanation": "这里应该用〈树〉。集团军是许多兵组成的队伍，没有叶子这样的部分。"}, {"text": "这个集团军有三个窗户。", "explanation": "这里应该用〈房子〉。集团军不是建筑，没有窗户。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97a53332-e7ed-4493-b479-854c6d71a992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87105, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只集团军在山里行军。", "corrected_sentence": "一支集团军在山里行军。", "error_description": "“只”用于动物或零星小物件；集团军是一大队伍，应用量词“支”，应为“一支集团军”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97a53332-e7ed-4493-b479-854c6d71a992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87105, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一名集团军在山谷里扎营。", "corrected_sentence": "一支集团军在山谷里扎营。", "error_description": "“名”用于指人，集团军不是人，应用量词“支”，应为“一支集团军”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97a53332-e7ed-4493-b479-854c6d71a992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
