INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87106, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "军队的编制单位，由若干师、旅等部队合编而成，是战役层级的大型作战部队。", "primary_collocate": null, "pronunciation": "jí tuán jūn", "ipa": "tɕi˧˥ tʰwan˧˥ tɕyn˥", "syllable_count": 3, "sentences": [{"text": "这个集团军有三个师和两个旅。", "target_word": "集团军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "集团军司令正在检查部队。", "target_word": "集团军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第一集团军今天早上出发了。", "target_word": "集团军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战斗开始时，集团军向北边前进。", "target_word": "集团军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支集团军在战役中立了大功。", "target_word": "集团军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "集团军由几个师合编而成。", "target_word": "集团军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在集团军里工作了十年。", "target_word": "集团军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "集团军的指挥官制定了作战计划。", "target_word": "集团军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个集团军在河边会合了。", "target_word": "集团军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个集团军的任务是守住城市。", "target_word": "集团军", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "支", "label": "量词"}, {"form": "集团军司令", "label": "复合"}, {"form": "集團軍", "label": "繁体"}], "register": "书面", "sense_fingerprint": "由若干师旅合编的战役层级大型军队编制单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa2e5afa-4320-49bb-ab63-b0ef2a0774da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87106, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "集团军", "is_correct": true, "explanation": "集团军：军队的编制单位，由若干师、旅合编而成，与“三个师和两个旅”相符。"}, {"text": "学校", "is_correct": false, "explanation": "语义：“学校”不是军队编制，不能拥有“师”和“旅”。"}, {"text": "花园", "is_correct": false, "explanation": "语义：“花园”是供人观赏的场所，与“三个师和两个旅”不相符。"}, {"text": "乐队", "is_correct": false, "explanation": "搭配：“乐队”不以“师”“旅”作编制单位，这些词不与“乐队”搭配。"}], "explanations": {"集团军": "集团军：军队的编制单位，由若干师、旅合编而成，与“三个师和两个旅”相符。", "学校": "语义：“学校”不是军队编制，不能拥有“师”和“旅”。", "花园": "语义：“花园”是供人观赏的场所，与“三个师和两个旅”不相符。", "乐队": "搭配：“乐队”不以“师”“旅”作编制单位，这些词不与“乐队”搭配。"}, "sentence_index": 0, "correct_answer": "集团军"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个集团军每天卖很多面包。", "explanation": "这里应该用〈面包店〉。集团军是军队编制，不是卖东西的商店。"}, {"text": "我的叔叔是一个集团军。", "explanation": "这里应该用〈军官〉。集团军指军队编制，不能指一个人。"}, {"text": "这个集团军有五十个同学。", "explanation": "这里应该用〈班〉。集团军是军队编制，不能与“同学”这类成员搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97a53332-e7ed-4493-b479-854c6d71a992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87106, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "集团军", "is_correct": true, "explanation": "集团军：军队的编制单位，“在集团军里工作”指在部队任职，与语境相符。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是家电，不能作为“工作十年”的场所。"}, {"text": "鱼缸", "is_correct": false, "explanation": "语义：“鱼缸”是养鱼的容器，不能用来表示工作的地点。"}, {"text": "花盆", "is_correct": false, "explanation": "搭配：“花盆”是种花的器具，不能与“里工作”搭配。"}], "explanations": {"集团军": "集团军：军队的编制单位，“在集团军里工作”指在部队任职，与语境相符。", "冰箱": "语义：“冰箱”是家电，不能作为“工作十年”的场所。", "鱼缸": "语义：“鱼缸”是养鱼的容器，不能用来表示工作的地点。", "花盆": "搭配：“花盆”是种花的器具，不能与“里工作”搭配。"}, "sentence_index": 6, "correct_answer": "集团军"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民们在集团军里养了很多牛。", "explanation": "这里应该用〈农场〉。集团军是军队编制，不是养殖的场所。"}, {"text": "这个集团军每天生产五百台机器。", "explanation": "这里应该用〈工厂〉。集团军是军事单位，不是生产机器的单位。"}, {"text": "这个集团军有十层楼。", "explanation": "这里应该用〈大楼〉。集团军是军队编制，没有楼层。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97a53332-e7ed-4493-b479-854c6d71a992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87106, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "演习中，两只集团军同时出动了。", "corrected_sentence": "演习中，两支集团军同时出动了。", "error_description": "“只”用于动物或零星小物件；集团军是部队编制，应用量词“支”，应为“两支集团军”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97a53332-e7ed-4493-b479-854c6d71a992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87106, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一名集团军驻扎在北方。", "corrected_sentence": "一支集团军驻扎在北方。", "error_description": "“名”用于指人，集团军不是人，应用量词“支”，应为“一支集团军”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97a53332-e7ed-4493-b479-854c6d71a992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
