INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87108, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对批量生产的产品的外形、结构和功能进行构思与设计的工作。", "primary_collocate": null, "pronunciation": "gōng yè shè jì", "ipa": "kʊŋ˥ jɛ˥˩ ʂɤ˥˩ tɕi˥˩", "syllable_count": 4, "sentences": [{"text": "他大学学的是工业设计。", "target_word": "工业设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工业设计要考虑产品好不好用。", "target_word": "工业设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把椅子是工业设计的好例子。", "target_word": "工业设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她毕业后做工业设计，每天画图。", "target_word": "工业设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的工业设计让手机更好看，也更好用。", "target_word": "工业设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的工业设计很有名。", "target_word": "工业设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工业设计要先想好产品的外形和功能。", "target_word": "工业设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥想学工业设计，以后设计汽车。", "target_word": "工业设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的工业设计作品得了大奖。", "target_word": "工业设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做工业设计，也要想工厂怎么生产。", "target_word": "工业设计", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "工业设计师", "label": "复合"}], "register": "中性", "sense_fingerprint": "对批量产品的外形、结构、功能做构思设计的工作或专业", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96df1d2b-98d4-4058-aa95-b548c2ba3b98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87108, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厨房", "is_correct": false, "explanation": "语义：厨房是地点，不是大学里学习的专业。"}, {"text": "工业设计", "is_correct": true, "explanation": "这里指学习的专业。“学的是”后接学科名称，符合语境。"}, {"text": "饭菜", "is_correct": false, "explanation": "搭配：“学的是”后接的应是学科或技能，“饭菜”不能这样搭配（可说“学做饭菜”）。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是一种疾病，不是可以学习的内容。"}], "explanations": {"厨房": "语义：厨房是地点，不是大学里学习的专业。", "工业设计": "这里指学习的专业。“学的是”后接学科名称，符合语境。", "饭菜": "搭配：“学的是”后接的应是学科或技能，“饭菜”不能这样搭配（可说“学做饭菜”）。", "感冒": "语义：感冒是一种疾病，不是可以学习的内容。"}, "sentence_index": 0, "correct_answer": "工业设计"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这栋房子的工业设计很好。", "explanation": "这里应该用〈装修〉。工业设计指对批量生产的产品进行外形、结构和功能的设计，房子不是批量生产的产品，说房屋的室内布置要用〈装修〉。"}, {"text": "这位老人的工业设计很好。", "explanation": "这里应该用〈手艺〉。工业设计针对批量生产的产品，老人的手工技艺不属于此，要用〈手艺〉。"}, {"text": "她毕业后负责这次活动的工业设计，每天开会。", "explanation": "这里应该用〈策划〉。工业设计针对批量生产产品的外形、结构和功能，活动的安排和方案要用〈策划〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bde90eb-7d60-4472-9330-89734b4b836e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87108, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "配价：“想好……”需要有意识的施事，“天气”不能充当这里的主语。"}, {"text": "水泥", "is_correct": false, "explanation": "语义：水泥是建筑材料，不能构思产品的外形和功能。"}, {"text": "工业设计", "is_correct": true, "explanation": "指对产品外形和功能进行构思的工作，作主语，符合语境。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是自然物，无法构思产品的外形和功能。"}], "explanations": {"天气": "配价：“想好……”需要有意识的施事，“天气”不能充当这里的主语。", "水泥": "语义：水泥是建筑材料，不能构思产品的外形和功能。", "工业设计": "指对产品外形和功能进行构思的工作，作主语，符合语境。", "石头": "语义：石头是自然物，无法构思产品的外形和功能。"}, "sentence_index": 6, "correct_answer": "工业设计"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件木雕的工业设计很精细。", "explanation": "这里应该用〈雕刻〉。工业设计是为批量生产的产品设计外形和功能，手工雕刻不属于此，要用〈雕刻〉。"}, {"text": "他的工业设计很动听。", "explanation": "这里应该用〈作曲〉。工业设计指对产品外形、结构和功能的设计，不能用来形容音乐作品，要用〈作曲〉。"}, {"text": "这场演出的工业设计很精彩。", "explanation": "这里应该用〈舞台设计〉。工业设计针对批量生产的产品，演出的舞台布置要用〈舞台设计〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bde90eb-7d60-4472-9330-89734b4b836e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87108, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的毕业作品是一座工业设计。", "corrected_sentence": "他的毕业作品是一项工业设计。", "error_description": "量词错误：“座”用于山、楼等大型固定的物体，工业设计应用量词“项”，应说“一项工业设计”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bde90eb-7d60-4472-9330-89734b4b836e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87108, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这幅工业设计获得了金奖。", "corrected_sentence": "这项工业设计获得了金奖。", "error_description": "量词错误：“幅”用于画作，工业设计应用量词“项”，应说“这项工业设计”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bde90eb-7d60-4472-9330-89734b4b836e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87109, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "简单", "is_correct": true, "explanation": "反义：“麻烦”指事情不好做、费力，“简单”指不费力，二者相反。"}, {"text": "漂亮", "is_correct": false, "explanation": "与“麻烦”在词义上没有反义关系，“漂亮”形容外貌。"}, {"text": "聪明", "is_correct": false, "explanation": "与“麻烦”在词义上没有反义关系，“聪明”形容人的智力。"}, {"text": "干净", "is_correct": false, "explanation": "与“麻烦”在词义上没有反义关系，“干净”形容清洁。"}], "correct_answer": "简单", "explanations": {"简单": "反义：“麻烦”指事情不好做、费力，“简单”指不费力，二者相反。", "漂亮": "与“麻烦”在词义上没有反义关系，“漂亮”形容外貌。", "聪明": "与“麻烦”在词义上没有反义关系，“聪明”形容人的智力。", "干净": "与“麻烦”在词义上没有反义关系，“干净”形容清洁。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87109, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "简单", "is_correct": true, "explanation": "反义：“麻烦”指事情不好做、费力，“简单”指不费力，二者相反。"}, {"text": "明亮", "is_correct": false, "explanation": "与“麻烦”在词义上没有反义关系，“明亮”形容光线或颜色。"}, {"text": "结实", "is_correct": false, "explanation": "与“麻烦”在词义上没有反义关系，“结实”形容物体坚固。"}, {"text": "整齐", "is_correct": false, "explanation": "与“麻烦”在词义上没有反义关系，“整齐”形容排列有序。"}], "correct_answer": "简单", "explanations": {"简单": "反义：“麻烦”指事情不好做、费力，“简单”指不费力，二者相反。", "明亮": "与“麻烦”在词义上没有反义关系，“明亮”形容光线或颜色。", "结实": "与“麻烦”在词义上没有反义关系，“结实”形容物体坚固。", "整齐": "与“麻烦”在词义上没有反义关系，“整齐”形容排列有序。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87109, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "麻烦是一件事不好做，要花很多力气。", "primary_collocate": null, "pronunciation": "má fan", "ipa": "ma˧˥ fan", "syllable_count": 2, "sentences": [{"text": "这件事不好做，要花很多力气，真麻烦。", "target_word": "麻烦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗这么多衣服，又要用手洗，太麻烦了。", "target_word": "麻烦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家要打包、搬箱子、再整理，非常麻烦。", "target_word": "麻烦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道菜要洗、切、炒，做起来很麻烦。", "target_word": "麻烦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个一个地数，真麻烦，我们用机器吧。", "target_word": "麻烦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修这台旧机器很麻烦，不如买台新的。", "target_word": "麻烦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把这些东西一件一件搬上楼，实在麻烦。", "target_word": "麻烦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手写这么多信太麻烦，我想用电脑打。", "target_word": "麻烦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他觉得种花很麻烦，每天都要浇水、除草。", "target_word": "麻烦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法太麻烦了，有没有简单一点的？", "target_word": "麻烦", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "麻煩", "label": "繁体"}, {"form": "麻烦事", "label": "复合"}], "register": "口语", "sense_fingerprint": "形容做事步骤多、不好做、费力气", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08020456-83a6-4525-94f5-4b11f7843608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87109, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "麻烦", "is_correct": true, "explanation": "正确：“麻烦”表示事情不好做、要花力气，与句意相符。"}, {"text": "简单", "is_correct": false, "explanation": "语义：“简单”与“不好做、要花很多力气”的句意相反，读起来矛盾。"}, {"text": "轻松", "is_correct": false, "explanation": "语义：“轻松”表示不费力，与“要花很多力气”矛盾。"}, {"text": "漂亮", "is_correct": false, "explanation": "搭配：“漂亮”形容外貌或表现，不用来评价做事的难度。"}], "explanations": {"麻烦": "正确：“麻烦”表示事情不好做、要花力气，与句意相符。", "简单": "语义：“简单”与“不好做、要花很多力气”的句意相反，读起来矛盾。", "轻松": "语义：“轻松”表示不费力，与“要花很多力气”矛盾。", "漂亮": "搭配：“漂亮”形容外貌或表现，不用来评价做事的难度。"}, "sentence_index": 0, "correct_answer": "麻烦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这支笔麻烦得很，写字很流畅。", "explanation": "这里应该用〈方便〉。“麻烦”表示事情费力，与“写字很流畅”矛盾；形容好用的东西应说“方便”。"}, {"text": "他的成绩很麻烦，考了满分。", "explanation": "这里应该用〈优秀〉。“麻烦”说事情费力，不能用来形容成绩；评价成绩应说“优秀”。"}, {"text": "这件事很麻烦，我三分钟就做完了。", "explanation": "这里应该用〈简单〉。“麻烦”表示费力，与“三分钟就做完”矛盾；应说“简单”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87109, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "麻烦", "is_correct": true, "explanation": "正确：句子说一件件搬东西很费力，“麻烦”表示抱怨费事，符合句意。"}, {"text": "凉快", "is_correct": false, "explanation": "语义：“凉快”说天气舒服，与一件件搬东西的费力情景矛盾。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”形容体型，不能用来评价搬东西的事。"}, {"text": "被", "is_correct": false, "explanation": "语法：“被”是介词，后面要接施事和动词，“实在被”不成句。"}], "explanations": {"麻烦": "正确：句子说一件件搬东西很费力，“麻烦”表示抱怨费事，符合句意。", "凉快": "语义：“凉快”说天气舒服，与一件件搬东西的费力情景矛盾。", "胖": "体貌：“胖”形容体型，不能用来评价搬东西的事。", "被": "语法：“被”是介词，后面要接施事和动词，“实在被”不成句。"}, "sentence_index": 6, "correct_answer": "麻烦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道菜很麻烦，洗一下就能吃。", "explanation": "这里应该用〈简单〉。“麻烦”表示费力，与“洗一下就能吃”矛盾；应说“简单”。"}, {"text": "他的画很麻烦，画得很好看。", "explanation": "这里应该用〈精美〉。“麻烦”说事情费力，不能用来赞美画作；应说“精美”。"}, {"text": "这份工作很麻烦，他每天都很轻松地完成。", "explanation": "这里应该用〈轻松〉。“麻烦”表示费力，与“很轻松地完成”矛盾；应说“轻松”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87109, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "算这些账很麻烦了我。", "corrected_sentence": "算这些账很麻烦。", "error_description": "错误：形容词“麻烦”（费事）不能带宾语“我”，应删去“了我”，说“算这些账很麻烦”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87109, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "整理这些资料麻烦很得。", "corrected_sentence": "整理这些资料麻烦得很。", "error_description": "错误：程度补语“得”与“很”的位置颠倒。“得”要接在形容词后面，表示程度，应说“麻烦得很”，改为“整理这些资料麻烦得很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87110, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "方便", "is_correct": true, "explanation": "反义：“麻烦”指条件不便、办起来费事，“方便”指便利，二者相反。"}, {"text": "漂亮", "is_correct": false, "explanation": "与“麻烦”在词义上没有反义关系，“漂亮”形容外貌。"}, {"text": "聪明", "is_correct": false, "explanation": "与“麻烦”在词义上没有反义关系，“聪明”形容人的智力。"}, {"text": "干净", "is_correct": false, "explanation": "与“麻烦”在词义上没有反义关系，“干净”形容清洁。"}], "correct_answer": "方便", "explanations": {"方便": "反义：“麻烦”指条件不便、办起来费事，“方便”指便利，二者相反。", "漂亮": "与“麻烦”在词义上没有反义关系，“漂亮”形容外貌。", "聪明": "与“麻烦”在词义上没有反义关系，“聪明”形容人的智力。", "干净": "与“麻烦”在词义上没有反义关系，“干净”形容清洁。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
