INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87110, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "烦琐费事；不方便。", "primary_collocate": null, "pronunciation": "má fan", "ipa": "ma˧˥ fan", "syllable_count": 2, "sentences": [{"text": "办这个手续要跑好几个地方，真麻烦。", "target_word": "麻烦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家离地铁站很远，出门有点麻烦。", "target_word": "麻烦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上买东西不用出门，一点也不麻烦。", "target_word": "麻烦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要填五张表，还要盖三个章，太麻烦了。", "target_word": "麻烦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里没有电梯，搬东西上楼很麻烦。", "target_word": "麻烦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每次换车都要重新买票，实在麻烦。", "target_word": "麻烦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手续这么麻烦，难怪大家都不想办。", "target_word": "麻烦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上不通电，用手机充电也很麻烦。", "target_word": "麻烦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在有了手机支付，付钱不再麻烦了。", "target_word": "麻烦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出国办签证很麻烦，要准备很多材料。", "target_word": "麻烦", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "麻煩", "label": "繁体"}, {"form": "麻烦事", "label": "复合"}], "register": "口语", "sense_fingerprint": "形容手续烦琐、条件不便、办起来费事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08020456-83a6-4525-94f5-4b11f7843608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87110, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "麻烦", "is_correct": true, "explanation": "正确：“麻烦”表示手续繁琐、办起来费事，与“要跑好几个地方”相符。"}, {"text": "方便", "is_correct": false, "explanation": "语义：“方便”表示省事，与“要跑好几个地方”的抱怨矛盾。"}, {"text": "省事", "is_correct": false, "explanation": "语义：“省事”表示不费事，与句中要跑好几个地方的情况矛盾。"}, {"text": "精彩", "is_correct": false, "explanation": "搭配：“精彩”多用于表演、比赛，不用来评价办手续。"}], "explanations": {"麻烦": "正确：“麻烦”表示手续繁琐、办起来费事，与“要跑好几个地方”相符。", "方便": "语义：“方便”表示省事，与“要跑好几个地方”的抱怨矛盾。", "省事": "语义：“省事”表示不费事，与句中要跑好几个地方的情况矛盾。", "精彩": "搭配：“精彩”多用于表演、比赛，不用来评价办手续。"}, "sentence_index": 0, "correct_answer": "麻烦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器很麻烦，一按按钮就好了。", "explanation": "这里应该用〈方便〉。“麻烦”表示手续繁琐、不便，与“一按按钮就好”矛盾；形容省事应说“方便”。"}, {"text": "这家店很麻烦，买东西只要两分钟。", "explanation": "这里应该用〈便利〉。“麻烦”表示不方便，与“只要两分钟”矛盾；形容购物省事应说“便利”。"}, {"text": "这条路很麻烦，我骑车十分钟就到了。", "explanation": "这里应该用〈近〉。“麻烦”表示不方便，与“骑车十分钟就到”矛盾；说距离近应说“近”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87110, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "麻烦", "is_correct": true, "explanation": "正确：“手续这么麻烦”表示手续繁琐，与“大家都不想办”的因果相符。"}, {"text": "痛快", "is_correct": false, "explanation": "语义：“痛快”表示顺利爽快，与“难怪大家都不想办”的因果矛盾。"}, {"text": "干净", "is_correct": false, "explanation": "语义：“干净”形容清洁，不用来评价手续的繁简。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”形容味道，不能用来评价手续。"}], "explanations": {"麻烦": "正确：“手续这么麻烦”表示手续繁琐，与“大家都不想办”的因果相符。", "痛快": "语义：“痛快”表示顺利爽快，与“难怪大家都不想办”的因果矛盾。", "干净": "语义：“干净”形容清洁，不用来评价手续的繁简。", "甜": "搭配：“甜”形容味道，不能用来评价手续。"}, "sentence_index": 6, "correct_answer": "麻烦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个软件很麻烦，安装只要一分钟。", "explanation": "这里应该用〈简单〉。“麻烦”表示不便，与“安装只要一分钟”矛盾；形容操作容易应说“简单”。"}, {"text": "办护照很麻烦，带上身份证五分钟就办好了。", "explanation": "这里应该用〈方便〉。“麻烦”表示手续烦琐，与“五分钟就办好了”矛盾；应说“方便”。"}, {"text": "这辆车很麻烦，开起来很顺。", "explanation": "这里应该用〈顺手〉。“麻烦”表示不便，与“开起来很顺”矛盾；形容使用顺利应说“顺手”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87110, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店离车站远，买东西很麻烦很。", "corrected_sentence": "这家店离车站远，买东西很麻烦。", "error_description": "错误：句末多了一个“很”。“很”已修饰“麻烦”，“麻烦很”不成立，应删去句末的“很”，说“买东西很麻烦”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87110, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这里没有电梯，搬家麻烦很得。", "corrected_sentence": "这里没有电梯，搬家麻烦得很。", "error_description": "错误：程度补语“得”与“很”的位置颠倒。“得”要接在形容词后面表示程度，应说“麻烦得很”，改为“搬家麻烦得很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
