INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87111, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "电路是电走的路。电沿着这条路走，灯才会亮。", "primary_collocate": null, "pronunciation": "diàn lù", "ipa": "tjɛn˥˩ lu˥˩", "syllable_count": 2, "sentences": [{"text": "电路坏了，所以灯不亮。", "target_word": "电路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电沿着电路走，灯就亮了。", "target_word": "电路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个玩具的电路很简单。", "target_word": "电路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上画了一个电路。", "target_word": "电路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明把电路连好，灯亮了。", "target_word": "电路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家里的电路有问题，要请人来修。", "target_word": "电路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条电路是用电线连起来的。", "target_word": "电路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电路断了，电就走不过去了。", "target_word": "电路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在课上学习怎么连电路。", "target_word": "电路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨太大，电路进水了，电灯不亮了。", "target_word": "电路", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "電路", "label": "繁体"}, {"form": "电路板", "label": "复合"}], "register": "中性", "sense_fingerprint": "电走的路，电通过它灯才会亮", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '538b8765-1c9e-4db9-8583-9f5d1dd35ff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87111, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "电路", "is_correct": true, "explanation": "电路（diàn lù）：电流通过的路径，正确答案。"}, {"text": "电炉", "is_correct": false, "explanation": "lú（第二声）与 lù（第四声）声调不同，电炉指用电加热的炉子。"}, {"text": "电度", "is_correct": false, "explanation": "dù 与 lù 声母不同（d 与 l），电度指用电量的计量单位。"}, {"text": "线路", "is_correct": false, "explanation": "xiàn 与 diàn 声母不同（x 与 d），线路指电线或交通路线。"}], "explanations": {"电路": "电路（diàn lù）：电流通过的路径，正确答案。", "电炉": "lú（第二声）与 lù（第四声）声调不同，电炉指用电加热的炉子。", "电度": "dù 与 lù 声母不同（d 与 l），电度指用电量的计量单位。", "线路": "xiàn 与 diàn 声母不同（x 与 d），线路指电线或交通路线。"}, "sentence_index": null, "correct_answer": "电路"}, "level_3": {"options": [{"text": "电路", "is_correct": true, "explanation": "电路：坏了会使灯不亮，与后半句的因果相符。"}, {"text": "道路", "is_correct": false, "explanation": "语义：道路是供车辆和行人走的地面通道，坏了不会使灯不亮。"}, {"text": "电流", "is_correct": false, "explanation": "搭配：“坏”用于具体的物件，不说电流坏了。"}, {"text": "水管", "is_correct": false, "explanation": "语义：水管与电灯无关，坏了不会使灯不亮。"}], "explanations": {"电路": "电路：坏了会使灯不亮，与后半句的因果相符。", "道路": "语义：道路是供车辆和行人走的地面通道，坏了不会使灯不亮。", "电流": "搭配：“坏”用于具体的物件，不说电流坏了。", "水管": "语义：水管与电灯无关，坏了不会使灯不亮。"}, "sentence_index": 0, "correct_answer": "电路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "电路亮了，把整个房间照得很亮。", "explanation": "这里应该用〈灯泡〉。电路只是电流通过的路径，本身不会发光，亮的是灯泡。"}, {"text": "这个电路吃完了，要再点一份。", "explanation": "这里应该用〈饭菜〉。电路不能吃，“吃完”和“再点一份”针对的是食物。"}, {"text": "这条电路很粗，水能流过去。", "explanation": "这里应该用〈管道〉。管道用来输送水、气体，电路只是电流通过的路径，水不能从里面流过。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d1df8c-23e6-4bf6-8b40-263efbffaf4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87111, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电路", "is_correct": true, "explanation": "电路：可以用电线连起来，与“这条”和“连起来”相符。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不是用电线连起来的，句子不通。"}, {"text": "操场", "is_correct": false, "explanation": "语义：操场不是用电线连起来的，句子不通。"}, {"text": "电能", "is_correct": false, "explanation": "搭配：电能是能量，不是可以用电线“连起来”的具体物件，也不用“条”计量。"}], "explanations": {"电路": "电路：可以用电线连起来，与“这条”和“连起来”相符。", "河流": "语义：河流不是用电线连起来的，句子不通。", "操场": "语义：操场不是用电线连起来的，句子不通。", "电能": "搭配：电能是能量，不是可以用电线“连起来”的具体物件，也不用“条”计量。"}, "sentence_index": 6, "correct_answer": "电路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个电路穿错了，人就不能出门了。", "explanation": "这里应该用〈衣服〉。电路不能穿，“穿”的对象是衣物。"}, {"text": "这条电路很长，我们沿着它散步了一个下午。", "explanation": "这里应该用〈小路〉。电路是电流经过的通路，人不能沿着它散步。"}, {"text": "这块电路很干净，能看见外面的风景。", "explanation": "这里应该用〈玻璃〉。电路不透明，不能用来看风景。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d1df8c-23e6-4bf6-8b40-263efbffaf4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87111, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块板子上有一根电路，连着三个灯。", "corrected_sentence": "这块板子上有一个电路，连着三个灯。", "error_description": "量词错误：电路应该用“个”。“根”用于细长的东西，如电线，把“个”换成“根”就说错了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d1df8c-23e6-4bf6-8b40-263efbffaf4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87111, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张电路是用铜线连起来的。", "corrected_sentence": "这条电路是用铜线连起来的。", "error_description": "量词错误：电路用“条”或“个”。“张”用于纸、桌子等平面的东西，不能用于电路。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d1df8c-23e6-4bf6-8b40-263efbffaf4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
