INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87112, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "电流通过的路径，由电源、导线、开关和用电器等元件连接而成。", "primary_collocate": null, "pronunciation": "diàn lù", "ipa": "tjɛn˥˩ lu˥˩", "syllable_count": 2, "sentences": [{"text": "电路由电源、导线、开关和灯泡连接而成。", "target_word": "电路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开关一关，电路就断开了。", "target_word": "电路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块板子上的电路非常复杂。", "target_word": "电路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电路中的电流从电源正极流出。", "target_word": "电路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师正在检查手机里的电路。", "target_word": "电路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验时要先连接好电路，再打开开关。", "target_word": "电路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电路里有一个元件坏了。", "target_word": "电路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们学会了画简单的电路。", "target_word": "电路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电路接通以后，小灯泡亮了。", "target_word": "电路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器的电路设计得很好。", "target_word": "电路", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "電路", "label": "繁体"}, {"form": "电路板", "label": "复合"}], "register": "中性", "sense_fingerprint": "由电源、导线、开关、元件连成的电流路径", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '538b8765-1c9e-4db9-8583-9f5d1dd35ff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87112, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "电路", "is_correct": true, "explanation": "电路（diàn lù）：由电源、导线、开关等连成的电流路径，正确答案。"}, {"text": "电炉", "is_correct": false, "explanation": "lú（第二声）与 lù（第四声）声调不同，电炉指用电加热的炉子。"}, {"text": "电度", "is_correct": false, "explanation": "dù 与 lù 声母不同（d 与 l），电度指用电量的计量单位。"}, {"text": "线路", "is_correct": false, "explanation": "xiàn 与 diàn 声母不同（x 与 d），线路指电线或交通路线。"}], "explanations": {"电路": "电路（diàn lù）：由电源、导线、开关等连成的电流路径，正确答案。", "电炉": "lú（第二声）与 lù（第四声）声调不同，电炉指用电加热的炉子。", "电度": "dù 与 lù 声母不同（d 与 l），电度指用电量的计量单位。", "线路": "xiàn 与 diàn 声母不同（x 与 d），线路指电线或交通路线。"}, "sentence_index": null, "correct_answer": "电路"}, "level_3": {"options": [{"text": "电路", "is_correct": true, "explanation": "电路：由电源、导线、开关和灯泡连接而成，与句中列出的元件相符。"}, {"text": "道路", "is_correct": false, "explanation": "语义：道路不是由电源、导线和开关连接而成的。"}, {"text": "电流", "is_correct": false, "explanation": "搭配：“连接而成”说的是具体的装置，不能说电流由元件连接而成。"}, {"text": "水管", "is_correct": false, "explanation": "语义：水管不由电源和开关连接，句子不通。"}], "explanations": {"电路": "电路：由电源、导线、开关和灯泡连接而成，与句中列出的元件相符。", "道路": "语义：道路不是由电源、导线和开关连接而成的。", "电流": "搭配：“连接而成”说的是具体的装置，不能说电流由元件连接而成。", "水管": "语义：水管不由电源和开关连接，句子不通。"}, "sentence_index": 0, "correct_answer": "电路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "电路由玻璃外壳和灯丝组成。", "explanation": "这里应该用〈灯泡〉。玻璃外壳和灯丝是灯泡的构造，电路由电源、导线等元件连成。"}, {"text": "电路唱了一首歌，大家都很高兴。", "explanation": "这里应该用〈歌手〉。电路不会唱歌，唱歌的是人。"}, {"text": "这条电路很粗，水能流过去。", "explanation": "这里应该用〈管道〉。管道用来输送水、气体，电路只是电流通过的路径，水不能从里面流过。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d1df8c-23e6-4bf6-8b40-263efbffaf4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87112, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电路", "is_correct": true, "explanation": "电路：电路里的元件可以坏，与“里有一个元件坏了”相符。"}, {"text": "操场", "is_correct": false, "explanation": "语义：操场里不会装电路元件，句子不通。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流里没有电路元件，句子不通。"}, {"text": "电能", "is_correct": false, "explanation": "搭配：“里”后接的应是能容纳元件的装置，电能是能量，不说“电能里”。"}], "explanations": {"电路": "电路：电路里的元件可以坏，与“里有一个元件坏了”相符。", "操场": "语义：操场里不会装电路元件，句子不通。", "河流": "语义：河流里没有电路元件，句子不通。", "电能": "搭配：“里”后接的应是能容纳元件的装置，电能是能量，不说“电能里”。"}, "sentence_index": 6, "correct_answer": "电路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈用电路把衣服缝好了。", "explanation": "这里应该用〈线〉。缝衣服要用线，电路是电流通过的路径，不能用来缝东西。"}, {"text": "这个电路很好吃，我吃了两个。", "explanation": "这里应该用〈面包〉。面包才能吃，电路是电流通过的路径，不能吃。"}, {"text": "我们沿着这条电路走了一天。", "explanation": "这里应该用〈公路〉。电路不能让人走，公路才能沿着走。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d1df8c-23e6-4bf6-8b40-263efbffaf4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87112, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块板子上有一根电路烧坏了。", "corrected_sentence": "这块板子上有一个电路烧坏了。", "error_description": "量词错误：电路应该用“个”或“条”。“根”用于细长的东西，如电线，不能用于电路。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d1df8c-23e6-4bf6-8b40-263efbffaf4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87112, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工程师设计了一根新电路，效果很好。", "corrected_sentence": "工程师设计了一个新电路，效果很好。", "error_description": "量词错误：电路应该用“个”。“根”用于细长的东西，如电线，把“个”换成“根”就说错了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d1df8c-23e6-4bf6-8b40-263efbffaf4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
