INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87113, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "人家是说别的人，不是你，也不是我。", "primary_collocate": null, "pronunciation": "rén jia", "ipa": "ʐən˧˥ tɕja", "syllable_count": 2, "sentences": [{"text": "人家都到了，你怎么还没起床？", "target_word": "人家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别总看人家，要看自己。", "target_word": "人家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书是人家的，要还给人家。", "target_word": "人家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人家说得对，我们应该听。", "target_word": "人家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要随便拿人家的东西。", "target_word": "人家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人家已经走了，你别等了。", "target_word": "人家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别问人家的事。", "target_word": "人家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想麻烦人家。", "target_word": "人家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人家帮了我，我要谢谢人家。", "target_word": "人家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看，人家的孩子多聪明！", "target_word": "人家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "指说话人和听话人以外的别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72d39edd-56d4-44c7-b5fd-93bb63a43a9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87113, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人家", "is_correct": true, "explanation": "正确：「人家」指说话人和听话人以外的人，与「都到了」的语境相符。"}, {"text": "你", "is_correct": false, "explanation": "语义：「你」指听话人，与后句「你怎么还没起床」的对象重复，前后矛盾。"}, {"text": "它", "is_correct": false, "explanation": "语义：「它」指事物，不能指人，「它都到了」不通，句子不成立。"}, {"text": "自己", "is_correct": false, "explanation": "语义：「自己」指说话人本人，与后句对听话人的责问不符。"}], "explanations": {"人家": "正确：「人家」指说话人和听话人以外的人，与「都到了」的语境相符。", "你": "语义：「你」指听话人，与后句「你怎么还没起床」的对象重复，前后矛盾。", "它": "语义：「它」指事物，不能指人，「它都到了」不通，句子不成立。", "自己": "语义：「自己」指说话人本人，与后句对听话人的责问不符。"}, "sentence_index": 0, "correct_answer": "人家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "人家，请你过来一下。", "explanation": "称呼：「人家」指说话人和听话人以外的人，不能直接用来称呼对方，这里应该用「您」或对方的名字。"}, {"text": "我们班的人家都很努力。", "explanation": "搭配：「人家」已排除说话人，不能和「我们班的」连用，这里应该用「同学」。"}, {"text": "这条街上住着二十户人家，大家都很熟。", "explanation": "语义：这里的「人家」指家庭、住户，「二十户人家」是二十家的意思，与指说话人以外的人的「人家」不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7aa74082-3c8b-4a38-b801-f88e0d556f49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87113, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人家", "is_correct": true, "explanation": "正确：「人家」指别人，「别问人家的事」表示不要过问别人的私事，符合句意。"}, {"text": "您", "is_correct": false, "explanation": "语义：「您」指听话人，与主语「你」是同一个人，「你别问您的事」前后矛盾。"}, {"text": "怎么", "is_correct": false, "explanation": "语法：「怎么」是疑问代词，不能作「…的事」的定语，「问怎么的事」不成立。"}, {"text": "这么", "is_correct": false, "explanation": "语法：「这么」修饰形容词或动词，不能直接加「的事」，句子不通。"}], "explanations": {"人家": "正确：「人家」指别人，「别问人家的事」表示不要过问别人的私事，符合句意。", "您": "语义：「您」指听话人，与主语「你」是同一个人，「你别问您的事」前后矛盾。", "怎么": "语法：「怎么」是疑问代词，不能作「…的事」的定语，「问怎么的事」不成立。", "这么": "语法：「这么」修饰形容词或动词，不能直接加「的事」，句子不通。"}, "sentence_index": 6, "correct_answer": "人家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这户人家很好客，常请邻居来吃饭。", "explanation": "义项：此处「人家」是名词，指一户家庭，与指说话人和听话人以外之人的代词义项不同。"}, {"text": "看，人家的孩子是我的，多聪明！", "explanation": "语义：「人家」指说话人以外的人，不能指说话人自己的孩子，与「我的」矛盾。"}, {"text": "人家是我，我的孩子多聪明！", "explanation": "语义：「人家」是他人，不能用来指说话人自己，这句话前后指代冲突。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7aa74082-3c8b-4a38-b801-f88e0d556f49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87113, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是人家雨伞，明天要还。", "corrected_sentence": "这是人家的雨伞，明天要还。", "error_description": "错误：「人家」作定语修饰名词时，中间要加「的」。正确说法是「人家的雨伞」，表示所属关系；「人家雨伞」不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7aa74082-3c8b-4a38-b801-f88e0d556f49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87113, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份工作是人家。", "corrected_sentence": "这份工作是人家的。", "error_description": "错误：「人家」作谓语表示所属时，后面要加「的」。正确说法是「这份工作是人家的」；「是人家」不能表示归属。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7aa74082-3c8b-4a38-b801-f88e0d556f49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
