INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87115, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "音乐家是会唱歌、会弹琴、会写曲子的人。他们的工作就是做音乐。", "primary_collocate": null, "pronunciation": "yīn yuè jiā", "ipa": "in˥ ɥœ˥˩ tɕja˥", "syllable_count": 3, "sentences": [{"text": "我姐姐想当音乐家。", "target_word": "音乐家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐家每天都练习弹琴。", "target_word": "音乐家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位音乐家会唱歌，也会写曲子。", "target_word": "音乐家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明长大以后想做音乐家。", "target_word": "音乐家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐家正在房间里弹钢琴。", "target_word": "音乐家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位音乐家写了一首新歌。", "target_word": "音乐家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "街上有一位音乐家在拉小提琴。", "target_word": "音乐家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐家的家里有很多乐器。", "target_word": "音乐家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我认识一位音乐家，他会弹吉他。", "target_word": "音乐家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐家把新歌唱给我们听。", "target_word": "音乐家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "音乐家们", "label": "复数"}, {"form": "音樂家", "label": "繁体"}], "register": "中性", "sense_fingerprint": "会唱歌弹琴写曲子、以音乐为工作的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa2e5afa-4320-49bb-ab63-b0ef2a0774da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87115, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "音乐家", "is_correct": true, "explanation": "正确：“想当音乐家”表示职业志向，符合句中的语境。"}, {"text": "病人", "is_correct": false, "explanation": "语义：“病人”是患病的状态，不是职业，“想当病人”不成立。"}, {"text": "同事", "is_correct": false, "explanation": "配价：“同事”是关系名词，需要说明与谁共事，不能单独说“想当同事”。"}, {"text": "邻居", "is_correct": false, "explanation": "配价：“邻居”同样是关系名词，需要说明住在谁的旁边，不能作为职业目标。"}], "explanations": {"音乐家": "正确：“想当音乐家”表示职业志向，符合句中的语境。", "病人": "语义：“病人”是患病的状态，不是职业，“想当病人”不成立。", "同事": "配价：“同事”是关系名词，需要说明与谁共事，不能单独说“想当同事”。", "邻居": "配价：“邻居”同样是关系名词，需要说明住在谁的旁边，不能作为职业目标。"}, "sentence_index": 0, "correct_answer": "音乐家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这段音乐家很感人。", "explanation": "这里应该用〈音乐〉。音乐家指人，不能用来形容一段音乐的感染力；“这段”修饰的应是乐曲。"}, {"text": "这位音乐家每天给病人看病，态度很好。", "explanation": "这里应该用〈医生〉。音乐家指会唱歌、弹琴、写曲子的人，不负责给病人看病。"}, {"text": "这个音乐家的成员都很年轻。", "explanation": "这里应该用〈乐团〉。乐团由多名成员组成；音乐家指一个人，不能说“成员”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97a53332-e7ed-4493-b479-854c6d71a992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87115, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "音乐家", "is_correct": true, "explanation": "正确：在街上拉小提琴的人可以是音乐家，符合句中的语境。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿不会拉小提琴，与“在拉小提琴”的动作相冲突。"}, {"text": "对手", "is_correct": false, "explanation": "配价：“对手”是关系名词，需要说明是谁的对手，且与街头拉琴的语境不符。"}, {"text": "死者", "is_correct": false, "explanation": "语义：死者已经去世，不可能在街上拉小提琴。"}], "explanations": {"音乐家": "正确：在街上拉小提琴的人可以是音乐家，符合句中的语境。", "婴儿": "语义：婴儿不会拉小提琴，与“在拉小提琴”的动作相冲突。", "对手": "配价：“对手”是关系名词，需要说明是谁的对手，且与街头拉琴的语境不符。", "死者": "语义：死者已经去世，不可能在街上拉小提琴。"}, "sentence_index": 6, "correct_answer": "音乐家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是一名很有经验的音乐家，经常在法庭上为客户辩护。", "explanation": "这里应该用〈律师〉。音乐家是会唱歌、会弹琴、会写曲子的人，不会在法庭上为客户辩护。"}, {"text": "她每天练习弹那位音乐家。", "explanation": "这里应该用〈吉他〉。“弹”的对象是乐器，音乐家是人，不能被弹。"}, {"text": "这位音乐家每天在街上巡逻，维护治安。", "explanation": "这里应该用〈警察〉。音乐家的工作是做音乐，巡逻、维护治安是警察的职责。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97a53332-e7ed-4493-b479-854c6d71a992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87115, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我认识三音乐家。", "corrected_sentence": "我认识三位音乐家。", "error_description": "量词遗漏：数词与名词之间要加量词，应说“三位音乐家”，不能说“三音乐家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97a53332-e7ed-4493-b479-854c6d71a992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87115, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我姐姐想成为一只音乐家。", "corrected_sentence": "我姐姐想成为一位音乐家。", "error_description": "量词误用：音乐家指人，应用量词“位”（或“个”）；“只”用于动物，不能说“一只音乐家”，应改为“一位音乐家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97a53332-e7ed-4493-b479-854c6d71a992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
