INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87116, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在音乐方面有很高造诣、从事作曲、演奏或演唱等工作的人。", "primary_collocate": null, "pronunciation": "yīn yuè jiā", "ipa": "in˥ ɥœ˥˩ tɕja˥", "syllable_count": 3, "sentences": [{"text": "这位音乐家的作品很有名。", "target_word": "音乐家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一位著名的音乐家。", "target_word": "音乐家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位音乐家写了很多好听的曲子。", "target_word": "音乐家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐家在音乐会上演奏了一首新曲。", "target_word": "音乐家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老音乐家在音乐学院教了三十年书。", "target_word": "音乐家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人去听那位音乐家的音乐会。", "target_word": "音乐家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他小时候就想成为一位音乐家。", "target_word": "音乐家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位音乐家得过很多国际大奖。", "target_word": "音乐家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐家们坐在台上，准备演出。", "target_word": "音乐家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最喜欢的音乐家是贝多芬。", "target_word": "音乐家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "音乐家们", "label": "复数"}, {"form": "音樂家", "label": "繁体"}], "register": "中性", "sense_fingerprint": "音乐造诣很高、从事作曲演奏演唱的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa2e5afa-4320-49bb-ab63-b0ef2a0774da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87116, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "音乐家", "is_correct": true, "explanation": "正确：“音乐家”可以有作品，符合“这位……的作品很有名”的语境。"}, {"text": "司机", "is_correct": false, "explanation": "搭配：“作品”指文艺或学术方面的创作成果，司机不从事创作，不能说“司机的作品”。"}, {"text": "收银员", "is_correct": false, "explanation": "搭配：收银员的工作是收款找零，不从事创作，“作品”的说法不成立。"}, {"text": "运动员", "is_correct": false, "explanation": "语义：运动员靠比赛成绩出名，不说“作品很有名”，与句中的语境不符。"}], "explanations": {"音乐家": "正确：“音乐家”可以有作品，符合“这位……的作品很有名”的语境。", "司机": "搭配：“作品”指文艺或学术方面的创作成果，司机不从事创作，不能说“司机的作品”。", "收银员": "搭配：收银员的工作是收款找零，不从事创作，“作品”的说法不成立。", "运动员": "语义：运动员靠比赛成绩出名，不说“作品很有名”，与句中的语境不符。"}, "sentence_index": 0, "correct_answer": "音乐家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首音乐家很好听。", "explanation": "这里应该用〈音乐〉。音乐家指人，不能用来形容一首曲子；评价歌曲好听要说“音乐”或“曲子”。"}, {"text": "这位音乐家每天给病人看病，态度很好。", "explanation": "这里应该用〈医生〉。音乐家指从事音乐创作或演奏的人，不负责给病人看病；给病人看病的应是医生。"}, {"text": "这支音乐家下个月要去国外巡演。", "explanation": "这里应该用〈乐队〉。“支”用于乐队这类群体，音乐家指单个的人，不能用“支”来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97a53332-e7ed-4493-b479-854c6d71a992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87116, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "音乐家", "is_correct": true, "explanation": "正确：“成为一位音乐家”是常见的志向说法，与“小时候就想”相符。"}, {"text": "小孩", "is_correct": false, "explanation": "语义：“小孩”是小时候的身份，不能作为小时候想成为的目标，与“想成为”矛盾。"}, {"text": "病人", "is_correct": false, "explanation": "语义：没有人会立志成为病人，“想成为一位病人”与句中的志向语境不符。"}, {"text": "同事", "is_correct": false, "explanation": "配价：“同事”是关系名词，需要说明与谁共事，不能单独作为志向的目标。"}], "explanations": {"音乐家": "正确：“成为一位音乐家”是常见的志向说法，与“小时候就想”相符。", "小孩": "语义：“小孩”是小时候的身份，不能作为小时候想成为的目标，与“想成为”矛盾。", "病人": "语义：没有人会立志成为病人，“想成为一位病人”与句中的志向语境不符。", "同事": "配价：“同事”是关系名词，需要说明与谁共事，不能单独作为志向的目标。"}, "sentence_index": 6, "correct_answer": "音乐家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场音乐家很精彩。", "explanation": "这里应该用〈音乐会〉。“这场”修饰的是活动，音乐家是人，不能用来评价演出精彩。"}, {"text": "这位音乐家在法庭上为当事人辩护，非常专业。", "explanation": "这里应该用〈律师〉。音乐家是从事音乐创作或演奏的人，不负责在法庭上为当事人辩护。"}, {"text": "他正在演奏那位音乐家。", "explanation": "这里应该用〈曲子〉。“演奏”的对象是乐曲或乐器，音乐家是人，不能被演奏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97a53332-e7ed-4493-b479-854c6d71a992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87116, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校请来了两支音乐家给学生上课。", "corrected_sentence": "学校请来了两位音乐家给学生上课。", "error_description": "量词错误：音乐家指人，应用量词“位”，不能用“支”（“支”多用于乐队等群体）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97a53332-e7ed-4493-b479-854c6d71a992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87116, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我认识一位很有名音乐家。", "corrected_sentence": "我认识一位很有名的音乐家。", "error_description": "“的”遗漏：“很有名”修饰名词时要加“的”，应说“很有名的音乐家”，不能说“很有名音乐家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97a53332-e7ed-4493-b479-854c6d71a992') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
