INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87118, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "昨天的前一天；前天。", "primary_collocate": null, "pronunciation": "qián rì", "ipa": "tɕʰjɛn˧˥ ɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "昨天和前日都下了雨，今天晴了。", "target_word": "前日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我前日在家休息，没有出门。", "target_word": "前日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天是十号，前日是八号。", "target_word": "前日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他前日给我打了电话，昨天又打了一次。", "target_word": "前日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前日的会议开得很长。", "target_word": "前日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨日晴，前日下雨。", "target_word": "前日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她前日买的衣服，今天就穿了。", "target_word": "前日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前日晚上，我们一起吃了饭。", "target_word": "前日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上说，前日城里下了大雪。", "target_word": "前日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他前日才到北京，今天就要走了。", "target_word": "前日", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "昨天的前一天，即前天", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96df1d2b-98d4-4058-aa95-b548c2ba3b98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87118, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "前日", "is_correct": true, "explanation": "qián rì 指昨天的前一天，即前天。"}, {"text": "前例", "is_correct": false, "explanation": "qián lì：lì 与 rì 声母不同（l 与 r），意思是先前的例子。"}, {"text": "全日", "is_correct": false, "explanation": "quán rì：quán 与 qián 韵母不同（u 与 i），意思是整天。"}, {"text": "前世", "is_correct": false, "explanation": "qián shì：shì 与 rì 声母不同（sh 与 r），意思是前生。"}], "explanations": {"前日": "qián rì 指昨天的前一天，即前天。", "前例": "qián lì：lì 与 rì 声母不同（l 与 r），意思是先前的例子。", "全日": "quán rì：quán 与 qián 韵母不同（u 与 i），意思是整天。", "前世": "qián shì：shì 与 rì 声母不同（sh 与 r），意思是前生。"}, "sentence_index": null, "correct_answer": "前日"}, "level_3": {"options": [{"text": "今天", "is_correct": false, "explanation": "语义：“今天”与“昨天”并列，但下一分句说“今天晴了”，前后矛盾。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”指将来，与“都下了雨”的过去时间不符。"}, {"text": "前日", "is_correct": true, "explanation": "指昨天的前一天，与“昨天”并列表示两个过去的日子，符合语境。"}, {"text": "蓝天", "is_correct": false, "explanation": "搭配：“下雨”的主语应是天气或时间，“蓝天”不能与“下了雨”搭配。"}], "explanations": {"今天": "语义：“今天”与“昨天”并列，但下一分句说“今天晴了”，前后矛盾。", "明天": "语义：“明天”指将来，与“都下了雨”的过去时间不符。", "前日": "指昨天的前一天，与“昨天”并列表示两个过去的日子，符合语境。", "蓝天": "搭配：“下雨”的主语应是天气或时间，“蓝天”不能与“下了雨”搭配。"}, "sentence_index": 0, "correct_answer": "前日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我前日要去北京出差。", "explanation": "这里应该用〈明天〉或〈后天〉。“前日”指过去的某一天，不能用于将来的计划。"}, {"text": "这几个前日我都在忙。", "explanation": "这里应该用〈这几天〉。“前日”指一个具体的日子，不能用“这几个”表示一段时间。"}, {"text": "我每前日都去跑步。", "explanation": "这里应该用〈每天〉。“前日”指一个具体的日子，不能表示每次或习惯性的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bde90eb-7d60-4472-9330-89734b4b836e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87118, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下周", "is_correct": false, "explanation": "语义：下周还没到，买的衣服不可能今天就穿了。"}, {"text": "明年", "is_correct": false, "explanation": "语义：明年尚未到来，与“今天就穿了”相冲突。"}, {"text": "前日", "is_correct": true, "explanation": "作时间状语修饰“买”，指昨天的前一天，符合语境。"}, {"text": "下个月", "is_correct": false, "explanation": "语义：下个月还没到，与“今天就穿了”矛盾。"}], "explanations": {"下周": "语义：下周还没到，买的衣服不可能今天就穿了。", "明年": "语义：明年尚未到来，与“今天就穿了”相冲突。", "前日": "作时间状语修饰“买”，指昨天的前一天，符合语境。", "下个月": "语义：下个月还没到，与“今天就穿了”矛盾。"}, "sentence_index": 6, "correct_answer": "前日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他打算前日回国。", "explanation": "这里应该用〈后天〉或〈明天〉。“前日”指过去的某一天，不能用于将来的打算。"}, {"text": "他前日的一整年都在北京工作。", "explanation": "这里不能用〈前日〉。“前日”只指一天，不能用来修饰长时段，应改用〈去年〉之类的时间词。"}, {"text": "我前日一直住在上海，已经住了十年。", "explanation": "这里不能用〈前日〉。“前日”只指昨天的前一天，不能和“已经住了十年”这样的长时段连用，应改用〈以前〉之类的说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bde90eb-7d60-4472-9330-89734b4b836e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87118, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他前日就要到了北京。", "corrected_sentence": "他前日就到了北京。", "error_description": "时间矛盾：“就要”表示即将发生的将来，与表示过去的“前日”不能共现；应去掉“要”，说“他前日就到了北京。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bde90eb-7d60-4472-9330-89734b4b836e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87118, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我前日的买了一本书，今天读完了。", "corrected_sentence": "我前日买了一本书，今天读完了。", "error_description": "“的”不能直接加在时间词“前日”后面修饰动词：“前日”作状语时后面直接接动词，应去掉“的”，说“我前日买了一本书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bde90eb-7d60-4472-9330-89734b4b836e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
