INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87119, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "养成是天天做同一件事，后来变成自己的习惯。", "primary_collocate": null, "pronunciation": "yǎng chéng", "ipa": "jɑŋ˨˩˦ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他天天早起，养成了好习惯。", "target_word": "养成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天读书，已经养成了习惯。", "target_word": "养成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每天十点睡觉，坚持了一年，他养成了早睡的习惯。", "target_word": "养成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候妈妈让我养成饭前洗手的习惯。", "target_word": "养成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她天天写日记，养成了每晚写字的习惯。", "target_word": "养成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在国外养成了喝咖啡的习惯。", "target_word": "养成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住在北京三年，他养成了坐地铁上班的习惯。", "target_word": "养成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天天听中文歌，他养成了听歌学中文的习惯。", "target_word": "养成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，好习惯要从小养成。", "target_word": "养成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她养成了出门带伞的习惯。", "target_word": "养成", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "养成了", "label": "体标"}, {"form": "养成教育", "label": "复合"}, {"form": "養成", "label": "繁体"}], "register": "中性", "sense_fingerprint": "天天重复做一件事，后来变成自己的习惯", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e64b3b0f-81c3-4b52-bcde-e97b5fd7793c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87119, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "戒掉", "is_correct": false, "explanation": "语义：“戒掉”是放弃习惯，与“天天早起”的语境矛盾。"}, {"text": "丢掉", "is_correct": false, "explanation": "搭配：“丢掉”多用于丢失物品，且与“天天早起”的语境矛盾。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”与“天天早起”的积极语境相反，句意不通。"}, {"text": "养成", "is_correct": true, "explanation": "正确答案。“养成了好习惯”指长期重复做某事后形成习惯，符合句意。"}], "explanations": {"戒掉": "语义：“戒掉”是放弃习惯，与“天天早起”的语境矛盾。", "丢掉": "搭配：“丢掉”多用于丢失物品，且与“天天早起”的语境矛盾。", "放弃": "语义：“放弃”与“天天早起”的积极语境相反，句意不通。", "养成": "正确答案。“养成了好习惯”指长期重复做某事后形成习惯，符合句意。"}, "sentence_index": 0, "correct_answer": "养成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校要注重养成学生的创新能力。", "explanation": "这里应该用〈培养〉。养成用于习惯、作风、性格，培养能力、人才要用“培养”。"}, {"text": "他对这座城市养成了好印象。", "explanation": "这里应该用〈形成〉。印象、看法要用“形成”，养成只用于习惯、作风等。"}, {"text": "两国养成了友好的关系。", "explanation": "这里应该用〈建立〉。关系要用“建立”，养成不能与“关系”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb1be39-7926-42f2-9d30-b93febba9078') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87119, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开始", "is_correct": false, "explanation": "搭配：“开始”不直接带“习惯”作宾语，句中说“开始了习惯”不通。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”表示反感，与句中“养成习惯”的结果相反。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”与“住了三年”后形成习惯的语境不合。"}, {"text": "养成", "is_correct": true, "explanation": "正确答案。“养成了坐地铁上班的习惯”指住了三年后形成习惯，符合句意。"}], "explanations": {"开始": "搭配：“开始”不直接带“习惯”作宾语，句中说“开始了习惯”不通。", "讨厌": "语义：“讨厌”表示反感，与句中“养成习惯”的结果相反。", "拒绝": "语义：“拒绝”与“住了三年”后形成习惯的语境不合。", "养成": "正确答案。“养成了坐地铁上班的习惯”指住了三年后形成习惯，符合句意。"}, "sentence_index": 6, "correct_answer": "养成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他多年来养成了丰富的经验。", "explanation": "这里应该用〈积累〉。经验要靠“积累”获得，养成只用于习惯、作风等。"}, {"text": "他很快就养成了这门技术。", "explanation": "这里应该用〈掌握〉。技术要用“掌握”，养成不能与“技术”搭配。"}, {"text": "公司要养成良好的形象。", "explanation": "这里应该用〈树立〉。形象要用“树立”，养成不能与“形象”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb1be39-7926-42f2-9d30-b93febba9078') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87119, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爷爷从年轻时就养成着早起锻炼的习惯。", "corrected_sentence": "爷爷从年轻时就养成了早起锻炼的习惯。", "error_description": "体标错误：“养成”是完成性动作，应说“养成了”，不能用“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb1be39-7926-42f2-9d30-b93febba9078') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87119, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在北京工作以后，养成起了坐地铁上班的习惯。", "corrected_sentence": "他在北京工作以后，养成了坐地铁上班的习惯。", "error_description": "补语错误：“养成”已表示习惯形成，后面不能再加“起”，应说“养成了”，不能说“养成起了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb1be39-7926-42f2-9d30-b93febba9078') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
