INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87121, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cb825-c0b4-48bd-9283-9eddacabb02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87121, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "体力是身体里的力气。有体力，才能跑得快、跳得高。", "primary_collocate": null, "pronunciation": "tǐ lì", "ipa": "tʰi˨˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "跑五千米要有好体力。", "target_word": "体力", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他体力很好，跑了十公里还不累。", "target_word": "体力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛到最后，大家的体力都不够了。", "target_word": "体力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "想踢好球，先要有体力。", "target_word": "体力", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "每天游泳能增强体力。", "target_word": "体力", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她体力太差，爬三层楼就累了。", "target_word": "体力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃饱饭才有体力打球。", "target_word": "体力", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "运动员的体力比一般人好得多。", "target_word": "体力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "跳了一个小时绳，我的体力用完了。", "target_word": "体力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多睡觉，体力才会恢复得快。", "target_word": "体力", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "體力", "label": "繁体"}, {"form": "体力活", "label": "复合"}, {"form": "体力劳动", "label": "复合"}], "register": "中性", "sense_fingerprint": "身体里的力气，能让人跑跳运动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '157552df-a86f-4558-b9ec-500c2d87da0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87121, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体力", "is_correct": true, "explanation": "体力指身体里的力气，跑五千米需要有好体力，与句意吻合。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“好体重”不是自然的说法，体重只说轻重，不说好坏。"}, {"text": "学历", "is_correct": false, "explanation": "语义：跑五千米与学历无关，“学历”不能用来说明跑步的条件。"}, {"text": "考试", "is_correct": false, "explanation": "语义：跑五千米需要的是身体的能力，不是“考试”。"}], "explanations": {"体力": "体力指身体里的力气，跑五千米需要有好体力，与句意吻合。", "体重": "搭配：“好体重”不是自然的说法，体重只说轻重，不说好坏。", "学历": "语义：跑五千米与学历无关，“学历”不能用来说明跑步的条件。", "考试": "语义：跑五千米需要的是身体的能力，不是“考试”。"}, "sentence_index": 0, "correct_answer": "体力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他解数学题的体力很强，几分钟就做完了。", "explanation": "这里应该用〈脑力〉。体力是身体里的力气，解数学题靠的是脑力，不能用体力。"}, {"text": "他背诗的体力很好，一百首都能背下来。", "explanation": "这里应该用〈记忆力〉。体力是身体里的力气，背诗靠的是记忆力，不能说背诗的体力好。"}, {"text": "他的体力很轻，所以跑起来特别快。", "explanation": "这里应该用〈体重〉。“轻”描述的是人的重量，体力不能说轻重，要说体重。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cb825-c0b4-48bd-9283-9eddacabb02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87121, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体力", "is_correct": true, "explanation": "吃饱饭后才有体力打球，“体力”说的是身体的力量，与句意吻合。"}, {"text": "球场", "is_correct": false, "explanation": "语义：吃饱饭不能带来球场，“球场”与“吃饭”的条件无关。"}, {"text": "课本", "is_correct": false, "explanation": "语义：吃饱饭不会带来课本，“课本”与打球需要的条件无关，句意不通。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“有”后面接“体温”不成词组，“体温”也不能表示打球的条件。"}], "explanations": {"体力": "吃饱饭后才有体力打球，“体力”说的是身体的力量，与句意吻合。", "球场": "语义：吃饱饭不能带来球场，“球场”与“吃饭”的条件无关。", "课本": "语义：吃饱饭不会带来课本，“课本”与打球需要的条件无关，句意不通。", "体温": "搭配：“有”后面接“体温”不成词组，“体温”也不能表示打球的条件。"}, "sentence_index": 6, "correct_answer": "体力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对同学的体力很温和，从不大声说话。", "explanation": "这里应该用〈态度〉。体力是身体里的力气，形容对同学温和要用态度，不能说体力温和。"}, {"text": "这所学校的体力很强，每年都有很多学生考上大学。", "explanation": "这里应该用〈实力〉。体力只用于人的身体，形容学校的能力水平要用实力。"}, {"text": "上课时她的体力很集中。", "explanation": "这里应该用〈注意力〉。“集中”说的是注意力，体力不能集中，要说注意力集中。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cb825-c0b4-48bd-9283-9eddacabb02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87121, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "想跑马拉松，要先好有体力。", "corrected_sentence": "想跑马拉松，要先有好体力。", "error_description": "修饰“体力”的“好”要放在“有”后面，说“好有体力”是错的，应说“有好体力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cb825-c0b4-48bd-9283-9eddacabb02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87121, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "早点睡觉，体力恢复地快。", "corrected_sentence": "早点睡觉，体力恢复得快。", "error_description": "错误：补语要用“得”连接，“地”只用于状语。“快”是“恢复”的补语，应说“恢复得快”，不能说“恢复地快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cb825-c0b4-48bd-9283-9eddacabb02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
