INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87122, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人体从事活动或劳动所具有的力量。", "primary_collocate": null, "pronunciation": "tǐ lì", "ipa": "tʰi˨˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "他每天跑步，体力越来越好。", "target_word": "体力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "搬了一上午箱子，我的体力用完了。", "target_word": "体力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人们体力很好，一天能搬很多货。", "target_word": "体力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人的体力不如年轻人。", "target_word": "体力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爬山要花很多体力，你带水了吗？", "target_word": "体力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸做完农活，体力已经不行了。", "target_word": "体力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她生病以后，体力一直没有恢复。", "target_word": "体力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份工作需要好体力，你能做吗？", "target_word": "体力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "休息一会儿吧，我想恢复一下体力。", "target_word": "体力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们玩了一天，晚上没有体力了。", "target_word": "体力", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "體力", "label": "繁体"}, {"form": "体力活", "label": "复合"}, {"form": "体力劳动", "label": "复合"}], "register": "中性", "sense_fingerprint": "人做事、劳动时身体所具有的力量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '157552df-a86f-4558-b9ec-500c2d87da0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87122, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体力", "is_correct": true, "explanation": "体力指身体从事活动的力量，跑步后会越来越好，与句意吻合。"}, {"text": "工资", "is_correct": false, "explanation": "语义：跑步不会让工资越来越好，“工资”与前文的“跑步”无关。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“体温”说高低、正常，不说“越来越好”。"}, {"text": "词汇", "is_correct": false, "explanation": "语义：跑步不会增加词汇，“词汇”与前文的运动无关。"}], "explanations": {"体力": "体力指身体从事活动的力量，跑步后会越来越好，与句意吻合。", "工资": "语义：跑步不会让工资越来越好，“工资”与前文的“跑步”无关。", "体温": "搭配：“体温”说高低、正常，不说“越来越好”。", "词汇": "语义：跑步不会增加词汇，“词汇”与前文的运动无关。"}, "sentence_index": 0, "correct_answer": "体力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他考试的体力很好，从没考过第二名。", "explanation": "这里应该用〈智力〉。体力指身体的力量，考试考的是智力，不能用体力来形容。"}, {"text": "他的体力很轻，所以跑起来特别快。", "explanation": "这里应该用〈体重〉。“轻”描述的是人的重量，体力不能说轻重，要说体重。"}, {"text": "他学开车的体力很强，一个星期就学会了。", "explanation": "这里应该用〈能力〉。体力指身体的力量，不用来说学技能；学会开车要说能力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cb825-c0b4-48bd-9283-9eddacabb02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87122, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体力", "is_correct": true, "explanation": "体力是身体的力量，生病后会下降，需要慢慢恢复，与句意吻合。"}, {"text": "房租", "is_correct": false, "explanation": "语义：生病后恢复的不是房租，“房租”与句中的“生病”无关。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：“恢复”通常搭配健康、体力、元气，不搭配“性格”。"}, {"text": "试卷", "is_correct": false, "explanation": "语义：生病与试卷无关，“试卷”也不存在“恢复”的问题。"}], "explanations": {"体力": "体力是身体的力量，生病后会下降，需要慢慢恢复，与句意吻合。", "房租": "语义：生病后恢复的不是房租，“房租”与句中的“生病”无关。", "性格": "搭配：“恢复”通常搭配健康、体力、元气，不搭配“性格”。", "试卷": "语义：生病与试卷无关，“试卷”也不存在“恢复”的问题。"}, "sentence_index": 6, "correct_answer": "体力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的体力很和气，从不跟人吵架。", "explanation": "这里应该用〈脾气〉。体力指身体的力量，不能用来形容和气；形容性情和气要用脾气。"}, {"text": "这家公司的体力很强，客户很多。", "explanation": "这里应该用〈实力〉。体力只用于人的身体，形容公司或团队的能力水平要用实力。"}, {"text": "他看书的时候体力很集中。", "explanation": "这里应该用〈注意力〉。“集中”说的是心思或注意力，体力不能集中，要说注意力集中。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cb825-c0b4-48bd-9283-9eddacabb02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87122, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他跑完步，还剩一个体力。", "corrected_sentence": "他跑完步，还剩一点体力。", "error_description": "“体力”是不可数名词，数量要用“一点”，不能说“一个体力”。应说：“他跑完步，还剩一点体力。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cb825-c0b4-48bd-9283-9eddacabb02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87122, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很体力，每天都能爬山。", "corrected_sentence": "他很有体力，每天都能爬山。", "error_description": "“体力”作谓语时要说“有体力”，“很体力”是错的，应说“很有体力”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cb825-c0b4-48bd-9283-9eddacabb02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87125, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "静", "is_correct": true, "explanation": "静与动相对，指不动、静止，是这一义项的反义词。"}, {"text": "吃", "is_correct": false, "explanation": "吃是进食动作，与“动”没有反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "唱是发声动作，与“动”没有反义关系。"}, {"text": "写", "is_correct": false, "explanation": "写是书写动作，与“动”没有反义关系。"}], "correct_answer": "静", "explanations": {"静": "静与动相对，指不动、静止，是这一义项的反义词。", "吃": "吃是进食动作，与“动”没有反义关系。", "唱": "唱是发声动作，与“动”没有反义关系。", "写": "写是书写动作，与“动”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87125, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "静", "is_correct": true, "explanation": "静与动相对，指不动、静止，是这一义项的反义词。"}, {"text": "跑", "is_correct": false, "explanation": "跑是快速移动的动作，本身是动态的，与“动”不构成反义。"}, {"text": "看", "is_correct": false, "explanation": "看是视觉动作，与“动”没有反义关系。"}, {"text": "喝", "is_correct": false, "explanation": "喝是进食动作，与“动”没有反义关系。"}], "correct_answer": "静", "explanations": {"静": "静与动相对，指不动、静止，是这一义项的反义词。", "跑": "跑是快速移动的动作，本身是动态的，与“动”不构成反义。", "看": "看是视觉动作，与“动”没有反义关系。", "喝": "喝是进食动作，与“动”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87125, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "动是身体或东西换了地方，或者不是一直不动。", "primary_collocate": null, "pronunciation": "dòng", "ipa": "tʊŋ˥˩", "syllable_count": 1, "sentences": [{"text": "前面的车一直不动，我们到不了。", "target_word": "动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗坐在门口，一动也不动。", "target_word": "动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他太累了，躺在床上不想动。", "target_word": "动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张桌子太重，我一个人动不了。", "target_word": "动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要动，我给你拍张照片。", "target_word": "动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风很大，树上的叶子都在动。", "target_word": "动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子睡着了，一点儿也没动。", "target_word": "动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的脚很疼，不能动了。", "target_word": "动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面的人动了，我们也走吧。", "target_word": "动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鱼在水里动来动去。", "target_word": "动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "動", "label": "繁体"}, {"form": "动了", "label": "体标"}, {"form": "动着", "label": "体标"}, {"form": "动过", "label": "体标"}, {"form": "动动", "label": "重叠"}], "register": "中性", "sense_fingerprint": "身体或物体移动位置，与不动相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62420910-ffdd-4a2d-9c1d-95797acdc4fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87125, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "动", "is_correct": true, "explanation": "正确：动（dòng）指身体或东西换了位置。"}, {"text": "冬", "is_correct": false, "explanation": "dōng（第一声）与 dòng（第四声）声调不同，意思是冬天。"}, {"text": "董", "is_correct": false, "explanation": "dǒng（第三声）与 dòng（第四声）声调不同，常用作姓。"}, {"text": "痛", "is_correct": false, "explanation": "tòng 与 dòng 声母不同（t 与 d），意思是疼痛。"}, {"text": "懂", "is_correct": false, "explanation": "dǒng（第三声）与 dòng（第四声）声调不同，意思是明白。"}], "explanations": {"动": "正确：动（dòng）指身体或东西换了位置。", "冬": "dōng（第一声）与 dòng（第四声）声调不同，意思是冬天。", "董": "dǒng（第三声）与 dòng（第四声）声调不同，常用作姓。", "痛": "tòng 与 dòng 声母不同（t 与 d），意思是疼痛。", "懂": "dǒng（第三声）与 dòng（第四声）声调不同，意思是明白。"}, "sentence_index": null, "correct_answer": "动"}, "level_3": {"options": [{"text": "动", "is_correct": true, "explanation": "正确：“一直不动”说车没有移动，所以“我们到不了”。"}, {"text": "吃", "is_correct": false, "explanation": "语义：车不会“吃”，句子说的是车停着不走，“吃”与句意无关。"}, {"text": "说", "is_correct": false, "explanation": "语义：车不会“说”，与“我们到不了”的前后语境不符。"}, {"text": "推", "is_correct": false, "explanation": "配价：“推”需要带受事宾语，“一直不推”后面缺少宾语，不成立。"}], "explanations": {"动": "正确：“一直不动”说车没有移动，所以“我们到不了”。", "吃": "语义：车不会“吃”，句子说的是车停着不走，“吃”与句意无关。", "说": "语义：车不会“说”，与“我们到不了”的前后语境不符。", "推": "配价：“推”需要带受事宾语，“一直不推”后面缺少宾语，不成立。"}, "sentence_index": 0, "correct_answer": "动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他动了一个小时的数学题，终于做完了。", "explanation": "这里应该用〈做〉。动表示移动或变化，做数学题要用做，不能说动题。"}, {"text": "听了这个故事，我很动。", "explanation": "这里应该用〈感动〉。动在此表示移动，心里受触动要用感动，“很动”不成立。"}, {"text": "他一只手动着一杯水，另一只手开门。", "explanation": "这里应该用〈端〉。动强调换了位置，端指用手托着，不是移动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87125, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "动", "is_correct": true, "explanation": "正确：动（dòng）指身体或东西换了位置。"}, {"text": "东", "is_correct": false, "explanation": "dōng（第一声）与 dòng（第四声）声调不同，意思是东方。"}, {"text": "弄", "is_correct": false, "explanation": "nòng 与 dòng 声母不同（n 与 d），意思是摆弄、做。"}, {"text": "共", "is_correct": false, "explanation": "gòng 与 dòng 声母不同（g 与 d），意思是共同。"}, {"text": "空", "is_correct": false, "explanation": "kòng 与 dòng 声母不同（k 与 d），意思是空闲。"}], "explanations": {"动": "正确：动（dòng）指身体或东西换了位置。", "东": "dōng（第一声）与 dòng（第四声）声调不同，意思是东方。", "弄": "nòng 与 dòng 声母不同（n 与 d），意思是摆弄、做。", "共": "gòng 与 dòng 声母不同（g 与 d），意思是共同。", "空": "kòng 与 dòng 声母不同（k 与 d），意思是空闲。"}, "sentence_index": null, "correct_answer": "动"}, "level_3": {"options": [{"text": "动", "is_correct": true, "explanation": "正确：“一点儿也没动”指孩子睡着时一点儿没有活动。"}, {"text": "是", "is_correct": false, "explanation": "搭配：“是”不能用“没”否定，“一点儿也没是”不成立。"}, {"text": "喜欢", "is_correct": false, "explanation": "语义：孩子睡着时不会“没喜欢”什么，与句意不合。"}, {"text": "感到", "is_correct": false, "explanation": "配价：“感到”需要带成分（如“累”），单独“没感到”不完整。"}], "explanations": {"动": "正确：“一点儿也没动”指孩子睡着时一点儿没有活动。", "是": "搭配：“是”不能用“没”否定，“一点儿也没是”不成立。", "喜欢": "语义：孩子睡着时不会“没喜欢”什么，与句意不合。", "感到": "配价：“感到”需要带成分（如“累”），单独“没感到”不完整。"}, "sentence_index": 6, "correct_answer": "动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他刚才动了一个电话，很快就接通了。", "explanation": "这里应该用〈打〉。动表示移动或变化，打电话要用打，不能说动电话。"}, {"text": "他动上了一件外套。", "explanation": "这里应该用〈穿〉。动表示位置变化，穿衣服要用穿。"}, {"text": "他一边唱歌，一边动手里的吉他。", "explanation": "这里应该用〈弹〉。动表示移动，弹吉他要用弹，不能说动吉他。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87125, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子动动了小手。", "corrected_sentence": "孩子动了动小手。", "error_description": "“了”位置错误。“动了动”是动词重叠中间加“了”，应为“动了动”；“动动了”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87125, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小鱼在水里动地很快。", "corrected_sentence": "小鱼在水里动得很快。", "error_description": "“得”误写为“地”。“动”后的程度补语要用“得”，应为“动得很快”；“地”是状语标记，不能放在动词后作补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87126, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "静", "is_correct": true, "explanation": "静与动相对，指不动、静止，是这一义项的反义词。"}, {"text": "吃", "is_correct": false, "explanation": "吃是进食动作，与“动”没有反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "唱是发声动作，与“动”没有反义关系。"}, {"text": "写", "is_correct": false, "explanation": "写是书写动作，与“动”没有反义关系。"}], "correct_answer": "静", "explanations": {"静": "静与动相对，指不动、静止，是这一义项的反义词。", "吃": "吃是进食动作，与“动”没有反义关系。", "唱": "唱是发声动作，与“动”没有反义关系。", "写": "写是书写动作，与“动”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87126, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "静", "is_correct": true, "explanation": "静与动相对，指不动、静止，是这一义项的反义词。"}, {"text": "跑", "is_correct": false, "explanation": "跑是快速移动的动作，与“动”没有反义关系。"}, {"text": "看", "is_correct": false, "explanation": "看是视觉动作，与“动”没有反义关系。"}, {"text": "喝", "is_correct": false, "explanation": "喝是进食动作，与“动”没有反义关系。"}], "correct_answer": "静", "explanations": {"静": "静与动相对，指不动、静止，是这一义项的反义词。", "跑": "跑是快速移动的动作，与“动”没有反义关系。", "看": "看是视觉动作，与“动”没有反义关系。", "喝": "喝是进食动作，与“动”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87126, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "物体的位置或状态发生变化；做动作。", "primary_collocate": null, "pronunciation": "dòng", "ipa": "tʊŋ˥˩", "syllable_count": 1, "sentences": [{"text": "他动了动手指，看看还疼不疼。", "target_word": "动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐了很久，我站起来动动腿。", "target_word": "动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课后，大家动一动，做做操。", "target_word": "动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑里的图片动起来了。", "target_word": "动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器一开，轮子就动了。", "target_word": "动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子看见妈妈，高兴得手脚都动起来。", "target_word": "动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水面动了一下，可能有鱼。", "target_word": "动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的嘴动了动，却没有说话。", "target_word": "动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的手一动，杯子就倒了。", "target_word": "动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的手表前几天坏了，现在又动起来了。", "target_word": "动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "動", "label": "繁体"}, {"form": "动了", "label": "体标"}, {"form": "动着", "label": "体标"}, {"form": "动过", "label": "体标"}, {"form": "动动", "label": "重叠"}], "register": "中性", "sense_fingerprint": "物体状态变化或身体部位做动作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62420910-ffdd-4a2d-9c1d-95797acdc4fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87126, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "动", "is_correct": true, "explanation": "正确：动（dòng）指物体的位置或状态发生变化。"}, {"text": "冬", "is_correct": false, "explanation": "dōng（第一声）与 dòng（第四声）声调不同，意思是冬天。"}, {"text": "董", "is_correct": false, "explanation": "dǒng（第三声）与 dòng（第四声）声调不同，常用作姓。"}, {"text": "痛", "is_correct": false, "explanation": "tòng 与 dòng 声母不同（t 与 d），意思是疼痛。"}, {"text": "懂", "is_correct": false, "explanation": "dǒng（第三声）与 dòng（第四声）声调不同，意思是明白。"}], "explanations": {"动": "正确：动（dòng）指物体的位置或状态发生变化。", "冬": "dōng（第一声）与 dòng（第四声）声调不同，意思是冬天。", "董": "dǒng（第三声）与 dòng（第四声）声调不同，常用作姓。", "痛": "tòng 与 dòng 声母不同（t 与 d），意思是疼痛。", "懂": "dǒng（第三声）与 dòng（第四声）声调不同，意思是明白。"}, "sentence_index": null, "correct_answer": "动"}, "level_3": {"options": [{"text": "动", "is_correct": true, "explanation": "正确：“动了动手指”表示手指活动一下，句意完整。"}, {"text": "吃", "is_correct": false, "explanation": "语义：手指不能被“吃”，句子说的是活动手指。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写了手指”不成立，与看疼不疼的句意无关。"}, {"text": "抬", "is_correct": false, "explanation": "配价：“抬”需要带受事宾语，“抬了动手指”结构不成立。"}], "explanations": {"动": "正确：“动了动手指”表示手指活动一下，句意完整。", "吃": "语义：手指不能被“吃”，句子说的是活动手指。", "写": "语义：“写了手指”不成立，与看疼不疼的句意无关。", "抬": "配价：“抬”需要带受事宾语，“抬了动手指”结构不成立。"}, "sentence_index": 0, "correct_answer": "动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电脑动好了。", "explanation": "这里应该用〈修〉。动表示位置或状态的改变，电脑修好要用修。"}, {"text": "天色动起来了，看样子要下雨。", "explanation": "这里应该用〈暗下来〉。“要下雨”指天色变暗，动起来指开始活动，不能形容天色的变化。"}, {"text": "他昨天动了一幅水墨，很漂亮。", "explanation": "这里应该用〈画〉。动表示位置或状态的改变，画一幅水墨要用画，不能说动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87126, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "动", "is_correct": true, "explanation": "正确：动（dòng）指物体的位置或状态发生变化。"}, {"text": "东", "is_correct": false, "explanation": "dōng（第一声）与 dòng（第四声）声调不同，意思是东方。"}, {"text": "弄", "is_correct": false, "explanation": "nòng 与 dòng 声母不同（n 与 d），意思是摆弄、做。"}, {"text": "共", "is_correct": false, "explanation": "gòng 与 dòng 声母不同（g 与 d），意思是共同。"}, {"text": "空", "is_correct": false, "explanation": "kòng 与 dòng 声母不同（k 与 d），意思是空闲。"}], "explanations": {"动": "正确：动（dòng）指物体的位置或状态发生变化。", "东": "dōng（第一声）与 dòng（第四声）声调不同，意思是东方。", "弄": "nòng 与 dòng 声母不同（n 与 d），意思是摆弄、做。", "共": "gòng 与 dòng 声母不同（g 与 d），意思是共同。", "空": "kòng 与 dòng 声母不同（k 与 d），意思是空闲。"}, "sentence_index": null, "correct_answer": "动"}, "level_3": {"options": [{"text": "动", "is_correct": true, "explanation": "正确：“水面动了一下”说水面有了变化，所以“可能有鱼”。"}, {"text": "唱", "is_correct": false, "explanation": "语义：水面不会“唱”，与“可能有鱼”的句意不合。"}, {"text": "踢", "is_correct": false, "explanation": "配价：“踢”需要带宾语，“水面踢了一下”结构不成立。"}, {"text": "骂", "is_correct": false, "explanation": "语义：水面不会“骂”，与句意无关。"}], "explanations": {"动": "正确：“水面动了一下”说水面有了变化，所以“可能有鱼”。", "唱": "语义：水面不会“唱”，与“可能有鱼”的句意不合。", "踢": "配价：“踢”需要带宾语，“水面踢了一下”结构不成立。", "骂": "语义：水面不会“骂”，与句意无关。"}, "sentence_index": 6, "correct_answer": "动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他给墙动了一层漆，颜色很好看。", "explanation": "这里应该用〈涂〉。动表示位置或状态的改变，给墙涂漆要用涂，不能说动一层漆。"}, {"text": "门铃动起来了，有人来了。", "explanation": "这里应该用〈响〉。门铃发出声音要说响，动指位置或状态变化，不能说门铃动起来。"}, {"text": "他拿起笔，一边想一边动字。", "explanation": "这里应该用〈写〉。动表示位置或状态的改变，写字要用写，不能说动字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87126, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "屏幕突然动出来了。", "corrected_sentence": "屏幕突然动起来了。", "error_description": "补语“出来”用错。表示动作开始并持续的补语是“起来”，应说“动起来”；“动出来”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87126, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车子动地很慢，我们都在等。", "corrected_sentence": "车子动得很慢，我们都在等。", "error_description": "“得”误写为“地”。“动”后的程度补语要用“得”，应为“动得很慢”；“动地很慢”中“地”是状语标记，不能放在动词后作补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
