INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87128, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "难度很高的，多用作修饰语，如“高难动作”。", "primary_collocate": null, "pronunciation": "gāo nán", "ipa": "kaʊ˥ nan˧˥", "syllable_count": 2, "sentences": [{"text": "他在比赛中做了一个高难动作。", "target_word": "高难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "体操运动员完成了高难动作。", "target_word": "高难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位演员能拍高难的武打戏。", "target_word": "高难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她弹了一首高难的钢琴曲。", "target_word": "高难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一个高难任务，大家要小心。", "target_word": "高难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他练了很久高难技巧。", "target_word": "高难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友不能做高难动作。", "target_word": "高难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他完成了一次高难的跳水。", "target_word": "高难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛没有高难的项目。", "target_word": "高难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里有很多高难镜头。", "target_word": "高难", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "高难度", "label": "复合"}], "register": "中性", "sense_fingerprint": "放在名词前修饰，指难度很高的动作、技巧、任务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8eeb9b7-da00-4ad1-a443-5d1569c7e006') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87128, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高难", "is_correct": true, "explanation": "高难：指难度很高，修饰“动作”，符合句意。"}, {"text": "悠久", "is_correct": false, "explanation": "搭配：“悠久”说历史或时间很长，不能修饰“动作”。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材或外形，不能描述动作。"}, {"text": "漫长", "is_correct": false, "explanation": "语义：“漫长”说时间很长，与动作的难度无关。"}], "explanations": {"高难": "高难：指难度很高，修饰“动作”，符合句意。", "悠久": "搭配：“悠久”说历史或时间很长，不能修饰“动作”。", "高大": "体貌：“高大”形容身材或外形，不能描述动作。", "漫长": "语义：“漫长”说时间很长，与动作的难度无关。"}, "sentence_index": 0, "correct_answer": "高难"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座高难的大楼又高又漂亮。", "explanation": "这里应该用〈雄伟〉。高难指难度很高，形容大楼的壮观要用雄伟，不能用高难。"}, {"text": "他有一副高难的脾气。", "explanation": "这里应该用〈暴躁〉。高难指难度很高的动作、技巧，不用来形容脾气；脾气急躁要用暴躁。"}, {"text": "他喝了一碗高难的汤。", "explanation": "这里应该用〈鲜美〉。高难指难度很高，不用来形容汤的味道，味道好要用鲜美。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e9f44bb-1b42-4c1e-8695-cf84254f4d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87128, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高难", "is_correct": true, "explanation": "高难：指难度很高，与“动作”搭配，符合句意。"}, {"text": "年迈", "is_correct": false, "explanation": "语义：“年迈”说年纪很大，与“小朋友”矛盾。"}, {"text": "庞大", "is_correct": false, "explanation": "体貌：“庞大”形容体积或规模很大，不能修饰动作。"}, {"text": "健壮", "is_correct": false, "explanation": "搭配：“健壮”形容人或身体，不说“健壮动作”。"}], "explanations": {"高难": "高难：指难度很高，与“动作”搭配，符合句意。", "年迈": "语义：“年迈”说年纪很大，与“小朋友”矛盾。", "庞大": "体貌：“庞大”形容体积或规模很大，不能修饰动作。", "健壮": "搭配：“健壮”形容人或身体，不说“健壮动作”。"}, "sentence_index": 6, "correct_answer": "高难"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的弟弟是一个高难的人。", "explanation": "这里应该用〈能干〉。高难指事情的难度很高，形容人的本领强要用能干。"}, {"text": "他在高难的时候睡着了。", "explanation": "这里应该用〈困难〉。高难多指技术、动作等难度很高，表示处境艰难要用困难，不说高难的时候。"}, {"text": "她有一个高难的微笑。", "explanation": "这里应该用〈甜美〉。高难指难度很高的动作、技巧，不用来形容表情；形容笑容好看要用甜美。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e9f44bb-1b42-4c1e-8695-cf84254f4d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87128, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "运动员表演了一套高难地动作。", "corrected_sentence": "运动员表演了一套高难的动作。", "error_description": "错误：“高难地”，正确：“高难的”。“高难”修饰名词“动作”作定语，要用“的”，不能用“地”；“地”用在状语后面修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e9f44bb-1b42-4c1e-8695-cf84254f4d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87128, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位教练教给队员许多高难了动作。", "corrected_sentence": "这位教练教给队员许多高难动作。", "error_description": "错误：“高难了”，正确：“高难”。形容词“高难”作定语时不带“了”，直接修饰名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e9f44bb-1b42-4c1e-8695-cf84254f4d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
