INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87129, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "报道是把新发生的事写下来或说出来，告诉大家。", "primary_collocate": null, "pronunciation": "bào dào", "ipa": "pau̯˥˩ tau̯˥˩", "syllable_count": 2, "sentences": [{"text": "记者报道了这次比赛的结果。", "target_word": "报道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸今天报道了一场大雨。", "target_word": "报道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王每天报道学校里的新鲜事。", "target_word": "报道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网站马上报道了这件事。", "target_word": "报道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想报道城市里的新公园。", "target_word": "报道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个记者报道过很多大事。", "target_word": "报道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天的大火，电视台没有报道。", "target_word": "报道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要如实报道，不能说假话。", "target_word": "报道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他到现场报道那场足球赛。", "target_word": "报道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生记者报道了运动会的新闻。", "target_word": "报道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "报道了", "label": "完成体"}, {"form": "报道过", "label": "经历体"}, {"form": "報道", "label": "繁体"}], "register": "书面", "sense_fingerprint": "把新发生的事写出来或说出来告诉大家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '679c1d60-cd18-4bd7-984c-952bf355ca55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87129, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "报道", "is_correct": true, "explanation": "报道（bào dào）是正确答案：把新闻告诉大家。"}, {"text": "宝岛", "is_correct": false, "explanation": "bǎo dǎo（第三声、第三声）与 bào dào（第四声、第四声）声调不同，宝岛意思是宝贵的岛屿。"}, {"text": "宝刀", "is_correct": false, "explanation": "bǎo（第三声）与 bào（第四声）、dāo（第一声）与 dào（第四声）声调不同，宝刀意思是珍贵的刀。"}, {"text": "跑道", "is_correct": false, "explanation": "pǎo（第三声）与 bào（第四声）声母和声调都不同，跑道意思是跑步或飞机起降的路。"}], "explanations": {"报道": "报道（bào dào）是正确答案：把新闻告诉大家。", "宝岛": "bǎo dǎo（第三声、第三声）与 bào dào（第四声、第四声）声调不同，宝岛意思是宝贵的岛屿。", "宝刀": "bǎo（第三声）与 bào（第四声）、dāo（第一声）与 dào（第四声）声调不同，宝刀意思是珍贵的刀。", "跑道": "pǎo（第三声）与 bào（第四声）声母和声调都不同，跑道意思是跑步或飞机起降的路。"}, "sentence_index": null, "correct_answer": "报道"}, "level_3": {"options": [{"text": "报道", "is_correct": true, "explanation": "报道是正确答案：记者把比赛结果告诉大家，与“记者”搭配。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象应是食物，不能吃“比赛的结果”。"}, {"text": "原谅", "is_correct": false, "explanation": "配价：“原谅”的对象是人或行为，不能原谅“比赛的结果”。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是场地或房间，不能说打扫“结果”。"}], "explanations": {"报道": "报道是正确答案：记者把比赛结果告诉大家，与“记者”搭配。", "吃": "语义：“吃”的对象应是食物，不能吃“比赛的结果”。", "原谅": "配价：“原谅”的对象是人或行为，不能原谅“比赛的结果”。", "打扫": "搭配：“打扫”的对象是场地或房间，不能说打扫“结果”。"}, "sentence_index": 0, "correct_answer": "报道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师报道了明天放假的消息。", "explanation": "这里应该用〈通知〉。报道指媒体把新闻告诉公众，老师对学生发布事项要用通知。"}, {"text": "我向老板报道了这个月的销售情况。", "explanation": "这里应该用〈报告〉。报道用于向公众发布新闻，向上级或老板汇报工作要用报告。"}, {"text": "市长报道了新的交通规定。", "explanation": "这里应该用〈宣布〉。报道是媒体向公众播发消息，政府或领导正式公布规定要用宣布。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c3275f-1f36-42e1-853d-49a133abf938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87129, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "报道", "is_correct": true, "explanation": "报道是正确答案：电视台没有把大火的情况告诉大众。"}, {"text": "扑灭", "is_correct": false, "explanation": "语义：“扑灭”是把火弄灭，电视台并不灭火，与句意不合。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”的对象是车辆等交通工具，句中没有可驾驶的东西。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：“咳嗽”是身体动作，与大火和电视台无关，句意不通。"}], "explanations": {"报道": "报道是正确答案：电视台没有把大火的情况告诉大众。", "扑灭": "语义：“扑灭”是把火弄灭，电视台并不灭火，与句意不合。", "驾驶": "搭配：“驾驶”的对象是车辆等交通工具，句中没有可驾驶的东西。", "咳嗽": "语义：“咳嗽”是身体动作，与大火和电视台无关，句意不通。"}, "sentence_index": 6, "correct_answer": "报道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奶奶报道了小时候的故事。", "explanation": "这里应该用〈讲述〉。报道指把新闻告诉公众，讲述自己的经历和故事要用讲述。"}, {"text": "导游报道了这座古城的历史。", "explanation": "这里应该用〈介绍〉。报道侧重发布新闻，向游客讲解景点要用介绍。"}, {"text": "他在论坛上报道了自己的观点。", "explanation": "这里应该用〈发表〉。报道指媒体发布新闻，个人公开观点要用发表。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c3275f-1f36-42e1-853d-49a133abf938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87129, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "记者报道地这场比赛。", "corrected_sentence": "记者报道了这场比赛。", "error_description": "错误形式：“记者报道地这场比赛”。正确形式：“记者报道了这场比赛”。“地”是状语助词，不能放在动词和宾语之间，应删去；“了”表示动作已完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c3275f-1f36-42e1-853d-49a133abf938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87129, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "电视台把这件事报道。", "corrected_sentence": "电视台把这件事报道了。", "error_description": "错误形式：“电视台把这件事报道”。正确形式：“电视台把这件事报道了”。用“把”字句时，动词后面要有其他成分，这里应加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c3275f-1f36-42e1-853d-49a133abf938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
