INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87130, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通过报纸、广播、电视等把新闻告诉公众。", "primary_collocate": null, "pronunciation": "bào dào", "ipa": "pau̯˥˩ tau̯˥˩", "syllable_count": 2, "sentences": [{"text": "电视台正在报道今天的天气。", "target_word": "报道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广播里报道了一个好消息。", "target_word": "报道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸报道了新地铁开通的消息。", "target_word": "报道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视里报道着地震的最新情况。", "target_word": "报道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各大报纸都报道了这次会议。", "target_word": "报道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电台每天早上报道交通情况。", "target_word": "报道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨晚的新闻没有报道这件事。", "target_word": "报道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视台报道说，明天会下雪。", "target_word": "报道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上报道过那位老人的故事。", "target_word": "报道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广播刚才报道了火车晚点的消息。", "target_word": "报道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "报道了", "label": "完成体"}, {"form": "报道着", "label": "持续体"}, {"form": "报道过", "label": "经历体"}, {"form": "報道", "label": "繁体"}], "register": "书面", "sense_fingerprint": "通过报纸、广播、电视等向公众发布新闻", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '679c1d60-cd18-4bd7-984c-952bf355ca55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87130, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "报道", "is_correct": true, "explanation": "报道（bào dào）是正确答案：通过媒体把新闻告诉公众。"}, {"text": "宝岛", "is_correct": false, "explanation": "bǎo dǎo（第三声、第三声）与 bào dào（第四声、第四声）声调不同，宝岛意思是宝贵的岛屿。"}, {"text": "宝刀", "is_correct": false, "explanation": "bǎo（第三声）与 bào（第四声）、dāo（第一声）与 dào（第四声）声调不同，宝刀意思是珍贵的刀。"}, {"text": "跑道", "is_correct": false, "explanation": "pǎo（第三声）与 bào（第四声）声母和声调都不同，跑道意思是跑步或飞机起降的路。"}], "explanations": {"报道": "报道（bào dào）是正确答案：通过媒体把新闻告诉公众。", "宝岛": "bǎo dǎo（第三声、第三声）与 bào dào（第四声、第四声）声调不同，宝岛意思是宝贵的岛屿。", "宝刀": "bǎo（第三声）与 bào（第四声）、dāo（第一声）与 dào（第四声）声调不同，宝刀意思是珍贵的刀。", "跑道": "pǎo（第三声）与 bào（第四声）声母和声调都不同，跑道意思是跑步或飞机起降的路。"}, "sentence_index": null, "correct_answer": "报道"}, "level_3": {"options": [{"text": "报道", "is_correct": true, "explanation": "报道是正确答案：电视台向观众播报今天的天气情况。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”的对象是物品或身体，不能洗“天气”。"}, {"text": "出版", "is_correct": false, "explanation": "搭配：“出版”的对象是书刊等出版物，不能出版“天气”。"}, {"text": "尊敬", "is_correct": false, "explanation": "配价：“尊敬”的对象是人，不能尊敬“今天的天气”。"}], "explanations": {"报道": "报道是正确答案：电视台向观众播报今天的天气情况。", "洗": "语义：“洗”的对象是物品或身体，不能洗“天气”。", "出版": "搭配：“出版”的对象是书刊等出版物，不能出版“天气”。", "尊敬": "配价：“尊敬”的对象是人，不能尊敬“今天的天气”。"}, "sentence_index": 0, "correct_answer": "报道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "班长报道了这次考试的成绩。", "explanation": "这里应该用〈公布〉。报道是媒体向公众发布新闻，班长在班里公开成绩要用公布。"}, {"text": "妈妈报道了我小时候的事情。", "explanation": "这里应该用〈讲述〉。报道多指媒体发布新闻，家人讲述往事要用讲述。"}, {"text": "这位画家报道了自己的新作品。", "explanation": "这里应该用〈介绍〉。报道是对新闻的发布，向别人推介自己的作品要用介绍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c3275f-1f36-42e1-853d-49a133abf938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDE