INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87130, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "报道", "is_correct": true, "explanation": "报道是正确答案：昨晚的新闻没有把这件事告诉观众。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”的对象是交通工具，不能驾驶“这件事”。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：“咳嗽”是身体动作，与新闻无关，句意不通。"}, {"text": "拥抱", "is_correct": false, "explanation": "配价：“拥抱”的对象应是人，不能拥抱“这件事”。"}], "explanations": {"报道": "报道是正确答案：昨晚的新闻没有把这件事告诉观众。", "驾驶": "搭配：“驾驶”的对象是交通工具，不能驾驶“这件事”。", "咳嗽": "语义：“咳嗽”是身体动作，与新闻无关，句意不通。", "拥抱": "配价：“拥抱”的对象应是人，不能拥抱“这件事”。"}, "sentence_index": 6, "correct_answer": "报道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "班主任报道了明天放假的消息。", "explanation": "这里应该用〈通知〉。报道指媒体把新闻告诉公众，班主任对学生发布事项要用通知。"}, {"text": "市长报道了新的税收政策。", "explanation": "这里应该用〈宣布〉。报道是媒体向公众播发消息，政府正式公布政策要用宣布。"}, {"text": "他在网上报道了自己的观点。", "explanation": "这里应该用〈发表〉。报道指媒体发布新闻，个人公开观点要用发表。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c3275f-1f36-42e1-853d-49a133abf938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87130, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "电视台报道地这件事。", "corrected_sentence": "电视台报道了这件事。", "error_description": "错误形式：“电视台报道地这件事”。正确形式：“电视台报道了这件事”。“地”是状语助词，不能放在动词和宾语之间，应删去；“了”表示动作已完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c3275f-1f36-42e1-853d-49a133abf938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87130, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "报纸把这次地震报道。", "corrected_sentence": "报纸把这次地震报道了。", "error_description": "错误形式：“报纸把这次地震报道”。正确形式：“报纸把这次地震报道了”。用“把”字句时，动词后面要有其他成分，这里应加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c3275f-1f36-42e1-853d-49a133abf938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
