INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87131, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "点穿是把别人藏起来的事说出来，让大家都知道。", "primary_collocate": null, "pronunciation": "diǎn chuān", "ipa": "tiɛn²¹⁴ ʈʂʰuan⁵⁵", "syllable_count": 2, "sentences": [{"text": "我不小心点穿了小王的秘密。", "target_word": "点穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在会上点穿了同事的错误，大家都很吃惊。", "target_word": "点穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁也没想到，她当众点穿了这件事。", "target_word": "点穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友的小秘密，你别当着大家点穿。", "target_word": "点穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师当着全班点穿了他作弊的事。", "target_word": "点穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理点穿了公司藏着的问题，大家都知道了。", "target_word": "点穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件丢脸的事，请你不要在朋友面前点穿。", "target_word": "点穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从没在人多的地方点穿过别人的事。", "target_word": "点穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居当着大家点穿了他一直瞒着的事。", "target_word": "点穿", "complexity_tier": "T3", "furigana": "lín jū dāng zhe dà jiā diǎn chuān le tā yì zhí mán zhe de shì.", "sentence_source": "generated"}, {"text": "妈妈把弟弟藏起来的事点穿了。", "target_word": "点穿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "点穿了", "label": "体标"}, {"form": "点穿过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把别人藏着的事公开说出来，让众人知晓", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f67254c-2b72-48f7-a62f-6cc95d11eae2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87131, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "煮", "is_correct": false, "explanation": "语义：“煮”是烹饪动作，与“秘密”毫不相干，句子说不通。"}, {"text": "点穿", "is_correct": true, "explanation": "点穿：指把别人藏着的事公开说出来，与“不小心”和“小王的秘密”相符，句子通顺。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指把食物咽下去，与“秘密”毫无关系，句子说不通。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，后面不能直接带“秘密”作宾语。"}], "explanations": {"煮": "语义：“煮”是烹饪动作，与“秘密”毫不相干，句子说不通。", "点穿": "点穿：指把别人藏着的事公开说出来，与“不小心”和“小王的秘密”相符，句子通顺。", "吃": "语义：“吃”指把食物咽下去，与“秘密”毫无关系，句子说不通。", "睡": "配价：“睡”是不及物动词，后面不能直接带“秘密”作宾语。"}, "sentence_index": 0, "correct_answer": "点穿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他点穿了一个不需要保密的通知，大家都很高兴。", "explanation": "这里应该用〈公开〉。点穿指说出别人藏着的事，通知本来就是公开的，没有需要点穿的隐藏内容。"}, {"text": "她点穿了我的鞋子，大家都笑了。", "explanation": "这里应该用〈看见〉。点穿是把藏着的事说出来、让大家知道，鞋子是人人看得见的东西，不能说点穿。"}, {"text": "她点穿了桌上的苹果，大家都笑了。", "explanation": "这里应该用〈指着〉。点穿是把别人藏着的事说出来、让大家知道，桌上的苹果是人人看得见的东西，没有什么藏着的事，不能说点穿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87131, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”指把一种语言转换成另一种语言，与“丢脸的事”毫不相干，句子说不通。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”一般搭配衣物、身体等，不能说洗“丢脸的事”。"}, {"text": "点穿", "is_correct": true, "explanation": "点穿：指把藏着的事公开说出来，正好与“不要在朋友面前”和“丢脸的事”的语境相合。"}, {"text": "复印", "is_correct": false, "explanation": "语义：“复印”只用于文件、资料，不能用于一件丢脸的事。"}], "explanations": {"翻译": "语义：“翻译”指把一种语言转换成另一种语言，与“丢脸的事”毫不相干，句子说不通。", "洗": "搭配：“洗”一般搭配衣物、身体等，不能说洗“丢脸的事”。", "点穿": "点穿：指把藏着的事公开说出来，正好与“不要在朋友面前”和“丢脸的事”的语境相合。", "复印": "语义：“复印”只用于文件、资料，不能用于一件丢脸的事。"}, "sentence_index": 6, "correct_answer": "点穿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "校长点穿了放假的消息，大家都很高兴。", "explanation": "这里应该用〈宣布〉。点穿指揭开别人藏着的事，放假的消息本来就是公开的，不能说点穿。"}, {"text": "爷爷点穿了窗外的风景，我们都很喜欢。", "explanation": "这里应该用〈欣赏〉。点穿是揭开别人藏着的事，窗外的风景是看得见的东西，应说欣赏，不能说点穿。"}, {"text": "老师点穿了今天的天气，大家都笑了。", "explanation": "这里应该用〈预报〉。点穿是揭开别人藏着的事，天气是人人都能感受到的，应说预报，不能说点穿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87131, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在聚会上把点穿了小李的秘密。", "corrected_sentence": "她在聚会上点穿了小李的秘密。", "error_description": "“把”字句中“把”必须后接宾语再接动词，如“把小李的秘密点穿了”；“把”直接放在“点穿”前面、宾语却在后面是错误的，正确形式是“点穿了小李的秘密”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87131, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他当着全班同学的点穿了我的小秘密。", "corrected_sentence": "他当着全班同学点穿了我的小秘密。", "error_description": "“当着全班同学”是状语，后面不能加结构助词“的”，应直接接动词“点穿”，写作“当着全班同学点穿了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
