INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87132, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把隐藏的事情或用意直接指出，揭穿。", "primary_collocate": null, "pronunciation": "diǎn chuān", "ipa": "tiɛn²¹⁴ ʈʂʰuan⁵⁵", "syllable_count": 2, "sentences": [{"text": "她一下子点穿了他的真正用意。", "target_word": "点穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友点穿了我心里的想法，我很不好意思。", "target_word": "点穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想借钱，我直接点穿了他的目的。", "target_word": "点穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师笑着点穿了学生的小心思。", "target_word": "点穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们点穿了对方的计划，他不再说话了。", "target_word": "点穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我一眼就点穿了他的用意。", "target_word": "点穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她话里有话，但我没有点穿。", "target_word": "点穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈点穿过我的心事，所以我什么也瞒不住。", "target_word": "点穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的借口太明显，我马上点穿了。", "target_word": "点穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要不要点穿他的用意，我想了很久。", "target_word": "点穿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "点穿了", "label": "体标"}, {"form": "点穿过", "label": "体标"}], "register": "中性", "sense_fingerprint": "直接指出对方隐藏的用意或想法，揭穿", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f67254c-2b72-48f7-a62f-6cc95d11eae2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87132, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "修改", "is_correct": false, "explanation": "搭配：“修改”用于文章、计划等可以改动的东西，不能说修改“用意”。"}, {"text": "点穿", "is_correct": true, "explanation": "点穿：指直接指出对方隐藏的用意，与“一下子”和“真正用意”相符，句子通顺。"}, {"text": "来", "is_correct": false, "explanation": "配价：“来”是不及物动词，后面不能直接带“用意”作宾语。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指把食物咽下去，与“用意”无关，句子说不通。"}], "explanations": {"修改": "搭配：“修改”用于文章、计划等可以改动的东西，不能说修改“用意”。", "点穿": "点穿：指直接指出对方隐藏的用意，与“一下子”和“真正用意”相符，句子通顺。", "来": "配价：“来”是不及物动词，后面不能直接带“用意”作宾语。", "吃": "语义：“吃”指把食物咽下去，与“用意”无关，句子说不通。"}, "sentence_index": 0, "correct_answer": "点穿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她点穿了这碗汤的咸淡，我很喜欢。", "explanation": "这里应该用〈尝出〉。点穿是揭开对方隐藏的用意，咸淡靠味觉感受，应说尝出，不能说点穿。"}, {"text": "老板点穿了这台机器的外壳，大家都很惊讶。", "explanation": "这里应该用〈打开〉。点穿是揭开对方隐藏的用意或事情，外壳是看得见的实物，应说打开，不能说点穿。"}, {"text": "她点穿了我的眼泪，我很不好意思。", "explanation": "这里应该用〈察觉〉。点穿是揭开对方隐藏的用意，哭出的泪是看得见的，只能说察觉，不能说点穿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87132, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "扔", "is_correct": false, "explanation": "配价：“扔”要带具体的东西作宾语，不能扔“话”，“没有扔”也说不通。"}, {"text": "点穿", "is_correct": true, "explanation": "点穿：指直接指出对方隐藏的用意，与“话里有话”的暗示相合，句子通顺。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指用声音演唱，与前句“话里有话”的暗示毫不相干。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”是烹饪动作，与前句说话的内容毫不相干，句子说不通。"}], "explanations": {"扔": "配价：“扔”要带具体的东西作宾语，不能扔“话”，“没有扔”也说不通。", "点穿": "点穿：指直接指出对方隐藏的用意，与“话里有话”的暗示相合，句子通顺。", "唱": "语义：“唱”指用声音演唱，与前句“话里有话”的暗示毫不相干。", "煮": "语义：“煮”是烹饪动作，与前句说话的内容毫不相干，句子说不通。"}, "sentence_index": 6, "correct_answer": "点穿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他无意中点穿了一条小道消息，大家都没当回事。", "explanation": "这里应该用〈透露〉。点穿针对的是对方隐藏的用意或想法，小道消息只是传闻，不是用意，不能用点穿。"}, {"text": "他很快点穿了这块蛋糕的分量，我们都吃饱了。", "explanation": "这里应该用〈估计〉。点穿是揭开对方隐藏的用意，分量要靠估计，不能说点穿。"}, {"text": "我点穿了厨房里飘来的香味，大家都很惊讶。", "explanation": "这里应该用〈闻到〉。点穿针对的是对方隐藏的用意或想法，香味靠嗅觉感受，不能说点穿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87132, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一看就把点穿了我的小计划。", "corrected_sentence": "他一看就点穿了我的小计划。", "error_description": "“把”字句中“把”必须后接宾语再接动词；“把”直接放在“点穿”前面、宾语却在后面是错误的，正确形式是“点穿了我的小计划”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87132, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师当面的点穿了他的用意，他很不好意思。", "corrected_sentence": "老师当面点穿了他的用意，他很不好意思。", "error_description": "“当面”是状语，后面不能加结构助词“的”，应直接接动词“点穿”，写作“当面点穿了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
