INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87133, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "司机是开汽车的人。", "primary_collocate": null, "pronunciation": "sī jī", "ipa": "sɨ˥ tɕi˥", "syllable_count": 2, "sentences": [{"text": "司机在门口等我们。", "target_word": "司机", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "出租车司机问我去哪儿。", "target_word": "司机", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这位司机开车很稳。", "target_word": "司机", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们公司请了一个司机。", "target_word": "司机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "司机把我送到了机场。", "target_word": "司机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是我们家的司机。", "target_word": "司机", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那个司机一直按喇叭，很吵。", "target_word": "司机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨了，司机开得很小心。", "target_word": "司机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "司机说前面堵车，要等一会儿。", "target_word": "司机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她想当一名出租车司机。", "target_word": "司机", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位司机", "label": "量词"}, {"form": "一名司机", "label": "量词"}, {"form": "出租车司机", "label": "复合"}, {"form": "司机师傅", "label": "复合"}, {"form": "司機", "label": "繁体"}], "register": "中性", "sense_fingerprint": "开汽车的人，如出租车司机、家用司机", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa572e2a-b4ac-45be-a597-2cd926dc15a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87133, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "司机", "is_correct": true, "explanation": "正确。司机指开汽车的人。"}, {"text": "死机", "is_correct": false, "explanation": "死机（sǐjī）第一个音节是第三声，与 sī（第一声）声调不同，意思是电脑等设备停止响应。"}, {"text": "四季", "is_correct": false, "explanation": "四季（sìjì）两个音节的声调都与 sījī 不同，意思是一年的四个季节。"}, {"text": "四级", "is_correct": false, "explanation": "四级（sìjí）两个音节的声调都与 sījī 不同，意思是等级。"}, {"text": "死记", "is_correct": false, "explanation": "死记（sǐjì）两个音节的声调都与 sījī 不同，意思是死记硬背。"}], "explanations": {"司机": "正确。司机指开汽车的人。", "死机": "死机（sǐjī）第一个音节是第三声，与 sī（第一声）声调不同，意思是电脑等设备停止响应。", "四季": "四季（sìjì）两个音节的声调都与 sījī 不同，意思是一年的四个季节。", "四级": "四级（sìjí）两个音节的声调都与 sījī 不同，意思是等级。", "死记": "死记（sǐjì）两个音节的声调都与 sījī 不同，意思是死记硬背。"}, "sentence_index": null, "correct_answer": "司机"}, "level_3": {"options": [{"text": "司机", "is_correct": true, "explanation": "正确。司机可以在门口等人。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子是家具，不会等人，与“在门口等我们”矛盾。"}, {"text": "大楼", "is_correct": false, "explanation": "搭配：“等我们”的主语一般是人，不说“大楼在门口等我们”。"}, {"text": "墙", "is_correct": false, "explanation": "语义：墙是建筑构件，不会主动等人。"}], "explanations": {"司机": "正确。司机可以在门口等人。", "椅子": "语义：椅子是家具，不会等人，与“在门口等我们”矛盾。", "大楼": "搭配：“等我们”的主语一般是人，不说“大楼在门口等我们”。", "墙": "语义：墙是建筑构件，不会主动等人。"}, "sentence_index": 0, "correct_answer": "司机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "司机站在甲板上指挥航行。", "explanation": "这里应该用〈船长〉。司机是开汽车的人，指挥船只航行的是船长。"}, {"text": "我的班主任是司机，每天在黑板上写字。", "explanation": "这里应该用〈老师〉。司机指驾驶车辆的人，在黑板上写字讲课是老师的工作。"}, {"text": "司机在厨房里炒菜，味道很好。", "explanation": "这里应该用〈厨师〉。司机指驾驶车辆的人，炒菜做饭是厨师的工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05a8306a-788d-4b3d-855a-baf197742313') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87133, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "司机", "is_correct": true, "explanation": "正确。司机指开汽车的人。"}, {"text": "时机", "is_correct": false, "explanation": "时机（shíjī）声母是 sh 而不是 s，第一个音节是第二声，与 sījī 读音不同。意思是合适的机会。"}, {"text": "诗集", "is_correct": false, "explanation": "诗集（shījí）声母是 sh 而不是 s，第二个音节是第二声，与 sījī 读音不同。意思是诗的合集。"}, {"text": "实际", "is_correct": false, "explanation": "实际（shíjì）声母是 sh，两个音节的声调都与 sījī 不同。意思是客观存在的情况。"}], "explanations": {"司机": "正确。司机指开汽车的人。", "时机": "时机（shíjī）声母是 sh 而不是 s，第一个音节是第二声，与 sījī 读音不同。意思是合适的机会。", "诗集": "诗集（shījí）声母是 sh 而不是 s，第二个音节是第二声，与 sījī 读音不同。意思是诗的合集。", "实际": "实际（shíjì）声母是 sh，两个音节的声调都与 sījī 不同。意思是客观存在的情况。"}, "sentence_index": null, "correct_answer": "司机"}, "level_3": {"options": [{"text": "司机", "is_correct": true, "explanation": "正确。司机开车，会按喇叭。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会按喇叭，与句中的动作矛盾。"}, {"text": "大树", "is_correct": false, "explanation": "语义：大树不会按喇叭，句中的动作需要人或车辆来完成。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“按喇叭”的主语是人或车辆，不搭配“窗户”。"}], "explanations": {"司机": "正确。司机开车，会按喇叭。", "石头": "语义：石头不会按喇叭，与句中的动作矛盾。", "大树": "语义：大树不会按喇叭，句中的动作需要人或车辆来完成。", "窗户": "搭配：“按喇叭”的主语是人或车辆，不搭配“窗户”。"}, "sentence_index": 6, "correct_answer": "司机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "司机在演播室里播报新闻，声音很好听。", "explanation": "这里应该用〈播音员〉。司机指驾驶车辆的人，播报新闻是播音员的工作。"}, {"text": "司机在病房里给病人打针。", "explanation": "这里应该用〈护士〉。司机指驾驶车辆的人，给病人打针是护士的工作。"}, {"text": "司机在法庭上为被告辩护，很有说服力。", "explanation": "这里应该用〈律师〉。司机指驾驶车辆的人，在法庭上为被告辩护是律师的工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05a8306a-788d-4b3d-855a-baf197742313') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87133, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我姐姐现在是一只出租车司机。", "corrected_sentence": "我姐姐现在是一名出租车司机。", "error_description": "错误形式：“一只出租车司机”。正确形式：“一名出租车司机”。“只”用于动物和部分物件，指人的司机应用量词“名”（或“位”）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05a8306a-788d-4b3d-855a-baf197742313') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87133, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "舅舅是我们家的一司机。", "corrected_sentence": "舅舅是我们家的一个司机。", "error_description": "错误形式：“我们家的一司机”。正确形式：“我们家的一个司机”。数量词“一”后面必须接量词“个”，不能直接接名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05a8306a-788d-4b3d-855a-baf197742313') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
