INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87134, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "驾驶汽车、火车等交通工具的人。", "primary_collocate": null, "pronunciation": "sī jī", "ipa": "sɨ˥ tɕi˥", "syllable_count": 2, "sentences": [{"text": "这位司机开了二十年火车。", "target_word": "司机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地铁司机每天早上五点上班。", "target_word": "司机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "司机师傅，请在前面停车。", "target_word": "司机", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "卡车司机长时间开车，容易累。", "target_word": "司机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公共汽车司机提醒大家抓紧扶手。", "target_word": "司机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那位火车司机很有经验，从不迟到。", "target_word": "司机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "司机看见前面有人，马上停了车。", "target_word": "司机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我爸爸是长途汽车司机，常常不在家。", "target_word": "司机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "司机必须遵守交通规则，保证乘客安全。", "target_word": "司机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雾天，司机把车开得很慢。", "target_word": "司机", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位司机", "label": "量词"}, {"form": "一名司机", "label": "量词"}, {"form": "出租车司机", "label": "复合"}, {"form": "司机师傅", "label": "复合"}, {"form": "司機", "label": "繁体"}], "register": "中性", "sense_fingerprint": "驾驶汽车、火车、地铁等交通工具的职业人员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa572e2a-b4ac-45be-a597-2cd926dc15a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87134, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "司机", "is_correct": true, "explanation": "正确。司机指驾驶汽车、火车等交通工具的人。"}, {"text": "四级", "is_correct": false, "explanation": "四级（sìjí）与 sījī 两个音节的声调都不同，意思是等级或考试级别。"}, {"text": "四季", "is_correct": false, "explanation": "四季（sìjì）与 sījī 两个音节的声调都不同，意思是一年的四个季节。"}, {"text": "死记", "is_correct": false, "explanation": "死记（sǐjì）第一个音节是第三声、第二个音节是第四声，与 sījī 声调不同，意思是死记硬背。"}], "explanations": {"司机": "正确。司机指驾驶汽车、火车等交通工具的人。", "四级": "四级（sìjí）与 sījī 两个音节的声调都不同，意思是等级或考试级别。", "四季": "四季（sìjì）与 sījī 两个音节的声调都不同，意思是一年的四个季节。", "死记": "死记（sǐjì）第一个音节是第三声、第二个音节是第四声，与 sījī 声调不同，意思是死记硬背。"}, "sentence_index": null, "correct_answer": "司机"}, "level_3": {"options": [{"text": "司机", "is_correct": true, "explanation": "正确。司机是驾驶火车的人，与“开了二十年火车”相符。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：乘客是乘车的人，不会“开”火车，与“开了二十年火车”矛盾。"}, {"text": "售票员", "is_correct": false, "explanation": "搭配：“开”火车的主语是驾驶者，售票员的动作是卖票，不搭配“开火车”。"}, {"text": "老师", "is_correct": false, "explanation": "语义：老师不驾驶火车，句中“开了二十年火车”指的是驾驶经历。"}], "explanations": {"司机": "正确。司机是驾驶火车的人，与“开了二十年火车”相符。", "乘客": "语义：乘客是乘车的人，不会“开”火车，与“开了二十年火车”矛盾。", "售票员": "搭配：“开”火车的主语是驾驶者，售票员的动作是卖票，不搭配“开火车”。", "老师": "语义：老师不驾驶火车，句中“开了二十年火车”指的是驾驶经历。"}, "sentence_index": 0, "correct_answer": "司机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "司机在田里种庄稼，收成很好。", "explanation": "这里应该用〈农民〉。司机指驾驶交通工具的人，种庄稼是农民的工作。"}, {"text": "我爸爸是司机，每天检查公司的账目。", "explanation": "这里应该用〈会计〉。司机指驾驶车辆的人，检查公司账目是会计的工作。"}, {"text": "司机带领船员出海。", "explanation": "这里应该用〈船长〉。司机指驾驶汽车、火车等陆上交通工具的人，带领船员出海的人称船长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05a8306a-788d-4b3d-855a-baf197742313') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87134, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "司机", "is_correct": true, "explanation": "正确。司机指驾驶汽车、火车等交通工具的人。"}, {"text": "死机", "is_correct": false, "explanation": "死机（sǐjī）第一个音节是第三声，与 sī（第一声）声调不同，意思是电脑等设备停止响应。"}, {"text": "时机", "is_correct": false, "explanation": "时机（shíjī）声母是 sh 而不是 s，第一个音节是第二声，与 sījī 读音不同。意思是合适的机会。"}, {"text": "诗集", "is_correct": false, "explanation": "诗集（shījí）声母是 sh 而不是 s，第二个音节是第二声，与 sījī 读音不同。意思是诗的合集。"}], "explanations": {"司机": "正确。司机指驾驶汽车、火车等交通工具的人。", "死机": "死机（sǐjī）第一个音节是第三声，与 sī（第一声）声调不同，意思是电脑等设备停止响应。", "时机": "时机（shíjī）声母是 sh 而不是 s，第一个音节是第二声，与 sījī 读音不同。意思是合适的机会。", "诗集": "诗集（shījí）声母是 sh 而不是 s，第二个音节是第二声，与 sījī 读音不同。意思是诗的合集。"}, "sentence_index": null, "correct_answer": "司机"}, "level_3": {"options": [{"text": "司机", "is_correct": true, "explanation": "正确。司机驾车，能看见前面的人并停车。"}, {"text": "盲人", "is_correct": false, "explanation": "体貌：盲人看不见，与“看见前面有人”矛盾。"}, {"text": "行人", "is_correct": false, "explanation": "语义：行人不驾驶车辆，无法“停了车”。"}, {"text": "小学生", "is_correct": false, "explanation": "语义：小学生不会驾驶车辆，与句中“停了车”的动作不符。"}], "explanations": {"司机": "正确。司机驾车，能看见前面的人并停车。", "盲人": "体貌：盲人看不见，与“看见前面有人”矛盾。", "行人": "语义：行人不驾驶车辆，无法“停了车”。", "小学生": "语义：小学生不会驾驶车辆，与句中“停了车”的动作不符。"}, "sentence_index": 6, "correct_answer": "司机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "司机在图书馆里帮读者找书。", "explanation": "这里应该用〈图书管理员〉。司机指驾驶车辆的人，帮读者找书是图书管理员的工作。"}, {"text": "司机在工厂里设计新产品的外形。", "explanation": "这里应该用〈设计师〉。司机指驾驶车辆的人，设计产品外形是设计师的工作。"}, {"text": "司机在医院里给病人看病。", "explanation": "这里应该用〈医生〉。司机指驾驶车辆的人，给病人看病是医生的工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05a8306a-788d-4b3d-855a-baf197742313') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87134, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈给我们家请了一只司机。", "corrected_sentence": "妈妈给我们家请了一位司机。", "error_description": "错误形式：“一只司机”。正确形式：“一位司机”。“只”用于动物和部分物件，指人的司机应用量词“位”（或“名”）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05a8306a-788d-4b3d-855a-baf197742313') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87134, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们家新请了一司机。", "corrected_sentence": "他们家新请了一个司机。", "error_description": "错误形式：“一司机”。正确形式：“一个司机”。数量词“一”后面必须接量词“个”，不能直接接名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05a8306a-788d-4b3d-855a-baf197742313') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
