INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87135, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "上游是河水开始流下来的那一头。那里离河的出口最远。", "primary_collocate": null, "pronunciation": "shàng yóu", "ipa": "ʂɑŋ˥˩ joʊ˧˥", "syllable_count": 2, "sentences": [{"text": "这条河的上游在山里。", "target_word": "上游", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船从下游开到了上游。", "target_word": "上游", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水从上游流下来。", "target_word": "上游", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上游的水很清，下游的水很脏。", "target_word": "上游", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐船去河的上游玩。", "target_word": "上游", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上游下雨了，河水涨了。", "target_word": "上游", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小河的上游离海最远。", "target_word": "上游", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鱼游到了河的上游。", "target_word": "上游", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上游有一座老桥。", "target_word": "上游", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家住在河的上游。", "target_word": "上游", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "河水开始流下来的一头，离出口最远", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d56d81d-7b32-4ed2-b81f-faaa77360a2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87135, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "上游", "is_correct": true, "explanation": "正确：上游（shàng yóu）指河水开始流下来的那一头，离河的出口最远。"}, {"text": "畅游", "is_correct": false, "explanation": "chàng yóu 与 shàng yóu 的声母不同（ch 与 sh），意思是尽情游玩。"}, {"text": "尚有", "is_correct": false, "explanation": "shàng yǒu 与 shàng yóu 的第二个音节声调不同（第三声与第二声），意思是还有。"}, {"text": "赏游", "is_correct": false, "explanation": "shǎng yóu 与 shàng yóu 的第一个音节声调不同（第三声与第四声），意思是游览观赏。"}], "explanations": {"上游": "正确：上游（shàng yóu）指河水开始流下来的那一头，离河的出口最远。", "畅游": "chàng yóu 与 shàng yóu 的声母不同（ch 与 sh），意思是尽情游玩。", "尚有": "shàng yǒu 与 shàng yóu 的第二个音节声调不同（第三声与第二声），意思是还有。", "赏游": "shǎng yóu 与 shàng yóu 的第一个音节声调不同（第三声与第四声），意思是游览观赏。"}, "sentence_index": null, "correct_answer": "上游"}, "level_3": {"options": [{"text": "上游", "is_correct": true, "explanation": "正确：“上游”指河水开始流下来的一头，与“这条河的……在山里”相合。"}, {"text": "河口", "is_correct": false, "explanation": "语义：河口是河水入海的地方，离山很远，不会在山里。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海不在山里，与河流的部位不合。"}, {"text": "海边", "is_correct": false, "explanation": "搭配：“海边”指临海的地方，不用来说河流的部位。"}], "explanations": {"上游": "正确：“上游”指河水开始流下来的一头，与“这条河的……在山里”相合。", "河口": "语义：河口是河水入海的地方，离山很远，不会在山里。", "大海": "语义：大海不在山里，与河流的部位不合。", "海边": "搭配：“海边”指临海的地方，不用来说河流的部位。"}, "sentence_index": 0, "correct_answer": "上游"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位企业家属于上游阶层，经常出席宴会。", "explanation": "这里应该用〈上流〉。上游指河水开始流下来的那一头，指社会阶层时要说上流。"}, {"text": "这根绳子的上游挂着一个铃铛。", "explanation": "这里应该用〈上端〉。上游只用于河流，绳子的顶部要说上端。"}, {"text": "山的上游有一座古庙。", "explanation": "这里应该用〈高处〉。山没有“上游”，山上的位置要说高处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b664e9ad-97d3-45f2-b78a-e8211ea03883') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87135, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上游", "is_correct": true, "explanation": "正确：“上游”指河水开始流下来的一头，离河的出口最远，与“小河的……离海最远”相合。"}, {"text": "大厦", "is_correct": false, "explanation": "搭配：“大厦”是高楼，不能用来说小河的部位。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房与河流无关，“小河的厨房离海最远”说不通。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是学习的地方，不是河流的部位，与句意不合。"}], "explanations": {"上游": "正确：“上游”指河水开始流下来的一头，离河的出口最远，与“小河的……离海最远”相合。", "大厦": "搭配：“大厦”是高楼，不能用来说小河的部位。", "厨房": "语义：厨房与河流无关，“小河的厨房离海最远”说不通。", "教室": "语义：教室是学习的地方，不是河流的部位，与句意不合。"}, "sentence_index": 6, "correct_answer": "上游"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "书架的上游挂着一幅画。", "explanation": "这里应该用〈上方〉。上游只用于河流，书架上面的位置要说上方。"}, {"text": "这辆车的上游撞坏了。", "explanation": "这里应该用〈前端〉。上游不指车身的部位，车的前部要说前端。"}, {"text": "他住在楼房的上游。", "explanation": "这里应该用〈上层〉。上游只用于河流，楼房的高层要说上层。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b664e9ad-97d3-45f2-b78a-e8211ea03883') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87135, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "河水从上游流上来。", "corrected_sentence": "河水从上游流到下游。", "error_description": "方向补语误用：水从上游往下游流，“流上来”表示向说话人一侧上升，与水的流向相反，应改为“流到下游”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b664e9ad-97d3-45f2-b78a-e8211ea03883') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87135, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的农场往上游。", "corrected_sentence": "他的农场在上游。", "error_description": "介词误用：表示位置要用“在”；“往”表示朝某个方向移动，农场是静止的，不能说“往上游”，应说“在上游”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b664e9ad-97d3-45f2-b78a-e8211ea03883') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
