INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87136, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "河流接近源头的一段，也泛指事物发展过程中靠前的阶段。", "primary_collocate": null, "pronunciation": "shàng yóu", "ipa": "ʂɑŋ˥˩ joʊ˧˥", "syllable_count": 2, "sentences": [{"text": "这条河的上游有很多山。", "target_word": "上游", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们沿着河往上游走。", "target_word": "上游", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上游的水很干净。", "target_word": "上游", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上游的工厂把河水弄脏了。", "target_word": "上游", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司在产业链的上游。", "target_word": "上游", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上游的原料涨价了，下游也要涨价。", "target_word": "上游", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写故事是做电影的上游工作。", "target_word": "上游", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河的上游下了大雨，下游会涨水。", "target_word": "上游", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上游的质量不好，后面的工作就很难做。", "target_word": "上游", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子在大河上游的山里。", "target_word": "上游", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "河的靠近源头一段，也指事物发展靠前的阶段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d56d81d-7b32-4ed2-b81f-faaa77360a2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED