INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87136, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们负责电视节目的上游地工作。", "corrected_sentence": "我们负责电视节目的上游工作。", "error_description": "结构助词错误：“上游”后应直接接名词“工作”，“地”用于修饰动词，不能用在名词前。正确为“电视节目的上游工作”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b664e9ad-97d3-45f2-b78a-e8211ea03883') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
