INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87137, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "周围是一样东西旁边的一圈。", "primary_collocate": null, "pronunciation": "zhōu wéi", "ipa": "ʈʂou̯˥ uei̯˧˥", "syllable_count": 2, "sentences": [{"text": "桌子周围坐着六个人。", "target_word": "周围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子周围种了一些花。", "target_word": "周围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们围在老师周围听故事。", "target_word": "周围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "池塘周围有一圈小路。", "target_word": "周围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火堆周围站满了人。", "target_word": "周围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块地周围有一道铁网。", "target_word": "周围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车周围都是水。", "target_word": "周围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书架周围放着很多箱子。", "target_word": "周围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钟周围画了十二个小点。", "target_word": "周围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛋糕周围放着红色的草莓。", "target_word": "周围", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "周围的", "label": "定语形式"}, {"form": "周圍", "label": "繁体"}], "register": "中性", "sense_fingerprint": "某样东西旁边的一圈", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '679c1d60-cd18-4bd7-984c-952bf355ca55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87137, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "周围", "is_correct": true, "explanation": "“周围”指桌子旁边的一圈，符合句意。"}, {"text": "重量", "is_correct": false, "explanation": "语义：“重量”指轻重的程度，“桌子重量坐着六个人”句意不通。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指钱数，不能表示位置，句意不通。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”只用于人或动物，不能与“桌子”搭配。"}], "explanations": {"周围": "“周围”指桌子旁边的一圈，符合句意。", "重量": "语义：“重量”指轻重的程度，“桌子重量坐着六个人”句意不通。", "价格": "语义：“价格”指钱数，不能表示位置，句意不通。", "身高": "搭配：“身高”只用于人或动物，不能与“桌子”搭配。"}, "sentence_index": 0, "correct_answer": "周围"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "杯子周围装满了水。", "explanation": "这里应该用〈里面〉。装满东西要说〈里面〉，“周围”指杯子外面的一圈，水不能装在外围。"}, {"text": "饭碗周围盛着米饭。", "explanation": "这里应该用〈里面〉。米饭盛在碗中要说〈里面〉，“周围”指碗外面的一圈。"}, {"text": "书架周围正中央摆着一盆花。", "explanation": "这里应该用〈中心〉。花盆摆在书架正中要说〈中心〉，“周围”指外围的一带，与“正中央”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c3275f-1f36-42e1-853d-49a133abf938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87137, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "周围", "is_correct": true, "explanation": "“周围”指车四周的一圈，符合句意。"}, {"text": "年份", "is_correct": false, "explanation": "语义：“年份”指时间，不能表示位置，“车年份都是水”句意不通。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”指气味或滋味，不能表示位置，句意不通。"}, {"text": "身份证", "is_correct": false, "explanation": "搭配：“身份证”只用于人，不能与“车”搭配。"}], "explanations": {"周围": "“周围”指车四周的一圈，符合句意。", "年份": "语义：“年份”指时间，不能表示位置，“车年份都是水”句意不通。", "味道": "语义：“味道”指气味或滋味，不能表示位置，句意不通。", "身份证": "搭配：“身份证”只用于人，不能与“车”搭配。"}, "sentence_index": 6, "correct_answer": "周围"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "行李箱周围塞满了衣服。", "explanation": "这里应该用〈里面〉。塞满东西要说〈里面〉，“周围”指行李箱外面的一带，衣服不能塞在外围。"}, {"text": "抽屉周围塞着很多文件。", "explanation": "这里应该用〈里面〉。文件放在抽屉中要说〈里面〉，“周围”指抽屉外面的一圈。"}, {"text": "院子周围正中央种着一棵树。", "explanation": "这里应该用〈中心〉。树种在院子正中要说〈中心〉，“周围”指外围的一带，与“正中央”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c3275f-1f36-42e1-853d-49a133abf938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
