INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87138, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "周围", "is_correct": true, "explanation": "“周围”指学校四周的一带，符合句意。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”不能表示地点，“学校名字有很多树”句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指事物的色彩，不能表示位置，句意不通。"}, {"text": "学期", "is_correct": false, "explanation": "搭配：“学期”是时间段，不能与“学校”组成表示地点的短语。"}], "explanations": {"周围": "“周围”指学校四周的一带，符合句意。", "名字": "语义：“名字”不能表示地点，“学校名字有很多树”句意不通。", "颜色": "语义：“颜色”指事物的色彩，不能表示位置，句意不通。", "学期": "搭配：“学期”是时间段，不能与“学校”组成表示地点的短语。"}, "sentence_index": 0, "correct_answer": "周围"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "箱子周围装满了书。", "explanation": "这里应该用〈里面〉。装满东西要说〈里面〉，“周围”指箱子外面的一带，书不能装在外围。"}, {"text": "碗周围盛着一碗汤。", "explanation": "这里应该用〈里面〉。盛在碗中要说〈里面〉，“周围”指碗外面的一圈。"}, {"text": "桌子周围正中央放着一个花瓶。", "explanation": "这里应该用〈中心〉。花瓶放在桌子正中要说〈中心〉，“周围”指外围的一带，与“正中央”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c3275f-1f36-42e1-853d-49a133abf938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87138, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "周围", "is_correct": true, "explanation": "“周围”指山的四周一带，符合句意。"}, {"text": "高度", "is_correct": false, "explanation": "语义：“高度”指高低的程度，不能表示位置，“这座山高度没有人家”句意不通。"}, {"text": "历史", "is_correct": false, "explanation": "语义：“历史”指过去的经过，不能表示位置，句意不通。"}, {"text": "生日", "is_correct": false, "explanation": "搭配：“生日”只用于人，不能与“山”搭配。"}], "explanations": {"周围": "“周围”指山的四周一带，符合句意。", "高度": "语义：“高度”指高低的程度，不能表示位置，“这座山高度没有人家”句意不通。", "历史": "语义：“历史”指过去的经过，不能表示位置，句意不通。", "生日": "搭配：“生日”只用于人，不能与“山”搭配。"}, "sentence_index": 6, "correct_answer": "周围"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "鞋柜周围装满了鞋。", "explanation": "这里应该用〈里面〉。装满东西要说〈里面〉，“周围”指鞋柜外面的一带，鞋不能装在外围。"}, {"text": "信封周围装着一张照片。", "explanation": "这里应该用〈里面〉。照片放在信封中要说〈里面〉，“周围”指信封外面的一圈。"}, {"text": "广场周围正中央立着一座雕像。", "explanation": "这里应该用〈中心〉。雕像立在广场正中要说〈中心〉，“周围”指外围的一带，与“正中央”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c3275f-1f36-42e1-853d-49a133abf938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87138, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "鸟儿湖周围飞。", "corrected_sentence": "鸟儿在湖周围飞。", "error_description": "错误：表示地点的“湖周围”前漏掉了“在”，应说“鸟儿在湖周围飞”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c3275f-1f36-42e1-853d-49a133abf938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87138, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们公园周围跑步。", "corrected_sentence": "孩子们在公园周围跑步。", "error_description": "错误：表示地点的“公园周围”前漏掉了“在”，应说“孩子们在公园周围跑步”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c3275f-1f36-42e1-853d-49a133abf938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
