INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87140, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "记录语言的符号；文字。", "primary_collocate": null, "pronunciation": "zì", "ipa": "tsɹ̩˥˩", "syllable_count": 1, "sentences": [{"text": "字是用来记录语言的符号。", "target_word": "字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候的人先有话，后来才有字。", "target_word": "字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个字有两个读音，你知道吗？", "target_word": "字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个字都有自己的意思。", "target_word": "字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在字典里查这个字的意思。", "target_word": "字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个字有八笔，写的时候要小心。", "target_word": "字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国的字很早就有了。", "target_word": "字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不认识字的人，很难读书看报。", "target_word": "字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他会说汉语，可是还不会写字。", "target_word": "字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了字，人们才能把话写下来。", "target_word": "字", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "汉字", "label": "复合"}, {"form": "文字", "label": "复合"}], "register": "中性", "sense_fingerprint": "记录语言的文字符号，有读音、意思和笔画", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62420910-ffdd-4a2d-9c1d-95797acdc4fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87140, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "字", "is_correct": true, "explanation": "字（zì，第四声）指记录语言的文字符号，是本题的正确答案。"}, {"text": "子", "is_correct": false, "explanation": "zǐ（第三声）与 zì（第四声）声调不同，意思是儿子、子女。"}, {"text": "次", "is_correct": false, "explanation": "cì 与 zì 声母不同（c 与 z），意思是次数、次序。"}, {"text": "四", "is_correct": false, "explanation": "sì 与 zì 声母不同（s 与 z），意思是数字四。"}, {"text": "志", "is_correct": false, "explanation": "zhì 与 zì 声母不同（zh 与 z），意思是志向、志气。"}], "explanations": {"字": "字（zì，第四声）指记录语言的文字符号，是本题的正确答案。", "子": "zǐ（第三声）与 zì（第四声）声调不同，意思是儿子、子女。", "次": "cì 与 zì 声母不同（c 与 z），意思是次数、次序。", "四": "sì 与 zì 声母不同（s 与 z），意思是数字四。", "志": "zhì 与 zì 声母不同（zh 与 z），意思是志向、志气。"}, "sentence_index": null, "correct_answer": "字"}, "level_3": {"options": [{"text": "笔", "is_correct": false, "explanation": "语义：笔是书写工具，不是用来记录语言的符号，与“符号”的语境不合。"}, {"text": "字", "is_correct": true, "explanation": "字：记录语言的文字符号，与“用来记录语言的符号”相合，是唯一能填入的词。"}, {"text": "图画", "is_correct": false, "explanation": "语义：图画表达的是形象，不是记录语言的符号，与句子语境不合。"}, {"text": "录音", "is_correct": false, "explanation": "搭配：“符号”一般指文字、图形等书面标记，不说录音是符号。"}], "explanations": {"笔": "语义：笔是书写工具，不是用来记录语言的符号，与“符号”的语境不合。", "字": "字：记录语言的文字符号，与“用来记录语言的符号”相合，是唯一能填入的词。", "图画": "语义：图画表达的是形象，不是记录语言的符号，与句子语境不合。", "录音": "搭配：“符号”一般指文字、图形等书面标记，不说录音是符号。"}, "sentence_index": 0, "correct_answer": "字"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个门牌号有四个字。", "explanation": "这里应该用〈数字〉。门牌号由数字组成，“字”指记录语言的符号，号码不能说字。"}, {"text": "这条字我不认识。", "explanation": "这里应该用〈个〉。“字”用量词“个”，“条”用于长条形的东西，不能配字。"}, {"text": "英语有二十六个字。", "explanation": "这里应该用〈字母〉。字母指拼音文字的符号，“字”一般指汉字，英语的符号要说字母。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87140, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "字", "is_correct": true, "explanation": "字（zì，第四声）指记录语言的文字符号，是本题的正确答案。"}, {"text": "紫", "is_correct": false, "explanation": "zǐ（第三声）与 zì（第四声）声调不同，意思是紫色。"}, {"text": "刺", "is_correct": false, "explanation": "cì 与 zì 声母不同（c 与 z），意思是尖的东西、刺。"}, {"text": "寺", "is_correct": false, "explanation": "sì 与 zì 声母不同（s 与 z），意思是寺庙。"}, {"text": "质", "is_correct": false, "explanation": "zhì 与 zì 声母不同（zh 与 z），意思是质量、品质。"}], "explanations": {"字": "字（zì，第四声）指记录语言的文字符号，是本题的正确答案。", "紫": "zǐ（第三声）与 zì（第四声）声调不同，意思是紫色。", "刺": "cì 与 zì 声母不同（c 与 z），意思是尖的东西、刺。", "寺": "sì 与 zì 声母不同（s 与 z），意思是寺庙。", "质": "zhì 与 zì 声母不同（zh 与 z），意思是质量、品质。"}, "sentence_index": null, "correct_answer": "字"}, "level_3": {"options": [{"text": "高铁", "is_correct": false, "explanation": "语义：高铁是近几十年才出现的，与“很早就有了”的语境不合。"}, {"text": "字", "is_correct": true, "explanation": "字：记录语言的文字，有悠久历史，与“很早就有了”相合，是唯一能填入的词。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是近年才出现的，与“很早就有了”的语境不合。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑是近几十年才有的，与“很早就有了”的语境不合。"}], "explanations": {"高铁": "语义：高铁是近几十年才出现的，与“很早就有了”的语境不合。", "字": "字：记录语言的文字，有悠久历史，与“很早就有了”相合，是唯一能填入的词。", "手机": "语义：手机是近年才出现的，与“很早就有了”的语境不合。", "电脑": "语义：电脑是近几十年才有的，与“很早就有了”的语境不合。"}, "sentence_index": 6, "correct_answer": "字"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "数学用字表示数量。", "explanation": "这里应该用〈符号〉。字指记录语言的文字，表示数量要用数字或符号，数学一般不说用字。"}, {"text": "这个密码有六个字。", "explanation": "这里应该用〈数字〉。密码一般由数字组成，“字”指记录语言的符号，不能用来说密码的位数。"}, {"text": "这块字我不认识。", "explanation": "这里应该用〈个〉。“字”用量词“个”，“块”用于块状的东西，不能配字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87140, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只字可以有两种读音。", "corrected_sentence": "一个字可以有两种读音。", "error_description": "错误：“一只字”。正确：“一个字”。字用量词“个”，“只”一般用于动物或小东西，不能配字。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87140, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在黑板上写了三本字。", "corrected_sentence": "他在黑板上写了三个字。", "error_description": "错误：“三本字”。正确：“三个字”。字用量词“个”，“本”用于书册，不能用于字。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87141, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "舒适", "is_correct": true, "explanation": "正确：“舒适”与“不适”相对，指身体舒服。"}, {"text": "愉快", "is_correct": false, "explanation": "与“不适”指身体感觉的义项没有反义关系，“愉快”指心情。"}, {"text": "勤奋", "is_correct": false, "explanation": "与“不适”没有反义关系，“勤奋”指努力工作的态度。"}, {"text": "明亮", "is_correct": false, "explanation": "与“不适”没有反义关系，“明亮”指光线或颜色。"}], "correct_answer": "舒适", "explanations": {"舒适": "正确：“舒适”与“不适”相对，指身体舒服。", "愉快": "与“不适”指身体感觉的义项没有反义关系，“愉快”指心情。", "勤奋": "与“不适”没有反义关系，“勤奋”指努力工作的态度。", "明亮": "与“不适”没有反义关系，“明亮”指光线或颜色。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a60b13-703b-4e62-85a9-0f05821c45f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87141, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "舒适", "is_correct": true, "explanation": "正确：“舒适”与“不适”相对，指身体舒服。"}, {"text": "清楚", "is_correct": false, "explanation": "与“不适”没有反义关系，“清楚”指清晰、明白。"}, {"text": "安静", "is_correct": false, "explanation": "与“不适”没有反义关系，“安静”指环境或声音。"}, {"text": "结实", "is_correct": false, "explanation": "与“不适”没有反义关系，“结实”指物体坚固或身体强壮。"}], "correct_answer": "舒适", "explanations": {"舒适": "正确：“舒适”与“不适”相对，指身体舒服。", "清楚": "与“不适”没有反义关系，“清楚”指清晰、明白。", "安静": "与“不适”没有反义关系，“安静”指环境或声音。", "结实": "与“不适”没有反义关系，“结实”指物体坚固或身体强壮。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a60b13-703b-4e62-85a9-0f05821c45f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87141, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不适是身体觉得不舒服。", "primary_collocate": null, "pronunciation": "bú shì", "ipa": "pu˧˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "我今天身体有点不适，想早点回家休息。", "target_word": "不适", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃了太多冷饮，他的胃觉得很不适。", "target_word": "不适", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐了一整天的车，她感到有些不适。", "target_word": "不适", "complexity_tier": "T3", "furigana": "zuò le yì zhěng tiān de chē, tā gǎndào yǒuxiē búshì.", "sentence_source": "generated"}, {"text": "他脸色很差，说自己浑身不适。", "target_word": "不适", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机起飞的时候，我耳朵有些不适。", "target_word": "不适", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨晚没睡好，今早我一直觉得不适。", "target_word": "不适", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喝完那杯咖啡，我的心口有点不适。", "target_word": "不适", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子说肚子不适，不想吃早饭。", "target_word": "不适", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气太热，奶奶出门后感到不适。", "target_word": "不适", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他强忍着身体的不适，把工作做完了。", "target_word": "不适", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不适感", "label": "复合"}], "register": "书面语", "sense_fingerprint": "身体觉得不舒服", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c4848e3-df86-4870-9771-0c70385a07a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87141, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不适", "is_correct": true, "explanation": "正确：不适指身体觉得不舒服。"}, {"text": "不时", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，“不时”意思是时常、偶尔。"}, {"text": "不失", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，“不失”意思是不丢失。"}, {"text": "不实", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，“不实”意思是不真实。"}], "explanations": {"不适": "正确：不适指身体觉得不舒服。", "不时": "shí（第二声）与 shì（第四声）声调不同，“不时”意思是时常、偶尔。", "不失": "shī（第一声）与 shì（第四声）声调不同，“不失”意思是不丢失。", "不实": "shí（第二声）与 shì（第四声）声调不同，“不实”意思是不真实。"}, "sentence_index": null, "correct_answer": "不适"}, "level_3": {"options": [{"text": "不适", "is_correct": true, "explanation": "正确：“不适”指身体不舒服，与“有点”和“想早点回家休息”的语境吻合。"}, {"text": "健康", "is_correct": false, "explanation": "搭配：“有点”后面一般接不好的情况，不说“身体有点健康”。"}, {"text": "明亮", "is_correct": false, "explanation": "语义：“明亮”形容光线或眼神，不能用来形容身体的状态。"}, {"text": "安静", "is_correct": false, "explanation": "语义：“安静”形容环境或声音，不能用来形容身体的状态。"}], "explanations": {"不适": "正确：“不适”指身体不舒服，与“有点”和“想早点回家休息”的语境吻合。", "健康": "搭配：“有点”后面一般接不好的情况，不说“身体有点健康”。", "明亮": "语义：“明亮”形容光线或眼神，不能用来形容身体的状态。", "安静": "语义：“安静”形容环境或声音，不能用来形容身体的状态。"}, "sentence_index": 0, "correct_answer": "不适"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "听到这件事，他心里很不适，一晚上都没有合眼。", "explanation": "这里应该用〈不安〉。不适只指身体不舒服，心里的忐忑、焦虑要用“不安”。"}, {"text": "被老师误会后，他觉得很不适，一个人躲在角落里。", "explanation": "这里应该用〈委屈〉。不适只指身体的不舒服，受了冤枉的心情要用“委屈”。"}, {"text": "最近工作上的事让他很不适，动不动就发脾气。", "explanation": "这里应该用〈烦躁〉。不适指身体感觉，心里的急躁要用“烦躁”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a60b13-703b-4e62-85a9-0f05821c45f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
