INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87141, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "吃完饭后，他感到一个不适。", "corrected_sentence": "吃完饭后，他感到一阵不适。", "error_description": "“不适”指身体的感觉，量词应用“阵”或“点”，不能用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a60b13-703b-4e62-85a9-0f05821c45f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
