INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87142, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "（身体）不舒服。", "primary_collocate": null, "pronunciation": "bú shì", "ipa": "pu˧˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "服药后出现不适，请马上告诉医生。", "target_word": "不适", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他身体不适，今天请假没来上班。", "target_word": "不适", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动时觉得不适，就应该马上停下来。", "target_word": "不适", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师发现小明脸色不好，问他哪里不适。", "target_word": "不适", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生问我：“你哪里不适？”", "target_word": "不适", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为身体不适，她没去参加晚会。", "target_word": "不适", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药可能会让人感到轻微的不适。", "target_word": "不适", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "如有不适，请及时去医院检查。", "target_word": "不适", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说自己有点不适，想先坐一会儿。", "target_word": "不适", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乘船的人常常会有头晕、恶心等不适。", "target_word": "不适", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不适感", "label": "复合"}], "register": "书面语", "sense_fingerprint": "身体不舒服（多用于医疗、请假等场合）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c4848e3-df86-4870-9771-0c70385a07a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87142, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不适", "is_correct": true, "explanation": "正确：不适指身体不舒服，多用于医疗、请假等场合。"}, {"text": "不识", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，“不识”意思是不认识。"}, {"text": "不使", "is_correct": false, "explanation": "shǐ（第三声）与 shì（第四声）声调不同，“不使”意思是不让、不致使。"}, {"text": "不施", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，“不施”意思是不施加、不给予。"}, {"text": "不实", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，“不实”意思是不真实。"}], "explanations": {"不适": "正确：不适指身体不舒服，多用于医疗、请假等场合。", "不识": "shí（第二声）与 shì（第四声）声调不同，“不识”意思是不认识。", "不使": "shǐ（第三声）与 shì（第四声）声调不同，“不使”意思是不让、不致使。", "不施": "shī（第一声）与 shì（第四声）声调不同，“不施”意思是不施加、不给予。", "不实": "shí（第二声）与 shì（第四声）声调不同，“不实”意思是不真实。"}, "sentence_index": null, "correct_answer": "不适"}, "level_3": {"options": [{"text": "不适", "is_correct": true, "explanation": "正确：“服药后出现不适”指药后身体出现不舒服的反应，与“请马上告诉医生”相符。"}, {"text": "月光", "is_correct": false, "explanation": "语义：月光不是服药后会出现的反应，句意不通。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本不是药物的反应，不能说“服药后出现课本”。"}, {"text": "水果", "is_correct": false, "explanation": "搭配：“出现”后一般接症状、现象，不说“出现水果”。"}], "explanations": {"不适": "正确：“服药后出现不适”指药后身体出现不舒服的反应，与“请马上告诉医生”相符。", "月光": "语义：月光不是服药后会出现的反应，句意不通。", "课本": "语义：课本不是药物的反应，不能说“服药后出现课本”。", "水果": "搭配：“出现”后一般接症状、现象，不说“出现水果”。"}, "sentence_index": 0, "correct_answer": "不适"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "听到这个消息，她心里很不适。", "explanation": "这里应该用〈难受〉。不适指身体不舒服，心里的难过要用“难受”。"}, {"text": "孩子考砸了，妈妈心里很不适。", "explanation": "这里应该用〈失望〉。不适只指身体的不舒服，心里的失落要用“失望”。"}, {"text": "他听说火车晚点，心里很不适。", "explanation": "这里应该用〈着急〉。不适指身体的感觉，急切的心情要用“着急”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a60b13-703b-4e62-85a9-0f05821c45f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87142, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "不适", "is_correct": true, "explanation": "正确：不适指身体不舒服，多用于医疗、请假等场合。"}, {"text": "不时", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，“不时”意思是时常、偶尔。"}, {"text": "不失", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，“不失”意思是不丢失。"}, {"text": "不食", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，“不食”意思是不吃。"}, {"text": "不湿", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，“不湿”意思是不潮湿。"}], "explanations": {"不适": "正确：不适指身体不舒服，多用于医疗、请假等场合。", "不时": "shí（第二声）与 shì（第四声）声调不同，“不时”意思是时常、偶尔。", "不失": "shī（第一声）与 shì（第四声）声调不同，“不失”意思是不丢失。", "不食": "shí（第二声）与 shì（第四声）声调不同，“不食”意思是不吃。", "不湿": "shī（第一声）与 shì（第四声）声调不同，“不湿”意思是不潮湿。"}, "sentence_index": null, "correct_answer": "不适"}, "level_3": {"options": [{"text": "不适", "is_correct": true, "explanation": "正确：“轻微的不适”指吃药后身体的轻微不舒服，符合句意。"}, {"text": "形状", "is_correct": false, "explanation": "语义：形状不是人身体上能感到的不适，句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“感到”后接感觉，不说“感到颜色”。"}, {"text": "图书", "is_correct": false, "explanation": "语义：图书不是能感到的状态，“感到轻微的图书”不成立。"}], "explanations": {"不适": "正确：“轻微的不适”指吃药后身体的轻微不舒服，符合句意。", "形状": "语义：形状不是人身体上能感到的不适，句意不通。", "颜色": "搭配：“感到”后接感觉，不说“感到颜色”。", "图书": "语义：图书不是能感到的状态，“感到轻微的图书”不成立。"}, "sentence_index": 6, "correct_answer": "不适"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "收到生日礼物，她心里很不适，笑个不停。", "explanation": "这里应该用〈开心〉。不适只表示身体不舒服，高兴的心情要用“开心”。"}, {"text": "比赛就要开始了，他心里很不适，一直来回踱步。", "explanation": "这里应该用〈紧张〉。不适只指身体不舒服，心里的紧张要用“紧张”。"}, {"text": "想到明天要当众发言，她心里很不适，夜里翻来覆去睡不着。", "explanation": "这里应该用〈忐忑〉。不适只指身体不舒服，心里的不安要用“忐忑”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a60b13-703b-4e62-85a9-0f05821c45f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87142, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "服药后，他感到一个轻微的不适。", "corrected_sentence": "服药后，他感到一种轻微的不适。", "error_description": "“不适”是身体的感觉，量词应用“种”或“阵”，不能用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a60b13-703b-4e62-85a9-0f05821c45f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87142, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他忽然感到一块不适，只好停下来。", "corrected_sentence": "他忽然感到一阵不适，只好停下来。", "error_description": "“不适”是身体的感觉，量词应用“阵”，不能用“块”；“块”用于块状物，不能用于感觉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a60b13-703b-4e62-85a9-0f05821c45f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
