INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87145, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "中旬是一个月里中间的十天。就是十一号到二十号。", "primary_collocate": null, "pronunciation": "zhōng xún", "ipa": "ʈʂʊŋ˥ ɕɥn˧˥", "syllable_count": 2, "sentences": [{"text": "我们三月中旬去旅行。", "target_word": "中旬", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考试在六月中旬。", "target_word": "中旬", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个月中旬天气会变冷。", "target_word": "中旬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他十月中旬回国。", "target_word": "中旬", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "九月中旬学校开学。", "target_word": "中旬", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中旬的时候我不在家。", "target_word": "中旬", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请在五月中旬以前交作业。", "target_word": "中旬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司二月中旬开会。", "target_word": "中旬", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的生日在七月中旬。", "target_word": "中旬", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下个月中旬我要搬家。", "target_word": "中旬", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "名词，每月十一日到二十日这十天", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '538b8765-1c9e-4db9-8583-9f5d1dd35ff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87145, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "中午", "is_correct": false, "explanation": "语义：中午指一天中的一个时段，与“三月”这一整月的时间范围不搭。"}, {"text": "中旬", "is_correct": true, "explanation": "正确：“三月中旬”指三月十一日到二十日，正好可以放在这里表示出发时间。"}, {"text": "年底", "is_correct": false, "explanation": "语义：年底指一年的末尾，与“三月”冲突，三月不可能是年底。"}, {"text": "半夜", "is_correct": false, "explanation": "搭配：“三月”作时间范围时，不与“半夜”这种一天之内的时点连用。"}], "explanations": {"中午": "语义：中午指一天中的一个时段，与“三月”这一整月的时间范围不搭。", "中旬": "正确：“三月中旬”指三月十一日到二十日，正好可以放在这里表示出发时间。", "年底": "语义：年底指一年的末尾，与“三月”冲突，三月不可能是年底。", "半夜": "搭配：“三月”作时间范围时，不与“半夜”这种一天之内的时点连用。"}, "sentence_index": 0, "correct_answer": "中旬"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他十月中旬一整个月都在外地。", "explanation": "这里把“中旬”当成了〈整月〉的意思。中旬只指一个月中间的十天（十一到二十日），不能表示整月，所以和“一整个月”矛盾。"}, {"text": "我们在中旬的公园见面。", "explanation": "中旬是时间词，只能表示时段，不能当作地点来用，“中旬的公园”说不通。"}, {"text": "这本书的中旬有几页被撕掉了。", "explanation": "这里应该用〈中间〉。中旬只指一个月中间的十天，不能指书的中间部分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d1df8c-23e6-4bf6-8b40-263efbffaf4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87145, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "清晨", "is_correct": false, "explanation": "语义：清晨是一天的开始，与“五月”这样的月份范围冲突，不能用在“以前”前面。"}, {"text": "中旬", "is_correct": true, "explanation": "正确：“五月中旬以前”指五月十一日到二十日之前的时间，符合句意。"}, {"text": "深夜", "is_correct": false, "explanation": "语义：深夜指一天之内很晚的时段，不能与“五月”这一整月的范围连用。"}, {"text": "下午", "is_correct": false, "explanation": "搭配：“以前”前接的是月份或日期，不接“下午”这种一天之中的时段。"}], "explanations": {"清晨": "语义：清晨是一天的开始，与“五月”这样的月份范围冲突，不能用在“以前”前面。", "中旬": "正确：“五月中旬以前”指五月十一日到二十日之前的时间，符合句意。", "深夜": "语义：深夜指一天之内很晚的时段，不能与“五月”这一整月的范围连用。", "下午": "搭配：“以前”前接的是月份或日期，不接“下午”这种一天之中的时段。"}, "sentence_index": 6, "correct_answer": "中旬"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我下周中旬要搬家。", "explanation": "这里应该用〈下个月〉。中旬要和月份连用，不能和“下周”这种一周的时间连用。"}, {"text": "下个月中旬有二十天，我们要搬家。", "explanation": "这里应该用〈十日〉的时段概念：中旬只指一个月中间的十天（十一到二十日），不是二十天，数量说错了。"}, {"text": "我们在国外过了一只中旬。", "explanation": "量词用错：〈只〉用于动物等，不用于时段，这里应该用〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d1df8c-23e6-4bf6-8b40-263efbffaf4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87145, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹七中旬要去北京玩。", "corrected_sentence": "妹妹七月中旬要去北京玩。", "error_description": "错误形式：“七中旬”；正确形式：“七月中旬”。数字表示月份时后面要加“月”，“七”后漏了“月”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d1df8c-23e6-4bf6-8b40-263efbffaf4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87145, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我打算三中旬去北京。", "corrected_sentence": "我打算三月中旬去北京。", "error_description": "错误形式：“三中旬”；正确形式：“三月中旬”。数字表示月份时后面要加“月”，“三”后漏了“月”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d1df8c-23e6-4bf6-8b40-263efbffaf4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
