INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87146, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "每月的第十一日到第二十日。", "primary_collocate": null, "pronunciation": "zhōng xún", "ipa": "ʈʂʊŋ˥ ɕɥn˧˥", "syllable_count": 2, "sentences": [{"text": "这本书将在四月中旬出版。", "target_word": "中旬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每个月中旬都会回家看妈妈。", "target_word": "中旬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "八月中旬，天气还很热。", "target_word": "中旬", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "十二月中旬，城里下了第一场雪。", "target_word": "中旬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每月中旬前要付租金。", "target_word": "中旬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "展览会在十一月中旬结束。", "target_word": "中旬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年春节在二月中旬。", "target_word": "中旬", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我打算一月中旬去北京。", "target_word": "中旬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，七月中旬我就能出院。", "target_word": "中旬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛安排在本月中旬。", "target_word": "中旬", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "名词，每月第十一日至第二十日的时间段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '538b8765-1c9e-4db9-8583-9f5d1dd35ff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87146, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "早上", "is_correct": false, "explanation": "语义：早上是一天之内的时段，与“四月”这个月份不搭配，句子说不通。"}, {"text": "中旬", "is_correct": true, "explanation": "正确：“四月中旬”指四月十一日到二十日，正好说明出版的时间。"}, {"text": "寒假", "is_correct": false, "explanation": "语义：寒假在冬天，与“四月”的季节不符。"}, {"text": "深夜", "is_correct": false, "explanation": "搭配：“在……出版”后接月份时，不接“深夜”这类一天之内的时点。"}], "explanations": {"早上": "语义：早上是一天之内的时段，与“四月”这个月份不搭配，句子说不通。", "中旬": "正确：“四月中旬”指四月十一日到二十日，正好说明出版的时间。", "寒假": "语义：寒假在冬天，与“四月”的季节不符。", "深夜": "搭配：“在……出版”后接月份时，不接“深夜”这类一天之内的时点。"}, "sentence_index": 0, "correct_answer": "中旬"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天中旬都去跑步。", "explanation": "这里应该用〈每个月〉。中旬要和月份连用，不能和“每天”连用。"}, {"text": "这条河的中旬有一座桥。", "explanation": "这里应该用〈中间〉。中旬只指一个月中间的十天，不能指河的中间部分。"}, {"text": "我们在中旬的超市买了东西。", "explanation": "中旬是时间词，只能表示时段，不能当作地点，“中旬的超市”说不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d1df8c-23e6-4bf6-8b40-263efbffaf4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87146, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年底", "is_correct": false, "explanation": "语义：年底是一年的末尾，与“二月”冲突，二月不可能是年底。"}, {"text": "凌晨", "is_correct": false, "explanation": "搭配：“在……”后接月份时，不接“凌晨”这种一天之内的时段。"}, {"text": "初夏", "is_correct": false, "explanation": "语义：初夏在夏天开始，二月是冬末，季节上完全对不上。"}, {"text": "中旬", "is_correct": true, "explanation": "正确：“二月中旬”指二月十一日到二十日，符合“春节在这段时间”的句意。"}], "explanations": {"年底": "语义：年底是一年的末尾，与“二月”冲突，二月不可能是年底。", "凌晨": "搭配：“在……”后接月份时，不接“凌晨”这种一天之内的时段。", "初夏": "语义：初夏在夏天开始，二月是冬末，季节上完全对不上。", "中旬": "正确：“二月中旬”指二月十一日到二十日，符合“春节在这段时间”的句意。"}, "sentence_index": 6, "correct_answer": "中旬"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次比赛安排在本月中旬，也就是三号到五号。", "explanation": "这里应该用〈上旬〉。中旬指每月十一日到二十日，三号到五号属于上旬。"}, {"text": "这次比赛安排了一座中旬。", "explanation": "量词用错：〈座〉用于建筑、山等，不用于时段，这里应该用〈个〉。"}, {"text": "中旬只有五天，这次比赛安排在本月中旬。", "explanation": "这里把“中旬”的长度误当成了〈五日〉的时段。中旬指一个月中间的十天（十一到二十日），这里数量说错了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d1df8c-23e6-4bf6-8b40-263efbffaf4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87146, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "弟弟八中旬要回老家。", "corrected_sentence": "弟弟八月中旬要回老家。", "error_description": "错误形式：“八中旬”；正确形式：“八月中旬”。数字表示月份时后面要加“月”，“八”后漏了“月”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d1df8c-23e6-4bf6-8b40-263efbffaf4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87146, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爷爷三中旬要去医院复查。", "corrected_sentence": "爷爷三月中旬要去医院复查。", "error_description": "错误形式：“三中旬”；正确形式：“三月中旬”。数字表示月份时后面要加“月”，“三”后漏了“月”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d1df8c-23e6-4bf6-8b40-263efbffaf4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
