INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87147, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "最好是说这样做比别的都要好。", "primary_collocate": null, "pronunciation": "zuì hǎo", "ipa": "tsuei˥˩ xau˨˩˦", "syllable_count": 2, "sentences": [{"text": "你感冒了，最好在家休息。", "target_word": "最好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面很冷，你最好多穿一件衣服。", "target_word": "最好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去山上最好带着水。", "target_word": "最好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上最好别喝咖啡。", "target_word": "最好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事最好先问问老师。", "target_word": "最好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你最好现在就给妈妈打电话。", "target_word": "最好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看书的时候最好坐直。", "target_word": "最好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天最好不要骑车。", "target_word": "最好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买票最好提前一个星期。", "target_word": "最好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃饭以后最好走一走。", "target_word": "最好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "副词；用于建议，表示这样做比别的做法都好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed471b59-6733-4165-85bc-54587c636e4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87147, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "最好", "is_correct": true, "explanation": "正确答案是「最好」（zuì hǎo），用于建议，表示这样做比别的做法都好。"}, {"text": "做好", "is_correct": false, "explanation": "zuò（第四声）与 zuì（第四声）韵母不同，意思是「做好」。"}, {"text": "睡好", "is_correct": false, "explanation": "shuì 与 zuì 声母不同（sh 与 z），意思是「睡好」。"}, {"text": "最少", "is_correct": false, "explanation": "shǎo 与 hǎo 声母不同（sh 与 h），意思是「最少」。"}, {"text": "最早", "is_correct": false, "explanation": "zǎo 与 hǎo 声母不同（z 与 h），意思是「最早」。"}], "explanations": {"最好": "正确答案是「最好」（zuì hǎo），用于建议，表示这样做比别的做法都好。", "做好": "zuò（第四声）与 zuì（第四声）韵母不同，意思是「做好」。", "睡好": "shuì 与 zuì 声母不同（sh 与 z），意思是「睡好」。", "最少": "shǎo 与 hǎo 声母不同（sh 与 h），意思是「最少」。", "最早": "zǎo 与 hǎo 声母不同（z 与 h），意思是「最早」。"}, "sentence_index": null, "correct_answer": "最好"}, "level_3": {"options": [{"text": "最好", "is_correct": true, "explanation": "「最好」用于建议，句意是在家休息比别的做法都好，与「感冒了」相合。"}, {"text": "非常", "is_correct": false, "explanation": "语义：「非常」只表示程度，不表示建议，「你感冒了，非常在家休息」不通。"}, {"text": "很", "is_correct": false, "explanation": "语义：「很」表示程度高，不能表示建议，句子不通。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：「曾经」指过去的经历，与句中现在感冒后的建议不符。"}], "explanations": {"最好": "「最好」用于建议，句意是在家休息比别的做法都好，与「感冒了」相合。", "非常": "语义：「非常」只表示程度，不表示建议，「你感冒了，非常在家休息」不通。", "很": "语义：「很」表示程度高，不能表示建议，句子不通。", "曾经": "语义：「曾经」指过去的经历，与句中现在感冒后的建议不符。"}, "sentence_index": 0, "correct_answer": "最好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我最好吃了三碗饭。", "explanation": "这里应该用〈一共〉。「最好」表示建议或理想，不用来统计已经吃掉的总数；说总数用「一共」。"}, {"text": "最好我们提前出发，没有迟到。", "explanation": "这里应该用〈幸好〉。「最好」表示建议或理想，不用来庆幸已经发生的事；说庆幸时用「幸好」。"}, {"text": "他上个月最好去过北京。", "explanation": "这里应该用〈曾经〉。「最好」表示建议或理想，不用来叙述已经有过的经历；说过去的经历用「曾经」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1457f693-2d6a-41c0-9c05-14b6511666e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87147, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "最好", "is_correct": true, "explanation": "正确答案是「最好」（zuì hǎo），用于建议，表示这样做比别的做法都好。"}, {"text": "坐好", "is_correct": false, "explanation": "zuò（第四声）与 zuì（第四声）韵母不同，意思是「坐好」。"}, {"text": "最小", "is_correct": false, "explanation": "xiǎo 与 hǎo 声母不同（x 与 h），意思是「最小」。"}, {"text": "最后", "is_correct": false, "explanation": "hòu 与 hǎo 韵母和声调都不同，意思是「最后」。"}, {"text": "最高", "is_correct": false, "explanation": "gāo 与 hǎo 声母和声调都不同，意思是「最高」。"}], "explanations": {"最好": "正确答案是「最好」（zuì hǎo），用于建议，表示这样做比别的做法都好。", "坐好": "zuò（第四声）与 zuì（第四声）韵母不同，意思是「坐好」。", "最小": "xiǎo 与 hǎo 声母不同（x 与 h），意思是「最小」。", "最后": "hòu 与 hǎo 韵母和声调都不同，意思是「最后」。", "最高": "gāo 与 hǎo 声母和声调都不同，意思是「最高」。"}, "sentence_index": null, "correct_answer": "最好"}, "level_3": {"options": [{"text": "最好", "is_correct": true, "explanation": "「最好」用于建议，句意是读书时坐直比别的坐法都好。"}, {"text": "太", "is_correct": false, "explanation": "语义：「太」表示程度过高，不能表示建议，「看书的时候太坐直」不通。"}, {"text": "竟然", "is_correct": false, "explanation": "语义：「竟然」表示出乎意料，与句中的建议语气不符。"}, {"text": "却", "is_correct": false, "explanation": "语义：「却」表示转折，句中没有可以转折的前文，不能这样用。"}], "explanations": {"最好": "「最好」用于建议，句意是读书时坐直比别的坐法都好。", "太": "语义：「太」表示程度过高，不能表示建议，「看书的时候太坐直」不通。", "竟然": "语义：「竟然」表示出乎意料，与句中的建议语气不符。", "却": "语义：「却」表示转折，句中没有可以转折的前文，不能这样用。"}, "sentence_index": 6, "correct_answer": "最好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们最好到车站，车就开了。", "explanation": "这里应该用〈刚〉。「最好」表示建议或理想，不表示动作刚刚发生；说刚到达用「刚」。"}, {"text": "我的房间最好十平方米了。", "explanation": "这里应该用〈将近〉。「最好」表示建议或理想，不用来估计数量；约略的数字要用「将近」。"}, {"text": "这件事最好重要。", "explanation": "这里应该用〈非常〉。「最好」不能直接修饰形容词作谓语，说程度很高时用「非常」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1457f693-2d6a-41c0-9c05-14b6511666e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87147, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "早上出门前，你最好的吃点东西。", "corrected_sentence": "早上出门前，你最好吃点东西。", "error_description": "「最好」作副词表示建议，后面直接接动词；「最好的」是形容词性短语，不能修饰动词「吃」。「你最好的吃点东西」错误，应说「你最好吃点东西」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1457f693-2d6a-41c0-9c05-14b6511666e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87147, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下雨天最好的带着雨伞。", "corrected_sentence": "下雨天最好带着雨伞。", "error_description": "「最好」作副词表示建议，后面直接接动词；「最好的」是形容词性短语，不能修饰动词「带着」。「下雨天最好的带着雨伞」错误，应说「下雨天最好带着雨伞」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1457f693-2d6a-41c0-9c05-14b6511666e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
