INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87150, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "表面没有高低凹凸，不倾斜。", "primary_collocate": null, "pronunciation": "píng", "ipa": "pʰiŋ˧˥", "syllable_count": 1, "sentences": [{"text": "这条路很平，骑车一点儿也不累。", "target_word": "平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子不平，写字的时候总是动。", "target_word": "平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把床单拉平，上面不要有皱褶。", "target_word": "平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖面平得像一面镜子。", "target_word": "平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块地很平，适合盖房子。", "target_word": "平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把纸放在桌上压平了。", "target_word": "平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草地平平的，孩子们在上面踢球。", "target_word": "平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地板不太平，走路要小心。", "target_word": "平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把书架放平，不然书会掉下来。", "target_word": "平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的山路不平，开车要慢一点。", "target_word": "平", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "平平的", "label": "重叠"}, {"form": "平整", "label": "复合"}, {"form": "平地", "label": "复合"}], "register": "中性", "sense_fingerprint": "平|表面无高低凹凸|形容词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94425b3a-c4ef-47ea-b6af-b5c17af3720b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87150, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "平", "is_correct": true, "explanation": "平（第二声）是正确答案，指表面没有高低凹凸。"}, {"text": "明", "is_correct": false, "explanation": "míng（第二声）与 píng 声母不同（m 与 p），意思是明亮。"}, {"text": "乒", "is_correct": false, "explanation": "pīng（第一声）与 píng（第二声）只是声调不同，用于“乒乓球”。"}, {"text": "旁", "is_correct": false, "explanation": "páng 与 píng 韵母不同（ang 与 ing），意思是旁边。"}, {"text": "朋", "is_correct": false, "explanation": "péng 与 píng 韵母不同（eng 与 ing），意思是朋友。"}], "explanations": {"平": "平（第二声）是正确答案，指表面没有高低凹凸。", "明": "míng（第二声）与 píng 声母不同（m 与 p），意思是明亮。", "乒": "pīng（第一声）与 píng（第二声）只是声调不同，用于“乒乓球”。", "旁": "páng 与 píng 韵母不同（ang 与 ing），意思是旁边。", "朋": "péng 与 píng 韵母不同（eng 与 ing），意思是朋友。"}, "sentence_index": null, "correct_answer": "平"}, "level_3": {"options": [{"text": "平", "is_correct": true, "explanation": "平指表面平整，与后半句“骑车一点儿也不累”相符。"}, {"text": "颠簸", "is_correct": false, "explanation": "语义：颠簸指路面起伏、震动大，骑车会很累，与“一点儿也不累”矛盾。"}, {"text": "崎岖", "is_correct": false, "explanation": "语义：崎岖指路面高低不平、难走，骑车会累，与后半句矛盾。"}, {"text": "高", "is_correct": false, "explanation": "搭配：“高”说的是高度，不用来描述路面平不平。"}], "explanations": {"平": "平指表面平整，与后半句“骑车一点儿也不累”相符。", "颠簸": "语义：颠簸指路面起伏、震动大，骑车会很累，与“一点儿也不累”矛盾。", "崎岖": "语义：崎岖指路面高低不平、难走，骑车会累，与后半句矛盾。", "高": "搭配：“高”说的是高度，不用来描述路面平不平。"}, "sentence_index": 0, "correct_answer": "平"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把这笔钱平给了三个孩子。", "explanation": "这里的“平”被用成了“平分”的意思，但“平”单用不能表示把钱分给别人，应该用〈分〉。“平”只指表面平整、不高低。"}, {"text": "学校平了三天的课，大家都很高兴。", "explanation": "这里的“平”被用成了“停”的意思，但“平”不表示停止，应该用〈停〉。“平”只指表面平整。"}, {"text": "这个问题很平，大家一听就懂了。", "explanation": "这里的“平”被用成了“简单”的意思，但“平”不表示难易，应该用〈简单〉。“平”只用于表面的平坦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d6d4d56-8f24-4af4-9609-d7826352ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87150, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "平", "is_correct": true, "explanation": "平（第二声）是正确答案，指表面没有高低凹凸。"}, {"text": "停", "is_correct": false, "explanation": "tíng（第二声）与 píng 声母不同（t 与 p），声调相同，意思是停止。"}, {"text": "零", "is_correct": false, "explanation": "líng（第二声）与 píng 声母不同（l 与 p），声调相同，意思是零。"}, {"text": "乒", "is_correct": false, "explanation": "pīng（第一声）与 píng（第二声）只是声调不同，用于“乒乓球”。"}], "explanations": {"平": "平（第二声）是正确答案，指表面没有高低凹凸。", "停": "tíng（第二声）与 píng 声母不同（t 与 p），声调相同，意思是停止。", "零": "líng（第二声）与 píng 声母不同（l 与 p），声调相同，意思是零。", "乒": "pīng（第一声）与 píng（第二声）只是声调不同，用于“乒乓球”。"}, "sentence_index": null, "correct_answer": "平"}, "level_3": {"options": [{"text": "平", "is_correct": true, "explanation": "平与“草地平平的”的结构相符，指地面平坦。"}, {"text": "酸", "is_correct": false, "explanation": "搭配：“酸”形容味道，不能用来形容草地。"}, {"text": "凸", "is_correct": false, "explanation": "语义：“凸”表示向外鼓起，与前文的“平”意思相反。"}, {"text": "陡", "is_correct": false, "explanation": "语义：“陡”指坡度很大，与“平”相反，草地陡陡的孩子们无法踢球。"}], "explanations": {"平": "平与“草地平平的”的结构相符，指地面平坦。", "酸": "搭配：“酸”形容味道，不能用来形容草地。", "凸": "语义：“凸”表示向外鼓起，与前文的“平”意思相反。", "陡": "语义：“陡”指坡度很大，与“平”相反，草地陡陡的孩子们无法踢球。"}, "sentence_index": 6, "correct_answer": "平"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把这块布平给了邻居。", "explanation": "这里的“平”被用成了“送”的意思，但“平”不表示把东西送人，应该用〈送〉。“平”只指表面平整。"}, {"text": "今天的作业很平，我十分钟就写完了。", "explanation": "这里的“平”被用成了“简单”的意思，但“平”指表面没有高低凹凸，不表示难易，应该用〈简单〉。"}, {"text": "他把这块石头平得很结实。", "explanation": "这里的“平”被用成了“坚固”的意思，但“平”指表面平整，不能形容石头结实，应该用〈坚固〉或〈结实〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d6d4d56-8f24-4af4-9609-d7826352ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_