INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87150, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "操场的地面平的像桌面。", "corrected_sentence": "操场的地面平得像桌面。", "error_description": "“平”后面的程度补语要用“得”，写成“的”是错误。正确：平得像桌面；错误：平的像桌面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d6d4d56-8f24-4af4-9609-d7826352ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87150, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把草丛踩了平。", "corrected_sentence": "他把草丛踩平了。", "error_description": "“了”应放在补语“平”的后面，写成“踩了平”是错误。正确：踩平了；错误：踩了平。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d6d4d56-8f24-4af4-9609-d7826352ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
