INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87151, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "左翼是队伍或鸟的左边那一边。", "primary_collocate": null, "pronunciation": "zuǒ yì", "ipa": "tsuo˨˩˦ i˥˩", "syllable_count": 2, "sentences": [{"text": "球队的左翼速度很快，常常突破对方防线。", "target_word": "左翼", "complexity_tier": "T3", "furigana": "qiú duì de zuǒ yì sù dù hěn kuài, cháng cháng tū pò duì fāng fáng xiàn。", "sentence_source": "generated"}, {"text": "小李在球队的左翼踢球。", "target_word": "左翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛中，他负责我们队伍的左翼。", "target_word": "左翼", "complexity_tier": "T3", "furigana": "bǐ sài zhōng, tā fù zé wǒ men duì wu de zuǒ yì。", "sentence_source": "generated"}, {"text": "这支队伍的左翼很强，防守很稳。", "target_word": "左翼", "complexity_tier": "T3", "furigana": "zhè zhī duì wu de zuǒ yì hěn qiáng, fáng shǒu hěn wěn。", "sentence_source": "generated"}, {"text": "球赛开始了，他从左翼跑向前面。", "target_word": "左翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "左翼的同学站得很整齐。", "target_word": "左翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把左翼交给速度最快的同学。", "target_word": "左翼", "complexity_tier": "T3", "furigana": "wǒ men bǎ zuǒ yì jiāo gěi sù dù zuì kuài de tóng xué。", "sentence_source": "generated"}, {"text": "比赛时，左翼没有人防守。", "target_word": "左翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "进攻时，左翼要从边路快速插上。", "target_word": "左翼", "complexity_tier": "T3", "furigana": "jìn gōng shí, zuǒ yì yào cóng biān lù kuài sù chā shàng。", "sentence_source": "generated"}, {"text": "教练请小王去队伍的左翼帮忙。", "target_word": "左翼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "队伍或鸟的左边一侧", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8381a54f-c1d7-4b10-9819-04a640eace4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87151, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "左翼", "is_correct": true, "explanation": "正确：“左翼”指球队中的边路位置，可以速度很快地突破对方防线。"}, {"text": "裁判", "is_correct": false, "explanation": "语义：裁判是执法的人，不是球队的位置，不会突破对方防线。"}, {"text": "门票", "is_correct": false, "explanation": "语义：门票是入场凭证，不能说速度很快或突破防线。"}, {"text": "球门", "is_correct": false, "explanation": "搭配：球门是固定的设施，不能与“速度很快”“突破对方防线”搭配。"}], "explanations": {"左翼": "正确：“左翼”指球队中的边路位置，可以速度很快地突破对方防线。", "裁判": "语义：裁判是执法的人，不是球队的位置，不会突破对方防线。", "门票": "语义：门票是入场凭证，不能说速度很快或突破防线。", "球门": "搭配：球门是固定的设施，不能与“速度很快”“突破对方防线”搭配。"}, "sentence_index": 0, "correct_answer": "左翼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他坐在我的左翼。", "explanation": "这里应该用〈左边〉。左翼指队伍、阵地或鸟、飞机的左侧部分，不用来指人身旁的位置。"}, {"text": "他的左翼受了伤。", "explanation": "这里应该用〈左侧〉。左翼不用于人的身体部位。"}, {"text": "这首歌的左翼很好听。", "explanation": "这里应该用〈旋律〉。左翼指队伍、鸟或飞机的一侧，不用来形容歌曲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2c0918d-5d4f-460c-a92e-20bad0a042f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87151, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "左翼", "is_correct": true, "explanation": "正确：“把……交给”后面可以接队伍中的位置或任务，左翼可以安排给同学。"}, {"text": "教练", "is_correct": false, "explanation": "搭配：“把……交给”后接的是任务或物品，不说把“教练”交给同学。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是固定的房间，不能被交给同学。"}, {"text": "体育馆", "is_correct": false, "explanation": "语义：体育馆是场馆建筑，不能当作东西交给同学。"}], "explanations": {"左翼": "正确：“把……交给”后面可以接队伍中的位置或任务，左翼可以安排给同学。", "教练": "搭配：“把……交给”后接的是任务或物品，不说把“教练”交给同学。", "教室": "语义：教室是固定的房间，不能被交给同学。", "体育馆": "语义：体育馆是场馆建筑，不能当作东西交给同学。"}, "sentence_index": 6, "correct_answer": "左翼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道题的左翼很难做。", "explanation": "这里应该用〈难点〉。左翼指队伍、鸟或飞机的一侧，不用来形容题目。"}, {"text": "这台电脑的左翼坏了，要送去修。", "explanation": "这里应该用〈主板〉。左翼不用于电脑的部件。"}, {"text": "这条河的左翼很宽。", "explanation": "这里应该用〈左岸〉。左翼指队伍、鸟或飞机的一侧，不用于河流。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2c0918d-5d4f-460c-a92e-20bad0a042f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87151, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "教练把小张安排左翼。", "corrected_sentence": "教练把小张安排在左翼。", "error_description": "错误：「安排左翼」。「把……安排」后面表示位置时要加「在」，应为「安排在左翼」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2c0918d-5d4f-460c-a92e-20bad0a042f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87151, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他左翼踢球。", "corrected_sentence": "他在左翼踢球。", "error_description": "错误：「左翼踢球」。表示位置的「左翼」前面要加介词「在」，应说「在左翼踢球」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2c0918d-5d4f-460c-a92e-20bad0a042f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
