INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87154, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "天主教、东正教及圣公会中主管一个教区的高级神职人员。", "primary_collocate": null, "pronunciation": "zhǔ jiào", "ipa": "ʈʂu˨˩ tɕjɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这个教区的主教是一位老人。", "target_word": "主教", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个教区都有一位主教负责管理。", "target_word": "主教", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "东正教也有主教。", "target_word": "主教", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教皇任命他做这个城市的主教。", "target_word": "主教", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "圣公会的主教来中国访问了。", "target_word": "主教", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当了二十年主教，管理着整个教区。", "target_word": "主教", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主教的职位比神父高。", "target_word": "主教", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神父们都要听主教的安排。", "target_word": "主教", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位主教管着十几座教堂。", "target_word": "主教", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新主教昨天到了这个教区。", "target_word": "主教", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大主教", "label": "复合"}], "register": "中性", "sense_fingerprint": "主管一个教区的高级神职人员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '538b8765-1c9e-4db9-8583-9f5d1dd35ff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87154, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "主教", "is_correct": true, "explanation": "主教：主管一个教区的神职人员，与“这个教区”和“老人”相符。"}, {"text": "教练", "is_correct": false, "explanation": "语义：教练是体育指导，不负责教区，句子说不通。"}, {"text": "教堂", "is_correct": false, "explanation": "搭配：“是一位老人”要求指人，教堂是建筑，不能这样说。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不是人，不能是这个教区的老人。"}], "explanations": {"主教": "主教：主管一个教区的神职人员，与“这个教区”和“老人”相符。", "教练": "语义：教练是体育指导，不负责教区，句子说不通。", "教堂": "搭配：“是一位老人”要求指人，教堂是建筑，不能这样说。", "窗户": "语义：窗户不是人，不能是这个教区的老人。"}, "sentence_index": 0, "correct_answer": "主教"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈用主教切菜。", "explanation": "这里应该用〈刀〉。主教是神职人员，不是工具，不能用来切菜。"}, {"text": "他每天骑主教去教堂做礼拜。", "explanation": "这里应该用〈自行车〉。主教是神职人员，不是交通工具，不能骑着去教堂。"}, {"text": "这座主教很大，里面能坐一千人。", "explanation": "这里应该用〈大教堂〉。主教指神职人员，不指建筑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d1df8c-23e6-4bf6-8b40-263efbffaf4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87154, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主教", "is_correct": true, "explanation": "主教：职位高于神父，与“职位比神父高”相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有职位，句子不通。"}, {"text": "河流", "is_correct": false, "explanation": "搭配：“职位”只用于人或机构，不说河流的职位。"}, {"text": "树", "is_correct": false, "explanation": "语义：树没有职位，句子不通。"}], "explanations": {"主教": "主教：职位高于神父，与“职位比神父高”相符。", "石头": "语义：石头没有职位，句子不通。", "河流": "搭配：“职位”只用于人或机构，不说河流的职位。", "树": "语义：树没有职位，句子不通。"}, "sentence_index": 6, "correct_answer": "主教"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈煮了一锅主教，全家一起喝。", "explanation": "这里应该用〈汤〉。主教是神职人员，不能煮或喝。"}, {"text": "这个学校的主教正在上数学课。", "explanation": "这里应该用〈老师〉。主教是教会的神职人员，不是学校老师。"}, {"text": "我家养了一只主教，每天喂它。", "explanation": "这里应该用〈猫〉。主教是人，不能当宠物饲养。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d1df8c-23e6-4bf6-8b40-263efbffaf4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87154, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那座主教管着整个城市的教堂。", "corrected_sentence": "那位主教管着整个城市的教堂。", "error_description": "量词错误：指人的主教应用“位”。“座”用于建筑、山等，不能用于人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d1df8c-23e6-4bf6-8b40-263efbffaf4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87154, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两位主教们都来了，神父们很高兴。", "corrected_sentence": "两位主教都来了，神父们很高兴。", "error_description": "数量词错误：“两位”之后不能再加“们”，应说“两位主教”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d1df8c-23e6-4bf6-8b40-263efbffaf4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
