INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87157, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "市制是我国以前常用的一套量东西的办法，比如斤和尺。", "primary_collocate": null, "pronunciation": "shì zhì", "ipa": "ʂɻ̩˥˩ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "爷爷说，以前菜市场都用市制。", "target_word": "市制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "斤和尺都是市制里的单位。", "target_word": "市制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市制是中国以前常用的量东西的办法。", "target_word": "市制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我外婆量布时还用市制的尺。", "target_word": "市制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校里教公制，家里老人还用市制。", "target_word": "市制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买米论斤，是市制的说法。", "target_word": "市制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道市制和公制有什么不同吗？", "target_word": "市制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把市制的重量换算成了公斤。", "target_word": "市制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张老照片旁写着市制的尺寸。", "target_word": "市制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在商店标价多用公制，很少用市制。", "target_word": "市制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "我国以前常用的一套量东西的办法，如斤和尺", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83c1835b-777f-4252-a671-77d7f731f642') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87157, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "市制", "is_correct": true, "explanation": "市制：以前常用的一套量东西的办法，就是这个词。"}, {"text": "试纸", "is_correct": false, "explanation": "zhǐ（第三声）与 zhì（第四声）声调不同，意思是试纸。"}, {"text": "实质", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是本质、实际内容。"}, {"text": "食指", "is_correct": false, "explanation": "shí 与 shì、zhǐ 与 zhì 声调都不同，意思是食指。"}, {"text": "十指", "is_correct": false, "explanation": "shí 与 shì、zhǐ 与 zhì 声调都不同，意思是十根手指。"}], "explanations": {"市制": "市制：以前常用的一套量东西的办法，就是这个词。", "试纸": "zhǐ（第三声）与 zhì（第四声）声调不同，意思是试纸。", "实质": "shí（第二声）与 shì（第四声）声调不同，意思是本质、实际内容。", "食指": "shí 与 shì、zhǐ 与 zhì 声调都不同，意思是食指。", "十指": "shí 与 shì、zhǐ 与 zhì 声调都不同，意思是十根手指。"}, "sentence_index": null, "correct_answer": "市制"}, "level_3": {"options": [{"text": "市制", "is_correct": true, "explanation": "正确：句子说以前菜市场都用的量东西的办法，就是市制。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：蔬菜是食物，不是量东西的办法，“用蔬菜”说不通。"}, {"text": "歌曲", "is_correct": false, "explanation": "配价：“用”要带可以用来量东西的工具，“歌曲”不能被用来量东西。"}, {"text": "眼镜", "is_correct": false, "explanation": "语义：眼镜是用来看东西的，不是量东西的办法，句子说不通。"}], "explanations": {"市制": "正确：句子说以前菜市场都用的量东西的办法，就是市制。", "蔬菜": "语义：蔬菜是食物，不是量东西的办法，“用蔬菜”说不通。", "歌曲": "配价：“用”要带可以用来量东西的工具，“歌曲”不能被用来量东西。", "眼镜": "语义：眼镜是用来看东西的，不是量东西的办法，句子说不通。"}, "sentence_index": 0, "correct_answer": "市制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我外婆量布时还用一把市制。", "explanation": "这里应该用〈套〉。市制指一套度量衡制度，量词“把”用于有柄的工具，不能用来数制度。"}, {"text": "这匹布的市制很厚。", "explanation": "这里不能形容布的厚薄。市制是度量衡制度，没有厚薄之说；描述布料厚薄应说“布很厚”。"}, {"text": "外婆的市制很好。", "explanation": "这里应该用〈手艺〉。市制指度量衡制度，不能说某人有“市制”这种能力；形容人的技能要说〈手艺〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4228f373-c193-47c6-a436-97b96b692f0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87157, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "市制", "is_correct": true, "explanation": "市制：以前常用的一套量东西的办法，就是这个词。"}, {"text": "四至", "is_correct": false, "explanation": "sì 与 shì 声母不同（s/sh），意思是四面的界限。"}, {"text": "时制", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是语法中的时态制度。"}, {"text": "实职", "is_correct": false, "explanation": "shí 与 shì、zhí 与 zhì 声调都不同，意思是实际担任的职务。"}, {"text": "示指", "is_correct": false, "explanation": "zhǐ（第三声）与 zhì（第四声）声调不同，意思是食指。"}], "explanations": {"市制": "市制：以前常用的一套量东西的办法，就是这个词。", "四至": "sì 与 shì 声母不同（s/sh），意思是四面的界限。", "时制": "shí（第二声）与 shì（第四声）声调不同，意思是语法中的时态制度。", "实职": "shí 与 shì、zhí 与 zhì 声调都不同，意思是实际担任的职务。", "示指": "zhǐ（第三声）与 zhì（第四声）声调不同，意思是食指。"}, "sentence_index": null, "correct_answer": "市制"}, "level_3": {"options": [{"text": "市制", "is_correct": true, "explanation": "正确：市制与公制是两种度量体系，句子正在比较二者。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是气象状况，不是度量体系，不能与公制比较。"}, {"text": "书法", "is_correct": false, "explanation": "语义：书法是写字的艺术，不是度量体系，与公制无法比较。"}, {"text": "俗语", "is_correct": false, "explanation": "语义：俗语是语言中的固定说法，与“公制”属于不同类别，无法相比。"}], "explanations": {"市制": "正确：市制与公制是两种度量体系，句子正在比较二者。", "天气": "语义：天气是气象状况，不是度量体系，不能与公制比较。", "书法": "语义：书法是写字的艺术，不是度量体系，与公制无法比较。", "俗语": "语义：俗语是语言中的固定说法，与“公制”属于不同类别，无法相比。"}, "sentence_index": 6, "correct_answer": "市制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种市制很便宜。", "explanation": "这里把〈市制〉当成了有价格的商品。市制是度量衡制度，没有价格，不能用来比价；能标价的应是商品。"}, {"text": "这个市制比米还贵。", "explanation": "这里把〈市制〉当成了有价格的商品。市制是度量衡制度，不能拿来与米比价；能标价的应是商品。"}, {"text": "店员把市制称了三遍。", "explanation": "这里称的应是米、菜等物品。市制是制度，不能放在秤上称。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4228f373-c193-47c6-a436-97b96b692f0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87157, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把秤原来是市制了。", "corrected_sentence": "这把秤原来是市制的。", "error_description": "语气词误用：“是”字句中说明事物的性质或来源要用“的”，“是市制了”应改为“是市制的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4228f373-c193-47c6-a436-97b96b692f0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87157, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们用不市制量布。", "corrected_sentence": "我们不用市制量布。", "error_description": "否定词位置错误：否定词“不”应放在动词“用”之前，说“不用市制量布”，不能说“用不市制量布”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4228f373-c193-47c6-a436-97b96b692f0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
