INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87158, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "中国传统的度量衡制度，以市斤、市尺、市升为单位。", "primary_collocate": null, "pronunciation": "shì zhì", "ipa": "ʂɻ̩˥˩ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "市制以市斤、市尺和市升为单位。", "target_word": "市制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在市制里，一市斤等于十市两。", "target_word": "市制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公制和市制不一样，一公斤等于两市斤。", "target_word": "市制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶买菜时还习惯用市制称重量。", "target_word": "市制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市制的长度单位是市尺，不是米。", "target_word": "市制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书介绍了市制和公制的区别。", "target_word": "市制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们国家以前常用市制，现在多用公制。", "target_word": "市制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "按市制算，这袋米有二十市斤重。", "target_word": "市制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们把市制单位换成公制单位。", "target_word": "市制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市制里的一市升，差不多等于一公升。", "target_word": "市制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "中国传统度量衡制度，单位为市斤、市尺、市升", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83c1835b-777f-4252-a671-77d7f731f642') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87158, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "市制", "is_correct": true, "explanation": "市制：中国传统的度量衡制度，以市斤、市尺、市升为单位，就是这个词。"}, {"text": "试纸", "is_correct": false, "explanation": "zhǐ（第三声）与 zhì（第四声）声调不同，意思是试纸。"}, {"text": "实质", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是本质、实际内容。"}, {"text": "食指", "is_correct": false, "explanation": "shí 与 shì、zhǐ 与 zhì 声调都不同，意思是食指。"}, {"text": "十指", "is_correct": false, "explanation": "shí 与 shì、zhǐ 与 zhì 声调都不同，意思是十根手指。"}], "explanations": {"市制": "市制：中国传统的度量衡制度，以市斤、市尺、市升为单位，就是这个词。", "试纸": "zhǐ（第三声）与 zhì（第四声）声调不同，意思是试纸。", "实质": "shí（第二声）与 shì（第四声）声调不同，意思是本质、实际内容。", "食指": "shí 与 shì、zhǐ 与 zhì 声调都不同，意思是食指。", "十指": "shí 与 shì、zhǐ 与 zhì 声调都不同，意思是十根手指。"}, "sentence_index": null, "correct_answer": "市制"}, "level_3": {"options": [{"text": "市制", "is_correct": true, "explanation": "正确：市制以市斤、市尺、市升为单位，与句中的单位相符。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：时间的计量单位是小时、分钟，不会以市斤、市尺为单位。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是气象状况，不是度量单位的制度，不能以市斤为单位。"}, {"text": "货币", "is_correct": false, "explanation": "语义：货币以元、角、分为单位，与市斤、市尺无关，句子说不通。"}], "explanations": {"市制": "正确：市制以市斤、市尺、市升为单位，与句中的单位相符。", "时间": "搭配：时间的计量单位是小时、分钟，不会以市斤、市尺为单位。", "天气": "语义：天气是气象状况，不是度量单位的制度，不能以市斤为单位。", "货币": "语义：货币以元、角、分为单位，与市斤、市尺无关，句子说不通。"}, "sentence_index": 0, "correct_answer": "市制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个学校的市制很严格。", "explanation": "这里应该用〈制度〉。市制特指中国传统的度量衡制度，不能指学校里的规章；学校的规定要说〈制度〉。"}, {"text": "这袋米重二十市制。", "explanation": "这里应该用〈市斤〉。市制是度量衡制度，不是计量单位，表示重量的数量后要接具体的单位，如市斤，不能直接接“市制”。"}, {"text": "我们厂专门生产市制。", "explanation": "这里应该用〈尺子〉。市制是抽象的度量衡制度，不是可以生产的实物，工厂生产的应是尺子之类的具体产品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4228f373-c193-47c6-a436-97b96b692f0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87158, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "市制", "is_correct": true, "explanation": "市制：中国传统的度量衡制度，以市斤、市尺、市升为单位，就是这个词。"}, {"text": "四至", "is_correct": false, "explanation": "sì 与 shì 声母不同（s/sh），意思是四面的界限。"}, {"text": "时制", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是语法中的时态制度。"}, {"text": "实职", "is_correct": false, "explanation": "shí 与 shì、zhí 与 zhì 声调都不同，意思是实际担任的职务。"}, {"text": "示指", "is_correct": false, "explanation": "zhǐ（第三声）与 zhì（第四声）声调不同，意思是食指。"}], "explanations": {"市制": "市制：中国传统的度量衡制度，以市斤、市尺、市升为单位，就是这个词。", "四至": "sì 与 shì 声母不同（s/sh），意思是四面的界限。", "时制": "shí（第二声）与 shì（第四声）声调不同，意思是语法中的时态制度。", "实职": "shí 与 shì、zhí 与 zhì 声调都不同，意思是实际担任的职务。", "示指": "zhǐ（第三声）与 zhì（第四声）声调不同，意思是食指。"}, "sentence_index": null, "correct_answer": "市制"}, "level_3": {"options": [{"text": "市制", "is_correct": true, "explanation": "正确：句子说以前常用市制，现在多用公制，市制符合语境。"}, {"text": "书法", "is_correct": false, "explanation": "语义：书法是写字的艺术，不是度量体系，与“公制”的对比说不通。"}, {"text": "乐器", "is_correct": false, "explanation": "搭配：“常用”后面接的应是计量制度，乐器不能与“公制”构成对比。"}, {"text": "方言", "is_correct": false, "explanation": "语义：方言是地方话，不是计量制度，句子说不通。"}], "explanations": {"市制": "正确：句子说以前常用市制，现在多用公制，市制符合语境。", "书法": "语义：书法是写字的艺术，不是度量体系，与“公制”的对比说不通。", "乐器": "搭配：“常用”后面接的应是计量制度，乐器不能与“公制”构成对比。", "方言": "语义：方言是地方话，不是计量制度，句子说不通。"}, "sentence_index": 6, "correct_answer": "市制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这套市制很漂亮。", "explanation": "这里不能用来形容外貌。市制是抽象的度量衡制度，没有外貌，评价或描述制度应说〈完善〉之类的词。"}, {"text": "市制以公斤为单位。", "explanation": "这里应该用〈公制〉。公斤是公制的单位，市制以市斤、市尺等为单位，两者不能混用。"}, {"text": "我把市制送给了朋友。", "explanation": "这里不能用〈送〉这类动作。市制是抽象的制度，不是可以送人的东西；送人的应是具体的物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4228f373-c193-47c6-a436-97b96b692f0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87158, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本旧书讲解了一条市制。", "corrected_sentence": "这本旧书讲解了一套市制。", "error_description": "量词错误：“市制”指一套度量衡制度，应用量词“套”，不能用“条”（条多用于细长的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4228f373-c193-47c6-a436-97b96b692f0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87158, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把市制换算公制。", "corrected_sentence": "我们把市制换算成公制。", "error_description": "补语遗漏：“把……换算”后要用“成”引出结果，应说“换算成公制”，不能省略“成”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4228f373-c193-47c6-a436-97b96b692f0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
