INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87159, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "二心是心里想着别的人，不全心对你。", "primary_collocate": null, "pronunciation": "èr xīn", "ipa": "ɚ˥˩ ɕin˥", "syllable_count": 2, "sentences": [{"text": "她怀疑男朋友对她有二心。", "target_word": "二心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "结婚以后，他从来没有二心。", "target_word": "二心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只爱你一个人，没有二心。", "target_word": "二心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她发现丈夫有了二心，很难过。", "target_word": "二心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谈恋爱不能有二心。", "target_word": "二心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对女朋友有二心，被她发现了。", "target_word": "二心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要是有二心，就早点告诉我。", "target_word": "二心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她相信他对自己没有二心。", "target_word": "二心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爱一个人，就不要有二心。", "target_word": "二心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友说他对女朋友早就有了二心。", "target_word": "二心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "感情上的二心：爱着别人，对恋人或爱人不专一", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed69058d-24aa-4c07-bc40-36884250d128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87159, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "信心", "is_correct": false, "explanation": "语义：“怀疑”与“信心”意思相反，句中说的是怀疑，不能同时说对她有信心。"}, {"text": "能力", "is_correct": false, "explanation": "搭配：“能力”要说“有……能力”，不能说“对她有能力”。"}, {"text": "二心", "is_correct": true, "explanation": "正确：“二心”指对恋人不专一，“对她有二心”即心里另有所爱，与“怀疑”相合。"}, {"text": "感激", "is_correct": false, "explanation": "搭配：“感激”一般说“对她感激”，不说“对她有感激”。"}], "explanations": {"信心": "语义：“怀疑”与“信心”意思相反，句中说的是怀疑，不能同时说对她有信心。", "能力": "搭配：“能力”要说“有……能力”，不能说“对她有能力”。", "二心": "正确：“二心”指对恋人不专一，“对她有二心”即心里另有所爱，与“怀疑”相合。", "感激": "搭配：“感激”一般说“对她感激”，不说“对她有感激”。"}, "sentence_index": 0, "correct_answer": "二心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他上课时总是有二心，老师很生气。", "explanation": "这里应该用〈分心〉。“二心”指对爱人不专一，不能用来形容上课时走神。"}, {"text": "她做菜很有二心，菜特别好吃。", "explanation": "这里应该用〈用心〉。“二心”指对爱人不专一，不能表示做事认真、花心思。"}, {"text": "她对那个新玩具很有二心。", "explanation": "这里应该用〈好奇〉。“二心”指对人不专一，不能用来形容对新玩具的兴趣。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b40bdfe4-ba79-4ecd-b88f-4c9a825bd20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87159, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "胡子", "is_correct": false, "explanation": "语义：“胡子”不是需要早点告诉对方的事，“有胡子”与句意不合，句意不通。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”是外形特征，不是需要告诉对方的事。"}, {"text": "二心", "is_correct": true, "explanation": "正确：“有二心”指心里对恋人不专一，需要早点说出来，与句意相合。"}, {"text": "面子", "is_correct": false, "explanation": "语义：“面子”与“早点告诉我”没有关联，句意不通。"}], "explanations": {"胡子": "语义：“胡子”不是需要早点告诉对方的事，“有胡子”与句意不合，句意不通。", "体重": "体貌：“体重”是外形特征，不是需要告诉对方的事。", "二心": "正确：“有二心”指心里对恋人不专一，需要早点说出来，与句意相合。", "面子": "语义：“面子”与“早点告诉我”没有关联，句意不通。"}, "sentence_index": 6, "correct_answer": "二心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她看到那件衣服，很有二心。", "explanation": "这里应该用〈动心〉。“二心”指对人不专一，不能用来表示对东西产生想要的念头。"}, {"text": "他很有二心，经常帮助别人。", "explanation": "这里应该用〈爱心〉。“二心”指对人不专一，不能表示关心、帮助别人的心意。"}, {"text": "她学习时常常有二心，成绩不好。", "explanation": "这里应该用〈分心〉。“二心”指对人不专一，不能用来形容学习时注意力不集中。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b40bdfe4-ba79-4ecd-b88f-4c9a825bd20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87159, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他答应过我，心里不会有一个二心。", "corrected_sentence": "他答应过我，心里不会有一点二心。", "error_description": "量词错误：“二心”前应用“点”（一点二心），不能用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b40bdfe4-ba79-4ecd-b88f-4c9a825bd20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87159, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他对她是二心，她很伤心。", "corrected_sentence": "他对她有二心，她很伤心。", "error_description": "动词错误：“有”不能换成“是”，“是二心”不成立，应为“有二心”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b40bdfe4-ba79-4ecd-b88f-4c9a825bd20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87160, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "忠心", "is_correct": true, "explanation": "反义：“忠心”与“二心”相对，指对人或集体忠诚，与“没有二心”意思对立。"}, {"text": "窗户", "is_correct": false, "explanation": "无关：“窗户”是房屋的构件，与“二心”没有反义关系。"}, {"text": "书包", "is_correct": false, "explanation": "无关：“书包”指装书的袋子，与“二心”没有反义关系。"}, {"text": "早餐", "is_correct": false, "explanation": "无关：“早餐”指早上吃的饭，与“二心”没有反义关系。"}], "correct_answer": "忠心", "explanations": {"忠心": "反义：“忠心”与“二心”相对，指对人或集体忠诚，与“没有二心”意思对立。", "窗户": "无关：“窗户”是房屋的构件，与“二心”没有反义关系。", "书包": "无关：“书包”指装书的袋子，与“二心”没有反义关系。", "早餐": "无关：“早餐”指早上吃的饭，与“二心”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b40bdfe4-ba79-4ecd-b88f-4c9a825bd20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87160, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "忠心", "is_correct": true, "explanation": "反义：“忠心”与“二心”相对，指对人忠诚，与“二心”意思对立。"}, {"text": "桌子", "is_correct": false, "explanation": "无关：“桌子”是家具，与“二心”没有反义关系。"}, {"text": "雨伞", "is_correct": false, "explanation": "无关：“雨伞”是遮雨用的器具，与“二心”没有反义关系。"}, {"text": "钥匙", "is_correct": false, "explanation": "无关：“钥匙”是开锁的工具，与“二心”没有反义关系。"}], "correct_answer": "忠心", "explanations": {"忠心": "反义：“忠心”与“二心”相对，指对人忠诚，与“二心”意思对立。", "桌子": "无关：“桌子”是家具，与“二心”没有反义关系。", "雨伞": "无关：“雨伞”是遮雨用的器具，与“二心”没有反义关系。", "钥匙": "无关：“钥匙”是开锁的工具，与“二心”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b40bdfe4-ba79-4ecd-b88f-4c9a825bd20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87160, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对人不忠诚、不专一的想法；不忠实的心思。", "primary_collocate": null, "pronunciation": "èr xīn", "ipa": "ɚ˥˩ ɕin˥", "syllable_count": 2, "sentences": [{"text": "这个人对公司有二心，大家都知道。", "target_word": "二心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对朋友从来没有二心。", "target_word": "二心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板发现经理对自己怀有二心。", "target_word": "二心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们对工厂没有二心，一直很努力。", "target_word": "二心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王怀疑大臣有二心。", "target_word": "二心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做事认真，对我们没有二心。", "target_word": "二心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要是对朋友有二心，朋友就会离开你。", "target_word": "二心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他怀有二心，所以大家不相信他。", "target_word": "二心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "将军对国家忠心，没有二心。", "target_word": "二心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们是一家人，谁也不能有二心。", "target_word": "二心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "对人或集体不忠诚的想法，如对公司、朋友、国家有二心", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed69058d-24aa-4c07-bc40-36884250d128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87160, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "名字", "is_correct": false, "explanation": "语义：“名字”不能对公司有，句意说的是态度，不是名字。"}, {"text": "二心", "is_correct": true, "explanation": "正确：“二心”指对公司或集体不忠诚的想法，与后面“大家都知道”相符。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是外形特征，与对公司的态度无关。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”不是对公司可以有的东西，句意不通。"}], "explanations": {"名字": "语义：“名字”不能对公司有，句意说的是态度，不是名字。", "二心": "正确：“二心”指对公司或集体不忠诚的想法，与后面“大家都知道”相符。", "身高": "体貌：“身高”是外形特征，与对公司的态度无关。", "年龄": "语义：“年龄”不是对公司可以有的东西，句意不通。"}, "sentence_index": 0, "correct_answer": "二心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人们上班时总是有二心，效率很低。", "explanation": "这里应该用〈分心〉。“二心”指对人或集体不忠诚，不能用来形容上班时注意力不集中。"}, {"text": "他们两个人很有二心，总是想到一起。", "explanation": "这里应该用〈默契〉。“二心”指对人或集体不忠诚，不能表示两人想法一致、配合得好。"}, {"text": "他对新鲜事很有二心。", "explanation": "这里应该用〈好奇〉。“二心”指对人或集体不忠诚的想法，不能用来形容对新鲜事物的兴趣。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b40bdfe4-ba79-4ecd-b88f-4c9a825bd20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87160, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "存款", "is_correct": false, "explanation": "语义：“存款”不是对朋友可以有的东西，句意不通。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”是外形特征，与对朋友的态度无关。"}, {"text": "二心", "is_correct": true, "explanation": "正确：“对朋友有二心”指对朋友不忠诚，朋友会因此离开，与句意相合。"}, {"text": "生日", "is_correct": false, "explanation": "语义：“生日”不能对朋友有，与句意不符。"}], "explanations": {"存款": "语义：“存款”不是对朋友可以有的东西，句意不通。", "体重": "体貌：“体重”是外形特征，与对朋友的态度无关。", "二心": "正确：“对朋友有二心”指对朋友不忠诚，朋友会因此离开，与句意相合。", "生日": "语义：“生日”不能对朋友有，与句意不符。"}, "sentence_index": 6, "correct_answer": "二心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈对孩子的安全很有二心。", "explanation": "这里应该用〈担心〉。“二心”指对人或集体不忠诚，不能表示为别人的安全着急。"}, {"text": "她在两件衣服之间有二心，不知道买哪件。", "explanation": "这里应该用〈犹豫〉。“二心”指对人或集体不忠诚，不能表示拿不定主意。"}, {"text": "她看到那件衣服很有二心。", "explanation": "这里应该用〈动心〉。“二心”指对人不专一，不能用来表示对衣服产生想要的念头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b40bdfe4-ba79-4ecd-b88f-4c9a825bd20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87160, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老板相信员工对公司都不有二心。", "corrected_sentence": "老板相信员工对公司都没有二心。", "error_description": "否定词错误：“有”的否定要用“没有”，不能说“不有”，应为“都没有二心”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b40bdfe4-ba79-4ecd-b88f-4c9a825bd20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87160, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他对朋友是二心，朋友很伤心。", "corrected_sentence": "他对朋友有二心，朋友很伤心。", "error_description": "动词错误：“有”不能换成“是”，“是二心”不成立，应为“有二心”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b40bdfe4-ba79-4ecd-b88f-4c9a825bd20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
