INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87161, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "东是太阳升起来的那一边。", "primary_collocate": null, "pronunciation": "dōng", "ipa": "tʊŋ˥", "syllable_count": 1, "sentences": [{"text": "过了桥，请往东走五分钟。", "target_word": "东", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳每天从东往西走。", "target_word": "东", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的门朝东，早上很亮。", "target_word": "东", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车一直向东开，明天到海边。", "target_word": "东", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面有两条路，你得往东拐。", "target_word": "东", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上，右边是东，左边是西。", "target_word": "东", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从学校往东走，看到一家书店。", "target_word": "东", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不去西边，往东去吧。", "target_word": "东", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从西走到东，用了一个小时。", "target_word": "东", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，去海边是往东还是往西？", "target_word": "东", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "东边", "label": "复合"}, {"form": "东面", "label": "复合"}, {"form": "東", "label": "繁体"}], "register": "中性", "sense_fingerprint": "东：太阳升起来的那一边，常说往东、朝东", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5557fc-539b-4cb6-b9b1-8d2660c41b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87161, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "东", "is_correct": true, "explanation": "正确：东（dōng）是太阳升起的方向，与「西」相对。"}, {"text": "通", "is_correct": false, "explanation": "「tōng」与「dōng」声母不同（t/d），意思是通过、通达。"}, {"text": "动", "is_correct": false, "explanation": "「dòng」（第四声）与「dōng」（第一声）声调不同，意思是运动。"}, {"text": "懂", "is_correct": false, "explanation": "「dǒng」（第三声）与「dōng」（第一声）声调不同，意思是明白。"}, {"text": "灯", "is_correct": false, "explanation": "「dēng」与「dōng」韵母不同（e/o），意思是灯。"}], "explanations": {"东": "正确：东（dōng）是太阳升起的方向，与「西」相对。", "通": "「tōng」与「dōng」声母不同（t/d），意思是通过、通达。", "动": "「dòng」（第四声）与「dōng」（第一声）声调不同，意思是运动。", "懂": "「dǒng」（第三声）与「dōng」（第一声）声调不同，意思是明白。", "灯": "「dēng」与「dōng」韵母不同（e/o），意思是灯。"}, "sentence_index": null, "correct_answer": "东"}, "level_3": {"options": [{"text": "东", "is_correct": true, "explanation": "正确：「往东走」指朝太阳升起的方向走。"}, {"text": "饭", "is_correct": false, "explanation": "语义：「饭」不是方向，「往饭走」无法构成行走的方向。"}, {"text": "鞋", "is_correct": false, "explanation": "语义：「鞋」不是方向，不能作行走的目标。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：「往」后接方向或处所，「作业」不能作行走的方向。"}], "explanations": {"东": "正确：「往东走」指朝太阳升起的方向走。", "饭": "语义：「饭」不是方向，「往饭走」无法构成行走的方向。", "鞋": "语义：「鞋」不是方向，不能作行走的目标。", "作业": "搭配：「往」后接方向或处所，「作业」不能作行走的方向。"}, "sentence_index": 0, "correct_answer": "东"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了很多东，都装进了箱子。", "explanation": "这里应该用「东西」。「东」只表示方向，表示物品要说「东西」。"}, {"text": "我家在学校东，走路五分钟就到。", "explanation": "这里应该用「东边」。「东」单独作处所不能这样说，表示方位要用「东边」。"}, {"text": "这个城市的东很热闹，有很多商店。", "explanation": "这里应该用「东部」。「东」不能单独指一个地区，指地区要说「东部」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49ae9169-ef07-43c7-8a80-89a7fba3a92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87161, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "东", "is_correct": true, "explanation": "正确：东（dōng）是太阳升起的方向，与「西」相对。"}, {"text": "洞", "is_correct": false, "explanation": "「dòng」（第四声）与「dōng」（第一声）声调不同，意思是洞穴。"}, {"text": "冻", "is_correct": false, "explanation": "「dòng」（第四声）与「dōng」（第一声）声调不同，意思是冰冻。"}, {"text": "董", "is_correct": false, "explanation": "「dǒng」（第三声）与「dōng」（第一声）声调不同，是一个姓氏。"}, {"text": "登", "is_correct": false, "explanation": "「dēng」与「dōng」韵母不同（e/o），意思是登上。"}], "explanations": {"东": "正确：东（dōng）是太阳升起的方向，与「西」相对。", "洞": "「dòng」（第四声）与「dōng」（第一声）声调不同，意思是洞穴。", "冻": "「dòng」（第四声）与「dōng」（第一声）声调不同，意思是冰冻。", "董": "「dǒng」（第三声）与「dōng」（第一声）声调不同，是一个姓氏。", "登": "「dēng」与「dōng」韵母不同（e/o），意思是登上。"}, "sentence_index": null, "correct_answer": "东"}, "level_3": {"options": [{"text": "东", "is_correct": true, "explanation": "正确：「从学校往东走」表示朝太阳升起的方向走。"}, {"text": "鸡", "is_correct": false, "explanation": "语义：「鸡」不是方向，「往鸡走」无法成立。"}, {"text": "书", "is_correct": false, "explanation": "语义：「书」不是方向或处所，与「从学校往……走」不符。"}, {"text": "镜子", "is_correct": false, "explanation": "搭配：「镜子」不是可以前往的处所，不能作「往」的宾语。"}], "explanations": {"东": "正确：「从学校往东走」表示朝太阳升起的方向走。", "鸡": "语义：「鸡」不是方向，「往鸡走」无法成立。", "书": "语义：「书」不是方向或处所，与「从学校往……走」不符。", "镜子": "搭配：「镜子」不是可以前往的处所，不能作「往」的宾语。"}, "sentence_index": 6, "correct_answer": "东"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的家乡在东，冬天很冷。", "explanation": "这里应该用「东边」或「东部」。「东」单用一般不能作处所宾语，说家乡的位置要用「在东边」或「在东部」。"}, {"text": "东文化历史悠久，影响很大。", "explanation": "这里应该用「东方」。「东」不能替代「东方」作名词。"}, {"text": "我们在东见面吧。", "explanation": "这里应该用「东门」。「东」不能单独作见面的地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49ae9169-ef07-43c7-8a80-89a7fba3a92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87161, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他东往走了五分钟，就到了。", "corrected_sentence": "他往东走了五分钟，就到了。", "error_description": "位置错误：介词「往」应放在「东」之前，应说「往东走」，不能说「东往走」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49ae9169-ef07-43c7-8a80-89a7fba3a92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87161, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家东走一条街就到。", "corrected_sentence": "我家往东走一条街就到。", "error_description": "漏词错误：表示方向要用「往东」，不能直接说「东走」，应补上介词「往」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49ae9169-ef07-43c7-8a80-89a7fba3a92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
