INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87162, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "方向名，太阳升起的一边，与“西”相对。", "primary_collocate": null, "pronunciation": "dōng", "ipa": "tʊŋ˥", "syllable_count": 1, "sentences": [{"text": "东和西是相反的方向。", "target_word": "东", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河往东流，山在北边。", "target_word": "东", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他向东看，没有看到人。", "target_word": "东", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路从东通到西。", "target_word": "东", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风往东吹，船也往东走。", "target_word": "东", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我面朝南，左手是东，右手是西。", "target_word": "东", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机从西飞向东，要十个小时。", "target_word": "东", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大门朝东，后门朝西。", "target_word": "东", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他先向东走，再向北走。", "target_word": "东", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "指南针上，东在右边，西在左边。", "target_word": "东", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "东边", "label": "复合"}, {"form": "东方", "label": "复合"}, {"form": "東", "label": "繁体"}], "register": "中性", "sense_fingerprint": "东：方向名，与西相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5557fc-539b-4cb6-b9b1-8d2660c41b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87162, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "东", "is_correct": true, "explanation": "正确：东（dōng）是方向名，与「西」相对。"}, {"text": "通", "is_correct": false, "explanation": "「tōng」与「dōng」声母不同（t/d），意思是通过、通达。"}, {"text": "洞", "is_correct": false, "explanation": "「dòng」（第四声）与「dōng」（第一声）声调不同，意思是洞穴。"}, {"text": "董", "is_correct": false, "explanation": "「dǒng」（第三声）与「dōng」（第一声）声调不同，是一个姓氏。"}, {"text": "登", "is_correct": false, "explanation": "「dēng」与「dōng」韵母不同（e/o），意思是登上。"}], "explanations": {"东": "正确：东（dōng）是方向名，与「西」相对。", "通": "「tōng」与「dōng」声母不同（t/d），意思是通过、通达。", "洞": "「dòng」（第四声）与「dōng」（第一声）声调不同，意思是洞穴。", "董": "「dǒng」（第三声）与「dōng」（第一声）声调不同，是一个姓氏。", "登": "「dēng」与「dōng」韵母不同（e/o），意思是登上。"}, "sentence_index": null, "correct_answer": "东"}, "level_3": {"options": [{"text": "东", "is_correct": true, "explanation": "正确：东与西是相反的方向。"}, {"text": "南", "is_correct": false, "explanation": "语义：南与西不是相反的方向，与「相反」冲突。"}, {"text": "北", "is_correct": false, "explanation": "语义：北与西也不是相反的方向，与「相反」冲突。"}, {"text": "中", "is_correct": false, "explanation": "搭配：「中」不是方向名，不能与「西」构成相对的方向。"}], "explanations": {"东": "正确：东与西是相反的方向。", "南": "语义：南与西不是相反的方向，与「相反」冲突。", "北": "语义：北与西也不是相反的方向，与「相反」冲突。", "中": "搭配：「中」不是方向名，不能与「西」构成相对的方向。"}, "sentence_index": 0, "correct_answer": "东"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们把东搬进车里，很快就完成了。", "explanation": "这里应该用「东西」。「东」只表示方向，表示物品要说「东西」。"}, {"text": "学校的东很大，有很多学生。", "explanation": "这里应该用「东边」或「东部」。「东」单独不能指学校的一块区域，表示方位要说“东边”或“东部”。"}, {"text": "我们在东吃完饭，再去看电影吧。", "explanation": "「东」单独作处所不能这样用，表示地点要说「东边」「东门」等具体名称。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49ae9169-ef07-43c7-8a80-89a7fba3a92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87162, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "东", "is_correct": true, "explanation": "正确：东（dōng）是方向名，与「西」相对。"}, {"text": "动", "is_correct": false, "explanation": "「dòng」（第四声）与「dōng」（第一声）声调不同，意思是运动。"}, {"text": "懂", "is_correct": false, "explanation": "「dǒng」（第三声）与「dōng」（第一声）声调不同，意思是明白。"}, {"text": "灯", "is_correct": false, "explanation": "「dēng」与「dōng」韵母不同（e/o），意思是灯。"}, {"text": "冻", "is_correct": false, "explanation": "「dòng」（第四声）与「dōng」（第一声）声调不同，意思是冰冻。"}], "explanations": {"东": "正确：东（dōng）是方向名，与「西」相对。", "动": "「dòng」（第四声）与「dōng」（第一声）声调不同，意思是运动。", "懂": "「dǒng」（第三声）与「dōng」（第一声）声调不同，意思是明白。", "灯": "「dēng」与「dōng」韵母不同（e/o），意思是灯。", "冻": "「dòng」（第四声）与「dōng」（第一声）声调不同，意思是冰冻。"}, "sentence_index": null, "correct_answer": "东"}, "level_3": {"options": [{"text": "东", "is_correct": true, "explanation": "正确：「飞机从西飞向东」表示飞向与西相对的方向。"}, {"text": "狗", "is_correct": false, "explanation": "语义：狗不是方向，飞机不能飞向狗。"}, {"text": "纸", "is_correct": false, "explanation": "语义：纸不是方向，无法作飞行的终点。"}, {"text": "锅", "is_correct": false, "explanation": "搭配：「飞向」后接方向或地点，「锅」不能作终点。"}], "explanations": {"东": "正确：「飞机从西飞向东」表示飞向与西相对的方向。", "狗": "语义：狗不是方向，飞机不能飞向狗。", "纸": "语义：纸不是方向，无法作飞行的终点。", "锅": "搭配：「飞向」后接方向或地点，「锅」不能作终点。"}, "sentence_index": 6, "correct_answer": "东"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他家在东，离车站很近。", "explanation": "这里应该用「东边」。「东」单独作处所不能这样说，表示方位要用「东边」。"}, {"text": "约好在东见面，别迟到。", "explanation": "这里应该用「东门」。「东」不能单独作见面的地点。"}, {"text": "我把东放在桌子上，等会儿再拿。", "explanation": "「东」只表示方向，表示物品要说「东西」。这里把物品说成「东」，应改用「东西」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49ae9169-ef07-43c7-8a80-89a7fba3a92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87162, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她东往看，没有看到车。", "corrected_sentence": "她往东看，没有看到车。", "error_description": "位置错误：介词「往」应放在「东」之前，应说「往东看」，不能说「东往看」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49ae9169-ef07-43c7-8a80-89a7fba3a92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87162, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只鸟东往飞了。", "corrected_sentence": "那只鸟往东飞了。", "error_description": "位置错误：介词「往」应放在「东」之前，应说「往东飞」，不能说「东往飞」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49ae9169-ef07-43c7-8a80-89a7fba3a92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
