INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87163, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "愿是心里很想做一件事，也乐意去做。", "primary_collocate": null, "pronunciation": "yuàn", "ipa": "yɛn˥˩", "syllable_count": 1, "sentences": [{"text": "他不愿一个人留在家里。", "target_word": "愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我愿帮你搬家。", "target_word": "愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁愿和我一起去爬山？", "target_word": "愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明不愿吃青菜。", "target_word": "愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她愿把自己的书借给我。", "target_word": "愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都愿听老师讲故事。", "target_word": "愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟不愿早睡。", "target_word": "愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你愿不愿和我们一起去？", "target_word": "愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我愿每天跑步半小时。", "target_word": "愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很忙，不愿再多说话了。", "target_word": "愿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "愿意", "label": "复合词"}, {"form": "愿望", "label": "复合词"}, {"form": "願", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "愿：情态动词，后接动词，表示心里想做并乐意去做，常说不愿、愿不愿", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08020456-83a6-4525-94f5-4b11f7843608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87163, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "愿", "is_correct": true, "explanation": "正确答案：愿 yuàn（第四声），表示心里想做并乐意去做。"}, {"text": "远", "is_correct": false, "explanation": "远 yuǎn（第三声）与 yuàn（第四声）声调不同，意思是距离大，与“愿”不同。"}, {"text": "元", "is_correct": false, "explanation": "元 yuán（第二声）与 yuàn（第四声）声调不同，意思是货币单位或开始，与“愿”不同。"}, {"text": "冤", "is_correct": false, "explanation": "冤 yuān（第一声）与 yuàn（第四声）声调不同，意思是冤枉。"}], "explanations": {"愿": "正确答案：愿 yuàn（第四声），表示心里想做并乐意去做。", "远": "远 yuǎn（第三声）与 yuàn（第四声）声调不同，意思是距离大，与“愿”不同。", "元": "元 yuán（第二声）与 yuàn（第四声）声调不同，意思是货币单位或开始，与“愿”不同。", "冤": "冤 yuān（第一声）与 yuàn（第四声）声调不同，意思是冤枉。"}, "sentence_index": null, "correct_answer": "愿"}, "level_3": {"options": [{"text": "愿", "is_correct": true, "explanation": "正确：“不愿”表示心里不乐意做某事，符合句意。"}, {"text": "被", "is_correct": false, "explanation": "语法：“被”构成被动句，“他不被一个人留在家里”不成立。"}, {"text": "把", "is_correct": false, "explanation": "语法：“把”后要接处置对象，“他不把一个人留在家里”缺少宾语，不成立。"}, {"text": "太", "is_correct": false, "explanation": "语法：“不太”修饰形容词或心理动词，不能直接接“一个人留在家里”这样的动作。"}], "explanations": {"愿": "正确：“不愿”表示心里不乐意做某事，符合句意。", "被": "语法：“被”构成被动句，“他不被一个人留在家里”不成立。", "把": "语法：“把”后要接处置对象，“他不把一个人留在家里”缺少宾语，不成立。", "太": "语法：“不太”修饰形容词或心理动词，不能直接接“一个人留在家里”这样的动作。"}, "sentence_index": 0, "correct_answer": "愿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事愿做得很好。", "explanation": "这里应该用〈能〉。“愿”表示有意愿的人乐意做某事，主语须是人；“能”表示做得到、做得好。“这件事能做得很好”说的是事情的成效，不是主语的意愿。"}, {"text": "我愿怕黑，所以从不关灯。", "explanation": "这里应该用〈怕〉。“愿”表示乐意去做某事，不能与“怕黑”这类心理状态搭配；“怕”表示害怕，说“我怕黑”才符合说法。"}, {"text": "他愿发烧。", "explanation": "这里应该用〈会〉。“愿”表示乐意去做某事，不能用于身体自然发生的事；“会”表示有可能发生，应说“他会发烧”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87163, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "愿", "is_correct": true, "explanation": "正确：“不愿”表示心里不乐意早睡，符合句意。"}, {"text": "的", "is_correct": false, "explanation": "语法：“的”是结构助词，不能放在“不”和动词之间，“弟弟不的早睡”不成立。"}, {"text": "了", "is_correct": false, "explanation": "语法：“了”是助词，不能直接跟在“不”后面再接动词，“弟弟不了早睡”不成立。"}, {"text": "从", "is_correct": false, "explanation": "语法：“从”是介词，要接起点，“弟弟不从早睡”不成立。"}], "explanations": {"愿": "正确：“不愿”表示心里不乐意早睡，符合句意。", "的": "语法：“的”是结构助词，不能放在“不”和动词之间，“弟弟不的早睡”不成立。", "了": "语法：“了”是助词，不能直接跟在“不”后面再接动词，“弟弟不了早睡”不成立。", "从": "语法：“从”是介词，要接起点，“弟弟不从早睡”不成立。"}, "sentence_index": 6, "correct_answer": "愿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我愿被雨淋湿，连忙打开了伞。", "explanation": "这里应该用〈不想〉。“愿”表示乐意去做，但“连忙打开了伞”说明我并不乐意淋雨，应说“我不想被雨淋湿”。"}, {"text": "这台机器愿自己洗衣服。", "explanation": "这里应该用〈能〉。“愿”的主语须是有意愿的人，机器没有意愿；表示做得到应说“这台机器能自己洗衣服”。"}, {"text": "他愿突然晕倒。", "explanation": "这里应该用〈会〉。“愿”表示乐意去做，而晕倒不是人能主动选择的事；表示可能发生应说“他会突然晕倒”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87163, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我愿了陪你去医院。", "corrected_sentence": "我愿陪你去医院。", "error_description": "错误：“愿”后面加了“了”。“愿”是情态动词，不能带“了”，应去掉“了”，改为“我愿陪你去医院”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87163, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈愿过为我们做饭。", "corrected_sentence": "妈妈愿为我们做饭。", "error_description": "错误：“愿”后面加了“过”。“愿”是情态动词，不能带“过”表示经历，应去掉“过”，改为“妈妈愿为我们做饭”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
