INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87164, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "希望；多用于祝愿，表示对他人或事情的美好期望。", "primary_collocate": null, "pronunciation": "yuàn", "ipa": "yɛn˥˩", "syllable_count": 1, "sentences": [{"text": "愿你每天都快乐。", "target_word": "愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "愿大家身体健康。", "target_word": "愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新年到了，愿你工作顺利。", "target_word": "愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "愿我们的友谊长久。", "target_word": "愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "愿天下的孩子都有书读。", "target_word": "愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生日快乐，愿你的梦想成真。", "target_word": "愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "愿世界和平。", "target_word": "愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "愿你考试顺利。", "target_word": "愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "愿老人们健康长寿。", "target_word": "愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "愿明天天气好。", "target_word": "愿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "愿意", "label": "复合词"}, {"form": "愿望", "label": "复合词"}, {"form": "願", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "愿：希望，常用于祝愿，句首“愿＋你／大家＋愿望内容”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08020456-83a6-4525-94f5-4b11f7843608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87164, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "愿", "is_correct": true, "explanation": "正确答案：愿 yuàn（第四声），表示希望，用于祝愿。"}, {"text": "远", "is_correct": false, "explanation": "远 yuǎn（第三声）与 yuàn（第四声）声调不同，意思是距离大，与“愿”不同。"}, {"text": "原", "is_correct": false, "explanation": "原 yuán（第二声）与 yuàn（第四声）声调不同，意思是原本、原来，与“愿”不同。"}, {"text": "冤", "is_correct": false, "explanation": "冤 yuān（第一声）与 yuàn（第四声）声调不同，意思是冤枉，与“愿”不同。"}], "explanations": {"愿": "正确答案：愿 yuàn（第四声），表示希望，用于祝愿。", "远": "远 yuǎn（第三声）与 yuàn（第四声）声调不同，意思是距离大，与“愿”不同。", "原": "原 yuán（第二声）与 yuàn（第四声）声调不同，意思是原本、原来，与“愿”不同。", "冤": "冤 yuān（第一声）与 yuàn（第四声）声调不同，意思是冤枉，与“愿”不同。"}, "sentence_index": null, "correct_answer": "愿"}, "level_3": {"options": [{"text": "愿", "is_correct": true, "explanation": "正确：句首“愿”用于美好的祝愿，“愿你每天都快乐”符合句意。"}, {"text": "得", "is_correct": false, "explanation": "语法：“得”作补语标记，不能单独位于句首，“得你每天都快乐”不成立。"}, {"text": "把", "is_correct": false, "explanation": "语法：“把”字句须有处置对象和动词，“把你每天都快乐”不成立。"}, {"text": "被", "is_correct": false, "explanation": "语法：“被”后要接施事和动词，“被你每天都快乐”不成立。"}], "explanations": {"愿": "正确：句首“愿”用于美好的祝愿，“愿你每天都快乐”符合句意。", "得": "语法：“得”作补语标记，不能单独位于句首，“得你每天都快乐”不成立。", "把": "语法：“把”字句须有处置对象和动词，“把你每天都快乐”不成立。", "被": "语法：“被”后要接施事和动词，“被你每天都快乐”不成立。"}, "sentence_index": 0, "correct_answer": "愿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他愿昨天就下雨。", "explanation": "这里应该用〈要是〉。“愿”表示对未来或他人的祝愿，不用于已经发生的过去；表示假设应说“要是昨天就下雨就好了”。"}, {"text": "愿你的病越来越重。", "explanation": "这里应该用〈怕〉。“愿”用于美好的祝愿，不能祝别人病重；表示担忧应说“怕你的病越来越重”。"}, {"text": "愿你昨天玩得开心。", "explanation": "这里应该用〈希望〉。“愿”的祝愿指向将来，不用于已经过去的事；应说“希望你昨天玩得开心”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87164, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "愿", "is_correct": true, "explanation": "正确：“愿世界和平”是对世界的美好祝愿，符合句意。"}, {"text": "了", "is_correct": false, "explanation": "语法：“了”是助词，不能位于句首，“了世界和平”不成句。"}, {"text": "很", "is_correct": false, "explanation": "语法：“很”是副词，修饰形容词或动词，不能放在名词“世界”前，“很世界和平”不成立。"}, {"text": "吗", "is_correct": false, "explanation": "语法：“吗”是句末疑问语气词，不能位于句首，“吗世界和平”不成立。"}], "explanations": {"愿": "正确：“愿世界和平”是对世界的美好祝愿，符合句意。", "了": "语法：“了”是助词，不能位于句首，“了世界和平”不成句。", "很": "语法：“很”是副词，修饰形容词或动词，不能放在名词“世界”前，“很世界和平”不成立。", "吗": "语法：“吗”是句末疑问语气词，不能位于句首，“吗世界和平”不成立。"}, "sentence_index": 6, "correct_answer": "愿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "愿你下次考试不及格。", "explanation": "这里应该用〈担心〉。“愿”表达美好祝愿，不能用于坏事；应说“担心你下次考试不及格”。"}, {"text": "愿明天下大暴雨，把房子冲倒。", "explanation": "这里应该用〈怕〉。“愿”只接美好的期望，房子被冲倒是坏事；应说“怕明天下大暴雨”。"}, {"text": "愿你永远找不到工作。", "explanation": "这里应该用〈担心〉。“愿”用于祝福，不能接不好的结果；应说“担心你找不到工作”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87164, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "愿着你们幸福快乐。", "corrected_sentence": "愿你们幸福快乐。", "error_description": "错误：“愿”后面加了“着”。祝愿句中“愿”后直接接祝福内容，不能加“着”，应说“愿你们幸福快乐”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87164, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "愿过你们早日康复。", "corrected_sentence": "愿你们早日康复。", "error_description": "错误：“愿”后面加了“过”。“愿”表示希望，不能带“过”表示经历，应去掉“过”，改为“愿你们早日康复”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
