INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87166, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指一年之内，常指今年剩下的时间。", "primary_collocate": null, "pronunciation": "nián nèi", "ipa": "njɛn³⁵ nei⁵¹", "syllable_count": 2, "sentences": [{"text": "这个项目年内可以完成。", "target_word": "年内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想年内把车买好。", "target_word": "年内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说年内一定还钱。", "target_word": "年内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年内我们打算去一次日本。", "target_word": "年内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新地铁年内就能开通。", "target_word": "年内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年内公司还要招十个人。", "target_word": "年内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你年内能把这本书读完吗？", "target_word": "年内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说年内还有一次考试。", "target_word": "年内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们年内要搬到新家。", "target_word": "年内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年内房子能卖出去吗？", "target_word": "年内", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "今年剩下的时间，多用于计划、期限", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e2e0b30-a3a1-4ae4-9be1-ab2c143552df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87166, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年内", "is_correct": true, "explanation": "正确：“年内”指今年剩下的时间，与“可以完成”的计划语境相合。"}, {"text": "去年", "is_correct": false, "explanation": "语义：“去年”是已经过去的时间，与“可以完成”的计划语义相冲突。"}, {"text": "昨天", "is_correct": false, "explanation": "语义：“昨天”是已经过去的时间，与“可以完成”的计划语义相冲突。"}, {"text": "每天", "is_correct": false, "explanation": "搭配：“每天”表示每日重复，不符合一个项目一次完成的说法。"}], "explanations": {"年内": "正确：“年内”指今年剩下的时间，与“可以完成”的计划语境相合。", "去年": "语义：“去年”是已经过去的时间，与“可以完成”的计划语义相冲突。", "昨天": "语义：“昨天”是已经过去的时间，与“可以完成”的计划语义相冲突。", "每天": "搭配：“每天”表示每日重复，不符合一个项目一次完成的说法。"}, "sentence_index": 0, "correct_answer": "年内"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "年内十点我们在机场见面。", "explanation": "这里应该用〈当天〉。“年内”指一段时间，不能与“十点”这样的钟点连用，把时段当成时点就错了。"}, {"text": "他年内七岁了。", "explanation": "这里应该用〈今年〉。说年龄要用“今年”，“年内”指今年剩下的一段时间，不能说年龄。"}, {"text": "这棵树的年内很大了。", "explanation": "这里应该用〈树龄〉。“树龄”指树的年数，“年内”指一年之内，不能用来表示树的年纪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c04a5e88-a9db-40ab-b6be-305f6e0ac38a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87166, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年内", "is_correct": true, "explanation": "正确：“年内”指今年剩下的时间，与“能把这本书读完吗”的计划询问相合。"}, {"text": "上周", "is_correct": false, "explanation": "语义：“上周”是已经过去的时间，与“能……吗”的未来可能性相冲突。"}, {"text": "刚才", "is_correct": false, "explanation": "语义：“刚才”是刚过去的时间，与“能……吗”的未来可能性相冲突。"}, {"text": "去年", "is_correct": false, "explanation": "语义：“去年”是已经过去的时间，与“能……吗”询问未来可能性相冲突。"}], "explanations": {"年内": "正确：“年内”指今年剩下的时间，与“能把这本书读完吗”的计划询问相合。", "上周": "语义：“上周”是已经过去的时间，与“能……吗”的未来可能性相冲突。", "刚才": "语义：“刚才”是刚过去的时间，与“能……吗”的未来可能性相冲突。", "去年": "语义：“去年”是已经过去的时间，与“能……吗”询问未来可能性相冲突。"}, "sentence_index": 6, "correct_answer": "年内"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "年内上午房子能卖出去吗？", "explanation": "这里应该用〈今天上午〉。“年内”指一段时间，不能与“上午”这样的时段搭配，两者时间范围不同。"}, {"text": "年内一秒房子就能卖出去吗？", "explanation": "这里应该用〈很快〉。“年内”是一年的时间，不能指一秒这样极短的时刻。"}, {"text": "年内三天前房子就卖出去了吗？", "explanation": "这里应该用〈前几天〉。“年内”指一段时间，不能与“三天前”这样的具体时点搭配，表示某个过去时点要用〈前几天〉这类词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c04a5e88-a9db-40ab-b6be-305f6e0ac38a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87166, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "年内我们要把这个项目做完年内。", "corrected_sentence": "年内我们要把这个项目做完。", "error_description": "错误在于句末多出的「年内」。句首的「年内」已是时间状语，句末「做完年内」不通，应删去句末的「年内」，说「年内我们要把这个项目做完」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c04a5e88-a9db-40ab-b6be-305f6e0ac38a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87166, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们年内以前要把新家装修好。", "corrected_sentence": "我们年内要把新家装修好。", "error_description": "错误在于「以前」。「年内」本身已表示今年之内的期限，后面不能再加「以前」，应去掉「以前」，说「我们年内要把新家装修好」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c04a5e88-a9db-40ab-b6be-305f6e0ac38a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87167, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "收款", "is_correct": true, "explanation": "收款与付款方向相反：付款是把钱交给对方，收款是收到对方的钱。"}, {"text": "唱歌", "is_correct": false, "explanation": "唱歌与付款的词义没有对立关系，不构成反义词。"}, {"text": "散步", "is_correct": false, "explanation": "散步与付款词义无关，不能构成反义关系。"}, {"text": "写字", "is_correct": false, "explanation": "写字与付款词义无关，不能构成反义关系。"}], "correct_answer": "收款", "explanations": {"收款": "收款与付款方向相反：付款是把钱交给对方，收款是收到对方的钱。", "唱歌": "唱歌与付款的词义没有对立关系，不构成反义词。", "散步": "散步与付款词义无关，不能构成反义关系。", "写字": "写字与付款词义无关，不能构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cb825-c0b4-48bd-9283-9eddacabb02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87167, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "收款", "is_correct": true, "explanation": "收款与付款方向相反：付款是把钱交给对方，收款是收到对方的钱。"}, {"text": "下棋", "is_correct": false, "explanation": "下棋与付款的词义没有对立关系，不构成反义词。"}, {"text": "画画", "is_correct": false, "explanation": "画画与付款词义无关，不能构成反义关系。"}, {"text": "游泳", "is_correct": false, "explanation": "游泳与付款词义无关，不能构成反义关系。"}], "correct_answer": "收款", "explanations": {"收款": "收款与付款方向相反：付款是把钱交给对方，收款是收到对方的钱。", "下棋": "下棋与付款的词义没有对立关系，不构成反义词。", "画画": "画画与付款词义无关，不能构成反义关系。", "游泳": "游泳与付款词义无关，不能构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cb825-c0b4-48bd-9283-9eddacabb02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87167, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "付款是把钱给别人，买下东西。", "primary_collocate": null, "pronunciation": "fù kuǎn", "ipa": "fu˥˩ kʰuan˨˩", "syllable_count": 2, "sentences": [{"text": "我在网上买了鞋，已经付款了。", "target_word": "付款", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你可以用手机付款。", "target_word": "付款", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请在收银台付款。", "target_word": "付款", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他看了看价格，马上付款了。", "target_word": "付款", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商店里可以现金付款，也可以刷卡。", "target_word": "付款", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "付款以后，店员给了我一个袋子。", "target_word": "付款", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书太贵，我不想付款。", "target_word": "付款", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她拿着东西去前面付款。", "target_word": "付款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在超市付款时发现没带钱包。", "target_word": "付款", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友帮我付款，我回家还他钱。", "target_word": "付款", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "付了款", "label": "体标"}, {"form": "付款人", "label": "复合"}, {"form": "付款方式", "label": "复合"}], "register": "中性", "sense_fingerprint": "买东西时把钱交给卖的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '157552df-a86f-4558-b9ec-500c2d87da0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87167, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "付款", "is_correct": true, "explanation": "付款指买东西后把钱交给卖家，与“我在网上买了鞋”的语境相符。"}, {"text": "开学", "is_correct": false, "explanation": "语义：开学与在网上买鞋无关，句意不通。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：毕业是完成学业，与在网上买鞋无关，句意不通。"}, {"text": "上架", "is_correct": false, "explanation": "语义：上架是商家把商品放上货架，与买家买鞋的行为无关。"}], "explanations": {"付款": "付款指买东西后把钱交给卖家，与“我在网上买了鞋”的语境相符。", "开学": "语义：开学与在网上买鞋无关，句意不通。", "毕业": "语义：毕业是完成学业，与在网上买鞋无关，句意不通。", "上架": "语义：上架是商家把商品放上货架，与买家买鞋的行为无关。"}, "sentence_index": 0, "correct_answer": "付款"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他为了这个项目，付款了很多心血。", "explanation": "这里应该用〈付出〉。付款的对象只能是钱款，不能说“付款心血”；付出可以带心血、努力等抽象对象。"}, {"text": "饭吃完了，服务员过来付款。", "explanation": "这里应该用〈收款〉。付款是把钱交给对方，服务员收钱要说收款，两者方向正好相反。"}, {"text": "他打碎了邻居的玻璃，要付款损失。", "explanation": "这里应该用〈赔偿〉。付款只用于交付应付的钱款，不能说“付款损失”；对损失进行补偿要说赔偿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cb825-c0b4-48bd-9283-9eddacabb02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87167, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "付款", "is_correct": true, "explanation": "付款是买下东西时交钱，与“这本书太贵”的语境相符。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：翻译与书的价格无关，“太贵”不是不去翻译的理由。"}, {"text": "出版", "is_correct": false, "explanation": "语义：出版是书的出版环节，与“太贵”这一语境不搭。"}, {"text": "装订", "is_correct": false, "explanation": "搭配：“装订”指书的加工工序，不搭配“太贵”这类价格评价。"}], "explanations": {"付款": "付款是买下东西时交钱，与“这本书太贵”的语境相符。", "翻译": "语义：翻译与书的价格无关，“太贵”不是不去翻译的理由。", "出版": "语义：出版是书的出版环节，与“太贵”这一语境不搭。", "装订": "搭配：“装订”指书的加工工序，不搭配“太贵”这类价格评价。"}, "sentence_index": 6, "correct_answer": "付款"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她把全部时间付款到工作中。", "explanation": "这里应该用〈投入〉。付款的对象只能是钱款，不能说“付款时间”；投入可以用于时间、精力。"}, {"text": "照顾孩子付款了很多精力。", "explanation": "这里应该用〈花费〉。付款用于钱款，精力是“花费”的对象，不能说“付款精力”。"}, {"text": "我一直想付款老师的恩情。", "explanation": "这里应该用〈报答〉。付款是交付钱款，恩情要用报答来回馈，不能说“付款恩情”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cb825-c0b4-48bd-9283-9eddacabb02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87167, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天已经付款房东了。", "corrected_sentence": "我昨天已经付款给房东了。", "error_description": "“付款”后面引进收款人时要用“给”，说“付款房东”是错的，应说“付款给房东”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cb825-c0b4-48bd-9283-9eddacabb02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87167, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我已经付款钱了，你可以走了。", "corrected_sentence": "我已经付款了，你可以走了。", "error_description": "“付款”的宾语已经是“款”，后面不能再加“钱”，应说“我已经付款了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cb825-c0b4-48bd-9283-9eddacabb02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87168, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "收款", "is_correct": true, "explanation": "收款与付款方向相反：付款是把钱交给对方，收款是收到对方的钱。"}, {"text": "跳舞", "is_correct": false, "explanation": "跳舞与付款的词义没有对立关系，不构成反义词。"}, {"text": "睡觉", "is_correct": false, "explanation": "睡觉与付款词义无关，不能构成反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "散步与付款词义无关，不能构成反义关系。"}], "correct_answer": "收款", "explanations": {"收款": "收款与付款方向相反：付款是把钱交给对方，收款是收到对方的钱。", "跳舞": "跳舞与付款的词义没有对立关系，不构成反义词。", "睡觉": "睡觉与付款词义无关，不能构成反义关系。", "散步": "散步与付款词义无关，不能构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cb825-c0b4-48bd-9283-9eddacabb02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87168, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "收款", "is_correct": true, "explanation": "收款与付款方向相反：付款是把钱交给对方，收款是收到对方的钱。"}, {"text": "下棋", "is_correct": false, "explanation": "下棋与付款的词义没有对立关系，不构成反义词。"}, {"text": "画画", "is_correct": false, "explanation": "画画与付款词义无关，不能构成反义关系。"}, {"text": "游泳", "is_correct": false, "explanation": "游泳与付款词义无关，不能构成反义关系。"}], "correct_answer": "收款", "explanations": {"收款": "收款与付款方向相反：付款是把钱交给对方，收款是收到对方的钱。", "下棋": "下棋与付款的词义没有对立关系，不构成反义词。", "画画": "画画与付款词义无关，不能构成反义关系。", "游泳": "游泳与付款词义无关，不能构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cb825-c0b4-48bd-9283-9eddacabb02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87168, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把应付的钱交给对方。", "primary_collocate": null, "pronunciation": "fù kuǎn", "ipa": "fu˥˩ kʰuan˨˩", "syllable_count": 2, "sentences": [{"text": "客人收到货以后再付款。", "target_word": "付款", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公司要在月底前付款。", "target_word": "付款", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老板问我们什么时候付款。", "target_word": "付款", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们已经把货送到了，请尽快付款。", "target_word": "付款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买家付款后，卖家才会发货。", "target_word": "付款", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没有按时付款，老板很生气。", "target_word": "付款", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这批货请你三天内付款。", "target_word": "付款", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "合同上写着，付款要在收货后十天内。", "target_word": "付款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们公司一直很晚付款。", "target_word": "付款", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "对方付款以后，我们就开始工作。", "target_word": "付款", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "付了款", "label": "体标"}, {"form": "付款人", "label": "复合"}, {"form": "付款方式", "label": "复合"}], "register": "中性", "sense_fingerprint": "按约定把该给的钱交给对方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '157552df-a86f-4558-b9ec-500c2d87da0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87168, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "付款", "is_correct": true, "explanation": "付款是按约定把钱交给对方，客人收到货之后付款，与句意吻合。"}, {"text": "生产", "is_correct": false, "explanation": "语义：货已经收到，不能再去生产，“生产”与“收到货以后”的顺序矛盾。"}, {"text": "报价", "is_correct": false, "explanation": "语义：报价发生在收货之前，与“收到货以后”的时间顺序矛盾。"}, {"text": "进货", "is_correct": false, "explanation": "搭配：“进货”的主体是商家，不能说客人进货。"}], "explanations": {"付款": "付款是按约定把钱交给对方，客人收到货之后付款，与句意吻合。", "生产": "语义：货已经收到，不能再去生产，“生产”与“收到货以后”的顺序矛盾。", "报价": "语义：报价发生在收货之前，与“收到货以后”的时间顺序矛盾。", "进货": "搭配：“进货”的主体是商家，不能说客人进货。"}, "sentence_index": 0, "correct_answer": "付款"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他为了这次比赛，付款了很多汗水。", "explanation": "这里应该用〈付出〉。付款的对象只能是钱款，不能说“付款汗水”；付出可以带汗水、努力等抽象对象。"}, {"text": "他每天都付款很多时间陪孩子。", "explanation": "这里应该用〈花〉。付款的对象只能是钱款，不能说“付款时间”；陪孩子的时间要说“花时间”。"}, {"text": "他对朋友付款了真诚的感谢。", "explanation": "这里应该用〈表示〉。付款的对象只能是钱款，不能说“付款感谢”；向别人表示感谢要说表示。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cb825-c0b4-48bd-9283-9eddacabb02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87168, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "付款", "is_correct": true, "explanation": "付款是按约定把钱交给对方，“三天内付款”是合同或约定中的常见说法。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌与这批货的交付和结算无关，句意不成立。"}, {"text": "散步", "is_correct": false, "explanation": "语义：散步与这批货的结算无关，不能用于此处。"}, {"text": "浇水", "is_correct": false, "explanation": "搭配：“浇水”的对象是植物，不搭配“这批货”。"}], "explanations": {"付款": "付款是按约定把钱交给对方，“三天内付款”是合同或约定中的常见说法。", "唱歌": "语义：唱歌与这批货的交付和结算无关，句意不成立。", "散步": "语义：散步与这批货的结算无关，不能用于此处。", "浇水": "搭配：“浇水”的对象是植物，不搭配“这批货”。"}, "sentence_index": 6, "correct_answer": "付款"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他搬这批货付款了很多力气。", "explanation": "这里应该用〈花〉。付款的对象只能是钱款，不能说“付款力气”；用了力气要说“花了很多力气”。"}, {"text": "学校每学期都要付款学费。", "explanation": "这里应该用〈收〉。学费是学校收的钱，付款是交出钱，两者方向相反，应说学校收学费。"}, {"text": "他把别人的车撞坏了，要付款对方的损失。", "explanation": "这里应该用〈赔偿〉。付款只用于交付应付的钱款，对损失进行补偿要说赔偿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cb825-c0b4-48bd-9283-9eddacabb02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87168, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "客人收到货以后，就付款着。", "corrected_sentence": "客人收到货以后，就付款。", "error_description": "错误：“付款”是一次性的动作，不能加“着”表示持续，应说“就付款”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cb825-c0b4-48bd-9283-9eddacabb02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87168, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这批货请你尽快付款过。", "corrected_sentence": "这批货请你尽快付款。", "error_description": "错误：请对方“尽快付款”是请求将来的动作，不能加“过”表示已经发生过的经历，应去掉“过”，说“尽快付款”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cb825-c0b4-48bd-9283-9eddacabb02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
