INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87169, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "机场是飞机起飞和停下来的地方。", "primary_collocate": null, "pronunciation": "jī chǎng", "ipa": "tɕi˥ ʈʂʰaŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们坐出租车去机场。", "target_word": "机场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机场离我家不太远。", "target_word": "机场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在机场等了两个小时。", "target_word": "机场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机场里有很多人。", "target_word": "机场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈明天到机场接我。", "target_word": "机场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个机场有一个大商店。", "target_word": "机场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机已经到机场了。", "target_word": "机场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的城市新建了一座机场。", "target_word": "机场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在机场买东西很贵。", "target_word": "机场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机场的椅子上坐满了人。", "target_word": "机场", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "国际机场", "label": "复合"}, {"form": "機場", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词；飞机起飞和降落停放的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed471b59-6733-4165-85bc-54587c636e4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87169, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "机场", "is_correct": true, "explanation": "正确答案是「机场」（jī chǎng），指飞机起降和停放的地方。"}, {"text": "几场", "is_correct": false, "explanation": "jǐ（第三声）与 jī（第一声）声调不同，意思是「几场」（几场比赛）。"}, {"text": "机长", "is_correct": false, "explanation": "zhǎng 与 chǎng 声母不同（zh 与 ch），意思是「机长」（飞机的驾驶员）。"}, {"text": "鸡肠", "is_correct": false, "explanation": "cháng（第二声）与 chǎng（第三声）声调不同，意思是「鸡肠」（鸡的肠子）。"}], "explanations": {"机场": "正确答案是「机场」（jī chǎng），指飞机起降和停放的地方。", "几场": "jǐ（第三声）与 jī（第一声）声调不同，意思是「几场」（几场比赛）。", "机长": "zhǎng 与 chǎng 声母不同（zh 与 ch），意思是「机长」（飞机的驾驶员）。", "鸡肠": "cháng（第二声）与 chǎng（第三声）声调不同，意思是「鸡肠」（鸡的肠子）。"}, "sentence_index": null, "correct_answer": "机场"}, "level_3": {"options": [{"text": "机场", "is_correct": true, "explanation": "「机场」是可以「去」的地方，与「坐出租车去」相合。"}, {"text": "飞机", "is_correct": false, "explanation": "语义：「飞机」是交通工具，不是可以前往的地点，「坐出租车去飞机」不通。"}, {"text": "护照", "is_correct": false, "explanation": "搭配：「去」后面要接场所，「护照」是证件，不能作目的地。"}, {"text": "行李", "is_correct": false, "explanation": "语义：「行李」指随身携带的物品，不是地点，「去行李」不通。"}], "explanations": {"机场": "「机场」是可以「去」的地方，与「坐出租车去」相合。", "飞机": "语义：「飞机」是交通工具，不是可以前往的地点，「坐出租车去飞机」不通。", "护照": "搭配：「去」后面要接场所，「护照」是证件，不能作目的地。", "行李": "语义：「行李」指随身携带的物品，不是地点，「去行李」不通。"}, "sentence_index": 0, "correct_answer": "机场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在机场的校园里散步。", "explanation": "这里应该用〈学校〉。机场没有校园，校园是学校的场所，不能用于机场。"}, {"text": "机场里停满了船。", "explanation": "这里应该用〈港口〉。船应停在港口或码头；机场停放的是飞机。"}, {"text": "我把机场放在包里了。", "explanation": "这里应该用〈护照〉。机场是一个很大的地方，不能放进包里；能放进包里的是护照这样的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1457f693-2d6a-41c0-9c05-14b6511666e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87169, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "机场", "is_correct": true, "explanation": "「机场」是飞机到达的地点，与「飞机已经到……了」相合。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：「乘客」指乘坐交通工具的人，不是飞机可以到达的地点，「飞机已经到乘客了」不通。"}, {"text": "车票", "is_correct": false, "explanation": "搭配：「到」后面要接地点，「车票」是凭证，不能作到达的终点。"}, {"text": "早餐", "is_correct": false, "explanation": "语义：「早餐」指一顿饭，不是飞机能到达的地方，句意不通。"}], "explanations": {"机场": "「机场」是飞机到达的地点，与「飞机已经到……了」相合。", "乘客": "语义：「乘客」指乘坐交通工具的人，不是飞机可以到达的地点，「飞机已经到乘客了」不通。", "车票": "搭配：「到」后面要接地点，「车票」是凭证，不能作到达的终点。", "早餐": "语义：「早餐」指一顿饭，不是飞机能到达的地方，句意不通。"}, "sentence_index": 6, "correct_answer": "机场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们坐机场去北京。", "explanation": "这里应该用〈飞机〉。机场是地点，不是交通工具；去北京要坐的是飞机。"}, {"text": "他在机场的教室里做作业。", "explanation": "这里应该用〈学校〉。机场里没有教室，做作业要在学校或家里。"}, {"text": "他感冒了，去机场挂号。", "explanation": "这里应该用〈医院〉。挂号要在医院办理，机场不办挂号。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1457f693-2d6a-41c0-9c05-14b6511666e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87169, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座城市最近新建了一条机场。", "corrected_sentence": "这座城市最近新建了一座机场。", "error_description": "量词错误。机场应使用量词「座」，「一条机场」中的「条」不对，应说「一座机场」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1457f693-2d6a-41c0-9c05-14b6511666e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87169, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们机场等了一个多小时。", "corrected_sentence": "我们在机场等了一个多小时。", "error_description": "介词「在」漏掉。表示动作发生的处所要用「在」引出，「我们机场等了一个多小时」应说「我们在机场等了一个多小时」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1457f693-2d6a-41c0-9c05-14b6511666e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
