INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87171, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87171, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示目前的状态只是一时的，以后会改变。", "primary_collocate": null, "pronunciation": "zàn shí", "ipa": "tsan˥˩ ʂɨ˧˥", "syllable_count": 2, "sentences": [{"text": "我暂时住在朋友家，下个月就搬走。", "target_word": "暂时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路暂时不能走，下周会修好。", "target_word": "暂时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的病暂时好了，但还要吃药。", "target_word": "暂时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司暂时没有空位，以后可能会有。", "target_word": "暂时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我暂时不想换工作，以后再说。", "target_word": "暂时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子暂时由奶奶照顾，妈妈出差回来就接走。", "target_word": "暂时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨暂时停了，不过晚上还会下。", "target_word": "暂时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店暂时关门，下个月重新开业。", "target_word": "暂时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "暂时先用这个电话，新的明天才到。", "target_word": "暂时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我暂时不回国，明年再决定。", "target_word": "暂时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "暫時", "label": "繁体"}, {"form": "暂时性", "label": "复合"}], "register": "通用", "sense_fingerprint": "表示目前的状态只是一时的，以后会改变", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08020456-83a6-4525-94f5-4b11f7843608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87171, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "暂时", "is_correct": true, "explanation": "正确。「我暂时住在朋友家，下个月就搬走」说的是目前的短期状态，之后会改变。"}, {"text": "永远", "is_correct": false, "explanation": "语义：「永远」表示长久不变，与后半句「下个月就搬走」矛盾。"}, {"text": "始终", "is_correct": false, "explanation": "语义：「始终」表示从头到尾都不变，与「下个月就搬走」矛盾。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：「从来」通常与否定词或表示经历的语境连用，不能直接修饰「住」来说当前状态。"}], "explanations": {"暂时": "正确。「我暂时住在朋友家，下个月就搬走」说的是目前的短期状态，之后会改变。", "永远": "语义：「永远」表示长久不变，与后半句「下个月就搬走」矛盾。", "始终": "语义：「始终」表示从头到尾都不变，与「下个月就搬走」矛盾。", "从来": "搭配：「从来」通常与否定词或表示经历的语境连用，不能直接修饰「住」来说当前状态。"}, "sentence_index": 0, "correct_answer": "暂时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "太阳暂时从东方升起。", "explanation": "这里不该用〈暂时〉。〈暂时〉说的是会改变的状态，太阳每天从东方升起是长期规律，应去掉〈暂时〉。"}, {"text": "这座桥暂时建于唐朝。", "explanation": "这里不该用〈暂时〉。〈建于唐朝〉是已经发生、不会再变的历史事实，不能用〈暂时〉限定。"}, {"text": "我暂时出生在北京。", "explanation": "这里不该用〈暂时〉。〈出生〉是一次性、不可逆的事件，出生地不会因「以后会变」而改变。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87171, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "暂时", "is_correct": true, "explanation": "正确。「雨暂时停了，不过晚上还会下」说停止只是暂时的，之后还会下。"}, {"text": "彻底", "is_correct": false, "explanation": "语义：「彻底」表示完全结束，与后半句「晚上还会下」矛盾。"}, {"text": "一直", "is_correct": false, "explanation": "搭配：「一直」表示持续不断，不能与表示变化已完成的「停了」搭配。"}, {"text": "总是", "is_correct": false, "explanation": "搭配：「总是」表示习惯性反复，不能修饰「停了」这种一次性变化。"}], "explanations": {"暂时": "正确。「雨暂时停了，不过晚上还会下」说停止只是暂时的，之后还会下。", "彻底": "语义：「彻底」表示完全结束，与后半句「晚上还会下」矛盾。", "一直": "搭配：「一直」表示持续不断，不能与表示变化已完成的「停了」搭配。", "总是": "搭配：「总是」表示习惯性反复，不能修饰「停了」这种一次性变化。"}, "sentence_index": 6, "correct_answer": "暂时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们暂时永远是朋友。", "explanation": "这里不该用〈暂时〉。〈暂时〉指以后会改变的状态，而这里要表达的是永久不变的关系，应去掉〈暂时〉。"}, {"text": "这所学校暂时办了五十年。", "explanation": "这里不该用〈暂时〉。〈暂时〉指很短的一段时间，不能用来说长期持续的办学，应去掉〈暂时〉。"}, {"text": "这份合同暂时写明永久有效。", "explanation": "这里不该用〈暂时〉。〈暂时〉指以后会改变，而合同要表达的是长久不变的约定，应去掉〈暂时〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87171, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条船很暂时停在码头，等风小了再开。", "corrected_sentence": "这条船暂时停在码头，等风小了再开。", "error_description": "错误：“很”放在了“暂时”前面。“暂时”是副词，不能被程度副词“很”修饰，应删去“很”，说“这条船暂时停在码头”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87171, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份工作暂时的由我负责，下个月换人。", "corrected_sentence": "这份工作暂时由我负责，下个月换人。", "error_description": "错误：「暂时」后多了「的」。此处「暂时」是修饰「由我负责」的状语，中间不能加「的」，应删去「的」，说「这份工作暂时由我负责」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
