INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87172, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示短时间内；时间不长。", "primary_collocate": null, "pronunciation": "zàn shí", "ipa": "tsan˥˩ ʂɨ˧˥", "syllable_count": 2, "sentences": [{"text": "你暂时坐在这儿等一下，医生马上来。", "target_word": "暂时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "暂时把手机放在桌上，等会儿再玩。", "target_word": "暂时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议暂时停一下，大家先休息十分钟。", "target_word": "暂时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请暂时不要出门，外面雨太大。", "target_word": "暂时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他暂时离开了房间，很快就回来。", "target_word": "暂时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我暂时出去一下，五分钟就回来。", "target_word": "暂时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些钱暂时够用，下个月还要再存。", "target_word": "暂时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师暂时不在，请你十分钟后再来。", "target_word": "暂时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我暂时借用你的笔，写完就还你。", "target_word": "暂时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络暂时不好，请稍等一会儿。", "target_word": "暂时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "暫時", "label": "繁体"}, {"form": "暂时性", "label": "复合"}], "register": "通用", "sense_fingerprint": "表示在短时间内先这样做，时间不长", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08020456-83a6-4525-94f5-4b11f7843608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87172, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "暂时", "is_correct": true, "explanation": "正确。「你暂时坐在这儿等一下，医生马上来」说的是先等一会儿，时间很短。"}, {"text": "永远", "is_correct": false, "explanation": "语义：「永远」表示长久不变，与「等一下」和「医生马上来」矛盾。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：「从来」须与否定词或经历语境连用，不能修饰「坐」这种即时动作。"}, {"text": "彻底", "is_correct": false, "explanation": "搭配：「彻底」修饰的是结束或改变，不能修饰「坐在这儿等」。"}], "explanations": {"暂时": "正确。「你暂时坐在这儿等一下，医生马上来」说的是先等一会儿，时间很短。", "永远": "语义：「永远」表示长久不变，与「等一下」和「医生马上来」矛盾。", "从来": "搭配：「从来」须与否定词或经历语境连用，不能修饰「坐」这种即时动作。", "彻底": "搭配：「彻底」修饰的是结束或改变，不能修饰「坐在这儿等」。"}, "sentence_index": 0, "correct_answer": "暂时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我暂时在北京住了三十年。", "explanation": "这里不该用〈暂时〉。〈暂时〉指短时间内，不能用来说长期居住，应去掉〈暂时〉。"}, {"text": "他暂时毕业于北京大学。", "explanation": "这里不该用〈暂时〉。〈毕业〉是一次性、不可逆的结果，不能用〈暂时〉修饰。"}, {"text": "这条河暂时自北向南流。", "explanation": "这里不该用〈暂时〉。河流的走向是长期不变的地理事实，不能用〈暂时〉限定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87172, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "暂时", "is_correct": true, "explanation": "正确。「这些钱暂时够用」说目前够用，之后还要再存，与句意一致。"}, {"text": "始终", "is_correct": false, "explanation": "语义：「始终」表示一直不变，与「下个月还要再存」矛盾。"}, {"text": "随时", "is_correct": false, "explanation": "搭配：「随时」指任何时候都可以，多用于动作，不能描述「够用」这种状态。"}, {"text": "白白", "is_correct": false, "explanation": "语义：「白白」表示徒然、没有效果，与「够用」的意思不合。"}], "explanations": {"暂时": "正确。「这些钱暂时够用」说目前够用，之后还要再存，与句意一致。", "始终": "语义：「始终」表示一直不变，与「下个月还要再存」矛盾。", "随时": "搭配：「随时」指任何时候都可以，多用于动作，不能描述「够用」这种状态。", "白白": "语义：「白白」表示徒然、没有效果，与「够用」的意思不合。"}, "sentence_index": 6, "correct_answer": "暂时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他暂时打算一辈子住在这里。", "explanation": "这里不该用〈暂时〉。〈暂时〉指短时间内，而这里要表达的是长期的安排，应去掉〈暂时〉。"}, {"text": "这座城市暂时永远不会变。", "explanation": "这里不该用〈暂时〉。〈暂时〉指短时间内，而这里要表达的是长久保持原状，应去掉〈暂时〉。"}, {"text": "这段感情暂时终身不变。", "explanation": "这里不该用〈暂时〉。〈暂时〉指短时间内，而这里要表达的是长久、恒定的状态，应去掉〈暂时〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87172, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你不暂时在门口等一下，我去拿钥匙。", "corrected_sentence": "你暂时在门口等一下，我去拿钥匙。", "error_description": "错误：「不」放在了「暂时」前面。此处「暂时」作状语，前面加「不」使句子不通，而且句子本身没有否定意思，应删去「不」，说「你暂时在门口等一下」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87172, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会议暂时的由王经理主持，明天再定。", "corrected_sentence": "会议暂时由王经理主持，明天再定。", "error_description": "错误：「暂时」后多了「的」。此处「暂时」作状语修饰「由王经理主持」，中间不能加「的」，应删去「的」，说「会议暂时由王经理主持」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87173, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "单色", "is_correct": true, "explanation": "正确：“单色”指只有一种颜色，与“彩色”相对。"}, {"text": "透明", "is_correct": false, "explanation": "透明指能透过光线，与颜色种类多少无关。"}, {"text": "粗糙", "is_correct": false, "explanation": "粗糙指表面不平滑，与“彩色”不构成相对关系。"}, {"text": "清晰", "is_correct": false, "explanation": "清晰指轮廓分明，与颜色种类无关。"}], "correct_answer": "单色", "explanations": {"单色": "正确：“单色”指只有一种颜色，与“彩色”相对。", "透明": "透明指能透过光线，与颜色种类多少无关。", "粗糙": "粗糙指表面不平滑，与“彩色”不构成相对关系。", "清晰": "清晰指轮廓分明，与颜色种类无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2c0918d-5d4f-460c-a92e-20bad0a042f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87173, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "单色", "is_correct": true, "explanation": "正确：“单色”指只有一种颜色，与“彩色”相对。"}, {"text": "安静", "is_correct": false, "explanation": "安静指没有声音或不吵闹，与颜色无关。"}, {"text": "柔软", "is_correct": false, "explanation": "柔软指质地不硬，与“彩色”不构成相对关系。"}, {"text": "锋利", "is_correct": false, "explanation": "锋利指边缘尖锐，与颜色种类无关。"}], "correct_answer": "单色", "explanations": {"单色": "正确：“单色”指只有一种颜色，与“彩色”相对。", "安静": "安静指没有声音或不吵闹，与颜色无关。", "柔软": "柔软指质地不硬，与“彩色”不构成相对关系。", "锋利": "锋利指边缘尖锐，与颜色种类无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2c0918d-5d4f-460c-a92e-20bad0a042f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87173, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "彩色是有很多种颜色的，像彩虹一样。", "primary_collocate": null, "pronunciation": "cǎi sè", "ipa": "tsʰai˨˩˦ sɤ˥˩", "syllable_count": 2, "sentences": [{"text": "我喜欢彩色的气球。", "target_word": "彩色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们用彩色的笔画了一幅画。", "target_word": "彩色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服是彩色的，很好看。", "target_word": "彩色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给我买了一本彩色的书。", "target_word": "彩色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里的彩色灯亮了。", "target_word": "彩色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的房间里有一面彩色的墙。", "target_word": "彩色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只小鸟有彩色的羽毛。", "target_word": "彩色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上放着彩色的糖果。", "target_word": "彩色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们喜欢彩色的蛋糕。", "target_word": "彩色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里的彩色纸很多，也很漂亮。", "target_word": "彩色", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "彩色电视", "label": "复合"}], "register": "中性", "sense_fingerprint": "有很多种颜色，像彩虹", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8381a54f-c1d7-4b10-9819-04a640eace4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87173, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "彩色", "is_correct": true, "explanation": "正确：“彩色”指有很多种颜色，可以修饰气球。"}, {"text": "沉重", "is_correct": false, "explanation": "语义：气球通常很轻，不说“沉重”。"}, {"text": "严肃", "is_correct": false, "explanation": "语义：气球没有态度或表情，不能说“严肃”。"}, {"text": "滚烫", "is_correct": false, "explanation": "搭配：“滚烫”多用于水、饭菜等，不说“滚烫的气球”。"}], "explanations": {"彩色": "正确：“彩色”指有很多种颜色，可以修饰气球。", "沉重": "语义：气球通常很轻，不说“沉重”。", "严肃": "语义：气球没有态度或表情，不能说“严肃”。", "滚烫": "搭配：“滚烫”多用于水、饭菜等，不说“滚烫的气球”。"}, "sentence_index": 0, "correct_answer": "彩色"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的彩色很暖和。", "explanation": "这里应该用〈保暖〉。彩色只形容颜色，不用来形容衣服的保暖性能。"}, {"text": "这场比赛的彩色很重。", "explanation": "这里应该用〈分量〉。“彩色”只说颜色，不说分量。"}, {"text": "这个城市的夜生活的彩色很贵。", "explanation": "这里应该用〈费用〉。“彩色”只说颜色，不说花费。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2c0918d-5d4f-460c-a92e-20bad0a042f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87173, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "彩色", "is_correct": true, "explanation": "正确：“彩色”指有很多种颜色，可以修饰小鸟的羽毛。"}, {"text": "辛辣", "is_correct": false, "explanation": "搭配：“辛辣”多用于食物的味道，不说“辛辣的羽毛”。"}, {"text": "严厉", "is_correct": false, "explanation": "语义：羽毛没有性格，不能说“严厉”。"}, {"text": "甜美", "is_correct": false, "explanation": "语义：“甜美”多形容声音或笑容，羽毛不说“甜美”。"}], "explanations": {"彩色": "正确：“彩色”指有很多种颜色，可以修饰小鸟的羽毛。", "辛辣": "搭配：“辛辣”多用于食物的味道，不说“辛辣的羽毛”。", "严厉": "语义：羽毛没有性格，不能说“严厉”。", "甜美": "语义：“甜美”多形容声音或笑容，羽毛不说“甜美”。"}, "sentence_index": 6, "correct_answer": "彩色"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌的彩色很好听。", "explanation": "这里应该用〈旋律〉。彩色只形容颜色，不用来形容声音。"}, {"text": "这道菜的彩色太咸了。", "explanation": "这里应该用〈味道〉。彩色只形容颜色，不用来形容味道。"}, {"text": "这辆车的彩色很快。", "explanation": "这里应该用〈速度〉。彩色只形容颜色，不用来形容速度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2c0918d-5d4f-460c-a92e-20bad0a042f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87173, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个气球是彩色。", "corrected_sentence": "这个气球是彩色的。", "error_description": "“的”缺失：作谓语的“彩色”后通常要加“的”，应说“这个气球是彩色的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2c0918d-5d4f-460c-a92e-20bad0a042f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87173, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她买了一件很彩色的衣服。", "corrected_sentence": "她买了一件彩色的衣服。", "error_description": "程度副词误用：“彩色”是区别词，不能受“很”修饰，应删去“很”，说“彩色的衣服”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2c0918d-5d4f-460c-a92e-20bad0a042f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87174, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "黑白", "is_correct": true, "explanation": "正确：“黑白”指只有黑色和白色，与“彩色”相对。"}, {"text": "透明", "is_correct": false, "explanation": "透明指能透过光线，与颜色有无不构成相对关系。"}, {"text": "粗糙", "is_correct": false, "explanation": "粗糙指表面不平滑，与“彩色”不构成相对关系。"}, {"text": "清晰", "is_correct": false, "explanation": "清晰指轮廓分明，与颜色有无无关。"}], "correct_answer": "黑白", "explanations": {"黑白": "正确：“黑白”指只有黑色和白色，与“彩色”相对。", "透明": "透明指能透过光线，与颜色有无不构成相对关系。", "粗糙": "粗糙指表面不平滑，与“彩色”不构成相对关系。", "清晰": "清晰指轮廓分明，与颜色有无无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2c0918d-5d4f-460c-a92e-20bad0a042f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87174, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "黑白", "is_correct": true, "explanation": "正确：“黑白”指只有黑色和白色，与“彩色”相对。"}, {"text": "安静", "is_correct": false, "explanation": "安静指没有声音或不吵闹，与颜色有无无关。"}, {"text": "柔软", "is_correct": false, "explanation": "柔软指质地不硬，与“彩色”不构成相对关系。"}, {"text": "锋利", "is_correct": false, "explanation": "锋利指边缘尖锐，与颜色有无无关。"}], "correct_answer": "黑白", "explanations": {"黑白": "正确：“黑白”指只有黑色和白色，与“彩色”相对。", "安静": "安静指没有声音或不吵闹，与颜色有无无关。", "柔软": "柔软指质地不硬，与“彩色”不构成相对关系。", "锋利": "锋利指边缘尖锐，与颜色有无无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2c0918d-5d4f-460c-a92e-20bad0a042f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87174, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "具有多种颜色的；不是单一黑白的。", "primary_collocate": null, "pronunciation": "cǎi sè", "ipa": "tsʰai˨˩˦ sɤ˥˩", "syllable_count": 2, "sentences": [{"text": "这张照片是彩色的，不是黑白的。", "target_word": "彩色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前的电视是黑白的，现在是彩色的。", "target_word": "彩色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想打印一份彩色的图。", "target_word": "彩色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部老电影是黑白的，那部是彩色的。", "target_word": "彩色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台彩色打印机很贵。", "target_word": "彩色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老照片是黑白的，新照片是彩色的。", "target_word": "彩色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明的画是彩色的，不是黑白的。", "target_word": "彩色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请用彩色的纸做这张卡片。", "target_word": "彩色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在的报纸有的是彩色的。", "target_word": "彩色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把黑白相机换成了彩色相机。", "target_word": "彩色", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "彩色电视", "label": "复合"}], "register": "中性", "sense_fingerprint": "与黑白相对，有多种颜色的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8381a54f-c1d7-4b10-9819-04a640eace4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87174, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "彩色", "is_correct": true, "explanation": "正确：“彩色”与黑白相对，可以修饰照片。"}, {"text": "黑白", "is_correct": false, "explanation": "语义：“黑白”与后半句“不是黑白的”矛盾。"}, {"text": "寂静", "is_correct": false, "explanation": "语义：照片不会“寂静”，与句意不符。"}, {"text": "辛辣", "is_correct": false, "explanation": "搭配：“辛辣”多用于食物的味道，不用来形容照片。"}], "explanations": {"彩色": "正确：“彩色”与黑白相对，可以修饰照片。", "黑白": "语义：“黑白”与后半句“不是黑白的”矛盾。", "寂静": "语义：照片不会“寂静”，与句意不符。", "辛辣": "搭配：“辛辣”多用于食物的味道，不用来形容照片。"}, "sentence_index": 0, "correct_answer": "彩色"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块石头的彩色很重。", "explanation": "这里应该用〈重量〉。彩色只说颜色，不说重量。"}, {"text": "今天的晚会的彩色很响，大家都很高兴。", "explanation": "这里应该用〈声音〉。“彩色”只说颜色，不说声音大小。"}, {"text": "这个故事的彩色很长，大家都爱听。", "explanation": "这里应该用〈篇幅〉。“彩色”只说颜色，不说长短。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2c0918d-5d4f-460c-a92e-20bad0a042f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87174, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "彩色", "is_correct": true, "explanation": "正确：“彩色”与黑白相对，可以修饰小明的画。"}, {"text": "透明", "is_correct": false, "explanation": "语义：画不说“透明”，与“不是黑白的”的语境无关。"}, {"text": "沉默", "is_correct": false, "explanation": "语义：画不会“沉默”，与句意不符。"}, {"text": "甜美", "is_correct": false, "explanation": "搭配：“甜美”多形容人、声音或笑容，不用来形容画。"}], "explanations": {"彩色": "正确：“彩色”与黑白相对，可以修饰小明的画。", "透明": "语义：画不说“透明”，与“不是黑白的”的语境无关。", "沉默": "语义：画不会“沉默”，与句意不符。", "甜美": "搭配：“甜美”多形容人、声音或笑容，不用来形容画。"}, "sentence_index": 6, "correct_answer": "彩色"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗汤的彩色太烫了。", "explanation": "这里应该用〈温度〉。彩色只形容颜色，不用来形容温度。"}, {"text": "这场演出的彩色很短，大家都很喜欢。", "explanation": "这里应该用〈时长〉。“彩色”只说颜色，不说时间长短。"}, {"text": "这段音乐的彩色很响。", "explanation": "这里应该用〈音量〉。彩色只形容颜色，不用来形容声音大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2c0918d-5d4f-460c-a92e-20bad0a042f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
