INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87176, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "整体中分给某一方或某个人应得的部分。", "primary_collocate": null, "pronunciation": "fèn é", "ipa": "fən˥˩ ɤ˧˥", "syllable_count": 2, "sentences": [{"text": "这笔奖金按合同分配，每位队员都能拿到自己的份额。", "target_word": "份额", "complexity_tier": "T3", "furigana": "fèn é", "sentence_source": "generated"}, {"text": "三个人投钱做生意，每人的份额不一样。", "target_word": "份额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想多拿一点儿自己的份额。", "target_word": "份额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板把年终奖按工龄分给员工，工龄长的人份额更多。", "target_word": "份额", "complexity_tier": "T3", "furigana": "fèn é", "sentence_source": "generated"}, {"text": "弟弟的份额已经分给他了。", "target_word": "份额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔钱你应得的份额是三分之一。", "target_word": "份额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王在公司里有百分之十的份额。", "target_word": "份额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遗产分配时，两个儿子为了自己的份额争执不下。", "target_word": "份额", "complexity_tier": "T3", "furigana": "fèn é", "sentence_source": "generated"}, {"text": "奶奶去世后，孩子们按规定分了各自的份额。", "target_word": "份额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "按比例分配利润时，我的份额最大。", "target_word": "份额", "complexity_tier": "T3", "furigana": "fèn é", "sentence_source": "generated"}], "morphological_forms": [{"form": "份額", "label": "繁体"}, {"form": "市场份额", "label": "复合"}], "register": "中性", "sense_fingerprint": "整体中某一方或某人应得的部分，如市场份额", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '538b8765-1c9e-4db9-8583-9f5d1dd35ff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87176, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "名字", "is_correct": false, "explanation": "语义：这里分配的是奖金，名字不能分配，与“按合同分配”的语境冲突。"}, {"text": "份额", "is_correct": true, "explanation": "正确：“份额”指整体中分给某人的部分，正好对应“按合同分配”后每人拿到的那一部分。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不是可以分配的东西，与“按合同分配”的句意不符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能按合同分配，也不能拿到，句子说不通。"}], "explanations": {"名字": "语义：这里分配的是奖金，名字不能分配，与“按合同分配”的语境冲突。", "份额": "正确：“份额”指整体中分给某人的部分，正好对应“按合同分配”后每人拿到的那一部分。", "年龄": "语义：年龄不是可以分配的东西，与“按合同分配”的句意不符。", "天气": "语义：天气不能按合同分配，也不能拿到，句子说不通。"}, "sentence_index": 0, "correct_answer": "份额"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这碗饭的份额很足。", "explanation": "这里应该用〈份量〉。份额指整体中分给某人的部分，不用来指一碗饭的量。"}, {"text": "他这次考试的份额很高。", "explanation": "这里应该用〈分数〉。份额指分得的部分，不表示考试成绩。"}, {"text": "他的份额有一米八。", "explanation": "这里应该用〈身高〉。份额指整体中分得的部分，不能表示人的高度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d1df8c-23e6-4bf6-8b40-263efbffaf4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87176, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”是人的性情，没有“百分之十”这样的比例份额，句子说不通。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“百分之十的”不用来修饰“身高”，两者不搭配。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不能用“百分之十的”这种比例来计算，句子说不通。"}, {"text": "份额", "is_correct": true, "explanation": "正确：“百分之十的份额”指公司中占十分之一的那部分，符合句意。"}], "explanations": {"脾气": "语义：“脾气”是人的性情，没有“百分之十”这样的比例份额，句子说不通。", "身高": "搭配：“百分之十的”不用来修饰“身高”，两者不搭配。", "颜色": "语义：“颜色”不能用“百分之十的”这种比例来计算，句子说不通。", "份额": "正确：“百分之十的份额”指公司中占十分之一的那部分，符合句意。"}, "sentence_index": 6, "correct_answer": "份额"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他住在份额里。", "explanation": "“份额”是抽象的分配部分，不能当作地点，“住在”后面不能接它。"}, {"text": "他是我们公司的份额。", "explanation": "这里把“份额”当成了指人的〈员工〉。份额指分得的部分，不能用来指人。"}, {"text": "他去婚礼时随了很大的份额。", "explanation": "这里应该用〈份子〉。“份额”指分得的部分，不指随礼的钱，“随”后面应接〈份子〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d1df8c-23e6-4bf6-8b40-263efbffaf4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87176, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他想多分一点儿自己地份额。", "corrected_sentence": "他想多分一点儿自己的份额。", "error_description": "错误形式：“自己地份额”；正确形式：“自己的份额”。“地”用于修饰动词，修饰名词“份额”时应该用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d1df8c-23e6-4bf6-8b40-263efbffaf4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87176, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们三个人各分了一半地份额。", "corrected_sentence": "我们三个人各分了一半的份额。", "error_description": "错误形式：“一半地份额”；正确形式：“一半的份额”。“地”用于修饰动词，修饰名词时应该用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d1df8c-23e6-4bf6-8b40-263efbffaf4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
