INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87181, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "伯爵是很久以前外国的一种贵族。他们住在大房子里，有很多土地。", "primary_collocate": null, "pronunciation": "bó jué", "ipa": "pwo˧˥ tɕye˧˥", "syllable_count": 2, "sentences": [{"text": "很久以前，这个国家有一位伯爵。", "target_word": "伯爵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "伯爵有很多土地，农民给他种地。", "target_word": "伯爵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位伯爵住在山上的大房子里。", "target_word": "伯爵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "伯爵的房子大得像一座小城。", "target_word": "伯爵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事里的伯爵很有钱，可是不快乐。", "target_word": "伯爵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "伯爵每年都会请朋友来家里开晚会。", "target_word": "伯爵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位外国伯爵的家里有很多马。", "target_word": "伯爵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在书里读到过一位伯爵的故事。", "target_word": "伯爵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "伯爵把一块土地送给了农民。", "target_word": "伯爵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候，我很想当一位伯爵。", "target_word": "伯爵", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}], "register": "中性", "sense_fingerprint": "很久以前外国的一种贵族，住大房子，有很多土地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4cf27cd-43b5-427b-9ffd-1e148fc0d9bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87181, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "伯爵", "is_correct": true, "explanation": "正确。伯爵是很久以前外国的贵族，与“很久以前”相合。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：很久以前还没有电脑，与“很久以前”的时代背景冲突。"}, {"text": "大象", "is_correct": false, "explanation": "搭配：量词“位”只用于人，不能说“一位大象”。"}, {"text": "土地", "is_correct": false, "explanation": "搭配：量词“位”只用于人，不能说“一位土地”。"}], "explanations": {"伯爵": "正确。伯爵是很久以前外国的贵族，与“很久以前”相合。", "电脑": "语义：很久以前还没有电脑，与“很久以前”的时代背景冲突。", "大象": "搭配：量词“位”只用于人，不能说“一位大象”。", "土地": "搭配：量词“位”只用于人，不能说“一位土地”。"}, "sentence_index": 0, "correct_answer": "伯爵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他家的客厅里放着一台伯爵。", "explanation": "这里应该用〈位〉。〈台〉用于机器等物品，伯爵是人，应该用〈位〉。"}, {"text": "昨天商店里来了一颗伯爵。", "explanation": "这里应该用〈位〉。〈颗〉用于小而圆的东西，伯爵是人，应该用〈位〉。"}, {"text": "山上住着一座伯爵。", "explanation": "这里应该用〈位〉。〈座〉用于山、建筑等大型物体，伯爵是人，应该用〈位〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7553a4a7-0986-4a7d-a848-bd4df466845b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87181, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "伯爵", "is_correct": true, "explanation": "正确。伯爵是外国贵族，家里有很多马，与句意相合。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有家，也不会养马，与“家里有很多马”说不通。"}, {"text": "河流", "is_correct": false, "explanation": "搭配：量词“这位”只用于人，不能说“这位河流”。"}, {"text": "草原", "is_correct": false, "explanation": "搭配：量词“这位”只用于人，不能说“这位草原”。"}], "explanations": {"伯爵": "正确。伯爵是外国贵族，家里有很多马，与句意相合。", "石头": "语义：石头没有家，也不会养马，与“家里有很多马”说不通。", "河流": "搭配：量词“这位”只用于人，不能说“这位河流”。", "草原": "搭配：量词“这位”只用于人，不能说“这位草原”。"}, "sentence_index": 6, "correct_answer": "伯爵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我爸爸的哥哥是我的伯爵，他很喜欢钓鱼。", "explanation": "这里应该用〈伯父〉。伯父是父亲的哥哥，是亲属称呼；伯爵是贵族爵位，不用来指亲属。"}, {"text": "伯父的妻子是我的伯爵，她会做很多好吃的菜。", "explanation": "这里应该用〈伯母〉。伯母是伯父的妻子，是亲属称呼；伯爵不能用来指亲属。"}, {"text": "爸爸的哥哥是我大伯，大家都叫他伯爵。", "explanation": "这里应该用〈大伯〉。大伯是父亲的哥哥，是亲属称呼；伯爵不能用来指亲属。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7553a4a7-0986-4a7d-a848-bd4df466845b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87181, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只伯爵的房子很大。", "corrected_sentence": "那位伯爵的房子很大。", "error_description": "量词用错：“伯爵”指人，应说“那位伯爵”，不能说“那只伯爵”。“只”用于动物，“位”用于人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7553a4a7-0986-4a7d-a848-bd4df466845b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87181, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位伯爵是马很多。", "corrected_sentence": "那位伯爵的马很多。", "error_description": "“的”用成“是”：表示伯爵拥有马，要用“的”，应说“那位伯爵的马很多”，不能说“那位伯爵是马很多”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7553a4a7-0986-4a7d-a848-bd4df466845b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
