INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87182, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "欧洲贵族爵位的一等，位在侯爵之下、子爵之上。", "primary_collocate": null, "pronunciation": "bó jué", "ipa": "pwo˧˥ tɕye˧˥", "syllable_count": 2, "sentences": [{"text": "这位伯爵住在法国的一座老城堡里。", "target_word": "伯爵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "伯爵的地位比侯爵低，比子爵高。", "target_word": "伯爵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位伯爵有一个很大的花园。", "target_word": "伯爵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里的伯爵每天都骑马出门。", "target_word": "伯爵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "伯爵请客人到城堡里吃晚饭。", "target_word": "伯爵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位伯爵的爷爷也是一位伯爵。", "target_word": "伯爵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "英国国王封他为伯爵。", "target_word": "伯爵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老伯爵去世以后，儿子成了新伯爵。", "target_word": "伯爵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的伯爵很有钱，也很爱读书。", "target_word": "伯爵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在博物馆看过一幅伯爵的画像。", "target_word": "伯爵", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}], "register": "中性", "sense_fingerprint": "欧洲贵族爵位的一等，在侯爵之下、子爵之上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4cf27cd-43b5-427b-9ffd-1e148fc0d9bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87182, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "伯爵", "is_correct": true, "explanation": "正确。伯爵是欧洲贵族的一等爵位，可以用“这位”指称，住在法国的城堡里也合理。"}, {"text": "老虎", "is_correct": false, "explanation": "搭配：量词“位”只用于人，不能说“这位老虎”。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不是人，不会住在城堡里。"}, {"text": "大海", "is_correct": false, "explanation": "搭配：量词“这位”只用于人，“大海”不能住在城堡里。"}], "explanations": {"伯爵": "正确。伯爵是欧洲贵族的一等爵位，可以用“这位”指称，住在法国的城堡里也合理。", "老虎": "搭配：量词“位”只用于人，不能说“这位老虎”。", "窗户": "语义：窗户不是人，不会住在城堡里。", "大海": "搭配：量词“这位”只用于人，“大海”不能住在城堡里。"}, "sentence_index": 0, "correct_answer": "伯爵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在动物园看见一只伯爵。", "explanation": "这里应该用〈位〉。伯爵指人，量词〈只〉用于动物，不能用来数伯爵。"}, {"text": "我家来了一把伯爵。", "explanation": "这里应该用〈位〉。〈把〉用于有柄的器具，伯爵是人，不能用〈把〉来数。"}, {"text": "我家门口走来一条伯爵。", "explanation": "这里应该用〈位〉。〈条〉用于长条形的东西或某些动物，伯爵指人，应该用〈位〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7553a4a7-0986-4a7d-a848-bd4df466845b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87182, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "伯爵", "is_correct": true, "explanation": "正确。“封为”后接爵位，伯爵是英国国王可以封授的爵位。"}, {"text": "大学", "is_correct": false, "explanation": "搭配：“封为”后接爵位或封号，“大学”不能作为称号。"}, {"text": "字母", "is_correct": false, "explanation": "语义：字母不是可以被封授的身份或称号。"}, {"text": "哥们", "is_correct": false, "explanation": "语义：“封为”后接爵位或封号，“哥们”只是口语称呼，不能被封授。"}], "explanations": {"伯爵": "正确。“封为”后接爵位，伯爵是英国国王可以封授的爵位。", "大学": "搭配：“封为”后接爵位或封号，“大学”不能作为称号。", "字母": "语义：字母不是可以被封授的身份或称号。", "哥们": "语义：“封为”后接爵位或封号，“哥们”只是口语称呼，不能被封授。"}, "sentence_index": 6, "correct_answer": "伯爵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我爸爸的哥哥是我的伯爵。", "explanation": "这里应该用〈伯父〉。伯父是父亲的哥哥，是亲属称呼；伯爵是欧洲贵族的爵位，不用来称呼亲属。"}, {"text": "伯父的妻子是我的伯爵，她做的饺子很好吃。", "explanation": "这里应该用〈伯母〉。伯母是伯父的妻子，是亲属称呼；伯爵不用来指亲属。"}, {"text": "爸爸的大哥是我的伯爵，他每个星期天都来家里吃饭。", "explanation": "这里应该用〈大伯〉。大伯是父亲的哥哥，是亲属称呼；伯爵是爵位，不能指亲属。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7553a4a7-0986-4a7d-a848-bd4df466845b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87182, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只伯爵每年都去欧洲旅行。", "corrected_sentence": "这位伯爵每年都去欧洲旅行。", "error_description": "量词用错：“伯爵”指人，应说“这位伯爵”，不能说“这只伯爵”。“只”用于动物，“位”用于人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7553a4a7-0986-4a7d-a848-bd4df466845b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87182, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位伯爵是城堡很大。", "corrected_sentence": "那位伯爵的城堡很大。", "error_description": "“的”用成“是”：表示伯爵拥有城堡，要用“的”，应说“那位伯爵的城堡很大”，不能说“那位伯爵是城堡很大”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7553a4a7-0986-4a7d-a848-bd4df466845b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
