INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87183, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "狗是一种小动物，会汪汪叫，能看家。", "primary_collocate": null, "pronunciation": "gǒu", "ipa": "kou̯˨˩˦", "syllable_count": 1, "sentences": [{"text": "我家有一只小狗。", "target_word": "狗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只狗一直汪汪叫。", "target_word": "狗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狗喜欢吃肉和骨头。", "target_word": "狗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟很怕大狗。", "target_word": "狗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天早上带狗去公园。", "target_word": "狗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条狗在门口睡觉。", "target_word": "狗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从小就喜欢狗。", "target_word": "狗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居的狗又叫了。", "target_word": "狗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狗看见我，马上跑过来。", "target_word": "狗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，我们不能带狗出去玩。", "target_word": "狗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "只", "label": "量词"}, {"form": "条", "label": "量词"}, {"form": "小狗", "label": "复合"}, {"form": "狗狗", "label": "重叠"}], "register": "中性", "sense_fingerprint": "家养小动物，会汪汪叫，宠物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01ececac-152b-4004-ac0a-24281145fd2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87183, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "狗", "is_correct": true, "explanation": "正确。gǒu，意思是狗，一种家养小动物。"}, {"text": "够", "is_correct": false, "explanation": "gòu（第四声）与 gǒu（第三声）声调不同，意思是足够。"}, {"text": "沟", "is_correct": false, "explanation": "gōu（第一声）与 gǒu（第三声）声调不同，意思是沟渠。"}, {"text": "口", "is_correct": false, "explanation": "kǒu 与 gǒu 声母不同（k 与 g），声调相同，意思是嘴。"}, {"text": "走", "is_correct": false, "explanation": "zǒu 与 gǒu 声母不同（z 与 g），声调相同，意思是走路。"}], "explanations": {"狗": "正确。gǒu，意思是狗，一种家养小动物。", "够": "gòu（第四声）与 gǒu（第三声）声调不同，意思是足够。", "沟": "gōu（第一声）与 gǒu（第三声）声调不同，意思是沟渠。", "口": "kǒu 与 gǒu 声母不同（k 与 g），声调相同，意思是嘴。", "走": "zǒu 与 gǒu 声母不同（z 与 g），声调相同，意思是走路。"}, "sentence_index": null, "correct_answer": "狗"}, "level_3": {"options": [{"text": "狗", "is_correct": true, "explanation": "正确。“小狗”的“狗”指家养的小动物，与“一只”搭配。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“只”用于动物，不能用来数“房子”，房子应用“间”或“座”。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“只”用于动物，“石头”应用“块”或“颗”。"}, {"text": "恒星", "is_correct": false, "explanation": "语义：恒星是遥远的天体，不能养在家里，与“我家有”不搭。"}], "explanations": {"狗": "正确。“小狗”的“狗”指家养的小动物，与“一只”搭配。", "房子": "搭配：“只”用于动物，不能用来数“房子”，房子应用“间”或“座”。", "石头": "搭配：“只”用于动物，“石头”应用“块”或“颗”。", "恒星": "语义：恒星是遥远的天体，不能养在家里，与“我家有”不搭。"}, "sentence_index": 0, "correct_answer": "狗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在动物园看见一只狗在吃竹子，它黑白相间，很可爱。", "explanation": "这里应该用〈熊猫〉。狗指家养动物，不指吃竹子、黑白相间的大熊猫。"}, {"text": "我在草原上看见一只狗，它比马还高，用长鼻子卷起草来吃。", "explanation": "这里应该用〈大象〉。狗不指用长鼻子卷草的大象。"}, {"text": "森林里有一只狗，它喜欢爬树和吃蜂蜜，冬天会冬眠。", "explanation": "这里应该用〈熊〉。狗指家养动物，不指爬树、冬眠的熊。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f486e30-3ae2-4f13-aa8f-30c337825229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87183, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "狗", "is_correct": true, "explanation": "正确。gǒu，意思是狗，一种家养小动物。"}, {"text": "购", "is_correct": false, "explanation": "gòu（第四声）与 gǒu（第三声）声调不同，意思是购买。"}, {"text": "鼓", "is_correct": false, "explanation": "gǔ 与 gǒu 韵母不同（u 与 ou），声调相同，意思是鼓。"}, {"text": "勾", "is_correct": false, "explanation": "gōu（第一声）与 gǒu（第三声）声调不同，意思是勾画、钩子。"}, {"text": "藕", "is_correct": false, "explanation": "ǒu 比 gǒu 少了声母 g，声调相同，意思是莲藕。"}], "explanations": {"狗": "正确。gǒu，意思是狗，一种家养小动物。", "购": "gòu（第四声）与 gǒu（第三声）声调不同，意思是购买。", "鼓": "gǔ 与 gǒu 韵母不同（u 与 ou），声调相同，意思是鼓。", "勾": "gōu（第一声）与 gǒu（第三声）声调不同，意思是勾画、钩子。", "藕": "ǒu 比 gǒu 少了声母 g，声调相同，意思是莲藕。"}, "sentence_index": null, "correct_answer": "狗"}, "level_3": {"options": [{"text": "狗", "is_correct": true, "explanation": "正确。喜欢的对象是动物，“狗”符合语境。"}, {"text": "病毒", "is_correct": false, "explanation": "语义：病毒是有害的，人不会“喜欢”它。"}, {"text": "眼泪", "is_correct": false, "explanation": "搭配：“喜欢”一般不接“眼泪”这类令人难过的对象。"}, {"text": "汽油", "is_correct": false, "explanation": "搭配：“喜欢”通常不与“汽油”这类物质搭配，说“喜欢汽油”不自然。"}], "explanations": {"狗": "正确。喜欢的对象是动物，“狗”符合语境。", "病毒": "语义：病毒是有害的，人不会“喜欢”它。", "眼泪": "搭配：“喜欢”一般不接“眼泪”这类令人难过的对象。", "汽油": "搭配：“喜欢”通常不与“汽油”这类物质搭配，说“喜欢汽油”不自然。"}, "sentence_index": 6, "correct_answer": "狗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "池塘里的狗呱呱叫，一群群地游来游去。", "explanation": "这里应该用〈鸭子〉。狗不会呱呱叫，这是鸭子的叫声。"}, {"text": "他骑着一只狗去上班，跑得很快。", "explanation": "这里应该用〈马〉。狗指家养动物，不能用来骑着去上班，骑的是马。"}, {"text": "花园里的狗开满了红花，香气很浓。", "explanation": "这里应该用〈花〉。狗是动物，不会开花，说花开要用“花”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f486e30-3ae2-4f13-aa8f-30c337825229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87183, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家养了一本狗。", "corrected_sentence": "我家养了一只狗。", "error_description": "“狗”应搭配量词“只”，不能说“一本狗”；“本”用于书籍。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f486e30-3ae2-4f13-aa8f-30c337825229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87183, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们以前见过那本狗。", "corrected_sentence": "我们以前见过那只狗。", "error_description": "“狗”应搭配量词“只”，不能说“那本狗”；“本”用于书籍。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f486e30-3ae2-4f13-aa8f-30c337825229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
