INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87187, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "抓去是用手抓住人或东西，带走。", "primary_collocate": null, "pronunciation": "zhuā qù", "ipa": "ʈʂua˥ tɕʰy˥˩", "syllable_count": 2, "sentences": [{"text": "老鹰把小鸡抓去了。", "target_word": "抓去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏人把小孩抓去了。", "target_word": "抓去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察把那个小偷抓去派出所了。", "target_word": "抓去", "complexity_tier": "T3", "furigana": "jǐng chá bǎ nà ge xiǎo tōu zhuā qù pài chū suǒ le.", "sentence_source": "generated"}, {"text": "小猫抓去了桌上的鱼。", "target_word": "抓去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟抓去了我的玩具，跑出门了。", "target_word": "抓去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大鸟从河里抓去一条鱼。", "target_word": "抓去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想把那只兔子抓去给孩子们看。", "target_word": "抓去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猴子抓去了游客的香蕉。", "target_word": "抓去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那些人把他抓去了很远的地方。", "target_word": "抓去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把弟弟抓去洗手间了。", "target_word": "抓去", "complexity_tier": "T3", "furigana": "mā ma bǎ dì di zhuā qù xǐ shǒu jiān le.", "sentence_source": "generated"}], "morphological_forms": [{"form": "抓去了", "label": "体标"}, {"form": "抓去过", "label": "体标"}], "register": "口语", "sense_fingerprint": "用手抓住人或东西并带走", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8381a54f-c1d7-4b10-9819-04a640eace4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87187, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "抓去", "is_correct": true, "explanation": "正确答案：zhuā qù，用手抓住并带走。"}, {"text": "抓取", "is_correct": false, "explanation": "zhuā qǔ（第三声）与 zhuā qù（第四声）末字声调不同，意思是用手抓住以获取。"}, {"text": "抓起", "is_correct": false, "explanation": "zhuā qǐ 与 zhuā qù 末字韵母（i/ü）和声调都不同，意思是拿起来。"}, {"text": "刷去", "is_correct": false, "explanation": "shuā qù 与 zhuā qù 声母不同（sh 与 zh），意思是刷掉。"}], "explanations": {"抓去": "正确答案：zhuā qù，用手抓住并带走。", "抓取": "zhuā qǔ（第三声）与 zhuā qù（第四声）末字声调不同，意思是用手抓住以获取。", "抓起": "zhuā qǐ 与 zhuā qù 末字韵母（i/ü）和声调都不同，意思是拿起来。", "刷去": "shuā qù 与 zhuā qù 声母不同（sh 与 zh），意思是刷掉。"}, "sentence_index": null, "correct_answer": "抓去"}, "level_3": {"options": [{"text": "抓去", "is_correct": true, "explanation": "老鹰用爪子抓住小鸡并带走，符合句中语境。"}, {"text": "唱", "is_correct": false, "explanation": "配价：唱的宾语是歌曲等，不能用“小鸡”作受事。"}, {"text": "演奏", "is_correct": false, "explanation": "搭配：演奏只能跟乐曲、乐器搭配，不能跟“小鸡”搭配。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”指书写文字，与老鹰抓小鸡的动作不符。"}], "explanations": {"抓去": "老鹰用爪子抓住小鸡并带走，符合句中语境。", "唱": "配价：唱的宾语是歌曲等，不能用“小鸡”作受事。", "演奏": "搭配：演奏只能跟乐曲、乐器搭配，不能跟“小鸡”搭配。", "写": "语义：“写”指书写文字，与老鹰抓小鸡的动作不符。"}, "sentence_index": 0, "correct_answer": "抓去"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师把学生的疑问抓去了。", "explanation": "这里应该用〈解答〉。疑问是抽象的内容，抓去只能用于用手抓住带走的具体东西，老师回应学生的疑问应说解答。"}, {"text": "他把这个念头抓去了。", "explanation": "这里应该用〈放弃〉。念头是抽象的，抓去只能用于具体东西，打消念头应说放弃。"}, {"text": "他把那件事抓去了。", "explanation": "这里应该用〈忘掉〉。事情是抽象的，不能用手抓去，忘掉一件事应说忘掉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2c0918d-5d4f-460c-a92e-20bad0a042f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87187, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抓去", "is_correct": true, "explanation": "他想把兔子用手抓去给孩子们看，符合句中语境。"}, {"text": "朗读", "is_correct": false, "explanation": "搭配：朗读的对象是文字或诗文，不能用于“那只兔子”。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：翻译针对语言文字，与“兔子”这一实物不符。"}, {"text": "背诵", "is_correct": false, "explanation": "配价：背诵的宾语是课文、诗词等文字，不能带“那只兔子”作受事。"}], "explanations": {"抓去": "他想把兔子用手抓去给孩子们看，符合句中语境。", "朗读": "搭配：朗读的对象是文字或诗文，不能用于“那只兔子”。", "翻译": "语义：翻译针对语言文字，与“兔子”这一实物不符。", "背诵": "配价：背诵的宾语是课文、诗词等文字，不能带“那只兔子”作受事。"}, "sentence_index": 6, "correct_answer": "抓去"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把这句祝福抓去朋友家了。", "explanation": "这里应该用〈转达〉。祝福是抽象的，抓去只能用于用手抓住带走的具体东西，向朋友传达问候应说转达。"}, {"text": "妈妈把孩子的病抓去了。", "explanation": "这里应该用〈治好〉。病是抽象的，不能被用手抓去，让孩子病好应说治好。"}, {"text": "我把那个误会抓去了。", "explanation": "这里应该用〈消除〉。误会是抽象的，抓去只能用于用手抓住带走的具体东西，消除误会应说消除。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2c0918d-5d4f-460c-a92e-20bad0a042f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
