INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87188, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "抓去", "is_correct": true, "explanation": "正确答案：zhuā qù，抓住后带走。"}, {"text": "抓取", "is_correct": false, "explanation": "zhuā qǔ（第三声）与 zhuā qù（第四声）末字声调不同，意思是用手抓住以获取。"}, {"text": "抓起", "is_correct": false, "explanation": "zhuā qǐ（第三声）与 zhuā qù（第四声）末字声调不同，意思是拿起来。"}, {"text": "刷去", "is_correct": false, "explanation": "shuā qù 与 zhuā qù 声母不同（sh 与 zh），意思是刷掉。"}, {"text": "撞去", "is_correct": false, "explanation": "zhuàng qù 与 zhuā qù 首字韵母多了 ng，声调也不同（第四声与第一声），意思是撞过去。"}], "explanations": {"抓去": "正确答案：zhuā qù，抓住后带走。", "抓取": "zhuā qǔ（第三声）与 zhuā qù（第四声）末字声调不同，意思是用手抓住以获取。", "抓起": "zhuā qǐ（第三声）与 zhuā qù（第四声）末字声调不同，意思是拿起来。", "刷去": "shuā qù 与 zhuā qù 声母不同（sh 与 zh），意思是刷掉。", "撞去": "zhuàng qù 与 zhuā qù 首字韵母多了 ng，声调也不同（第四声与第一声），意思是撞过去。"}, "sentence_index": null, "correct_answer": "抓去"}, "level_3": {"options": [{"text": "抓去", "is_correct": true, "explanation": "老虎扑住小羊并带走，符合句中语境。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：修理的对象是器物、机器，不能用于“一只小羊”。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”指书写文字，与老虎的动作不符。"}, {"text": "唱", "is_correct": false, "explanation": "配价：唱的宾语是歌曲等，不能带“一只小羊”作受事。"}], "explanations": {"抓去": "老虎扑住小羊并带走，符合句中语境。", "修理": "搭配：修理的对象是器物、机器，不能用于“一只小羊”。", "写": "语义：“写”指书写文字，与老虎的动作不符。", "唱": "配价：唱的宾语是歌曲等，不能带“一只小羊”作受事。"}, "sentence_index": 0, "correct_answer": "抓去"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把那句话抓去了。", "explanation": "这里应该用〈收回〉。话是抽象的，抓去只能用于用手抓住带走的具体东西，收回说过的话应说收回。"}, {"text": "我终于把那个承诺抓去了。", "explanation": "这里应该用〈兑现〉。承诺是抽象的，抓去只能用于用手抓住带走的具体东西，实现承诺应说兑现。"}, {"text": "老师把学生的错误抓去了。", "explanation": "这里应该用〈纠正〉。错误是抽象的，抓去只能用于用手抓住带走的具体东西，老师改正学生的错误应说纠正。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2c0918d-5d4f-460c-a92e-20bad0a042f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87188, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抓去", "is_correct": true, "explanation": "老鼠把桌上的饼干抓走，符合句中语境。"}, {"text": "擦", "is_correct": false, "explanation": "语义：擦的对象是桌面等表面，饼干不能被擦。"}, {"text": "熨", "is_correct": false, "explanation": "语义：熨是用熨斗烫平衣物，与“饼干”不符。"}, {"text": "缝", "is_correct": false, "explanation": "搭配：缝的对象是布料、衣物，不能跟“饼干”搭配。"}], "explanations": {"抓去": "老鼠把桌上的饼干抓走，符合句中语境。", "擦": "语义：擦的对象是桌面等表面，饼干不能被擦。", "熨": "语义：熨是用熨斗烫平衣物，与“饼干”不符。", "缝": "搭配：缝的对象是布料、衣物，不能跟“饼干”搭配。"}, "sentence_index": 6, "correct_answer": "抓去"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把这份心意抓去了。", "explanation": "这里应该用〈表达〉。心意是抽象的，抓去只能用于用手抓住带走的具体东西，传达心意应说表达。"}, {"text": "他把那个计划抓去了。", "explanation": "这里应该用〈取消〉。计划是抽象的，抓去只能用于用手抓住带走的具体东西，计划作罢应说取消。"}, {"text": "我把那场争吵抓去了。", "explanation": "这里应该用〈平息〉。争吵是抽象的，抓去只能用于用手抓住带走的具体东西，结束争吵应说平息。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2c0918d-5d4f-460c-a92e-20bad0a042f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87188, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老虎把山上的一只小羊抓去去了。", "corrected_sentence": "老虎把山上的一只小羊抓去了。", "error_description": "补语重复：“抓去”已含趋向补语“去”，后面不能再加“去”，应说“抓去了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2c0918d-5d4f-460c-a92e-20bad0a042f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87188, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只鸟被他们抓去着。", "corrected_sentence": "那只鸟被他们抓去了。", "error_description": "体标错误：“抓去”是动词加趋向补语，后面不能接“着”，表示已经完成应用“了”，应写作“抓去了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2c0918d-5d4f-460c-a92e-20bad0a042f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
