INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87191, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "乐是心里很高兴，脸上有笑。", "primary_collocate": null, "pronunciation": "lè", "ipa": "lɤ˥˩", "syllable_count": 1, "sentences": [{"text": "听到好消息，他乐得直笑。", "target_word": "乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看到礼物，乐了一整天。", "target_word": "乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子拿到新玩具，乐得跳起来。", "target_word": "乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你乐什么？说给我听听。", "target_word": "乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看他乐的，一定有好事。", "target_word": "乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷看见孙子，乐得合不拢嘴。", "target_word": "乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗一跑，孩子们都乐了。", "target_word": "乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹一听要去玩，就乐起来了。", "target_word": "乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别光顾着乐，快做作业。", "target_word": "乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她中了奖，乐坏了。", "target_word": "乐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "乐了", "label": "体标"}, {"form": "快乐", "label": "复合"}, {"form": "乐呵呵", "label": "复合"}, {"form": "樂", "label": "繁体"}], "register": "口语", "sense_fingerprint": "乐：心里高兴、脸上带笑，口语常说乐得、乐了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5557fc-539b-4cb6-b9b1-8d2660c41b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87191, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "乐", "is_correct": true, "explanation": "正确。乐读 lè（第四声），意思是心里高兴、脸上带笑。"}, {"text": "了", "is_correct": false, "explanation": "le（轻声）与 lè 声调不同，是助词“了”，不表示高兴。"}, {"text": "热", "is_correct": false, "explanation": "rè 与 lè 声母不同（r 与 l），意思是温度高。"}, {"text": "辣", "is_correct": false, "explanation": "là 与 lè 韵母不同（a 与 e），意思是味道刺激。"}], "explanations": {"乐": "正确。乐读 lè（第四声），意思是心里高兴、脸上带笑。", "了": "le（轻声）与 lè 声调不同，是助词“了”，不表示高兴。", "热": "rè 与 lè 声母不同（r 与 l），意思是温度高。", "辣": "là 与 lè 韵母不同（a 与 e），意思是味道刺激。"}, "sentence_index": null, "correct_answer": "乐"}, "level_3": {"options": [{"text": "乐", "is_correct": true, "explanation": "正确。“乐得”表示因高兴而笑，与“好消息”“直笑”相合。"}, {"text": "沮丧", "is_correct": false, "explanation": "语义：沮丧表示失落，与“好消息”矛盾，不能与“直笑”搭配。"}, {"text": "冷漠", "is_correct": false, "explanation": "语义：冷漠指态度淡漠，与“直笑”的热烈情绪相反。"}, {"text": "疲惫", "is_correct": false, "explanation": "体貌：疲惫描写身体状态，不用来形容因好消息而笑的心情。"}], "explanations": {"乐": "正确。“乐得”表示因高兴而笑，与“好消息”“直笑”相合。", "沮丧": "语义：沮丧表示失落，与“好消息”矛盾，不能与“直笑”搭配。", "冷漠": "语义：冷漠指态度淡漠，与“直笑”的热烈情绪相反。", "疲惫": "体貌：疲惫描写身体状态，不用来形容因好消息而笑的心情。"}, "sentence_index": 0, "correct_answer": "乐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他乐于帮别人搬家，大家都很感谢。", "explanation": "这里的“乐”是“乐意、愿意”义（lè），表示愿意去做，与本题“高兴”义不同。"}, {"text": "她每天练习乐器，手指很灵活。", "explanation": "这里的“乐”属于“乐器”一词，读 yuè，指音乐，与“高兴”义无关。"}, {"text": "乐毅是战国时期的名将。", "explanation": "这里的“乐”是姓氏，读 yuè，与“高兴”义无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49ae9169-ef07-43c7-8a80-89a7fba3a92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87191, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "乐", "is_correct": true, "explanation": "正确。乐读 lè（第四声），意思是心里高兴、脸上带笑。"}, {"text": "饿", "is_correct": false, "explanation": "è 与 lè 只差声母（零声母与 l），意思是肚子空、想吃东西。"}, {"text": "客", "is_correct": false, "explanation": "kè（第四声）与 lè 只差声母（k 与 l），意思是客人。"}, {"text": "类", "is_correct": false, "explanation": "lèi 与 lè 韵母不同（多了 i），意思是种类。"}], "explanations": {"乐": "正确。乐读 lè（第四声），意思是心里高兴、脸上带笑。", "饿": "è 与 lè 只差声母（零声母与 l），意思是肚子空、想吃东西。", "客": "kè（第四声）与 lè 只差声母（k 与 l），意思是客人。", "类": "lèi 与 lè 韵母不同（多了 i），意思是种类。"}, "sentence_index": null, "correct_answer": "乐"}, "level_3": {"options": [{"text": "乐", "is_correct": true, "explanation": "正确。“乐了”表示孩子们因小狗跑而高兴地笑。"}, {"text": "苍老", "is_correct": false, "explanation": "体貌：苍老形容老年人的样子，不能用于孩子。"}, {"text": "冷淡", "is_correct": false, "explanation": "语义：冷淡表示不热情，与“小狗一跑”的热闹场面不合。"}, {"text": "严肃", "is_correct": false, "explanation": "语义：严肃指神情郑重，与孩子们因小狗而嬉笑的场面矛盾。"}], "explanations": {"乐": "正确。“乐了”表示孩子们因小狗跑而高兴地笑。", "苍老": "体貌：苍老形容老年人的样子，不能用于孩子。", "冷淡": "语义：冷淡表示不热情，与“小狗一跑”的热闹场面不合。", "严肃": "语义：严肃指神情郑重，与孩子们因小狗而嬉笑的场面矛盾。"}, "sentence_index": 6, "correct_answer": "乐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我很乐这个城市，每天都想去逛逛。", "explanation": "这里应该用〈喜欢〉。乐作“高兴”讲时不带宾语，表示对事物有好感要用“喜欢”，不能说“乐这个城市”。"}, {"text": "我们度过了一个乐的周末。", "explanation": "这里应该用“快乐”。单音节的“乐”一般不直接修饰名词。"}, {"text": "她乐了地跑了过来。", "explanation": "“乐了”之后不能再接“地”修饰动作，应说“乐呵呵地跑过来”或“乐得跑了过来”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49ae9169-ef07-43c7-8a80-89a7fba3a92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87191, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一听，慢慢乐下来了。", "corrected_sentence": "他一听，慢慢乐起来了。", "error_description": "表示情绪逐渐变化要用趋向补语“起来”，写成“下来”不通；正确为“慢慢乐起来了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49ae9169-ef07-43c7-8a80-89a7fba3a92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87191, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一听，乐了得直拍手。", "corrected_sentence": "他一听，乐得直拍手。", "error_description": "“乐”后接表示程度或结果的补语要直接用“得”，不能写成“乐了得”；正确为“乐得直拍手”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49ae9169-ef07-43c7-8a80-89a7fba3a92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
