INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87192, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "快乐；高兴。", "primary_collocate": null, "pronunciation": "lè", "ipa": "lɤ˥˩", "syllable_count": 1, "sentences": [{"text": "听到这个消息，她心里乐开了花。", "target_word": "乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家一听放假，都乐了。", "target_word": "乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师夸了他，他乐得不知说什么。", "target_word": "乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到你这么乐，我也高兴。", "target_word": "乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟玩游戏玩得挺乐。", "target_word": "乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她买到喜欢的书，乐了半天。", "target_word": "乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这么乐，是不是有什么好事？", "target_word": "乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一赢就乐，一输就哭。", "target_word": "乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫跳来跳去，孩子们看着乐。", "target_word": "乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天是我的生日，大家乐得很。", "target_word": "乐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "乐了", "label": "体标"}, {"form": "快乐", "label": "复合"}, {"form": "乐呵呵", "label": "复合"}, {"form": "樂", "label": "繁体"}], "register": "口语", "sense_fingerprint": "乐：快乐、高兴，口语里表示因好事而开心", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5557fc-539b-4cb6-b9b1-8d2660c41b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87192, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "乐", "is_correct": true, "explanation": "正确。乐读 lè（第四声），意思是快乐、高兴。"}, {"text": "了", "is_correct": false, "explanation": "le（轻声）与 lè 声调不同，是助词“了”，不表示高兴。"}, {"text": "热", "is_correct": false, "explanation": "rè 与 lè 声母不同（r 与 l），意思是温度高。"}, {"text": "辣", "is_correct": false, "explanation": "là 与 lè 韵母不同（a 与 e），意思是味道刺激。"}], "explanations": {"乐": "正确。乐读 lè（第四声），意思是快乐、高兴。", "了": "le（轻声）与 lè 声调不同，是助词“了”，不表示高兴。", "热": "rè 与 lè 声母不同（r 与 l），意思是温度高。", "辣": "là 与 lè 韵母不同（a 与 e），意思是味道刺激。"}, "sentence_index": null, "correct_answer": "乐"}, "level_3": {"options": [{"text": "乐", "is_correct": true, "explanation": "正确。“心里乐开了花”是高兴到极点的惯用说法。"}, {"text": "难过", "is_correct": false, "explanation": "语义：难过是伤心，与“开了花”的喜悦相反。"}, {"text": "烦躁", "is_correct": false, "explanation": "语义：烦躁指焦躁不安，与“开了花”的欢喜矛盾。"}, {"text": "冷清", "is_correct": false, "explanation": "搭配：冷清多形容场所或气氛，不用来说“心里”。"}], "explanations": {"乐": "正确。“心里乐开了花”是高兴到极点的惯用说法。", "难过": "语义：难过是伤心，与“开了花”的喜悦相反。", "烦躁": "语义：烦躁指焦躁不安，与“开了花”的欢喜矛盾。", "冷清": "搭配：冷清多形容场所或气氛，不用来说“心里”。"}, "sentence_index": 0, "correct_answer": "乐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他乐于接受大家的意见。", "explanation": "这里的“乐”是“乐意、愿意”义（lè），表示愿意接受，与“快乐”义不同。"}, {"text": "乐队今晚在礼堂里演出。", "explanation": "这里的“乐”属于“乐队”一词，读 yuè，指音乐，与“高兴”义无关。"}, {"text": "乐山是四川的一座城市。", "explanation": "这里的“乐”是地名“乐山”的一部分，读 lè，不表示高兴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49ae9169-ef07-43c7-8a80-89a7fba3a92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87192, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "乐", "is_correct": true, "explanation": "正确。乐读 lè（第四声），意思是快乐、高兴。"}, {"text": "饿", "is_correct": false, "explanation": "è 与 lè 只差声母（零声母与 l），意思是肚子空、想吃东西。"}, {"text": "客", "is_correct": false, "explanation": "kè（第四声）与 lè 只差声母（k 与 l），意思是客人。"}, {"text": "类", "is_correct": false, "explanation": "lèi 与 lè 韵母不同（多了 i），意思是种类。"}], "explanations": {"乐": "正确。乐读 lè（第四声），意思是快乐、高兴。", "饿": "è 与 lè 只差声母（零声母与 l），意思是肚子空、想吃东西。", "客": "kè（第四声）与 lè 只差声母（k 与 l），意思是客人。", "类": "lèi 与 lè 韵母不同（多了 i），意思是种类。"}, "sentence_index": null, "correct_answer": "乐"}, "level_3": {"options": [{"text": "乐", "is_correct": true, "explanation": "正确。“你这么乐”指对方高兴，与“有什么好事”的推测相合。"}, {"text": "沮丧", "is_correct": false, "explanation": "语义：沮丧表示失落，与“有什么好事”的推测矛盾。"}, {"text": "冷漠", "is_correct": false, "explanation": "语义：冷漠指不热情，与“这么”所描述的高兴表现矛盾。"}, {"text": "疲惫", "is_correct": false, "explanation": "体貌：疲惫描写身体状态，与“有什么好事”的推测不相合。"}], "explanations": {"乐": "正确。“你这么乐”指对方高兴，与“有什么好事”的推测相合。", "沮丧": "语义：沮丧表示失落，与“有什么好事”的推测矛盾。", "冷漠": "语义：冷漠指不热情，与“这么”所描述的高兴表现矛盾。", "疲惫": "体貌：疲惫描写身体状态，与“有什么好事”的推测不相合。"}, "sentence_index": 6, "correct_answer": "乐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我很乐你的帮助。", "explanation": "这里应该用〈感谢〉。乐作“高兴”讲，不能用来表示对别人帮助的感谢，应说“感谢你的帮助”。"}, {"text": "我度过了一个乐的假期。", "explanation": "这里应该用“快乐”。单音节的“乐”一般不直接修饰名词。"}, {"text": "他乐了地说个不停。", "explanation": "“乐了”之后不能再接“地”修饰动作，应说“乐呵呵地说个不停”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49ae9169-ef07-43c7-8a80-89a7fba3a92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87192, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她听到消息，乐的跳了起来。", "corrected_sentence": "她听到消息，乐得跳了起来。", "error_description": "“乐”后的补语要用“得”，写成“的”不通；正确为“乐得跳了起来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49ae9169-ef07-43c7-8a80-89a7fba3a92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87192, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很的乐，一定是中奖了。", "corrected_sentence": "他很乐，一定是中奖了。", "error_description": "「很」修饰「乐」时后面不加「的」，应说「很乐」，不能说「很的乐」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49ae9169-ef07-43c7-8a80-89a7fba3a92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87193, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "高开", "is_correct": true, "explanation": "正确。「高开」指开盘价高于前一交易日收盘价，与「低开」相反。"}, {"text": "唱歌", "is_correct": false, "explanation": "与「低开」没有反义关系，「唱歌」与股价开盘无关。"}, {"text": "跑步", "is_correct": false, "explanation": "与「低开」没有反义关系，「跑步」与股价开盘无关。"}, {"text": "写字", "is_correct": false, "explanation": "与「低开」没有反义关系，「写字」与股价开盘无关。"}], "correct_answer": "高开", "explanations": {"高开": "正确。「高开」指开盘价高于前一交易日收盘价，与「低开」相反。", "唱歌": "与「低开」没有反义关系，「唱歌」与股价开盘无关。", "跑步": "与「低开」没有反义关系，「跑步」与股价开盘无关。", "写字": "与「低开」没有反义关系，「写字」与股价开盘无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cb825-c0b4-48bd-9283-9eddacabb02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
