INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87193, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "低开是一开始就比以前低。", "primary_collocate": null, "pronunciation": "dī kāi", "ipa": "ti˥ kʰaɪ˥", "syllable_count": 2, "sentences": [{"text": "今天股市一开盘就低开了。", "target_word": "低开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天涨了，今天股票却低开了。", "target_word": "低开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为坏消息，今天的股价低开了。", "target_word": "低开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻一出来，股市第二天就低开。", "target_word": "低开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天早上股市低开，很多人很担心。", "target_word": "低开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "美国股市昨晚下跌，所以今天这里低开。", "target_word": "低开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只股票今天低开，比昨天便宜了。", "target_word": "低开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天股票为什么低开？没有人知道。", "target_word": "低开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月第一天，股市低开了不少。", "target_word": "低开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说明天股市可能会低开。", "target_word": "低开", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "低开了", "label": "体标（了）"}, {"form": "低開", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一开始就比以前低，常说股市、股价开盘时比前一天低", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '157552df-a86f-4558-b9ec-500c2d87da0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87193, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "低开", "is_correct": true, "explanation": "正确。「低开」指开盘时价格比前一天低，符合「今天股市一开盘就低开了」的句意。"}, {"text": "收盘", "is_correct": false, "explanation": "语义：「收盘」指收市，与「一开盘就」的时间顺序矛盾。"}, {"text": "散步", "is_correct": false, "explanation": "语义：「散步」是人的活动，与股市开盘无关，句子不通。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：股市不能「吃」，这个动词不能用于股市。"}], "explanations": {"低开": "正确。「低开」指开盘时价格比前一天低，符合「今天股市一开盘就低开了」的句意。", "收盘": "语义：「收盘」指收市，与「一开盘就」的时间顺序矛盾。", "散步": "语义：「散步」是人的活动，与股市开盘无关，句子不通。", "吃": "搭配：股市不能「吃」，这个动词不能用于股市。"}, "sentence_index": 0, "correct_answer": "低开"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新闻一出来，股市第二天一整天都低开。", "explanation": "这里应该用〈下跌〉。低开只指开盘价比前一天低，全天一直下行要用下跌。"}, {"text": "这个城市的人口第二年就低开。", "explanation": "这里应该用〈下降〉。低开只指股市开盘价比前一天低，人口减少要用下降。"}, {"text": "新闻一出来，天气第二天就低开。", "explanation": "这里应该用〈降温〉。低开只用于股价、指数的开盘行情，天气变冷要用降温。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cb825-c0b4-48bd-9283-9eddacabb02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87193, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "低开", "is_correct": true, "explanation": "正确。「低开」指开盘价低于前一天，符合「这只股票今天低开，比昨天便宜了」的语境。"}, {"text": "涨价", "is_correct": false, "explanation": "语义：「涨价」表示价格变高，与「比昨天便宜了」矛盾。"}, {"text": "升值", "is_correct": false, "explanation": "语义：「升值」指价值增加，与「比昨天便宜了」矛盾。"}, {"text": "停牌", "is_correct": false, "explanation": "语义：股票停牌就没有价格变动，与「比昨天便宜了」矛盾。"}], "explanations": {"低开": "正确。「低开」指开盘价低于前一天，符合「这只股票今天低开，比昨天便宜了」的语境。", "涨价": "语义：「涨价」表示价格变高，与「比昨天便宜了」矛盾。", "升值": "语义：「升值」指价值增加，与「比昨天便宜了」矛盾。", "停牌": "语义：股票停牌就没有价格变动，与「比昨天便宜了」矛盾。"}, "sentence_index": 6, "correct_answer": "低开"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家餐厅的生意昨天低开了不少。", "explanation": "这里应该用〈下滑〉。低开只用于股市开盘价，生意的下滑不能说低开。"}, {"text": "我的电脑昨天低开了。", "explanation": "这里应该用〈开机〉。低开专指股市开盘价低于前一天，不能用于电脑开机。"}, {"text": "我的体重第一天就低开了三公斤。", "explanation": "这里应该用〈减轻〉。低开只用于开盘行情，体重下降要用减轻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cb825-c0b4-48bd-9283-9eddacabb02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87193, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨晚外盘大跌，今天把股市低开了。", "corrected_sentence": "昨晚外盘大跌，今天股市低开了。", "error_description": "错误：「低开」是不及物动词，不能用「把」字句。应说「今天股市低开了」，去掉「把」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cb825-c0b4-48bd-9283-9eddacabb02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87193, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司的股票今天低开着，价格比昨天低了一块。", "corrected_sentence": "这家公司的股票今天低开，价格比昨天低了一块。", "error_description": "错误：「低开」指开盘时一次性发生的变化，不能加「着」表示持续。应说「低开」，后面不加「着」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cb825-c0b4-48bd-9283-9eddacabb02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
