INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87195, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指望是盼着有好事发生，靠别人或靠某件事。", "primary_collocate": null, "pronunciation": "zhǐ wang", "ipa": "ʈʂɹ̩˨˩˦ wɑŋ", "syllable_count": 2, "sentences": [{"text": "我不指望你帮我，我自己能做好。", "target_word": "指望", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别指望他会来，他从来不守时。", "target_word": "指望", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她指望儿子毕业后能找个好工作。", "target_word": "指望", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你不要总指望别人给你钱。", "target_word": "指望", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们全家都指望着他的工资过日子。", "target_word": "指望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师指望学生们考试都能考好。", "target_word": "指望", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民指望今年天气好，多打点儿粮食。", "target_word": "指望", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他指望这次比赛能拿第一名。", "target_word": "指望", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你指望他帮忙，还不如自己动手。", "target_word": "指望", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别指望天上掉馅饼，好事要靠自己做。", "target_word": "指望", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "指望着", "label": "体标"}, {"form": "指望了", "label": "体标"}, {"form": "指望过", "label": "体标"}], "register": "口语", "sense_fingerprint": "指望：盼着好事发生，并把希望放在某人或某事上，想靠他（它）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157c64-73c7-4e54-9585-b5a2f818129e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87195, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "指望", "is_correct": true, "explanation": "“指望”表示靠别人或某件事而抱有期待，正好对应“不靠你帮我”的语境。"}, {"text": "看", "is_correct": false, "explanation": "语义：“看你帮我”说的是观看，与句子表达的依靠之意不符。"}, {"text": "怀疑", "is_correct": false, "explanation": "语义：怀疑是不相信，无法与“我自己能做好”这个理由衔接。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：嘲笑是取笑别人，“嘲笑你帮我”说不通，与句意不符。"}], "explanations": {"指望": "“指望”表示靠别人或某件事而抱有期待，正好对应“不靠你帮我”的语境。", "看": "语义：“看你帮我”说的是观看，与句子表达的依靠之意不符。", "怀疑": "语义：怀疑是不相信，无法与“我自己能做好”这个理由衔接。", "嘲笑": "语义：嘲笑是取笑别人，“嘲笑你帮我”说不通，与句意不符。"}, "sentence_index": 0, "correct_answer": "指望"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我去医院指望生病的奶奶。", "explanation": "这里应该用〈看望〉。指望表示盼望或依靠，去医院探望病人要用“看望”。"}, {"text": "我在超市指望水果。", "explanation": "这里应该用〈挑选〉。指望表示盼望或依靠，在超市选购水果要用“挑选”。"}, {"text": "他每天都指望牙。", "explanation": "这里应该用〈刷〉。指望表示盼望或依靠，清洁牙齿要用“刷”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87195, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "指望", "is_correct": true, "explanation": "“指望”表示盼着天气好、靠天气获得收成，与句意相合。"}, {"text": "打算", "is_correct": false, "explanation": "语义：“打算”表示自己计划要做的事，天气不能由农民打算。"}, {"text": "决定", "is_correct": false, "explanation": "语义：天气不是可以决定的事，“决定”与句意不合。"}, {"text": "担心", "is_correct": false, "explanation": "语义：担心表示忧虑，与盼望天气好、多打粮食的语意相反。"}], "explanations": {"指望": "“指望”表示盼着天气好、靠天气获得收成，与句意相合。", "打算": "语义：“打算”表示自己计划要做的事，天气不能由农民打算。", "决定": "语义：天气不是可以决定的事，“决定”与句意不合。", "担心": "语义：担心表示忧虑，与盼望天气好、多打粮食的语意相反。"}, "sentence_index": 6, "correct_answer": "指望"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他认真指望房间。", "explanation": "这里应该用〈打扫〉。指望表示盼望或依靠，清洁房间要用“打扫”。"}, {"text": "我们要指望环境。", "explanation": "这里应该用〈保护〉。指望是对外部依靠的盼望，爱护环境要用“保护”。"}, {"text": "大家在指望问题。", "explanation": "这里应该用〈讨论〉。指望表示盼望或依靠，就问题交换意见要用“讨论”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87195, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们都指望了暑假去旅游。", "corrected_sentence": "孩子们都指望着暑假去旅游。", "error_description": "体标错误：“指望着”表示持续的期待，“暑假去旅游”尚未发生，不能用“了”，应改为“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87195, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们不能只指望了他一个人。", "corrected_sentence": "我们不能只指望他一个人。", "error_description": "体标错误：“了”表示已完成的动作，与“不能”这类否定的情态语境不相容，“指望”后不能加“了”，应去掉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
