INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87196, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "盼望；寄希望于某人或某事。", "primary_collocate": null, "pronunciation": "zhǐ wang", "ipa": "ʈʂɹ̩˨˩˦ wɑŋ", "syllable_count": 2, "sentences": [{"text": "病人的家人都指望着医生能救他。", "target_word": "指望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王就指望这份工作养活全家。", "target_word": "指望", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都指望他拿个好成绩回来。", "target_word": "指望", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我指望明天天晴，好去爬山。", "target_word": "指望", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸妈都指望他将来能有出息。", "target_word": "指望", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司指望新产品能多卖点儿钱。", "target_word": "指望", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一直指望着有人来帮他一把。", "target_word": "指望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别指望一次考试就能提高很多。", "target_word": "指望", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们指望这场雨能让天气凉快点儿。", "target_word": "指望", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里人都指望这条路修好后能致富。", "target_word": "指望", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "指望着", "label": "体标"}, {"form": "指望了", "label": "体标"}, {"form": "指望过", "label": "体标"}], "register": "口语", "sense_fingerprint": "指望：盼望，把希望寄托在某人或某事上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157c64-73c7-4e54-9585-b5a2f818129e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87196, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "指望", "is_correct": true, "explanation": "“指望着”表示家人靠医生并抱有期待，正好对应句中的救治之意。"}, {"text": "骂", "is_correct": false, "explanation": "语义：骂是斥责，与家人寄予希望的情感完全相反，“骂着医生能救他”说不通。"}, {"text": "嫌", "is_correct": false, "explanation": "语义：嫌表示厌恶，与家人的期盼情感相反。"}, {"text": "催", "is_correct": false, "explanation": "语义：催是催促，句子表达的是盼望，而不是催促。"}], "explanations": {"指望": "“指望着”表示家人靠医生并抱有期待，正好对应句中的救治之意。", "骂": "语义：骂是斥责，与家人寄予希望的情感完全相反，“骂着医生能救他”说不通。", "嫌": "语义：嫌表示厌恶，与家人的期盼情感相反。", "催": "语义：催是催促，句子表达的是盼望，而不是催促。"}, "sentence_index": 0, "correct_answer": "指望"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天都指望房间。", "explanation": "这里应该用〈打扫〉。指望表示盼望或依靠，清洁房间要用“打扫”。"}, {"text": "我在商店指望衣服。", "explanation": "这里应该用〈挑选〉。指望表示盼望或依靠，在商店选衣服要用“挑选”。"}, {"text": "工人在指望水管。", "explanation": "这里应该用〈修理〉。指望表示盼望或依靠，修理水管要用“修理”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87196, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "指望", "is_correct": true, "explanation": "“指望着”表示一直靠别人来帮忙并抱有期待，与句意相合。"}, {"text": "打算", "is_correct": false, "explanation": "语义：打算是自己的计划，不能说“打算有人来帮他一把”。"}, {"text": "决定", "is_correct": false, "explanation": "语义：决定用于自己可以作主的事，“决定有人来帮他”不通。"}, {"text": "骂", "is_correct": false, "explanation": "语义：骂是斥责，“骂着有人来帮他一把”说不通，与句中的期待相反。"}], "explanations": {"指望": "“指望着”表示一直靠别人来帮忙并抱有期待，与句意相合。", "打算": "语义：打算是自己的计划，不能说“打算有人来帮他一把”。", "决定": "语义：决定用于自己可以作主的事，“决定有人来帮他”不通。", "骂": "语义：骂是斥责，“骂着有人来帮他一把”说不通，与句中的期待相反。"}, "sentence_index": 6, "correct_answer": "指望"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们要指望环境。", "explanation": "这里应该用〈保护〉。指望是对外部依靠的盼望，爱护环境要用“保护”。"}, {"text": "他在指望书包。", "explanation": "这里应该用〈收拾〉。指望表示盼望或依靠，整理书包要用“收拾”。"}, {"text": "老师在指望作业。", "explanation": "这里应该用〈批改〉。指望是对靠得住的人或事抱期待，批阅作业要用“批改”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87196, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我以前没指望了别人帮忙。", "corrected_sentence": "我以前没指望过别人帮忙。", "error_description": "体标错误：“没”否定过去的经历时，“指望”后不能用“了”，应改用经历体“过”，写成“没指望过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87196, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们只能指望自己，不能指望了别人。", "corrected_sentence": "我们只能指望自己，不能指望别人。", "error_description": "体标错误：“指望”后加“了”表示已经完成，与“不能”表示的否定、未完成语境不合，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
