INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87197, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "歌是可以唱出来的好听的话。", "primary_collocate": null, "pronunciation": "gē", "ipa": "kɤ˥", "syllable_count": 1, "sentences": [{"text": "这首歌很好听，我天天都听。", "target_word": "歌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈给我唱了一首歌。", "target_word": "歌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我会唱这首歌，你想听吗？", "target_word": "歌", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小孩一边走路，一边唱着歌。", "target_word": "歌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌的名字很长，我记不住。", "target_word": "歌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚会上，每个人都要唱一首歌。", "target_word": "歌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这首歌让我想起小时候。", "target_word": "歌", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师教我们唱一首新歌。", "target_word": "歌", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子们学会了这首歌，唱得很大声。", "target_word": "歌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在车里听着歌，一点也不累。", "target_word": "歌", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一首歌", "label": "量词"}, {"form": "歌曲", "label": "复合词"}, {"form": "歌手", "label": "复合词"}], "register": "中性", "sense_fingerprint": "可以唱出来的好听的话，日常所说的一首歌", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94425b3a-c4ef-47ea-b6af-b5c17af3720b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87197, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "歌", "is_correct": true, "explanation": "正确答案：歌（gē，第一声），指可以唱出来的好听的话。"}, {"text": "格", "is_correct": false, "explanation": "格（gé，第二声）与歌（gē，第一声）声调不同，意思是格子。"}, {"text": "个", "is_correct": false, "explanation": "个（gè，第四声）与歌（gē，第一声）声调不同，意思是个体、量词。"}, {"text": "科", "is_correct": false, "explanation": "科（kē）与歌（gē）声母不同，k 与 g 不同，意思是科学。"}, {"text": "喝", "is_correct": false, "explanation": "喝（hē）与歌（gē）声母不同，h 与 g 不同，意思是喝水。"}, {"text": "根", "is_correct": false, "explanation": "根（gēn）比歌（gē）多一个韵尾 n，意思是树根。"}], "explanations": {"歌": "正确答案：歌（gē，第一声），指可以唱出来的好听的话。", "格": "格（gé，第二声）与歌（gē，第一声）声调不同，意思是格子。", "个": "个（gè，第四声）与歌（gē，第一声）声调不同，意思是个体、量词。", "科": "科（kē）与歌（gē）声母不同，k 与 g 不同，意思是科学。", "喝": "喝（hē）与歌（gē）声母不同，h 与 g 不同，意思是喝水。", "根": "根（gēn）比歌（gē）多一个韵尾 n，意思是树根。"}, "sentence_index": null, "correct_answer": "歌"}, "level_3": {"options": [{"text": "歌", "is_correct": true, "explanation": "正确答案：这里是一首歌，“好听”和“听”都说明它是可以唱、可以听的歌曲。"}, {"text": "汤", "is_correct": false, "explanation": "语义：汤是用来喝的，不能说“好听”，也不能说“我天天都听”。"}, {"text": "树", "is_correct": false, "explanation": "语义：树是植物，不能被“听”，也不能用“好听”来形容。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：量词“首”只用于诗、歌、曲等作品，不能修饰桌子。"}], "explanations": {"歌": "正确答案：这里是一首歌，“好听”和“听”都说明它是可以唱、可以听的歌曲。", "汤": "语义：汤是用来喝的，不能说“好听”，也不能说“我天天都听”。", "树": "语义：树是植物，不能被“听”，也不能用“好听”来形容。", "桌子": "搭配：量词“首”只用于诗、歌、曲等作品，不能修饰桌子。"}, "sentence_index": 0, "correct_answer": "歌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一边走路，一边扔着歌。", "explanation": "这里应该用〈唱〉。扔用于具体的东西，歌不能扔。"}, {"text": "我昨天在网上听到一只歌，很好听。", "explanation": "量词错误：这里应该用〈首〉。歌曲用量词“首”，“只”用于动物等，不能修饰歌。"}, {"text": "他一路走，一路说着歌。", "explanation": "这里应该用〈话〉。说用于话、语言；歌是唱出来的，不能说说歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d6d4d56-8f24-4af4-9609-d7826352ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87197, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "歌", "is_correct": true, "explanation": "正确答案：歌（gē，第一声），指可以唱出来的好听的话。"}, {"text": "隔", "is_correct": false, "explanation": "隔（gé，第二声）与歌（gē，第一声）声调不同，意思是隔壁。"}, {"text": "各", "is_correct": false, "explanation": "各（gè，第四声）与歌（gē，第一声）声调不同，意思是各自。"}, {"text": "棵", "is_correct": false, "explanation": "棵（kē）与歌（gē）声母不同，k 与 g 不同，意思是量词“一棵树”的“棵”。"}, {"text": "更", "is_correct": false, "explanation": "更（gēng）比歌（gē）多一个韵尾 ng，意思是更新。"}], "explanations": {"歌": "正确答案：歌（gē，第一声），指可以唱出来的好听的话。", "隔": "隔（gé，第二声）与歌（gē，第一声）声调不同，意思是隔壁。", "各": "各（gè，第四声）与歌（gē，第一声）声调不同，意思是各自。", "棵": "棵（kē）与歌（gē）声母不同，k 与 g 不同，意思是量词“一棵树”的“棵”。", "更": "更（gēng）比歌（gē）多一个韵尾 ng，意思是更新。"}, "sentence_index": null, "correct_answer": "歌"}, "level_3": {"options": [{"text": "歌", "is_correct": true, "explanation": "正确答案：这里说的是一首歌，“让我想起小时候”是歌曲常有的作用。"}, {"text": "楼", "is_correct": false, "explanation": "搭配：量词“首”只用于诗、歌、曲等作品，楼要用“座”，不能说“这首楼”。"}, {"text": "雨", "is_correct": false, "explanation": "搭配：量词“首”不修饰雨，雨一般用“场”，不能说“这首雨”。"}, {"text": "饭", "is_correct": false, "explanation": "语义：“首”用于诗、歌、曲等作品，饭不属于这一类，不能说“这首饭”。"}], "explanations": {"歌": "正确答案：这里说的是一首歌，“让我想起小时候”是歌曲常有的作用。", "楼": "搭配：量词“首”只用于诗、歌、曲等作品，楼要用“座”，不能说“这首楼”。", "雨": "搭配：量词“首”不修饰雨，雨一般用“场”，不能说“这首雨”。", "饭": "语义：“首”用于诗、歌、曲等作品，饭不属于这一类，不能说“这首饭”。"}, "sentence_index": 6, "correct_answer": "歌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在车里讲着歌，一点也不累。", "explanation": "这里应该用〈笑话〉。讲用于笑话、故事；歌是唱或听的，不能说讲歌。"}, {"text": "我在车里读着歌，一点也不累。", "explanation": "这里应该用〈信〉。读用于书、信等文字；歌是唱或听的，不能说读歌。"}, {"text": "我在车里听着一幅歌，一点也不累。", "explanation": "量词错误：这里应该用〈首〉。幅用于字画，歌曲用量词“首”，不能用“幅”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d6d4d56-8f24-4af4-9609-d7826352ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87197, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天听了一个歌。", "corrected_sentence": "我昨天听了一首歌。", "error_description": "量词错误：歌曲应用量词“首”，“个”是通用量词，不能用来数歌曲。错误形式：一个歌；正确形式：一首歌。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d6d4d56-8f24-4af4-9609-d7826352ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87197, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天在朋友的生日会上唱一首歌。", "corrected_sentence": "我昨天在朋友的生日会上唱了一首歌。", "error_description": "动态助词“了”遗漏。叙述已经发生的动作，有“昨天”时要用“唱了”，不能说“唱一首歌”。错误形式：唱一首歌；正确形式：唱了一首歌。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d6d4d56-8f24-4af4-9609-d7826352ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
