INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87199, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "至少是最少也有这么多，可能还会更多。", "primary_collocate": null, "pronunciation": "zhì shǎo", "ipa": "tʂʐ̩˥˩ ʂɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个教室里至少有三十个学生。", "target_word": "至少", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去那里坐飞机至少要三个小时。", "target_word": "至少", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书我至少看过两遍。", "target_word": "至少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家离学校至少有五公里。", "target_word": "至少", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件衣服至少要两百块钱。", "target_word": "至少", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我等了他至少一个小时。", "target_word": "至少", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家饭馆至少有十年的历史。", "target_word": "至少", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每天至少喝八杯水，对身体好。", "target_word": "至少", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的年纪至少有六十岁了。", "target_word": "至少", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天来参加会议的人至少有一百个。", "target_word": "至少", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词；放在数量前，表示数量最少也有这么多，实际可能更多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f0f3827-7eef-4040-8225-662f43c0b4c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87199, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "至少", "is_correct": true, "explanation": "至少表示下限，说明教室里的学生人数不少于三十个，符合句意。"}, {"text": "从而", "is_correct": false, "explanation": "语法：「从而」是连词，用来连接结果分句，不能放在“有三十个学生”前面。"}, {"text": "反而", "is_correct": false, "explanation": "语义：「反而」表示与预期相反，句中没有可以相反的语境。"}, {"text": "险些", "is_correct": false, "explanation": "搭配：「险些」表示差一点发生某事，不能用来说明人数。"}], "explanations": {"至少": "至少表示下限，说明教室里的学生人数不少于三十个，符合句意。", "从而": "语法：「从而」是连词，用来连接结果分句，不能放在“有三十个学生”前面。", "反而": "语义：「反而」表示与预期相反，句中没有可以相反的语境。", "险些": "搭配：「险些」表示差一点发生某事，不能用来说明人数。"}, "sentence_index": 0, "correct_answer": "至少"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个箱子至少能装五公斤，超过就会坏。", "explanation": "这里应该用〈最多〉。〈至少〉表示下限，与“超过就会坏”的上限要求矛盾。"}, {"text": "他家离学校至少刚好五公里。", "explanation": "这里应该用〈大约〉。〈至少〉说的是下限，可能还会更多；“刚好五公里”说的是确定的距离，两者意思相冲。"}, {"text": "至少他家离学校的距离，我不清楚。", "explanation": "这里应该用〈至于〉。〈至少〉表示最低限度，不能用来引出话题。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef175001-3b2f-40fa-a90b-63d5df1dce81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87199, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "至少", "is_correct": true, "explanation": "至少表示下限，说明饭馆的历史不少于十年，符合句意。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：「偶尔」表示不常发生，不能用来说明历史年限。"}, {"text": "顺便", "is_correct": false, "explanation": "语义：「顺便」表示趁做某事时附带做另一件事，不能用来说明历史年限。"}, {"text": "况且", "is_correct": false, "explanation": "语法：「况且」是连词，用来追加理由，不能放在“有十年的历史”前面。"}], "explanations": {"至少": "至少表示下限，说明饭馆的历史不少于十年，符合句意。", "偶尔": "语义：「偶尔」表示不常发生，不能用来说明历史年限。", "顺便": "语义：「顺便」表示趁做某事时附带做另一件事，不能用来说明历史年限。", "况且": "语法：「况且」是连词，用来追加理由，不能放在“有十年的历史”前面。"}, "sentence_index": 6, "correct_answer": "至少"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天来参加会议的人至少不超过一百个。", "explanation": "这里应该用〈至多〉。〈至少〉表示下限，与“不超过”的上限相矛盾。"}, {"text": "今天来参加会议的人至少正好是一百个。", "explanation": "〈至少〉表示下限，可能还会更多，而这句说的是确定的数目，两者意思相冲，不能这样并用。"}, {"text": "今天来参加会议的人至少不到一百个，会场还空着不少座位。", "explanation": "这里应该用〈不足〉。〈至少〉表示下限，与“不到一百个”的上限相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef175001-3b2f-40fa-a90b-63d5df1dce81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87199, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次会议很至少要准备五十把椅子。", "corrected_sentence": "这次会议至少要准备五十把椅子。", "error_description": "用词错误：「至少」前面不能再加程度副词「很」，「很至少」不成词；应说“这次会议至少要准备五十把椅子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef175001-3b2f-40fa-a90b-63d5df1dce81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87199, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个湖里只至少有两百条鱼。", "corrected_sentence": "这个湖里至少有两百条鱼。", "error_description": "词语搭配错误：「只」表示限定、数量少，与「至少」表示的最低下限相冲，不能同用，应说“这个湖里至少有两百条鱼”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef175001-3b2f-40fa-a90b-63d5df1dce81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
