INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87200, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示最低限度。", "primary_collocate": null, "pronunciation": "zhì shǎo", "ipa": "tʂʐ̩˥˩ ʂɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "你至少应该打个电话告诉我。", "target_word": "至少", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "病好以前，你至少要休息一个星期。", "target_word": "至少", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做错了事，至少要说一声对不起。", "target_word": "至少", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事你至少得让我知道。", "target_word": "至少", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不来也行，至少该发个短信。", "target_word": "至少", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气不好，我们至少带把伞吧。", "target_word": "至少", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你不喜欢也没关系，至少试一试。", "target_word": "至少", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要想考好，至少得认真复习。", "target_word": "至少", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你要走也行，至少先把饭吃完。", "target_word": "至少", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出门在外，至少要照顾好自己。", "target_word": "至少", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词；表示最低限度的要求或做法，常与应该、要、得等连用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f0f3827-7eef-4040-8225-662f43c0b4c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87200, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "至少", "is_correct": true, "explanation": "至少表示最低限度的要求，与“应该打个电话”的劝告相符。"}, {"text": "正在", "is_correct": false, "explanation": "语义：「正在」表示动作进行中，不能与「应该」这类情态词直接搭配，句子不通。"}, {"text": "果然", "is_correct": false, "explanation": "语义：「果然」用来印证先前的预料，不能用来提出劝告。"}, {"text": "差点", "is_correct": false, "explanation": "搭配：「差点」接的是险些没发生的事，不能与「应该」搭配。"}], "explanations": {"至少": "至少表示最低限度的要求，与“应该打个电话”的劝告相符。", "正在": "语义：「正在」表示动作进行中，不能与「应该」这类情态词直接搭配，句子不通。", "果然": "语义：「果然」用来印证先前的预料，不能用来提出劝告。", "差点": "搭配：「差点」接的是险些没发生的事，不能与「应该」搭配。"}, "sentence_index": 0, "correct_answer": "至少"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "规定每人至少只能借两本书，多一本都不行。", "explanation": "这里应该用〈最多〉。〈至少〉表示最低下限，与“只能”“多一本都不行”的上限要求相矛盾。"}, {"text": "每位学生的作业至少不超过两页。", "explanation": "这里应该用〈至多〉。〈至少〉表示下限，与“不超过”表示的上限相矛盾。"}, {"text": "至少他的事情我不知道，你去问问别人吧。", "explanation": "这里应该用〈至于〉。〈至少〉表示最低限度，不能用来引出话题。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef175001-3b2f-40fa-a90b-63d5df1dce81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87200, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "至少", "is_correct": true, "explanation": "至少表示最低限度，劝人试一试，与句意相合。"}, {"text": "竟然", "is_correct": false, "explanation": "语义：「竟然」表示出乎意料，与「没关系」的平和语气不合。"}, {"text": "幸亏", "is_correct": false, "explanation": "搭配：「幸亏」要接已经发生的侥幸结果，不能用来劝人尝试。"}, {"text": "本来", "is_correct": false, "explanation": "语义：「本来」指原本的状态，不能表示劝人尝试的建议。"}], "explanations": {"至少": "至少表示最低限度，劝人试一试，与句意相合。", "竟然": "语义：「竟然」表示出乎意料，与「没关系」的平和语气不合。", "幸亏": "搭配：「幸亏」要接已经发生的侥幸结果，不能用来劝人尝试。", "本来": "语义：「本来」指原本的状态，不能表示劝人尝试的建议。"}, "sentence_index": 6, "correct_answer": "至少"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次旅行，至少不得超过三天就回家。", "explanation": "这里应该用〈顶多〉。〈至少〉表示下限，与“不得超过三天”的上限要求相矛盾。"}, {"text": "这次旅行的费用至少恰好是三千块。", "explanation": "这里应该用〈大约〉。〈至少〉表示下限，与“恰好”表示的确定数目相矛盾。"}, {"text": "这件事你至少才告诉我一声。", "explanation": "这里应该用〈只〉。〈至少〉表示最低限度，与“才”所表示的仅此而已相冲突，句子说不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef175001-3b2f-40fa-a90b-63d5df1dce81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87200, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事你很至少要告诉我一声。", "corrected_sentence": "这件事你至少要告诉我一声。", "error_description": "用词错误：「至少」前面不能再加程度副词「很」，「很至少」不成词；应说“这件事你至少要告诉我一声”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef175001-3b2f-40fa-a90b-63d5df1dce81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87200, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份报告只至少要写两页。", "corrected_sentence": "这份报告至少要写两页。", "error_description": "词语搭配错误：「只」表示限定，与「至少」表示的最低限度相冲，不能同用，应说“这份报告至少要写两页”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef175001-3b2f-40fa-a90b-63d5df1dce81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
