INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87201, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "何必是说这件事不用做，做了也没用。", "primary_collocate": null, "pronunciation": "hé bì", "ipa": "xɤ˧˥ pi˥˩", "syllable_count": 2, "sentences": [{"text": "事情已经这样了，你何必再生气呢？", "target_word": "何必", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不会听你的，你何必白费口舌？", "target_word": "何必", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "东西不贵，何必去那么远的地方买？", "target_word": "何必", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都是朋友，何必客气呢？", "target_word": "何必", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气这么好，何必待在家里玩手机？", "target_word": "何必", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这点小事，何必告诉老师呢？", "target_word": "何必", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路这么近，何必打车去？", "target_word": "何必", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他已经道歉了，你何必还记着？", "target_word": "何必", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们早就知道答案了，何必再问一遍？", "target_word": "何必", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "都是一家人，何必分得这么清楚？", "target_word": "何必", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "反问语气，劝人不必做某事，做了也没用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dee2df57-fb87-4f86-b7e0-dc23161c9f7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87201, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "何必", "is_correct": true, "explanation": "正确。“何必”用反问语气表示没有必要，符合劝人别再生气的语气。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示立刻发生，与“事情已经这样了”的情境和反问语气不合。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”表示过去的经历，句子说的是现在还要不要生气。"}, {"text": "千万", "is_correct": false, "explanation": "搭配：“千万”多用于“千万别……”等祈使句，不能直接用于“你……呢”的反问。"}], "explanations": {"何必": "正确。“何必”用反问语气表示没有必要，符合劝人别再生气的语气。", "马上": "语义：“马上”表示立刻发生，与“事情已经这样了”的情境和反问语气不合。", "曾经": "语义：“曾经”表示过去的经历，句子说的是现在还要不要生气。", "千万": "搭配：“千万”多用于“千万别……”等祈使句，不能直接用于“你……呢”的反问。"}, "sentence_index": 0, "correct_answer": "何必"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个主意不错，何必试一试？", "explanation": "这里应该用〈何妨〉。“何必”表示没有必要，与“不错”的建议语气矛盾；“何妨”表示“不妨”，是建议去做。"}, {"text": "这件事很重要，我何必去做。", "explanation": "这里应该用〈必须〉。“何必”表示没有必要，与“很重要”矛盾；表示一定要做，应该用〈必须〉。"}, {"text": "这次手术很危险，你何必小心？", "explanation": "这里应该用〈务必〉。“何必”表示没有必要，与“很危险”的提醒矛盾；提醒对方一定要小心，应该用〈务必〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a98ea9d3-b4df-4039-8afd-0d8e4106367f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87201, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "何必", "is_correct": true, "explanation": "正确。“何必”用反问表示没有必要，“路这么近，何必打车去”通顺。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突然发生，与“路这么近”的道理和反问语气不合。"}, {"text": "只好", "is_correct": false, "explanation": "语义：“只好”表示无奈的选择，与“路这么近”的条件不合，句子说不通。"}, {"text": "理应", "is_correct": false, "explanation": "语域：“理应”是书面语，口语反问中不用；语义上“应该打车”也与“路近”的情境冲突。"}], "explanations": {"何必": "正确。“何必”用反问表示没有必要，“路这么近，何必打车去”通顺。", "忽然": "语义：“忽然”表示突然发生，与“路这么近”的道理和反问语气不合。", "只好": "语义：“只好”表示无奈的选择，与“路这么近”的条件不合，句子说不通。", "理应": "语域：“理应”是书面语，口语反问中不用；语义上“应该打车”也与“路近”的情境冲突。"}, "sentence_index": 6, "correct_answer": "何必"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这是公司的规定，大家何必遵守。", "explanation": "这里应该用〈应该〉。规定要求大家遵守，“何必”表示没有必要，与规定的意思矛盾。"}, {"text": "下雨了，你何必带伞。", "explanation": "这里应该用〈要〉。下雨需要带伞，“何必”表示不必，与下雨的情境矛盾。"}, {"text": "你做错了事，何必向他道歉。", "explanation": "这里应该用〈该〉。做错了事应当向对方道歉，“何必”表示没有必要，与这一情境矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a98ea9d3-b4df-4039-8afd-0d8e4106367f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87201, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这么小的事，你很何必生气呢？", "corrected_sentence": "这么小的事，你何必生气呢？", "error_description": "副词位置错误：“何必”是副词，应直接放在动词前，前面不能再加“很”。正确说法是“你何必生气呢”，不说“你很何必生气呢”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a98ea9d3-b4df-4039-8afd-0d8e4106367f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87201, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这么晚了，你何必还出去还呢？", "corrected_sentence": "这么晚了，你何必还出去呢？", "error_description": "副词重复且位置错误：“还”只能放在动词前，“出去”后面多出的“还”应删去，正确说法是“你何必还出去呢”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a98ea9d3-b4df-4039-8afd-0d8e4106367f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
