INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87206, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "根据已有的线索，推测不清楚的事情。", "primary_collocate": null, "pronunciation": "cāi", "ipa": "tsʰai˥", "syllable_count": 1, "sentences": [{"text": "看他的笑脸，我猜他考得很好。", "target_word": "猜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地上有一把伞，我猜外面正在下雨。", "target_word": "猜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "根据脚印的大小，我猜这是个孩子。", "target_word": "猜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "门口放着很多鞋，你猜家里来了几个人？", "target_word": "猜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从他的口音，我猜他是南方人。", "target_word": "猜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桌上的蛋糕只剩一块，我猜弟弟已经吃了很多。", "target_word": "猜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看天上的乌云，你猜今天会不会下雨？", "target_word": "猜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一直看手机，我猜他在等朋友的消息。", "target_word": "猜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "从房间的灯光，我猜妈妈还没有睡。", "target_word": "猜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听声音就能猜出是谁来了。", "target_word": "猜", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "猜了", "label": "体标"}, {"form": "猜过", "label": "体标"}, {"form": "猜猜", "label": "重叠"}, {"form": "猜测", "label": "复合词"}], "register": "中性", "sense_fingerprint": "根据线索推测未知的事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94425b3a-c4ef-47ea-b6af-b5c17af3720b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87206, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "猜", "is_correct": true, "explanation": "猜（第一声）是正确答案，指根据线索推测不清楚的事情。"}, {"text": "才", "is_correct": false, "explanation": "cái（第二声）与 cāi 声调不同，意思是才能、刚刚。"}, {"text": "拆", "is_correct": false, "explanation": "chāi 与 cāi 声母不同（ch 与 c），意思是拆开。"}, {"text": "腮", "is_correct": false, "explanation": "sāi 与 cāi 声母不同（s 与 c），意思是脸颊。"}, {"text": "彩", "is_correct": false, "explanation": "cǎi（第三声）与 cāi 声调不同，意思是彩色。"}, {"text": "菜", "is_correct": false, "explanation": "cài（第四声）与 cāi 声调不同，意思是蔬菜。"}], "explanations": {"猜": "猜（第一声）是正确答案，指根据线索推测不清楚的事情。", "才": "cái（第二声）与 cāi 声调不同，意思是才能、刚刚。", "拆": "chāi 与 cāi 声母不同（ch 与 c），意思是拆开。", "腮": "sāi 与 cāi 声母不同（s 与 c），意思是脸颊。", "彩": "cǎi（第三声）与 cāi 声调不同，意思是彩色。", "菜": "cài（第四声）与 cāi 声调不同，意思是蔬菜。"}, "sentence_index": null, "correct_answer": "猜"}, "level_3": {"options": [{"text": "猜", "is_correct": true, "explanation": "猜表示根据笑脸推测，符合“看他的笑脸，我猜他考得很好”的语境。"}, {"text": "推", "is_correct": false, "explanation": "搭配：“推”的意思是推动，不能接“他考得很好”这样的从句。"}, {"text": "证明", "is_correct": false, "explanation": "语义：笑脸不能证明成绩，“证明”需要确凿的依据，与“看笑脸”的线索矛盾。"}, {"text": "听", "is_correct": false, "explanation": "语义：前半句说的是“看”笑脸，“听”是用耳朵，与线索冲突。"}], "explanations": {"猜": "猜表示根据笑脸推测，符合“看他的笑脸，我猜他考得很好”的语境。", "推": "搭配：“推”的意思是推动，不能接“他考得很好”这样的从句。", "证明": "语义：笑脸不能证明成绩，“证明”需要确凿的依据，与“看笑脸”的线索矛盾。", "听": "语义：前半句说的是“看”笑脸，“听”是用耳朵，与线索冲突。"}, "sentence_index": 0, "correct_answer": "猜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我猜了一个苹果，很甜。", "explanation": "这里应该用〈吃〉。猜是根据线索推测未知的事情，不能用于吃东西。"}, {"text": "他把这道数学题猜了一遍，写出了正确的步骤。", "explanation": "这里应该用〈计算〉。猜表示没有把握地推测答案，不是按步骤求解，不能用于计算过程。"}, {"text": "他闭上眼睛，猜自己成了宇航员。", "explanation": "这里应该用〈想象〉。猜是根据线索推断未知的事情，不能用来表示想象自己的样子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d6d4d56-8f24-4af4-9609-d7826352ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87206, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "猜", "is_correct": true, "explanation": "猜（第一声）是正确答案，指根据线索推测不清楚的事情。"}, {"text": "财", "is_correct": false, "explanation": "cái（第二声）与 cāi 声调不同，意思是财富。"}, {"text": "菜", "is_correct": false, "explanation": "cài（第四声）与 cāi 声调不同，意思是蔬菜。"}, {"text": "采", "is_correct": false, "explanation": "cǎi（第三声）与 cāi 声调不同，意思是采集。"}], "explanations": {"猜": "猜（第一声）是正确答案，指根据线索推测不清楚的事情。", "财": "cái（第二声）与 cāi 声调不同，意思是财富。", "菜": "cài（第四声）与 cāi 声调不同，意思是蔬菜。", "采": "cǎi（第三声）与 cāi 声调不同，意思是采集。"}, "sentence_index": null, "correct_answer": "猜"}, "level_3": {"options": [{"text": "猜", "is_correct": true, "explanation": "猜表示根据乌云推测，符合“看天上的乌云，你猜今天会不会下雨”的语境。"}, {"text": "拿", "is_correct": false, "explanation": "搭配：“拿”要求具体的实物作宾语，不能接“今天会不会下雨”这样的问句。"}, {"text": "量", "is_correct": false, "explanation": "搭配：“量”用于可以度量的事物，不能用来表示对天气的推测。"}, {"text": "闻", "is_correct": false, "explanation": "语义：前半句说的是“看乌云”，“闻”是用鼻子，与线索冲突。"}], "explanations": {"猜": "猜表示根据乌云推测，符合“看天上的乌云，你猜今天会不会下雨”的语境。", "拿": "搭配：“拿”要求具体的实物作宾语，不能接“今天会不会下雨”这样的问句。", "量": "搭配：“量”用于可以度量的事物，不能用来表示对天气的推测。", "闻": "语义：前半句说的是“看乌云”，“闻”是用鼻子，与线索冲突。"}, "sentence_index": 6, "correct_answer": "猜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他猜了一首歌，唱得很好。", "explanation": "这里应该用〈唱〉。猜是根据线索推断，不能用于演唱。"}, {"text": "工人用尺子猜桌子的长度。", "explanation": "这里应该用〈测量〉。猜是推断，不能用尺子去测量长度，测量能得到确定的数值。"}, {"text": "他把我的名字猜在黑板上。", "explanation": "这里应该用〈写〉。在黑板上留下名字是书写，猜是推测，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d6d4d56-8f24-4af4-9609-d7826352ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87206, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我不猜对他的年龄。", "corrected_sentence": "我没猜对他的年龄。", "error_description": "“猜对”是已经发生的结果，否定要用“没”，写成“不”是错误。正确：没猜对；错误：不猜对。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d6d4d56-8f24-4af4-9609-d7826352ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87206, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一次就猜了中我的心思。", "corrected_sentence": "他一次就猜中了我的心思。", "error_description": "“了”应放在补语“中”的后面，写成“猜了中”是错误。正确：猜中了；错误：猜了中。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d6d4d56-8f24-4af4-9609-d7826352ce9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
