INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87207, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "依托是靠着一个东西，让自己站得稳。", "primary_collocate": null, "pronunciation": "yī tuō", "ipa": "i˥ tʰuɔ˥", "syllable_count": 2, "sentences": [{"text": "藤蔓依托着石墙，一点点向上生长。", "target_word": "依托", "complexity_tier": "T3", "furigana": "téng màn yī tuō zhe shí qiáng, yì diǎn diǎn xiàng shàng shēng zhǎng.", "sentence_source": "generated"}, {"text": "这座古塔依托着山崖，屹立了几百年。", "target_word": "依托", "complexity_tier": "T3", "furigana": "zhè zuò gǔ tǎ yī tuō zhe shān yá, yì lì le jǐ bǎi nián.", "sentence_source": "generated"}, {"text": "这排木栅栏依托着几根石柱，才立得稳。", "target_word": "依托", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小树依托着木桩，才没有倒下。", "target_word": "依托", "complexity_tier": "T3", "furigana": "xiǎo shù yī tuō zhe mù zhuāng, cái méi yǒu dǎo xià.", "sentence_source": "generated"}, {"text": "这面旧墙依托着几根木柱，稳稳地立着。", "target_word": "依托", "complexity_tier": "T3", "furigana": "zhè miàn jiù qiáng yī tuō zhe jǐ gēn mù zhù, wěn wěn de lì zhe.", "sentence_source": "generated"}, {"text": "石桥依托着两岸的石墩，横跨河面。", "target_word": "依托", "complexity_tier": "T3", "furigana": "shí qiáo yī tuō zhe liǎng àn de shí dūn, héng kuà hé miàn.", "sentence_source": "generated"}, {"text": "这棵老树依托着山石，根扎得很深。", "target_word": "依托", "complexity_tier": "T3", "furigana": "zhè kē lǎo shù yī tuō zhe shān shí, gēn zhā de hěn shēn.", "sentence_source": "generated"}, {"text": "小木屋依托着身后的大石头，大风也吹不倒。", "target_word": "依托", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房屋依托着坚实的地基，才能站稳。", "target_word": "依托", "complexity_tier": "T3", "furigana": "fáng wū yī tuō zhe jiān shí de dì jī, cái néng zhàn wěn.", "sentence_source": "generated"}, {"text": "这段城墙依托着高高的土坡，立得很稳。", "target_word": "依托", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "依托着", "label": "体标（着）"}, {"form": "依托了", "label": "体标（了）"}], "register": "中性", "sense_fingerprint": "物体靠着某个支撑物，让自己立得稳", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '157552df-a86f-4558-b9ec-500c2d87da0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87207, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "语义：“吃”指把食物咽下去，藤蔓不能吃石墙，句意不通。"}, {"text": "依托", "is_correct": true, "explanation": "正确。依托表示靠着石墙让自己站稳，与“一点点向上生长”的情境相合。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”一般用于衣服、鞋袜，不能说“穿石墙”。"}, {"text": "举", "is_correct": false, "explanation": "语义：“举”需要有人用力把东西托起，藤蔓不能举起石墙。"}], "explanations": {"吃": "语义：“吃”指把食物咽下去，藤蔓不能吃石墙，句意不通。", "依托": "正确。依托表示靠着石墙让自己站稳，与“一点点向上生长”的情境相合。", "穿": "搭配：“穿”一般用于衣服、鞋袜，不能说“穿石墙”。", "举": "语义：“举”需要有人用力把东西托起，藤蔓不能举起石墙。"}, "sentence_index": 0, "correct_answer": "依托"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很依托父母，什么事都要问他们。", "explanation": "这里应该用〈依赖〉。依托指靠着有支撑的东西让自己站稳，人在心理和生活上需要别人时要用依赖。"}, {"text": "他总是依托父母的意见，从不反驳。", "explanation": "这里应该用〈依从〉。依从指听从、按照别人的意见做事，依托强调靠着有支撑的东西让自己站稳，不表示听从。"}, {"text": "小猫依托着妈妈，睡得很香。", "explanation": "这里应该用〈依偎〉。依偎指亲昵地贴着，依托强调靠着稳固的支撑让自己站稳，不用来形容亲昵地贴近。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cb825-c0b4-48bd-9283-9eddacabb02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87207, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "背", "is_correct": false, "explanation": "语义：“背”指用背部驮东西，树不能背山石，句意不通。"}, {"text": "依托", "is_correct": true, "explanation": "正确。依托表示靠着山石让自己站稳，与“根扎得很深”的描写相合。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：“戴”一般用于帽子、眼镜等，不能说“戴山石”。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”指用牙齿咬住东西，树不能咬山石，句意不通。"}], "explanations": {"背": "语义：“背”指用背部驮东西，树不能背山石，句意不通。", "依托": "正确。依托表示靠着山石让自己站稳，与“根扎得很深”的描写相合。", "戴": "搭配：“戴”一般用于帽子、眼镜等，不能说“戴山石”。", "咬": "语义：“咬”指用牙齿咬住东西，树不能咬山石，句意不通。"}, "sentence_index": 6, "correct_answer": "依托"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他依托着一个大包，一步步走进了房间。", "explanation": "这里应该用〈拎〉。依托指靠着有支撑的东西让自己站稳，不表示用手提拿东西。"}, {"text": "他把钥匙依托给邻居。", "explanation": "这里应该用〈托付〉。依托指靠着支撑物让自己立稳，不能表示把东西交给别人。"}, {"text": "他很依托孩子，一刻也离不开。", "explanation": "这里应该用〈依赖〉。依托指靠着有支撑的东西让自己站稳，不表示在感情或生活上离不开别人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cb825-c0b4-48bd-9283-9eddacabb02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87207, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这棵树依托着了崖壁，每年都在向上长。", "corrected_sentence": "这棵树依托着崖壁，每年都在向上长。", "error_description": "错误：“依托”后同时出现“着”和“了”，形成“着了”，不合语法。此处描述持续的依托状态，应只用“着”，即“依托着崖壁”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cb825-c0b4-48bd-9283-9eddacabb02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87207, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座小桥没有依托地石壁，就倒了。", "corrected_sentence": "这座小桥没有依托石壁，就倒了。", "error_description": "错误：「地」用于修饰动词或形容词，「石壁」是宾语，「依托」后不能加「地」。应去掉「地」，说「没有依托石壁」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cb825-c0b4-48bd-9283-9eddacabb02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
