INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87208, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "依靠某种事物作为凭借或支撑。", "primary_collocate": null, "pronunciation": "yī tuō", "ipa": "i˥ tʰuɔ˥", "syllable_count": 2, "sentences": [{"text": "这家公司依托大学做研究。", "target_word": "依托", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小镇依托旅游发展起来。", "target_word": "依托", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他依托多年的经验开了一家店。", "target_word": "依托", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个项目依托新技术，做得很好。", "target_word": "依托", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校依托网络给学生上课。", "target_word": "依托", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市依托大海，发展了港口。", "target_word": "依托", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司依托自己的品牌卖出了很多茶。", "target_word": "依托", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们依托这个平台，认识了很多朋友。", "target_word": "依托", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新工厂依托附近的铁路运送货物。", "target_word": "依托", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他依托父亲留下的店，做起了生意。", "target_word": "依托", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "依托着", "label": "体标（着）"}, {"form": "依托了", "label": "体标（了）"}], "register": "正式", "sense_fingerprint": "以某种条件、资源或基础作为凭借来做事或发展", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '157552df-a86f-4558-b9ec-500c2d87da0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87208, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "语义：“吃”指把食物咽下去，公司不能吃大学去做研究，句意不通。"}, {"text": "依托", "is_correct": true, "explanation": "正确。依托表示以大学为凭借来做研究，符合“依托某种条件做事”的意思。"}, {"text": "派", "is_correct": false, "explanation": "语义：“派”要派人或队伍去做事，“大学”不能被派去做研究，句意不通。"}, {"text": "拆", "is_correct": false, "explanation": "搭配：“拆”的对象是房屋、建筑，“拆大学”是拆毁学校的意思，与“做研究”不合。"}], "explanations": {"吃": "语义：“吃”指把食物咽下去，公司不能吃大学去做研究，句意不通。", "依托": "正确。依托表示以大学为凭借来做研究，符合“依托某种条件做事”的意思。", "派": "语义：“派”要派人或队伍去做事，“大学”不能被派去做研究，句意不通。", "拆": "搭配：“拆”的对象是房屋、建筑，“拆大学”是拆毁学校的意思，与“做研究”不合。"}, "sentence_index": 0, "correct_answer": "依托"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很依托朋友，遇事总要找朋友商量。", "explanation": "这里应该用〈依赖〉。依托指以某种条件作凭借来做事，不表示心理上对别人的依赖。"}, {"text": "学生总是依托老师的要求，不敢违反。", "explanation": "这里应该用〈依从〉。依从指听从、遵照别人的要求，依托表示凭借某种事物做事，不能用来表示听从别人的要求。"}, {"text": "孩子依托在妈妈身边，很安心。", "explanation": "这里应该用〈依偎〉。依偎指亲昵地贴近，依托表示凭借某种条件做事，不用来形容亲昵地靠近。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cb825-c0b4-48bd-9283-9eddacabb02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87208, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "丢", "is_correct": false, "explanation": "语义：“丢”指失去东西，丢掉自己的品牌后再卖茶，句意不通。"}, {"text": "依托", "is_correct": true, "explanation": "正确。依托表示凭借自己的品牌来卖茶，符合“依托某种条件做事”的意思。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：“戴”一般用于帽子、眼镜等，不能用于品牌。"}, {"text": "撕", "is_correct": false, "explanation": "语义：“撕”指把东西扯破，撕掉自己的品牌后卖茶，句意不通。"}], "explanations": {"丢": "语义：“丢”指失去东西，丢掉自己的品牌后再卖茶，句意不通。", "依托": "正确。依托表示凭借自己的品牌来卖茶，符合“依托某种条件做事”的意思。", "戴": "搭配：“戴”一般用于帽子、眼镜等，不能用于品牌。", "撕": "语义：“撕”指把东西扯破，撕掉自己的品牌后卖茶，句意不通。"}, "sentence_index": 6, "correct_answer": "依托"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把钥匙依托给邻居。", "explanation": "这里应该用〈托付〉。依托指以某物为凭借，不能表示把东西交给别人。"}, {"text": "他终于依托了这份压力，不再焦虑。", "explanation": "这里应该用〈摆脱〉。依托表示靠着或凭借某种事物，不表示脱离某种束缚。"}, {"text": "这个孩子依托奶奶，每天都要她陪着。", "explanation": "这里应该用〈依恋〉。依托指凭借某种条件或资源做事，不用来表示感情上的依恋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cb825-c0b4-48bd-9283-9eddacabb02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87208, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家餐厅依托着了当地的食材，做出了特色菜。", "corrected_sentence": "这家餐厅依托当地的食材，做出了特色菜。", "error_description": "错误：“依托”后同时出现“着”和“了”，形成“着了”，不合语法。此处表示凭借食材做事，应直接说“依托当地的食材”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cb825-c0b4-48bd-9283-9eddacabb02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87208, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座城市依托地港口，快速发展起来。", "corrected_sentence": "这座城市依托港口，快速发展起来。", "error_description": "错误：“依托”后加了“地”。“地”用于修饰动词，“港口”是宾语，不应加“地”，应说“依托港口”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cb825-c0b4-48bd-9283-9eddacabb02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87209, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "接纳", "is_correct": true, "explanation": "接纳：与“排斥”相对，指愿意让人加入、接受对方。"}, {"text": "观察", "is_correct": false, "explanation": "观察：指仔细看，与“排斥”没有反义关系。"}, {"text": "购买", "is_correct": false, "explanation": "购买：指付钱买东西，与“排斥”没有反义关系。"}, {"text": "整理", "is_correct": false, "explanation": "整理：指把东西收拾有序，与“排斥”没有反义关系。"}], "correct_answer": "接纳", "explanations": {"接纳": "接纳：与“排斥”相对，指愿意让人加入、接受对方。", "观察": "观察：指仔细看，与“排斥”没有反义关系。", "购买": "购买：指付钱买东西，与“排斥”没有反义关系。", "整理": "整理：指把东西收拾有序，与“排斥”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2148ebc6-1f27-460e-91d3-06a14eeef028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
