INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87209, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "排斥是不让别人加入，把他推到外面。", "primary_collocate": null, "pronunciation": "pái chì", "ipa": "pʰaɪ̯˧˥ tʂʰɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "同学们都排斥新来的小王。", "target_word": "排斥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们总是排斥外地来的人。", "target_word": "排斥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你不要排斥别的孩子。", "target_word": "排斥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家为什么排斥她？", "target_word": "排斥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "班里的人排斥他，不跟他玩。", "target_word": "排斥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老同事排斥新同事，不让他参加聚会。", "target_word": "排斥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他觉得朋友们在排斥他。", "target_word": "排斥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明太爱发脾气，同学都排斥他。", "target_word": "排斥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司里的老人排斥年轻人。", "target_word": "排斥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从来不排斥穷人家的孩子。", "target_word": "排斥", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "排斥了", "label": "体标（了）"}, {"form": "排斥着", "label": "体标（着）"}, {"form": "排斥过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "不让某人加入集体，把人推到圈子外面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c817ef8-4072-4671-8660-bc5321147c0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87209, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "排斥", "is_correct": true, "explanation": "排斥：不让新来的人加入集体，把他推到外面，符合句子语境。"}, {"text": "修理", "is_correct": false, "explanation": "语义：修理的对象是器物，不能用于人。"}, {"text": "关闭", "is_correct": false, "explanation": "搭配：关闭用于门窗、店铺等，不说关闭某个人。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：打扫用于房间、场所，不能用于人。"}], "explanations": {"排斥": "排斥：不让新来的人加入集体，把他推到外面，符合句子语境。", "修理": "语义：修理的对象是器物，不能用于人。", "关闭": "搭配：关闭用于门窗、店铺等，不说关闭某个人。", "打扫": "搭配：打扫用于房间、场所，不能用于人。"}, "sentence_index": 0, "correct_answer": "排斥"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用手排斥了飞来的足球。", "explanation": "这里应该用〈挡住〉。排斥指人际或观念上的推开、不接纳，用手挡住飞来的足球要说挡住。"}, {"text": "她排斥了我的邀请。", "explanation": "这里应该用〈拒绝〉。排斥指不让人加入、把人推到外面，针对人或群体；不接受别人的邀请要说拒绝。"}, {"text": "警察排斥了那个闹事的人，却一直护着他不让他受伤。", "explanation": "这里应该用〈保护〉。排斥指把人推到外面，与“护着他不让他受伤”相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2148ebc6-1f27-460e-91d3-06a14eeef028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87209, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "排斥", "is_correct": true, "explanation": "排斥：朋友们不接纳他，把他排除在外，符合句子语境。"}, {"text": "注射", "is_correct": false, "explanation": "语义：注射指把药液打入体内，与朋友之间的态度无关。"}, {"text": "装修", "is_correct": false, "explanation": "搭配：装修用于房屋、场所，不用于人。"}, {"text": "煮", "is_correct": false, "explanation": "语义：煮是用水加热食物，不能指朋友对他的态度。"}], "explanations": {"排斥": "排斥：朋友们不接纳他，把他排除在外，符合句子语境。", "注射": "语义：注射指把药液打入体内，与朋友之间的态度无关。", "装修": "搭配：装修用于房屋、场所，不用于人。", "煮": "语义：煮是用水加热食物，不能指朋友对他的态度。"}, "sentence_index": 6, "correct_answer": "排斥"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们应该排斥危险。", "explanation": "这里应该用〈躲避〉。排斥指不接纳人或观念，躲开危险要说躲避。"}, {"text": "农民用棍子排斥野猪。", "explanation": "这里应该用〈驱赶〉。排斥多用于人际关系或观念，赶走野猪要说驱赶。"}, {"text": "他总是排斥自己的责任，什么事都推给别人。", "explanation": "这里应该用〈逃避〉。排斥指推开人或观念，躲开自己该负的责任要说逃避。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2148ebc6-1f27-460e-91d3-06a14eeef028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87209, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家都把那个刚转来的学生排斥到外。", "corrected_sentence": "大家都把那个刚转来的学生排斥在外。", "error_description": "介词错误：表示处所要用介词“在”，不能用“到”。“排斥到外”不成立，应说“排斥在外”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2148ebc6-1f27-460e-91d3-06a14eeef028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
