INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87210, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使别人或别的事物离开自己，不接受。", "primary_collocate": null, "pronunciation": "pái chì", "ipa": "pʰaɪ̯˧˥ tʂʰɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他排斥一切新事物。", "target_word": "排斥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有些人排斥外来文化。", "target_word": "排斥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的身体排斥了新的肾。", "target_word": "排斥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人常常排斥新的想法。", "target_word": "排斥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不要排斥不同的意见。", "target_word": "排斥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他总是排斥别人的批评，听不进去。", "target_word": "排斥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我一点也不排斥吃辣的菜。", "target_word": "排斥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很排斥用手机，只用旧电话。", "target_word": "排斥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人的身体排斥着新心脏。", "target_word": "排斥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子排斥吃药，一吃就哭。", "target_word": "排斥", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "排斥了", "label": "体标（了）"}, {"form": "排斥着", "label": "体标（着）"}, {"form": "排斥过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "不接受别人或别的事物，使它离开自己", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c817ef8-4072-4671-8660-bc5321147c0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87210, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "排斥", "is_correct": true, "explanation": "排斥：指不接受新事物，使它离开自己，符合句子语境。"}, {"text": "测量", "is_correct": false, "explanation": "搭配：测量用于长度、重量等可度量的事物，不说测量新事物。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：烹饪指做饭做菜，与对待新事物的态度无关。"}, {"text": "翻修", "is_correct": false, "explanation": "搭配：翻修用于房屋、设施，不用于抽象的事物。"}], "explanations": {"排斥": "排斥：指不接受新事物，使它离开自己，符合句子语境。", "测量": "搭配：测量用于长度、重量等可度量的事物，不说测量新事物。", "烹饪": "语义：烹饪指做饭做菜，与对待新事物的态度无关。", "翻修": "搭配：翻修用于房屋、设施，不用于抽象的事物。"}, "sentence_index": 0, "correct_answer": "排斥"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他排斥了那道数学题，很快就做出来了。", "explanation": "这里应该用〈解答〉。排斥指不接受、使离开自己，与“很快就做出来了”相矛盾。"}, {"text": "他排斥了那场比赛，最后拿到了冠军。", "explanation": "这里应该用〈参加〉。排斥指不接受，与“最后拿到了冠军”相矛盾。"}, {"text": "他终于排斥了那杯咖啡，一口气就喝完了。", "explanation": "这里应该用〈喝〉。排斥指不接受，与“一口气就喝完了”相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2148ebc6-1f27-460e-91d3-06a14eeef028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87210, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "排斥", "is_correct": true, "explanation": "排斥：指不接受、不喜欢，符合句子语境。"}, {"text": "烧毁", "is_correct": false, "explanation": "语义：烧毁指把东西烧坏，与对吃辣菜的态度无关。"}, {"text": "擦拭", "is_correct": false, "explanation": "搭配：擦拭用于物体表面，不用于吃的菜。"}, {"text": "拆除", "is_correct": false, "explanation": "搭配：拆除用于建筑、设施，不能用于食物。"}], "explanations": {"排斥": "排斥：指不接受、不喜欢，符合句子语境。", "烧毁": "语义：烧毁指把东西烧坏，与对吃辣菜的态度无关。", "擦拭": "搭配：擦拭用于物体表面，不用于吃的菜。", "拆除": "搭配：拆除用于建筑、设施，不能用于食物。"}, "sentence_index": 6, "correct_answer": "排斥"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈排斥了那盘饺子，一口气全吃光了。", "explanation": "这里应该用〈吃〉。排斥指不接受，与“一口气全吃光了”相矛盾。"}, {"text": "他排斥了那个约定，却一直按时赴约。", "explanation": "这里应该用〈遵守〉。排斥指不接受，与“一直按时赴约”相矛盾。"}, {"text": "他终于排斥了那个新游戏，一有空就玩个不停。", "explanation": "这里应该用〈喜欢〉。排斥指不接受，与“一有空就玩个不停”相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2148ebc6-1f27-460e-91d3-06a14eeef028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87210, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个孩子排斥很厉害，一看到药就哭。", "corrected_sentence": "这个孩子排斥得很厉害，一看到药就哭。", "error_description": "错误在补语标记：程度补语要用“得”连接动词，应说“排斥得很厉害”，不能漏掉“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2148ebc6-1f27-460e-91d3-06a14eeef028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87210, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把很排斥新的科技，不愿意试。", "corrected_sentence": "他很排斥新的科技，不愿意试。", "error_description": "错误在句式：“把”字句中“把”后应接名词性宾语，此处“把”后直接接“很排斥”，结构不成立；应去掉“把”，说“他很排斥新的科技”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2148ebc6-1f27-460e-91d3-06a14eeef028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
