INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87215, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "并不是说，和你想的不一样，不是那样的。", "primary_collocate": null, "pronunciation": "bìng bù", "ipa": "piŋ˥˩ pu˥˩", "syllable_count": 2, "sentences": [{"text": "我并不是不想去，只是没时间。", "target_word": "并不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他并不是你想的那样。", "target_word": "并不", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我说这些并不是想批评你。", "target_word": "并不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有钱并不是最重要的事。", "target_word": "并不", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他不说话并不是生气了。", "target_word": "并不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我并不是说你做错了。", "target_word": "并不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师并不是不喜欢你，是希望你更好。", "target_word": "并不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的人并不是都会说英语。", "target_word": "并不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我今天不吃，并不是不饿。", "target_word": "并不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她笑并不是因为高兴，而是不好意思。", "target_word": "并不", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "並不", "label": "繁体"}], "register": "中性", "sense_fingerprint": "副词；多说并不是……，纠正对方的想法或误会，表示事实和想的不一样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f0f3827-7eef-4040-8225-662f43c0b4c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87215, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "并不", "is_correct": true, "explanation": "并不是用来纠正误会，说明“不是不想去”，与句意相合。"}, {"text": "偏偏", "is_correct": false, "explanation": "语义：「偏偏」表示有意与预料相反，句中没有这种语境。"}, {"text": "早就", "is_correct": false, "explanation": "语义：「早就」表示很早以前已经如此，句子就变成“我一直不想去”，与“并不是不想去”的意思相反。"}, {"text": "恰好", "is_correct": false, "explanation": "搭配：「恰好」表示碰巧，不能与“是不想去”这类判断句搭配。"}], "explanations": {"并不": "并不是用来纠正误会，说明“不是不想去”，与句意相合。", "偏偏": "语义：「偏偏」表示有意与预料相反，句中没有这种语境。", "早就": "语义：「早就」表示很早以前已经如此，句子就变成“我一直不想去”，与“并不是不想去”的意思相反。", "恰好": "搭配：「恰好」表示碰巧，不能与“是不想去”这类判断句搭配。"}, "sentence_index": 0, "correct_answer": "并不"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他并不是来了，我们都很高兴。", "explanation": "这里应该用〈确实〉。〈并不是〉用于澄清误会，不能用来陈述已经发生的事实。"}, {"text": "他并不知道这件事。", "explanation": "这里用的是副词〈并不〉修饰动词，只是加强否定语气，不是〈并不是〉纠正误会的用法。"}, {"text": "这件衣服并不贵，你可以买。", "explanation": "这里用的是副词〈并不〉修饰形容词，表示否定语气，不是〈并不是〉的澄清用法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef175001-3b2f-40fa-a90b-63d5df1dce81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87215, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "并不", "is_correct": true, "explanation": "并不是用来纠正误解，与“不是不喜欢”的解释相符。"}, {"text": "竟然", "is_correct": false, "explanation": "语义：「竟然」表示出乎意料，句中没有出乎意料的语境。"}, {"text": "从来", "is_correct": false, "explanation": "语义：「从来」表示一贯如此，句子就变成“老师从来不喜欢你”，与“并不是不喜欢你”的意思相反。"}, {"text": "险些", "is_correct": false, "explanation": "搭配：「险些」表示差一点发生某事，不能用于纠正误解的句式。"}], "explanations": {"并不": "并不是用来纠正误解，与“不是不喜欢”的解释相符。", "竟然": "语义：「竟然」表示出乎意料，句中没有出乎意料的语境。", "从来": "语义：「从来」表示一贯如此，句子就变成“老师从来不喜欢你”，与“并不是不喜欢你”的意思相反。", "险些": "搭配：「险些」表示差一点发生某事，不能用于纠正误解的句式。"}, "sentence_index": 6, "correct_answer": "并不"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她笑并不高兴，只是有点不好意思。", "explanation": "这里用的是副词〈并不〉修饰形容词，表示否定语气，不是〈并不是〉的澄清用法，不能用来引出原因。"}, {"text": "她并不笑，是因为不好意思。", "explanation": "这里用的是副词〈并不〉的否定用法，表示“不笑”，不是〈并不是〉的澄清用法。"}, {"text": "她并不太笑，大概是有点紧张。", "explanation": "这里用的是副词〈并不太〉的否定用法，表示“不太”，不是〈并不是〉的澄清用法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef175001-3b2f-40fa-a90b-63d5df1dce81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87215, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他没回信，很并不是忘了你，而是太忙。", "corrected_sentence": "他没回信，并不是忘了你，而是太忙。", "error_description": "叠用错误：「并不是」是固定的澄清结构，前面不能再加程度词「很」；应说“他没回信，并不是忘了你，而是太忙”，不能说“很并不是忘了你”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef175001-3b2f-40fa-a90b-63d5df1dce81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87215, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我太并不是讨厌你，只是有点忙。", "corrected_sentence": "我并不是讨厌你，只是有点忙。", "error_description": "叠用错误：「并不是」前面不能再加程度词「太」；应说“我并不是讨厌你，只是有点忙”，不能说“我太并不是讨厌你”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef175001-3b2f-40fa-a90b-63d5df1dce81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
