INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87216, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，用于否定，加强否定的语气。", "primary_collocate": null, "pronunciation": "bìng bù", "ipa": "piŋ˥˩ pu˥˩", "syllable_count": 2, "sentences": [{"text": "这件衣服并不贵。", "target_word": "并不", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他看起来并不高兴。", "target_word": "并不", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我并不知道他住在哪儿。", "target_word": "并不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这道题并不难，你再想想。", "target_word": "并不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "虽然下雨，天气并不冷。", "target_word": "并不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他并不喜欢吃辣的菜。", "target_word": "并不", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个办法并不太好。", "target_word": "并不", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我并不累，你先休息吧。", "target_word": "并不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她并不想去，是你让她去的。", "target_word": "并不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "住在城里并不方便。", "target_word": "并不", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "並不", "label": "繁体"}], "register": "中性", "sense_fingerprint": "副词；放在形容词或动词前，加强否定语气，如并不贵、并不知道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f0f3827-7eef-4040-8225-662f43c0b4c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87216, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "并不", "is_correct": true, "explanation": "并不用于加强否定语气，表示衣服不贵，与句意相合。"}, {"text": "正在", "is_correct": false, "explanation": "语法：「正在」表示动作进行，不能修饰形容词「贵」。"}, {"text": "曾", "is_correct": false, "explanation": "语法：「曾」表示过去经历，要接动词，不能直接修饰「贵」。"}, {"text": "刚刚", "is_correct": false, "explanation": "语法：「刚刚」表示时间刚过去，不能直接修饰「贵」。"}], "explanations": {"并不": "并不用于加强否定语气，表示衣服不贵，与句意相合。", "正在": "语法：「正在」表示动作进行，不能修饰形容词「贵」。", "曾": "语法：「曾」表示过去经历，要接动词，不能直接修饰「贵」。", "刚刚": "语法：「刚刚」表示时间刚过去，不能直接修饰「贵」。"}, "sentence_index": 0, "correct_answer": "并不"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我并不是怪你，只是有点累。", "explanation": "这里用的是〈并不是〉，表示“并不是说”，用来澄清误会，不是加强否定的副词用法。"}, {"text": "他并不是故意迟到，路上堵车了。", "explanation": "这里用的是〈并不是〉，表示澄清原因，不是加强否定语气的副词〈并不〉。"}, {"text": "这件事并不是你的错，别太自责。", "explanation": "这里用的是〈并不是〉，表示澄清误会，属于另一种用法，不是加强否定语气的副词用法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef175001-3b2f-40fa-a90b-63d5df1dce81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87216, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "并不", "is_correct": true, "explanation": "并不加强否定，与“不太好”搭配，符合句意。"}, {"text": "最", "is_correct": false, "explanation": "搭配：「最」与「太」都是程度副词，不能叠用，不能说“最太好”。"}, {"text": "十分", "is_correct": false, "explanation": "搭配：「十分」与「太」都是程度副词，不能叠用，不能说“十分太好”。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：「非常」与「太」都是程度副词，不能叠用，不能说“非常太好”。"}], "explanations": {"并不": "并不加强否定，与“不太好”搭配，符合句意。", "最": "搭配：「最」与「太」都是程度副词，不能叠用，不能说“最太好”。", "十分": "搭配：「十分」与「太」都是程度副词，不能叠用，不能说“十分太好”。", "非常": "搭配：「非常」与「太」都是程度副词，不能叠用，不能说“非常太好”。"}, "sentence_index": 6, "correct_answer": "并不"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们这次并不是很累，只是想换个地方。", "explanation": "这里用的是〈并不是〉，表示澄清误会，不是加强否定语气的副词〈并不〉。"}, {"text": "这次出差并不是为了工作，而是为了看朋友。", "explanation": "这里用的是〈并不是〉，表示澄清目的，属于另一种用法，不是加强否定语气的副词用法。"}, {"text": "他并不是因为生气才走的，是有急事。", "explanation": "这里用的是〈并不是〉，表示澄清原因，属于另一种用法，不是加强否定语气的副词用法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef175001-3b2f-40fa-a90b-63d5df1dce81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87216, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店的东西很并不便宜，我们走吧。", "corrected_sentence": "这家店的东西并不便宜，我们走吧。", "error_description": "叠用错误：「并不」已表示否定，前面不能再加程度词「很」，应说“这家店的东西并不便宜”，不能说“很并不便宜”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef175001-3b2f-40fa-a90b-63d5df1dce81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87216, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他太并不喜欢那部电影。", "corrected_sentence": "他并不喜欢那部电影。", "error_description": "叠用错误：「太」与「并不」都修饰后面的成分，不能连用，应说“他并不喜欢那部电影”，不能说“他太并不喜欢那部电影”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef175001-3b2f-40fa-a90b-63d5df1dce81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
