INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87217, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "损伤是使东西或身体被弄坏、弄伤。", "primary_collocate": null, "pronunciation": "sǔn shāng", "ipa": "swən˨˩˦ ʂɑŋ˥", "syllable_count": 2, "sentences": [{"text": "他摔倒时损伤了手腕。", "target_word": "损伤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨水损伤了书架。", "target_word": "损伤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太阳太强会损伤皮肤。", "target_word": "损伤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "搬花时小心点，别损伤了花。", "target_word": "损伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "声音太大会损伤听力。", "target_word": "损伤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "刀太快，不小心损伤了手指。", "target_word": "损伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过度减肥损伤了她的身体。", "target_word": "损伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开车时损伤了车门。", "target_word": "损伤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "虫子损伤了菜叶。", "target_word": "损伤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "搬运时要小心，别损伤电视机。", "target_word": "损伤", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "损伤了", "label": "体标（了）"}, {"form": "损伤过", "label": "体标（过）"}, {"form": "损伤着", "label": "体标（着）"}], "register": "中性", "sense_fingerprint": "把东西或身体弄坏、弄伤", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c817ef8-4072-4671-8660-bc5321147c0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87217, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "损伤", "is_correct": true, "explanation": "损伤：摔倒时手腕受到伤害，符合句子语境。"}, {"text": "收拾", "is_correct": false, "explanation": "语义：收拾是整理东西，与摔倒后的身体状况无关。"}, {"text": "摆放", "is_correct": false, "explanation": "语义：摆放指把东西放置好，不能用于手腕。"}, {"text": "熨烫", "is_correct": false, "explanation": "搭配：熨烫用于衣物，不用于身体部位。"}], "explanations": {"损伤": "损伤：摔倒时手腕受到伤害，符合句子语境。", "收拾": "语义：收拾是整理东西，与摔倒后的身体状况无关。", "摆放": "语义：摆放指把东西放置好，不能用于手腕。", "熨烫": "搭配：熨烫用于衣物，不用于身体部位。"}, "sentence_index": 0, "correct_answer": "损伤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大家一起努力，损伤了这个难题。", "explanation": "这里应该用〈解决〉。损伤用于具体的东西或身体，难题是抽象的，要说解决。"}, {"text": "吃药可以损伤他的疼痛。", "explanation": "这里应该用〈减轻〉。疼痛是感觉，不能被损伤，要说减轻。"}, {"text": "我们终于损伤了误会。", "explanation": "这里应该用〈消除〉。损伤用于具体的东西或身体，误会是抽象的，要说消除。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2148ebc6-1f27-460e-91d3-06a14eeef028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87217, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "损伤", "is_correct": true, "explanation": "损伤：过度减肥对身体造成伤害，符合句子语境。"}, {"text": "增强", "is_correct": false, "explanation": "语义：增强是加强，与过度减肥造成的后果相反，句子不通。"}, {"text": "清扫", "is_correct": false, "explanation": "搭配：清扫用于场所，不用于身体。"}, {"text": "检修", "is_correct": false, "explanation": "搭配：检修用于机器设备，不用于人的身体。"}], "explanations": {"损伤": "损伤：过度减肥对身体造成伤害，符合句子语境。", "增强": "语义：增强是加强，与过度减肥造成的后果相反，句子不通。", "清扫": "搭配：清扫用于场所，不用于身体。", "检修": "搭配：检修用于机器设备，不用于人的身体。"}, "sentence_index": 6, "correct_answer": "损伤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他损伤了噪音。", "explanation": "这里应该用〈降低〉。损伤不用于声音，减小噪音要说降低。"}, {"text": "他损伤了速度。", "explanation": "这里应该用〈加快〉。损伤用于具体物体或身体，速度不能被损伤，要说加快。"}, {"text": "他损伤了这个道理。", "explanation": "这里应该用〈理解〉。损伤不用于道理等抽象的内容，明白道理要说理解。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2148ebc6-1f27-460e-91d3-06a14eeef028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87217, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他没损伤了手腕。", "corrected_sentence": "他没损伤手腕。", "error_description": "错误在“了”：否定句里“没”后的动词不带“了”，应说“没损伤手腕”，不说“没损伤了手腕”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2148ebc6-1f27-460e-91d3-06a14eeef028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87217, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把那辆新车的门损伤。", "corrected_sentence": "他把那辆新车的门损伤了。", "error_description": "错误在动词后的“了”：“把”字句的动词要带补足成分，如“了”，应说“把那辆新车的门损伤了”，不能只说“损伤”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2148ebc6-1f27-460e-91d3-06a14eeef028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
