INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87221, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "侵入是没有人同意，自己跑进别人的地方里去。", "primary_collocate": null, "pronunciation": "qīn rù", "ipa": "tɕʰin˥ ʐu˥˩", "syllable_count": 2, "sentences": [{"text": "有人侵入了我们的院子。", "target_word": "侵入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小偷侵入邻居的家，拿走了钱。", "target_word": "侵入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一头野猪侵入了村里的菜地。", "target_word": "侵入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没有问我，就侵入我的房间。", "target_word": "侵入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夜里有陌生人侵入学校。", "target_word": "侵入", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这些孩子侵入了别人的花园。", "target_word": "侵入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请不要侵入别人的家。", "target_word": "侵入", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "邻居的鸡侵入我家的菜地。", "target_word": "侵入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "门口的牌子上写着：禁止侵入。", "target_word": "侵入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几个陌生人侵入了他们的村子。", "target_word": "侵入", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "侵入了", "label": "体标"}, {"form": "侵入者", "label": "复合"}], "register": "中性", "sense_fingerprint": "未经同意擅自闯进别人的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '157552df-a86f-4558-b9ec-500c2d87da0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87221, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "侵入", "is_correct": true, "explanation": "正确。「侵入」表示未经同意闯进别人的地方，符合「有人侵入了我们的院子」的句意。"}, {"text": "收割", "is_correct": false, "explanation": "搭配：「收割」用于庄稼等农作物，不能用于院子。"}, {"text": "喂", "is_correct": false, "explanation": "搭配：「喂」的对象是人或动物，不能说「喂院子」。"}, {"text": "吃", "is_correct": false, "explanation": "语义：「吃」指把食物咽下去，院子不能被吃。"}], "explanations": {"侵入": "正确。「侵入」表示未经同意闯进别人的地方，符合「有人侵入了我们的院子」的句意。", "收割": "搭配：「收割」用于庄稼等农作物，不能用于院子。", "喂": "搭配：「喂」的对象是人或动物，不能说「喂院子」。", "吃": "语义：「吃」指把食物咽下去，院子不能被吃。"}, "sentence_index": 0, "correct_answer": "侵入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他没有问我，就侵入了我的权利。", "explanation": "这里应该用〈侵犯〉。侵入指闯进某个地方，权利、利益这类抽象对象要用侵犯。"}, {"text": "下班后我侵入了自己的房间。", "explanation": "这里应该用〈进入〉。侵入含未经同意闯进别人地方的意思，回自己的房间不能说侵入。"}, {"text": "老板同意后，我们侵入了那座废弃的工厂，拍了很多照片。", "explanation": "这里应该用〈参观〉。侵入含未经同意强行闯入的意思，经过允许进入参观不能说侵入。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cb825-c0b4-48bd-9283-9eddacabb02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87221, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "侵入", "is_correct": true, "explanation": "正确。「侵入」表示未经同意闯入别人的家，符合「请不要……别人的家」的语境。"}, {"text": "养", "is_correct": false, "explanation": "搭配：「养」的对象是动物、植物或孩子，不能说养别人的家。"}, {"text": "栽", "is_correct": false, "explanation": "语义：「栽」指把植物种进土里，与「别人的家」不搭，句子不通。"}, {"text": "摘", "is_correct": false, "explanation": "搭配：「摘」指采下果实或花草，不能用于房子。"}], "explanations": {"侵入": "正确。「侵入」表示未经同意闯入别人的家，符合「请不要……别人的家」的语境。", "养": "搭配：「养」的对象是动物、植物或孩子，不能说养别人的家。", "栽": "语义：「栽」指把植物种进土里，与「别人的家」不搭，句子不通。", "摘": "搭配：「摘」指采下果实或花草，不能用于房子。"}, "sentence_index": 6, "correct_answer": "侵入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "周末我侵入了朋友的家，聊了一下午。", "explanation": "这里应该用〈拜访〉。侵入要求未经同意，朋友邀请的做客不能说侵入。"}, {"text": "我到得早，就侵入了窗边的座位。", "explanation": "这里应该用〈占据〉。侵入带有闯入、强行进入的意思，先到者坐下占座位不能说侵入。"}, {"text": "开放日那天，我们侵入了博物馆的展厅。", "explanation": "这里应该用〈参观〉。侵入是强行闯入，开放日的参观不能说侵入。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cb825-c0b4-48bd-9283-9eddacabb02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87221, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "有人侵入着邻居的菜园。", "corrected_sentence": "有人侵入了邻居的菜园。", "error_description": "错误：「侵入」指一次性的闯入动作，句中是已经发生的事，应用「了」，不能用「着」表示持续。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cb825-c0b4-48bd-9283-9eddacabb02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87221, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请不要侵入着别人的菜园。", "corrected_sentence": "请不要侵入别人的菜园。", "error_description": "错误：「侵入」用在禁止句「请不要……」中，不能加「着」。禁止句中应直接说「请不要侵入」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cb825-c0b4-48bd-9283-9eddacabb02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
