INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87222, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "未经许可强行进入，或指有害的东西进入。", "primary_collocate": null, "pronunciation": "qīn rù", "ipa": "tɕʰin˥ ʐu˥˩", "syllable_count": 2, "sentences": [{"text": "病毒侵入身体，人就会生病。", "target_word": "侵入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "黑客侵入了公司的电脑。", "target_word": "侵入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "坏人侵入他的家，被警察抓住了。", "target_word": "侵入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "细菌从伤口侵入身体。", "target_word": "侵入", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "病毒侵入电脑，文件都打不开了。", "target_word": "侵入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冷空气侵入房间，屋里很冷。", "target_word": "侵入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "敌人侵入边境，士兵马上出发。", "target_word": "侵入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有人侵入我的手机，看了我的照片。", "target_word": "侵入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "脏水侵入地下室，东西都湿了。", "target_word": "侵入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有人侵入了公司的服务器，系统发出了警报。", "target_word": "侵入", "complexity_tier": "T3", "furigana": "yǒu rén qīnrù le gōngsī de fúwùqì, xìtǒng fāchū le jǐngbào.", "sentence_source": "generated"}], "morphological_forms": [{"form": "侵入了", "label": "体标"}, {"form": "侵入者", "label": "复合"}], "register": "中性", "sense_fingerprint": "强行闯入，或有害的东西进入某处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '157552df-a86f-4558-b9ec-500c2d87da0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87222, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "侵入", "is_correct": true, "explanation": "正确。「侵入」表示有害的东西进入身体，符合「病毒侵入身体，人就会生病」的句意。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：「修理」的对象是器物，不能用于身体。"}, {"text": "收割", "is_correct": false, "explanation": "搭配：「收割」用于庄稼，人的身体不能被收割。"}, {"text": "吃", "is_correct": false, "explanation": "语义：「吃」指把食物咽下，病毒不能吃身体。"}], "explanations": {"侵入": "正确。「侵入」表示有害的东西进入身体，符合「病毒侵入身体，人就会生病」的句意。", "修理": "搭配：「修理」的对象是器物，不能用于身体。", "收割": "搭配：「收割」用于庄稼，人的身体不能被收割。", "吃": "语义：「吃」指把食物咽下，病毒不能吃身体。"}, "sentence_index": 0, "correct_answer": "侵入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我下班回到家，侵入了厨房。", "explanation": "这里应该用〈进入〉。侵入是强行或有害的进入，平常回到家里不能说侵入。"}, {"text": "我这次侵入了篮球队。", "explanation": "这里应该用〈加入〉。侵入是强行或有害的进入，自愿加入团体不能说侵入。"}, {"text": "河水侵入了大海。", "explanation": "这里应该用〈流入〉。侵入带有强行闯入或有害的意思，河水正常流入大海不能说侵入。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cb825-c0b4-48bd-9283-9eddacabb02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87222, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "侵入", "is_correct": true, "explanation": "正确。「侵入」表示强行闯入，符合「敌人侵入边境，士兵马上出发」的句意。"}, {"text": "喝", "is_correct": false, "explanation": "语义：「喝」指把液体咽下，边境不能被喝。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：「擦」的对象是物体表面，不能说擦边境。"}, {"text": "栽", "is_correct": false, "explanation": "语义：「栽」指种植，与敌军进攻的语境不符。"}], "explanations": {"侵入": "正确。「侵入」表示强行闯入，符合「敌人侵入边境，士兵马上出发」的句意。", "喝": "语义：「喝」指把液体咽下，边境不能被喝。", "擦": "搭配：「擦」的对象是物体表面，不能说擦边境。", "栽": "语义：「栽」指种植，与敌军进攻的语境不符。"}, "sentence_index": 6, "correct_answer": "侵入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们搬来后，侵入了这栋楼。", "explanation": "这里应该用〈入住〉。侵入带有强行或有害的意思，正常搬进楼里不能说侵入。"}, {"text": "今天我们侵入了博物馆，参观了很多展品。", "explanation": "这里应该用〈走进〉。侵入是强行闯入，开放的博物馆可以正常走进去参观，不能说侵入。"}, {"text": "我今天侵入了客厅，把地拖了一遍。", "explanation": "这里应该用〈走进〉。侵入含未经许可强行闯入的意思，在自己家里走进客厅不能说侵入。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cb825-c0b4-48bd-9283-9eddacabb02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87222, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "病毒侵入得肺部，人就会生病。", "corrected_sentence": "病毒侵入了肺部，人就会生病。", "error_description": "错误：「侵入」后面表示已经发生，要用「了」，「得」用于补语，不能接在这里。应说「病毒侵入了肺部」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cb825-c0b4-48bd-9283-9eddacabb02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87222, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "敌人侵入了过边境，所以士兵一直在守卫。", "corrected_sentence": "敌人侵入过边境，所以士兵一直在守卫。", "error_description": "错误：「了」和「过」不能同时用在同一个动词后。表示曾经发生过的经历只用「过」，应说「侵入过」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cb825-c0b4-48bd-9283-9eddacabb02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
