INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87223, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "什么人是问这是谁，是哪一个人。", "primary_collocate": null, "pronunciation": "shén me rén", "ipa": "ʂən˧˥ mɤ ʐən˧˥", "syllable_count": 3, "sentences": [{"text": "门口站着的那个人是什么人？", "target_word": "什么人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道他是什么人吗？", "target_word": "什么人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天来找你的是什么人？", "target_word": "什么人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么晚了，外面是什么人在说话？", "target_word": "什么人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那辆车里坐着什么人？", "target_word": "什么人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们是什么人，怎么进来的？", "target_word": "什么人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你到底是什么人，为什么跟着我？", "target_word": "什么人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个包是什么人落下的？", "target_word": "什么人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼上住的是什么人，晚上这么吵？", "target_word": "什么人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，您要找什么人？", "target_word": "什么人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "什麼人", "label": "繁体"}], "register": "口语", "sense_fingerprint": "询问某个人是谁、是哪一个人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08020456-83a6-4525-94f5-4b11f7843608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87223, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "什么人", "is_correct": true, "explanation": "正确。「门口站着的那个人是什么人」询问这个人的身份。"}, {"text": "什么事", "is_correct": false, "explanation": "语义：「什么事」问的是事情，不能用来问这个人的身份。"}, {"text": "什么名字", "is_correct": false, "explanation": "搭配：「是」后不接「名字」来问身份，问名字应说「叫什么名字」。"}, {"text": "什么地方", "is_correct": false, "explanation": "语义：「什么地方」问的是处所，不能回答这个人是谁。"}], "explanations": {"什么人": "正确。「门口站着的那个人是什么人」询问这个人的身份。", "什么事": "语义：「什么事」问的是事情，不能用来问这个人的身份。", "什么名字": "搭配：「是」后不接「名字」来问身份，问名字应说「叫什么名字」。", "什么地方": "语义：「什么地方」问的是处所，不能回答这个人是谁。"}, "sentence_index": 0, "correct_answer": "什么人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你叫什么人？", "explanation": "这里不该用〈什么人〉。问名字要说〈叫什么〉或〈叫什么名字〉，〈什么人〉不能接在〈叫〉后。"}, {"text": "你姓什么人？", "explanation": "这里不该用〈什么人〉。问姓氏要说〈姓什么〉，〈什么人〉不能搭配〈姓〉。"}, {"text": "你住在什么人？", "explanation": "这里不该用〈什么人〉。〈住在〉后接处所，应说〈住在什么地方〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87223, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "什么人", "is_correct": true, "explanation": "正确。「你到底是什么人」询问对方的身份，与「为什么跟着我」相合。"}, {"text": "什么办法", "is_correct": false, "explanation": "语义：「什么办法」问的是方式，不能回答对方是谁。"}, {"text": "什么年龄", "is_correct": false, "explanation": "搭配：问年龄应说「多大」或「几岁」，「是什么年龄」不能问人的身份。"}, {"text": "什么原因", "is_correct": false, "explanation": "语义：「什么原因」问的是缘由，与「你到底是……为什么跟着我」的句意不合。"}], "explanations": {"什么人": "正确。「你到底是什么人」询问对方的身份，与「为什么跟着我」相合。", "什么办法": "语义：「什么办法」问的是方式，不能回答对方是谁。", "什么年龄": "搭配：问年龄应说「多大」或「几岁」，「是什么年龄」不能问人的身份。", "什么原因": "语义：「什么原因」问的是缘由，与「你到底是……为什么跟着我」的句意不合。"}, "sentence_index": 6, "correct_answer": "什么人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那只猫是什么人？", "explanation": "这里不该用〈什么人〉。〈什么人〉只问人，问动物应用〈什么〉。"}, {"text": "这辆汽车是什么人？", "explanation": "这里不该用〈什么人〉。〈什么人〉不能用来问物品，问汽车应用〈什么〉。"}, {"text": "这个计划是什么人？", "explanation": "这里不该用〈什么人〉。〈什么人〉只用于人，问计划应用〈什么〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87223, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "门外站着一只什么人，你去看看。", "corrected_sentence": "门外站着一个什么人，你去看看。", "error_description": "错误：〈什么人〉中的「人」用量词「只」不对，「只」用于动物或物品。正确：应用「个」（或「位」），说「一个什么人」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87223, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你究竟是一只什么人，为什么闯进我家？", "corrected_sentence": "你究竟是一个什么人，为什么闯进我家？", "error_description": "错误：〈什么人〉前的量词「只」不对，「只」用于动物或物品，指人应用「个」。正确：应说「一个什么人」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
