INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87224, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "疑问代词短语，询问人的身份；谁。", "primary_collocate": null, "pronunciation": "shén me rén", "ipa": "ʂən˧˥ mɤ ʐən˧˥", "syllable_count": 3, "sentences": [{"text": "他是什么人？我从没见过他。", "target_word": "什么人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们公司的老板是什么人？", "target_word": "什么人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察问他：“你是什么人？”", "target_word": "什么人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个戴帽子的男人是什么人？", "target_word": "什么人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想知道我是什么人吗？", "target_word": "什么人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的邻居是什么人，你听说了吗？", "target_word": "什么人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面有人敲门，来的是什么人？", "target_word": "什么人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这封信是什么人写的？", "target_word": "什么人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你昨天和什么人一起吃饭？", "target_word": "什么人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先弄清楚，他到底是什么人。", "target_word": "什么人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "什麼人", "label": "繁体"}], "register": "口语", "sense_fingerprint": "疑问代词短语，询问人的身份，相当于谁", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08020456-83a6-4525-94f5-4b11f7843608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87224, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "什么人", "is_correct": true, "explanation": "正确。「他是什么人」询问他的身份，与「我从没见过他」相合。"}, {"text": "什么地方", "is_correct": false, "explanation": "语义：「什么地方」问的是处所，不能用来问他的身份。"}, {"text": "什么年龄", "is_correct": false, "explanation": "搭配：问年龄应说「多大」或「几岁」，「是什么年龄」不能问人的身份。"}, {"text": "什么办法", "is_correct": false, "explanation": "语义：「什么办法」问的是方式，不能回答「他是谁」。"}], "explanations": {"什么人": "正确。「他是什么人」询问他的身份，与「我从没见过他」相合。", "什么地方": "语义：「什么地方」问的是处所，不能用来问他的身份。", "什么年龄": "搭配：问年龄应说「多大」或「几岁」，「是什么年龄」不能问人的身份。", "什么办法": "语义：「什么办法」问的是方式，不能回答「他是谁」。"}, "sentence_index": 0, "correct_answer": "什么人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那只狗是什么人？", "explanation": "这里不该用〈什么人〉。〈什么人〉只问人，问动物应用〈什么〉。"}, {"text": "这座楼是什么人？", "explanation": "这里不该用〈什么人〉。〈什么人〉不能用来问建筑，问楼应用〈什么〉。"}, {"text": "这个想法是什么人？", "explanation": "这里不该用〈什么人〉。〈什么人〉不能用来问想法，这里应用〈什么〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87224, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "什么人", "is_correct": true, "explanation": "正确。「来的是什么人」询问来者的身份，与「外面有人敲门」相合。"}, {"text": "什么时候", "is_correct": false, "explanation": "语义：「什么时候」问的是时间，不能用来问来者是谁。"}, {"text": "什么颜色", "is_correct": false, "explanation": "语义：「什么颜色」问的是颜色，而敲门来的是人，问的是来者的身份。"}, {"text": "什么原因", "is_correct": false, "explanation": "语义：「什么原因」问的是缘由，不能回答来的是哪一个人。"}], "explanations": {"什么人": "正确。「来的是什么人」询问来者的身份，与「外面有人敲门」相合。", "什么时候": "语义：「什么时候」问的是时间，不能用来问来者是谁。", "什么颜色": "语义：「什么颜色」问的是颜色，而敲门来的是人，问的是来者的身份。", "什么原因": "语义：「什么原因」问的是缘由，不能回答来的是哪一个人。"}, "sentence_index": 6, "correct_answer": "什么人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的性格是什么人？", "explanation": "这里不该用〈什么人〉。〈什么人〉问的是人的身份，这里问的是性格特征，应说〈什么样〉。"}, {"text": "今天的天气是什么人？", "explanation": "这里不该用〈什么人〉。〈什么人〉问的是人的身份，天气不是人，应说〈怎么样〉。"}, {"text": "他的年龄是什么人？", "explanation": "这里不该用〈什么人〉。〈什么人〉问的是人的身份，年龄是数量，应问〈多大〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87224, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "刚才进来的那个人，我们都不知道是一只什么人。", "corrected_sentence": "刚才进来的那个人，我们都不知道是一个什么人。", "error_description": "错误：〈什么人〉前的量词「只」不对，「只」用于动物或物品，指人应用「个」。正确：应说「是一个什么人」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87224, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屋里坐着一只什么人，你小心点。", "corrected_sentence": "屋里坐着一个什么人，你小心点。", "error_description": "错误：〈什么人〉中的「人」用量词「只」不对，「只」用于动物或物品。正确：指人应用「个」，说「一个什么人」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20b46da-b881-452e-870c-ac659301b833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
